// Creature compiler (Cyrus R3): a validated RigSpec -> a Blockbench .bbmodel (format 5.0, what the pinned BetterModel
// 3.5.0 loads; verified by loading it on a real Paper 26.2 server, docs "Cyrus creature pipeline (R3)"), the skin PNG
// (box-unwrapped UV atlas painted by the texture pipeline's own DSL renderer) and the animations baked to keyframes.
// Deterministic: the same spec + namespace always gives byte-identical output (UUIDs are derived, not random).
// Pure (node:crypto + the PNG encoder only), server-side.
import { createHash } from "node:crypto";
import { checkSpec, type Op, type TextureSpec } from "../textures/dsl";
import { encodePng } from "../textures/png";
import { render, type Raster } from "../textures/render";
import { FACES, faceSize, modelKey, type Bone, type Clip, type Cube, type Face, type RigSpec, type Track } from "./spec";

export const COMPILER_VERSION = "rig-c1";
export const BBMODEL_FORMAT = "5.0";

export type FaceRect = { x: number; y: number; w: number; h: number };
export type CubeLayout = { bone: string; index: number; u: number; v: number; w: number; h: number; d: number; faces: Record<Face, FaceRect> };
export type SkinLayout = { size: 64 | 128; cubes: CubeLayout[] };

const ceil = (v: number) => Math.max(1, Math.ceil(v - 1e-9));
const r4 = (v: number) => { const x = Math.round(v * 10000) / 10000; return Object.is(x, -0) ? 0 : x; };

/** Box-UV rectangles of one cube at (u, v) (the Blockbench / Minecraft layout, so faces share edges like a net). */
function boxFaces(u: number, v: number, w: number, h: number, d: number): Record<Face, FaceRect> {
  return {
    east: { x: u, y: v + d, w: d, h },
    north: { x: u + d, y: v + d, w, h },
    west: { x: u + d + w, y: v + d, w: d, h },
    south: { x: u + 2 * d + w, y: v + d, w, h },
    up: { x: u + d, y: v, w, h: d },
    down: { x: u + d + w, y: v, w, h: d },
  };
}

/** Shelf-pack every cube's box net onto the smallest sheet (64 or 128) that fits; deterministic order. */
export function layoutSkin(spec: RigSpec): { ok: true; layout: SkinLayout } | { ok: false; error: string } {
  const items: { bone: string; index: number; w: number; h: number; d: number; fw: number; fh: number; order: number }[] = [];
  let order = 0;
  for (const b of spec.bones) for (const [i, c] of b.cubes.entries()) {
    const w = ceil(c.to[0] - c.from[0]), h = ceil(c.to[1] - c.from[1]), d = ceil(c.to[2] - c.from[2]);
    items.push({ bone: b.name, index: i, w, h, d, fw: 2 * (w + d), fh: d + h, order: order++ });
  }
  const sorted = [...items].sort((a, b) => b.fh - a.fh || b.fw - a.fw || a.order - b.order);
  const sizes = spec.skin.size ? [spec.skin.size] : [64, 128] as const;
  for (const size of sizes) {
    const placed: CubeLayout[] = [];
    let x = 0, y = 0, row = 0, ok = true;
    for (const it of sorted) {
      if (it.fw > size) { ok = false; break; }
      if (x + it.fw > size) { x = 0; y += row; row = 0; }
      if (y + it.fh > size) { ok = false; break; }
      placed.push({ bone: it.bone, index: it.index, u: x, v: y, w: it.w, h: it.h, d: it.d, faces: boxFaces(x, y, it.w, it.h, it.d) });
      x += it.fw; row = Math.max(row, it.fh);
    }
    if (ok) {
      placed.sort((a, b) => spec.bones.findIndex((q) => q.name === a.bone) - spec.bones.findIndex((q) => q.name === b.bone) || a.index - b.index);
      return { ok: true, layout: { size: size as 64 | 128, cubes: placed } };
    }
  }
  return { ok: false, error: `the cubes do not fit on a ${spec.skin.size ?? 128} px skin sheet; use fewer or smaller cubes` };
}

// ---------------------------------------------------------------------------------------------------- skin ----
const hex = (c: string) => [1, 3, 5].map((i) => parseInt(c.slice(i, i + 2), 16));
const toHex = (rgb: number[]) => `#${rgb.map((v) => Math.max(0, Math.min(255, Math.round(v))).toString(16).padStart(2, "0")).join("")}`;
const mix = (a: string, b: string, t: number) => toHex(hex(a).map((v, i) => v + (hex(b)[i] - v) * t));
/** Light/dark shades of a colour (lighten toward white, darken toward a cool near-black, like hand-painted ramps). */
const shadeOf = (c: string, k: "l" | "d" | "e") => (k === "l" ? mix(c, "#ffffff", 0.16) : k === "d" ? mix(c, "#0b0a14", 0.24) : mix(c, "#0b0a14", 0.4));

/**
 * The skin as a texture-pipeline TextureSpec (profile "skin"): per face a base fill (top light, bottom dark, sides
 * base or a stepped vertical fade), a darker 1 px rim on faces of 3+ px for definition, then the RigSpec's decals.
 */
export function skinTextureSpec(spec: RigSpec, layout: SkinLayout): TextureSpec {
  const palette: Record<string, string> = {};
  const key = (prefix: string, c: string) => {
    const k = `${prefix}_${c.slice(1)}`;
    palette[k] = c;
    return k;
  };
  const ops: Op[] = [];
  const P = spec.skin.palette;
  for (const cl of layout.cubes) {
    const cube = spec.bones.find((b) => b.name === cl.bone)!.cubes[cl.index];
    const base = P[cube.material];
    const fadeTo = cube.shade === "fade" && cube.fadeTo ? P[cube.fadeTo] : null;
    for (const f of FACES) {
      const r = cl.faces[f];
      if (f === "up") ops.push({ op: "rect", x: r.x, y: r.y, w: r.w, h: r.h, c: key("c", shadeOf(base, "l")) });
      else if (f === "down") ops.push({ op: "rect", x: r.x, y: r.y, w: r.w, h: r.h, c: key("c", shadeOf(fadeTo ?? base, "d")) });
      else if (!fadeTo || r.h < 2) ops.push({ op: "rect", x: r.x, y: r.y, w: r.w, h: r.h, c: key("c", base) });
      else {
        // stepped fade: at most 4 bands (flat areas, no smooth gradient banding)
        const bands = Math.min(4, r.h);
        for (let i = 0; i < bands; i++) {
          const y0 = r.y + Math.floor((i * r.h) / bands), y1 = r.y + Math.floor(((i + 1) * r.h) / bands);
          ops.push({ op: "rect", x: r.x, y: y0, w: r.w, h: y1 - y0, c: key("c", mix(base, fadeTo, bands === 1 ? 0 : i / (bands - 1))) });
        }
      }
      // rim: bottom and side edges one shade darker on side faces (reads as a crisp edge at a distance)
      if ((f === "north" || f === "south" || f === "east" || f === "west") && r.w >= 3 && r.h >= 3) {
        const rim = key("c", shadeOf(fadeTo ?? base, "d"));
        ops.push({ op: "rect", x: r.x, y: r.y + r.h - 1, w: r.w, h: 1, c: rim });
      }
      for (const d of cube.decals?.[f] ?? []) {
        const c = key("c", P[d.c]);
        if (d.op === "px") ops.push({ op: "px", x: r.x + d.x, y: r.y + d.y, c });
        else if (d.op === "rect") ops.push({ op: "rect", x: r.x + d.x, y: r.y + d.y, w: d.w, h: d.h, c });
        else ops.push({ op: "line", x1: r.x + d.x1, y1: r.y + d.y1, x2: r.x + d.x2, y2: r.y + d.y2, c });
      }
    }
  }
  return { name: spec.name, size: layout.size, palette: Object.fromEntries(Object.entries(palette).sort(([a], [b]) => (a < b ? -1 : 1))), ops };
}

// ------------------------------------------------------------------------------------------------- bbmodel ----
/** Deterministic UUID-shaped id from a seed (sha256, version nibble 5, RFC 4122 variant). */
export function stableUuid(seed: string): string {
  const h = createHash("sha256").update(seed).digest("hex").slice(0, 32).split("");
  h[12] = "5";
  h[16] = ((parseInt(h[16], 16) & 0x3) | 0x8).toString(16);
  const s = h.join("");
  return `${s.slice(0, 8)}-${s.slice(8, 12)}-${s.slice(12, 16)}-${s.slice(16, 20)}-${s.slice(20, 32)}`;
}

/** Bone name as BetterModel reads it: its tag prefixes (hi_ = head with children, glow_ = full-bright). */
export const bbBoneName = (b: Bone) => (b.tag === "head" ? `hi_${b.name}` : b.tag === "glow" ? `glow_${b.name}` : b.name);

const smooth = (t: number) => t * t * (3 - 2 * t);
/** Sample a track at clip time `time` (seconds). Rotation/position are offsets from rest; scale is a factor. */
export function sampleTrack(t: Track, clip: Clip, time: number): [number, number, number] {
  const base = t.channel === "scale" ? 1 : 0;
  if (t.wave) {
    const w = t.wave;
    const a = 2 * Math.PI * ((time / clip.length) * w.cycles + w.phase);
    return [0, 1, 2].map((k) => base + (w.offset?.[k] ?? 0) + w.amp[k] * Math.sin(a)) as [number, number, number];
  }
  const ks = t.keys!;
  const u = Math.max(0, Math.min(1, time / clip.length));
  let i = 0;
  while (i < ks.length - 2 && u > ks[i + 1].t) i++;
  const a = ks[i], b = ks[i + 1];
  const f = b.t === a.t ? 1 : Math.max(0, Math.min(1, (u - a.t) / (b.t - a.t)));
  const e = b.ease === "linear" ? f : smooth(f);
  return [0, 1, 2].map((k) => a.v[k] + (b.v[k] - a.v[k]) * e) as [number, number, number];
}

type Keyframe = { channel: string; data_points: { x: number; y: number; z: number }[]; uuid: string; time: number; color: number; interpolation: string };

/** Bake one track to Blockbench keyframes: waves at 8 samples per cycle (catmull-rom), key tracks as written. */
function bakeTrack(t: Track, clip: Clip, scale: number, seed: string): Keyframe[] {
  const out: Keyframe[] = [];
  const mul = t.channel === "position" ? scale : 1;
  const push = (time: number, v: number[], interp: string) => out.push({
    channel: t.channel, data_points: [{ x: r4(v[0] * mul), y: r4(v[1] * mul), z: r4(v[2] * mul) }],
    uuid: stableUuid(`${seed}:${t.bone}:${t.channel}:${out.length}`), time: r4(time), color: -1, interpolation: interp,
  });
  if (t.wave) {
    const n = 8 * t.wave.cycles;
    for (let i = 0; i <= n; i++) {
      const time = (i * clip.length) / n;
      push(time, i === n ? sampleTrack(t, clip, 0) : sampleTrack(t, clip, time), "catmullrom");
    }
  } else {
    for (const k of t.keys!) push(k.t * clip.length, k.v, k.ease === "linear" ? "linear" : "catmullrom");
  }
  return out;
}

export type CompiledCreature = {
  key: string;
  compiler: string;
  bbmodel: string;
  bbmodelSha256: string;
  png: Buffer;
  pngSha256: string;
  skin: TextureSpec;
  layout: SkinLayout;
  raster: Raster;
  stats: { bones: number; cubes: number; clips: number; keyframes: number; skinSize: number; bytes: number };
};
export type CompileResult = { ok: true; creature: CompiledCreature } | { ok: false; error: string };

const sha256 = (b: Buffer | string) => createHash("sha256").update(b).digest("hex");

/** RigSpec (already validated by checkRigSpec) -> .bbmodel + skin PNG. */
export function compileCreature(spec: RigSpec, namespace: string): CompileResult {
  const lay = layoutSkin(spec);
  if (!lay.ok) return lay;
  const layout = lay.layout;
  const skin = skinTextureSpec(spec, layout);
  const sc = checkSpec(skin, { profile: "skin" });
  if (!sc.ok) return { ok: false, error: `internal skin spec rejected: ${sc.error}` };
  const raster = render(sc.spec);
  const png = encodePng(raster);
  const key = modelKey(namespace, spec.name);
  const seed = `${COMPILER_VERSION}:${key}`;
  const s = spec.scale;
  const S = (v: number[]) => v.map((x) => r4(x * s));
  const boneUuid = new Map(spec.bones.map((b) => [b.name, stableUuid(`${seed}:bone:${b.name}`)]));

  const elements: Record<string, unknown>[] = [];
  const cubeUuids = new Map<string, string[]>();
  for (const cl of layout.cubes) {
    const bone = spec.bones.find((b) => b.name === cl.bone)!;
    const c: Cube = bone.cubes[cl.index];
    const uuid = stableUuid(`${seed}:cube:${cl.bone}:${cl.index}`);
    cubeUuids.set(cl.bone, [...(cubeUuids.get(cl.bone) ?? []), uuid]);
    const faces: Record<string, unknown> = {};
    for (const f of FACES) {
      const r = cl.faces[f];
      faces[f] = { uv: [r.x, r.y, r.x + r.w, r.y + r.h], texture: 0 };
    }
    elements.push({
      name: `${cl.bone}_${cl.index}`, box_uv: false, render_order: "default", locked: false, allow_mirror_modeling: true,
      from: S(c.from), to: S(c.to), autouv: 0, color: cl.index % 8, origin: S(bone.pivot), ...(c.inflate ? { inflate: r4(c.inflate * s) } : {}),
      ...(bone.tag === "glow" ? { light_emission: 15 } : {}),
      faces, type: "cube", uuid,
    });
  }
  const groups = spec.bones.map((b) => ({
    uuid: boneUuid.get(b.name)!, export: true, locked: false, origin: S(b.pivot), rotation: (b.rotation ?? [0, 0, 0]).map(r4), color: 0,
    name: bbBoneName(b), children: [], reset: false, shade: true, mirror_uv: false, selected: false, visibility: true, autouv: 0, isOpen: true,
  }));
  const tree = (name: string): Record<string, unknown> => ({
    uuid: boneUuid.get(name)!, isOpen: true,
    children: [...(cubeUuids.get(name) ?? []), ...spec.bones.filter((b) => b.parent === name).map((b) => tree(b.name))],
  });
  const root = spec.bones.find((b) => b.parent === null)!;
  let keyframes = 0;
  const animations = Object.entries(spec.animations).map(([name, clip]) => {
    const animators: Record<string, unknown> = {};
    for (const t of clip.tracks) {
      const b = spec.bones.find((x) => x.name === t.bone)!;
      const id = boneUuid.get(t.bone)!;
      const kf = bakeTrack(t, clip, s, `${seed}:anim:${name}`);
      keyframes += kf.length;
      const prev = animators[id] as { keyframes: Keyframe[] } | undefined;
      if (prev) prev.keyframes.push(...kf);
      else animators[id] = { name: bbBoneName(b), type: "bone", rotation_global: false, quaternion_interpolation: false, keyframes: kf };
    }
    return {
      uuid: stableUuid(`${seed}:clip:${name}`), name, loop: clip.loop ? "loop" : name === "death" ? "hold" : "once", override: false,
      length: r4(clip.length), snapping: 20, selected: false, anim_time_update: "", blend_weight: "", start_delay: "", loop_delay: "", animators,
    };
  });
  const model = {
    meta: { format_version: BBMODEL_FORMAT, model_format: "free", box_uv: false },
    name: key, model_identifier: "", visible_box: [1, 1, 0], variable_placeholders: "", variable_placeholder_buttons: [], timeline_setups: [], unhandled_root_fields: {},
    resolution: { width: layout.size, height: layout.size },
    elements, groups, outliner: [tree(root.name)],
    textures: [{
      path: "", name: `${key}.png`, folder: "", namespace: "", id: "0", group: "", width: layout.size, height: layout.size, uv_width: layout.size, uv_height: layout.size,
      particle: false, use_as_default: false, layers_enabled: false, sync_to_project: "", render_mode: "default", render_sides: "auto", pbr_channel: "color",
      frame_time: 1, frame_order_type: "loop", frame_order: "", frame_interpolate: false, visible: true, internal: true, saved: false,
      uuid: stableUuid(`${seed}:texture`), source: `data:image/png;base64,${png.toString("base64")}`,
    }],
    animations,
  };
  const bbmodel = JSON.stringify(model);
  return {
    ok: true,
    creature: {
      key, compiler: COMPILER_VERSION, bbmodel, bbmodelSha256: sha256(bbmodel), png, pngSha256: sha256(png), skin: sc.spec, layout, raster,
      stats: { bones: spec.bones.length, cubes: elements.length, clips: animations.length, keyframes, skinSize: layout.size, bytes: Buffer.byteLength(bbmodel) },
    },
  };
}

export { faceSize };

// RigSpec v1 (Cyrus R3 creature pipeline): what the build model writes in assets/creatures/<name>.json and what Nxeon's
// compiler (./compile.ts) turns into a Blockbench .bbmodel for the Nxeon-managed BetterModel plugin, a skin PNG and
// baked keyframe animations. The model never writes .bbmodel JSON, UUIDs, UV rectangles or keyframe maths itself.
// Pure + client-safe (Zod + plain TS). The build service's copy (services/modbuilder/creature-spec.js) is GENERATED
// from this file by scripts/cyrus/build-creature-artifacts.ts; test/cyrus-creature.test.ts checks it is current and
// gives the same answer on every fixture. The JSON Schema contract is ./rigspec.v1.schema.json (same script).
//
// Two forms, one schema:
//   template form  { version, name, archetype, template: { features?, height? }, skin: { palette }, sounds, ... }
//                  -> bones + animations come from Nxeon's archetype template (./templates.ts): the reliable path.
//   explicit form  { version, name, archetype, bones: [...], animations: {...}, skin, sounds, ... }
//                  -> for shapes no template covers (still validated against every limit below).
// Coordinates are Blockbench units (16 = one block), absolute (like Blockbench), y up, the creature faces north (-z).
import * as z from "zod/mini";
import { expandTemplate, TEMPLATE_ARCHETYPES, TEMPLATE_FEATURES, TEMPLATE_PALETTE_KEYS } from "./templates";

export const RIG_SPEC_VERSION = 1 as const;
export const ARCHETYPES = ["humanoid", "quadruped", "flyer", "floating_ghost"] as const;
export type Archetype = (typeof ARCHETYPES)[number];
export const REQUIRED_CLIPS = ["idle", "walk", "attack", "hurt", "death"] as const;
export const LOOPING_CLIPS = ["idle", "walk"] as const;
export const FACES = ["north", "east", "south", "west", "up", "down"] as const;
export type Face = (typeof FACES)[number];
export const CHANNELS = ["rotation", "position", "scale"] as const;
export const BONE_TAGS = ["none", "head", "glow"] as const;
/** Vanilla base mobs a creature may ride on (invisible + silent; it provides the hitbox, AI and attributes). */
export const BASE_ENTITIES = ["ZOMBIE", "HUSK", "SKELETON", "STRAY", "VEX", "ALLAY", "WOLF", "PIG", "COW", "SHEEP", "SPIDER", "PHANTOM", "BLAZE", "IRON_GOLEM", "PILLAGER", "WITCH", "CREEPER", "HORSE"] as const;
export const SOUND_ROLES = ["ambient", "hurt", "death", "attack", "step", "spawn"] as const;

// Cost guards (display entities: every bone is one item_display per viewer; every clip is baked into the pack).
export const MAX_BONES = 32;
export const MAX_CUBES = 64;
export const MAX_CUBES_PER_BONE = 12;
export const MAX_DEPTH = 6;
export const MAX_CLIPS = 8;
export const MAX_TRACKS_PER_CLIP = 32;
export const MAX_KEYS_PER_TRACK = 12;
export const MAX_DECALS_PER_FACE = 24;
export const MAX_DECALS_TOTAL = 160;
export const MAX_PALETTE = 16;
export const MAX_COORD = 64;
export const MAX_CREATURES = 4;
export const MAX_RIG_SPEC_BYTES = 48 * 1024;
export const SKIN_SIZES = [64, 128] as const;

export const NAME_RE = /^[a-z][a-z0-9_]{1,31}$/;
export const BONE_RE = /^[a-z][a-z0-9_]{0,23}$/;
export const PALETTE_KEY_RE = /^[a-z][a-z0-9_]{0,15}$/;
export const SOUND_KEY_RE = /^(nx_[a-z0-9]{8}):([a-z][a-z0-9_]{1,31})\.([a-z][a-z0-9_]{0,23})$/;

// zod/mini (not the classic API): the same validator is bundled into the build service, and mini tree-shakes to ~20 KB.
const num = (lo: number, hi: number) => z.number().check(z.minimum(lo), z.maximum(hi));
const int = (lo: number, hi: number) => z.int().check(z.minimum(lo), z.maximum(hi));
const re = (r: RegExp, msg?: string) => z.string().check(z.regex(r, msg));
const def = <T extends z.ZodMiniType>(t: T, v: z.output<T>) => z._default(t, v as never);
const Vec3 = z.tuple([num(-MAX_COORD, MAX_COORD), num(-MAX_COORD, MAX_COORD), num(-MAX_COORD, MAX_COORD)]);
const AngleVec = z.tuple([num(-360, 360), num(-360, 360), num(-360, 360)]);
const Ampl = z.tuple([num(-180, 180), num(-180, 180), num(-180, 180)]);
const paletteKey = re(PALETTE_KEY_RE);
const px = int(0, 127);

const DecalZ = z.discriminatedUnion("op", [
  z.strictObject({ op: z.literal("px"), x: px, y: px, c: paletteKey }),
  z.strictObject({ op: z.literal("rect"), x: px, y: px, w: int(1, 128), h: int(1, 128), c: paletteKey }),
  z.strictObject({ op: z.literal("line"), x1: px, y1: px, x2: px, y2: px, c: paletteKey }),
]);
export type Decal = z.output<typeof DecalZ>;

const CubeZ = z.strictObject({
  from: Vec3,
  to: Vec3,
  /** Palette key of the base colour. Nxeon derives the light/shadow shades itself. */
  material: paletteKey,
  /** solid (default) or fade: a stepped vertical ramp from `material` (top) to `fadeTo` (bottom) on the side faces. */
  shade: def(z.enum(["solid", "fade"]), "solid"),
  fadeTo: z.optional(paletteKey),
  /** Grow the cube by this many units on every side (outer layers like hoods); the texture keeps the base size. */
  inflate: def(num(0, 1), 0),
  /** Small pixel details per face, in face-local pixels (0,0 = top-left of that face as seen from outside). */
  decals: z.optional(z.partialRecord(z.enum(FACES), z.array(DecalZ).check(z.maxLength(MAX_DECALS_PER_FACE)))),
});
export type Cube = z.output<typeof CubeZ>;

const BoneZ = z.strictObject({
  name: re(BONE_RE, "bone names are 1-24 lowercase letters, digits and underscores"),
  parent: z.nullable(re(BONE_RE)),
  pivot: Vec3,
  rotation: z.optional(AngleVec),
  /** head: follows where the mob looks (BetterModel "hi_" tag); glow: always full-bright (eyes, runes). */
  tag: def(z.enum(BONE_TAGS), "none"),
  cubes: def(z.array(CubeZ).check(z.maxLength(MAX_CUBES_PER_BONE)), []),
});
export type Bone = z.output<typeof BoneZ>;

const WaveZ = z.strictObject({
  /** Amplitude per axis (degrees for rotation, units for position, factor for scale). */
  amp: Ampl,
  offset: z.optional(Ampl),
  /** Whole sine cycles over the clip (whole numbers so a loop is seamless). */
  cycles: def(int(1, 8), 1),
  /** Where in the cycle the clip starts, 0-1 (0.5 = opposite phase, e.g. the other leg). */
  phase: def(num(0, 1), 0),
});

const KeyZ = z.strictObject({
  /** Time as a fraction of the clip, 0-1. */
  t: num(0, 1),
  v: AngleVec,
  ease: def(z.enum(["linear", "smooth"]), "smooth"),
});

const TrackZ = z.strictObject({
  bone: re(BONE_RE),
  channel: z.enum(CHANNELS),
  wave: z.optional(WaveZ),
  keys: z.optional(z.array(KeyZ).check(z.minLength(2), z.maxLength(MAX_KEYS_PER_TRACK))),
});
export type Track = z.output<typeof TrackZ>;

const ClipZ = z.strictObject({
  length: num(0.1, 10),
  loop: z.boolean(),
  tracks: z.array(TrackZ).check(z.minLength(1), z.maxLength(MAX_TRACKS_PER_CLIP)),
});
export type Clip = z.output<typeof ClipZ>;

const TemplateZ = z.strictObject({
  /** Optional parts the archetype template knows (see TEMPLATE_FEATURES). */
  features: def(z.array(re(/^[a-z][a-z_]{1,23}$/)).check(z.maxLength(6)), []),
  /** Height multiplier for the template body (1 = default). */
  height: def(num(0.7, 1.5), 1),
});

export const RigSpecV1Schema = z.strictObject({
  version: z.literal(RIG_SPEC_VERSION),
  name: re(NAME_RE, "name is 2-32 lowercase letters, digits and underscores, starting with a letter"),
  displayName: z.optional(z.string().check(z.trim(), z.minLength(2), z.maxLength(40))),
  archetype: z.enum(ARCHETYPES),
  template: z.optional(TemplateZ),
  /** Uniform model scale (1 = Blockbench units as written). */
  scale: def(num(0.4, 3), 1),
  /** The invisible vanilla base mob's box, in blocks (BetterModel draws the model, the base mob is what gets hit). */
  hitbox: z.strictObject({ width: num(0.3, 3), height: num(0.3, 4) }),
  baseEntity: z.enum(BASE_ENTITIES),
  skin: z.strictObject({
    /** 64 or 128 px square sheet; omitted = the smallest that fits the cubes. */
    size: z.optional(z.union([z.literal(64), z.literal(128)])),
    palette: z.record(paletteKey, re(/^#[0-9a-fA-F]{6}$/)),
  }),
  bones: z.optional(z.array(BoneZ).check(z.maxLength(MAX_BONES))),
  animations: z.optional(z.record(re(/^[a-z][a-z0-9_]{1,23}$/), ClipZ)),
  /** Sound-slice keys "<namespace>:<set>.<event>" the plugin plays for this creature (base mob is silenced). */
  sounds: def(z.partialRecord(z.enum(SOUND_ROLES), re(SOUND_KEY_RE, "sound keys are <namespace>:<set>.<event>")), {}),
});

export type RigSpecInput = z.input<typeof RigSpecV1Schema>;
type Parsed = z.output<typeof RigSpecV1Schema>;
/** A validated, EXPANDED RigSpec: bones and every clip are always present (template form resolved). */
export type RigSpec = Omit<Parsed, "bones" | "animations"> & { bones: Bone[]; animations: Record<string, Clip>; skin: { size: 64 | 128 | undefined; palette: Record<string, string> } };

export type RigIssue = { path: string; message: string };
export type RigCheck =
  | { ok: true; spec: RigSpec; warnings: string[]; stats: RigStats }
  | { ok: false; error: string; errors: RigIssue[] };
export type RigStats = { bones: number; cubes: number; clips: number; tracks: number; decals: number; height: number };

/** JSON Schema (draft 2020-12) of what a producer writes (defaults optional). */
export function rigSpecJsonSchema(): Record<string, unknown> {
  return z.toJSONSchema(RigSpecV1Schema, { io: "input" }) as Record<string, unknown>;
}

const dims = (c: { from: number[]; to: number[] }) => [0, 1, 2].map((i) => c.to[i] - c.from[i]);
/** Texture footprint of a cube face in pixels (the compiler uses exactly this; decals are checked against it). */
export function faceSize(c: { from: number[]; to: number[] }, face: Face): [number, number] {
  const [w, h, d] = dims(c).map((v) => Math.max(1, Math.ceil(v - 1e-9)));
  if (face === "north" || face === "south") return [w, h];
  if (face === "east" || face === "west") return [d, h];
  return [w, d];
}

function decalBox(d: Decal): [number, number, number, number] {
  if (d.op === "px") return [d.x, d.y, d.x, d.y];
  if (d.op === "rect") return [d.x, d.y, d.x + d.w - 1, d.y + d.h - 1];
  return [Math.min(d.x1, d.x2), Math.min(d.y1, d.y2), Math.max(d.x1, d.x2), Math.max(d.y1, d.y2)];
}

/**
 * Validate untrusted JSON into an expanded RigSpec. Never throws. `namespace`, when given, must own every sound key.
 * Errors come back as a list plus `error` = the first one (what the build model is shown).
 */
export function checkRigSpec(raw: unknown, ctx: { namespace?: string } = {}): RigCheck {
  const fail = (errors: RigIssue[]): RigCheck => ({ ok: false, error: errors.map((e) => (e.path ? `${e.path}: ${e.message}` : e.message))[0] ?? "invalid", errors: errors.slice(0, 20) });
  const p = RigSpecV1Schema.safeParse(raw);
  if (!p.success) return fail(p.error.issues.map((i) => ({ path: i.path.map(String).join("."), message: i.message })));
  const s = p.data;
  const errors: RigIssue[] = [];
  const warnings: string[] = [];
  const err = (path: string, message: string) => errors.push({ path, message });

  // palette
  const pal = Object.keys(s.skin.palette);
  if (pal.length < 2 || pal.length > MAX_PALETTE) err("skin.palette", `needs 2-${MAX_PALETTE} colours`);

  // template form vs explicit form
  let bones: Bone[];
  let animations: Record<string, Clip>;
  if (s.template) {
    if (s.bones || s.animations) return fail([{ path: "template", message: "use either template or bones + animations, not both" }]);
    if (!(TEMPLATE_ARCHETYPES as readonly string[]).includes(s.archetype)) return fail([{ path: "archetype", message: `no template for ${s.archetype}; templates exist for ${TEMPLATE_ARCHETYPES.join(", ")} (write bones + animations instead)` }]);
    const known = TEMPLATE_FEATURES[s.archetype as (typeof TEMPLATE_ARCHETYPES)[number]];
    for (const f of s.template.features) if (!known.includes(f)) err("template.features", `unknown feature ${f} for ${s.archetype} (known: ${known.join(", ")})`);
    for (const k of TEMPLATE_PALETTE_KEYS[s.archetype as (typeof TEMPLATE_ARCHETYPES)[number]]) if (!(k in s.skin.palette)) err("skin.palette", `the ${s.archetype} template needs the colour "${k}" (needs: ${TEMPLATE_PALETTE_KEYS[s.archetype as (typeof TEMPLATE_ARCHETYPES)[number]].join(", ")})`);
    if (errors.length) return fail(errors);
    const t = expandTemplate(s.archetype as (typeof TEMPLATE_ARCHETYPES)[number], s.template);
    bones = t.bones.map((b) => BoneZ.parse(b));
    animations = Object.fromEntries(Object.entries(t.animations).map(([k, v]) => [k, ClipZ.parse(v)]));
  } else {
    if (!s.bones || !s.animations) return fail([{ path: "", message: "give template (recommended) or both bones and animations" }]);
    bones = s.bones;
    animations = s.animations;
  }

  // bones: unique, one root, parents exist, acyclic, depth
  const byName = new Map<string, Bone>();
  for (const [i, b] of bones.entries()) {
    if (byName.has(b.name)) err(`bones.${i}.name`, `duplicate bone ${b.name}`);
    byName.set(b.name, b);
  }
  if (!bones.length) err("bones", "needs at least one bone");
  const roots = bones.filter((b) => b.parent === null);
  if (roots.length !== 1) err("bones", `needs exactly one root bone (parent null), found ${roots.length}`);
  for (const [i, b] of bones.entries()) {
    if (b.parent !== null && !byName.has(b.parent)) err(`bones.${i}.parent`, `unknown parent ${b.parent}`);
    let depth = 0, cur: Bone | undefined = b;
    const seen = new Set<string>();
    while (cur && cur.parent !== null) {
      if (seen.has(cur.name)) { err(`bones.${i}`, `bone ${b.name} is part of a parent cycle`); break; }
      seen.add(cur.name);
      cur = byName.get(cur.parent);
      depth++;
    }
    if (depth > MAX_DEPTH) err(`bones.${i}`, `bone ${b.name} is nested ${depth} deep; the limit is ${MAX_DEPTH}`);
  }

  // cubes + decals
  let cubes = 0, decals = 0, minY = Infinity, maxY = -Infinity;
  const usedTags = { head: 0, glow: 0 };
  for (const [i, b] of bones.entries()) {
    if (b.tag === "head") usedTags.head++;
    for (const [j, c] of b.cubes.entries()) {
      cubes++;
      const at = `bones.${i}.cubes.${j}`;
      const d = dims(c);
      if (d.some((v) => v < 0.2)) err(at, "every cube side must be at least 0.2 units (to > from)");
      if (d.some((v) => v > 48)) err(at, "a cube side may be at most 48 units");
      if (!(c.material in s.skin.palette)) err(`${at}.material`, `unknown palette colour ${c.material}`);
      if (c.shade === "fade" && !(c.fadeTo && c.fadeTo in s.skin.palette)) err(`${at}.fadeTo`, "shade fade needs fadeTo, a palette colour");
      if (c.fadeTo && !(c.fadeTo in s.skin.palette)) err(`${at}.fadeTo`, `unknown palette colour ${c.fadeTo}`);
      minY = Math.min(minY, c.from[1] - c.inflate); maxY = Math.max(maxY, c.to[1] + c.inflate);
      for (const face of FACES) {
        const list = c.decals?.[face] ?? [];
        decals += list.length;
        const [fw, fh] = faceSize(c, face);
        for (const [k, dc] of list.entries()) {
          if (!(dc.c in s.skin.palette)) err(`${at}.decals.${face}.${k}`, `unknown palette colour ${dc.c}`);
          const [x0, y0, x1, y1] = decalBox(dc);
          if (x0 < 0 || y0 < 0 || x1 >= fw || y1 >= fh) err(`${at}.decals.${face}.${k}`, `outside the ${face} face (${fw}x${fh} px)`);
        }
      }
    }
  }
  if (usedTags.head > 1) err("bones", "only one bone may have tag head");
  if (cubes > MAX_CUBES) err("bones", `${cubes} cubes; the limit is ${MAX_CUBES}`);
  if (!cubes) err("bones", "the creature has no cubes");
  if (decals > MAX_DECALS_TOTAL) err("bones", `${decals} decals; the limit is ${MAX_DECALS_TOTAL}`);

  // animations
  const clipNames = Object.keys(animations);
  for (const c of REQUIRED_CLIPS) if (!(c in animations)) err("animations", `missing the ${c} clip (required: ${REQUIRED_CLIPS.join(", ")})`);
  if (clipNames.length > MAX_CLIPS) err("animations", `${clipNames.length} clips; the limit is ${MAX_CLIPS}`);
  let tracks = 0;
  for (const [name, clip] of Object.entries(animations)) {
    const at = `animations.${name}`;
    if ((LOOPING_CLIPS as readonly string[]).includes(name) && !clip.loop) err(`${at}.loop`, `${name} must loop`);
    if (name === "death" || name === "attack" || name === "hurt") { if (clip.loop) err(`${at}.loop`, `${name} plays once (loop false)`); }
    const seen = new Set<string>();
    for (const [i, t] of clip.tracks.entries()) {
      tracks++;
      const ta = `${at}.tracks.${i}`;
      if (!byName.has(t.bone)) err(`${ta}.bone`, `unknown bone ${t.bone}`);
      const key = `${t.bone}/${t.channel}`;
      if (seen.has(key)) err(ta, `two tracks animate ${key}`);
      seen.add(key);
      if (!!t.wave === !!t.keys) { err(ta, "a track needs exactly one of wave or keys"); continue; }
      const lim = t.channel === "rotation" ? 360 : t.channel === "position" ? 32 : 4;
      if (t.wave) {
        const mx = [0, 1, 2].map((k) => Math.abs((t.wave!.offset?.[k] ?? 0)) + Math.abs(t.wave!.amp[k]));
        if (mx.some((v) => v > lim)) err(`${ta}.wave`, `${t.channel} values must stay within ${lim}`);
        if (t.channel === "scale" && [0, 1, 2].some((k) => 1 + (t.wave!.offset?.[k] ?? 0) - Math.abs(t.wave!.amp[k]) < 0)) err(`${ta}.wave`, "scale may not go below 0");
      } else {
        const ks = t.keys!;
        if (ks[0].t !== 0 || ks[ks.length - 1].t !== 1) err(`${ta}.keys`, "keys must start at t 0 and end at t 1");
        for (let k = 1; k < ks.length; k++) if (!(ks[k].t > ks[k - 1].t)) err(`${ta}.keys.${k}.t`, "key times must increase");
        for (const [k, kv] of ks.entries()) {
          if (kv.v.some((v) => Math.abs(v) > lim)) err(`${ta}.keys.${k}.v`, `${t.channel} values must stay within ${lim}`);
          if (t.channel === "scale" && kv.v.some((v) => v < 0)) err(`${ta}.keys.${k}.v`, "scale may not be negative");
        }
        if (clip.loop && ks.length >= 2 && ks[0].v.some((v, k) => Math.abs(v - ks[ks.length - 1].v[k]) > 1e-6)) err(`${ta}.keys`, "a looping clip must end where it starts (first and last key equal)");
      }
    }
  }

  // sounds
  for (const [role, key] of Object.entries(s.sounds)) {
    const m = SOUND_KEY_RE.exec(key!);
    if (m && ctx.namespace && m[1] !== ctx.namespace) err(`sounds.${role}`, `uses the namespace ${m[1]}; this mod's reserved namespace is ${ctx.namespace}`);
  }

  if (errors.length) return fail(errors);

  // soft facts (never block)
  const height = Math.round((maxY - Math.min(0, minY)) * s.scale * 100) / 100;
  const modelBlocks = height / 16;
  if (s.hitbox.height > modelBlocks * 1.6 + 0.2 || s.hitbox.height < modelBlocks * 0.4) warnings.push(`hitbox height ${s.hitbox.height} blocks does not match the model (about ${modelBlocks.toFixed(2)} blocks tall)`);
  if (!usedTags.head) warnings.push("no bone has tag head, so the model will not look where the mob looks");
  for (const r of ["hurt", "death", "attack"] as const) if (!s.sounds[r]) warnings.push(`no ${r} sound: the creature is silent when it ${r === "attack" ? "attacks" : r === "hurt" ? "is hurt" : "dies"} (the base mob is silenced)`);

  const spec: RigSpec = { ...s, bones, animations, skin: { size: s.skin.size, palette: Object.fromEntries(Object.entries(s.skin.palette).map(([k, v]) => [k, v.toLowerCase()])) } };
  // The expanded spec is fully explicit (and validates to itself): the template choice is not kept in it.
  delete (spec as { template?: unknown }).template;
  return { ok: true, spec, warnings, stats: { bones: bones.length, cubes, clips: clipNames.length, tracks, decals, height } };
}

/** The BetterModel model key for a creature: `<namespace>_<name>` (file plugins/BetterModel/models/<key>.bbmodel). */
export const modelKey = (namespace: string, name: string) => `${namespace}_${name}`;

// Cyrus engine core: the plan-tier gate for custom assets (MASTER-PLAN section 2, owner decisions).
//   free, katara -> no asset studios, no asset generation
//   saka         -> SOUND (Sound Studio + Sound Library)
//   all          -> SOUND + TEXTURE (the top plan; it includes the Yakko model)
// Tiers are cumulative. The gate applies only to CREATING or EDITING asset content (a studio, a library pick, an
// upload, or Cyrus generating it automatically inside a build). Keeping, installing, rebuilding unchanged,
// exporting, importing your own mod and composing Mod Packs are NEVER gated. An unknown plan or token state
// denies creation (fail closed) but never denies keep/install/export.
// Pure + client-safe; the server must call it again on every request (the UI check is only a hint).
import type { AssetKind, AssetSource, ModSpec } from "./spec";
import { ASSET_KINDS } from "./spec";

export const ASSET_PLANS = ["free", "katara", "saka", "all"] as const;
export type AssetPlan = (typeof ASSET_PLANS)[number];
const RANK: Record<AssetPlan, number> = { free: 0, katara: 1, saka: 2, all: 3 };
export const PLAN_LABEL: Record<AssetPlan, string> = { free: "Free", katara: "Katara", saka: "Saka", all: "All models" };

/**
 * THE one place that reconciles plan spellings. The token economy calls the top plan `all`
 * (lib/cyrus/tokens/config.ts TOKEN_TIERS); the UI and the model list call it after its top model, Yakko.
 * Anything else (null, a typo, a future plan) is unknown -> null, and callers fail closed.
 */
export function normalizePlan(raw: unknown): AssetPlan | null {
  if (typeof raw !== "string") return null;
  const v = raw.trim().toLowerCase();
  if (v === "all" || v === "yakko" || v === "all models") return "all";
  if (v === "free" || v === "katara" || v === "saka") return v;
  return null;
}

/** Plan from a token state (lib/cyrus/tokens/view.ts TokenState) or anything with a `tier`. Missing state -> null (unknown). */
export const planFromTokenState = (state: { tier?: unknown } | null | undefined): AssetPlan | null => normalizePlan(state?.tier);

/**
 * Cheapest plan that may create/edit each kind. `model` and `ui` are visual assets drawn with the texture tools,
 * so they follow the Texture Studio (top plan).
 */
export const ASSET_MIN_PLAN: Readonly<Record<AssetKind, AssetPlan>> = { sound: "saka", texture: "all", model: "all", ui: "all" };

export const ASSET_OPS = ["create", "edit", "keep", "install", "export", "rebuild", "import", "compose"] as const;
export type AssetOp = (typeof ASSET_OPS)[number];
export const GATED_OPS: readonly AssetOp[] = ["create", "edit"];

export type AssetDecision =
  | { ok: true }
  | { ok: false; code: "asset_locked" | "plan_unknown" | "bad_request"; reason: string; needs?: AssetPlan };

const KIND_WORD: Record<AssetKind, string> = { sound: "custom sounds", texture: "custom textures", model: "custom models", ui: "custom menu and HUD art" };

export function canAsset(plan: unknown, kind: AssetKind, op: AssetOp): AssetDecision {
  if (!(ASSET_OPS as readonly string[]).includes(op)) return { ok: false, code: "bad_request", reason: `unknown asset operation ${String(op)}` };
  if (!GATED_OPS.includes(op)) return { ok: true }; // keep / install / export / rebuild / import / compose: never gated
  if (!(ASSET_KINDS as readonly string[]).includes(kind)) return { ok: false, code: "bad_request", reason: `unknown asset kind ${String(kind)}` };
  const needs = ASSET_MIN_PLAN[kind];
  const p = normalizePlan(plan);
  if (!p) return { ok: false, code: "plan_unknown", needs, reason: `We couldn't confirm your Cyrus plan, so ${KIND_WORD[kind]} can't be created or edited right now.` };
  if (RANK[p] < RANK[needs]) return { ok: false, code: "asset_locked", needs, reason: `Creating or editing ${KIND_WORD[kind]} needs the ${PLAN_LABEL[needs]} plan or higher.` };
  return { ok: true };
}

/** What a spec asset slot asks the engine to do with asset content. */
export function assetOpForSource(source: AssetSource): AssetOp {
  switch (source) {
    case "generate": case "library": case "upload": return "create";
    case "edit": return "edit";
    case "existing": return "keep";
    case "imported": return "import";
    default: return "create"; // unknown source: treat as the gated case
  }
}

export type AssetDenial = { assetId: string; kind: AssetKind; code: "asset_locked" | "plan_unknown" | "bad_request"; reason: string; needs?: AssetPlan };

/** Every asset slot of a spec the plan may not create/edit (no changes). The build service request runs this too. */
export function gateSpecAssets(spec: Pick<ModSpec, "assets">, plan: unknown): AssetDenial[] {
  const out: AssetDenial[] = [];
  for (const a of spec.assets) {
    const d = canAsset(plan, a.kind, assetOpForSource(a.source));
    if (!d.ok) out.push({ assetId: a.id, kind: a.kind, code: d.code, reason: d.reason, ...(d.needs ? { needs: d.needs } : {}) });
  }
  return out;
}

const FALLBACK: Record<AssetKind, string> = { sound: "a vanilla sound", texture: "a vanilla look", model: "a vanilla model", ui: "plain text and standard menus" };

/**
 * Router downgrade: strip the gated asset slots instead of failing the build, with a customer-visible reason
 * per slot. Requirements stay (the mod still does what was asked, without the custom asset). Pure: returns a copy.
 */
export function downgradeSpecAssets<S extends Pick<ModSpec, "assets">>(spec: S, plan: unknown): { spec: S; removed: AssetDenial[]; notices: string[] } {
  const removed = gateSpecAssets(spec, plan);
  if (!removed.length) return { spec, removed, notices: [] };
  const drop = new Set(removed.map((r) => r.assetId));
  const notices = removed.map((r) => `${r.reason} Cyrus will build "${r.assetId}" with ${FALLBACK[r.kind]} instead.`);
  return { spec: { ...spec, assets: spec.assets.filter((a) => !drop.has(a.id)) }, removed, notices };
}
// Cyrus engine core: the pure half of the revision store (file manifests, diffs, engine records).
// A revision's file manifest lists every file of the mod project at that revision as { path, sha256, role }.
// Pure + client-safe; the DB half is lib/cyrus/engine-core/store.ts.
import type { SpecIssue } from "./spec";
import { validateImportMeta, type ImportMeta } from "../import/attestation";
import { validateEngineReleaseField, type EngineRelease } from "./release";

export const REVISION_KINDS = ["generated", "edited", "imported", "asset", "revert"] as const;
export type RevisionKind = (typeof REVISION_KINDS)[number];
export const REVISION_STATUSES = ["pending", "passed", "failed"] as const;
export type RevisionStatus = (typeof REVISION_STATUSES)[number];

export const FILE_ROLES = ["source", "resource", "config", "asset", "resourcePack", "dataPack", "test", "doc", "artifact", "other"] as const;
export type FileRole = (typeof FILE_ROLES)[number];
export type ManifestEntry = { path: string; sha256: string; role: FileRole };
export const MAX_MANIFEST_FILES = 5000;

const SHA256 = /^[0-9a-f]{64}$/;

/** A safe project-relative path: forward slashes, no leading slash, no empty / "." / ".." segments, no control chars. */
export function isSafeProjectPath(p: unknown): p is string {
  if (typeof p !== "string" || p.length === 0 || p.length > 512) return false;
  if (p.startsWith("/") || p.includes("\\") || /[\u0000-\u001f]/.test(p)) return false;
  return p.split("/").every((s) => s.length > 0 && s !== "." && s !== "..");
}

export type ManifestResult = { ok: true; entries: ManifestEntry[] } | { ok: false; errors: SpecIssue[] };

/** Untrusted manifest -> entries sorted by path (a stable order, so equal manifests serialise identically). */
export function validateManifest(raw: unknown): ManifestResult {
  if (!Array.isArray(raw)) return { ok: false, errors: [{ path: "manifest", code: "not_array", message: "manifest must be an array" }] };
  if (raw.length > MAX_MANIFEST_FILES) return { ok: false, errors: [{ path: "manifest", code: "too_many_files", message: `at most ${MAX_MANIFEST_FILES} files` }] };
  const errors: SpecIssue[] = [];
  const seen = new Set<string>();
  const entries: ManifestEntry[] = [];
  raw.forEach((e, i) => {
    const at = `manifest[${i}]`;
    const r = (e ?? {}) as Record<string, unknown>;
    if (!isSafeProjectPath(r.path)) { errors.push({ path: `${at}.path`, code: "bad_path", message: "path must be a safe relative path" }); return; }
    if (typeof r.sha256 !== "string" || !SHA256.test(r.sha256)) errors.push({ path: `${at}.sha256`, code: "bad_sha256", message: "sha256 must be 64 lowercase hex characters" });
    if (!(FILE_ROLES as readonly string[]).includes(r.role as string)) errors.push({ path: `${at}.role`, code: "bad_role", message: `role must be one of ${FILE_ROLES.join(", ")}` });
    if (seen.has(r.path)) errors.push({ path: `${at}.path`, code: "duplicate_path", message: `${r.path} is listed twice` });
    seen.add(r.path);
    entries.push({ path: r.path, sha256: String(r.sha256), role: r.role as FileRole });
  });
  if (errors.length) return { ok: false, errors };
  entries.sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0));
  return { ok: true, entries };
}

export type ManifestDiff = {
  added: ManifestEntry[];
  removed: ManifestEntry[];
  changed: { path: string; from: ManifestEntry; to: ManifestEntry }[];
  unchanged: number;
};

/** Files added, removed and changed (content or role) going from `from` to `to`. Pure. */
export function diffManifests(from: readonly ManifestEntry[], to: readonly ManifestEntry[]): ManifestDiff {
  const a = new Map(from.map((e) => [e.path, e]));
  const b = new Map(to.map((e) => [e.path, e]));
  const out: ManifestDiff = { added: [], removed: [], changed: [], unchanged: 0 };
  for (const [p, e] of b) {
    const old = a.get(p);
    if (!old) out.added.push(e);
    else if (old.sha256 !== e.sha256 || old.role !== e.role) out.changed.push({ path: p, from: old, to: e });
    else out.unchanged++;
  }
  for (const [p, e] of a) if (!b.has(p)) out.removed.push(e);
  const byPath = (x: { path: string }, y: { path: string }) => (x.path < y.path ? -1 : 1);
  out.added.sort(byPath); out.removed.sort(byPath); out.changed.sort(byPath);
  return out;
}

/**
 * What produced a revision, as far as it is known (MASTER-PLAN R0 "per-build engine-release record").
 * Every field optional: record what is known, never invent a value.
 */
