// Cyrus Texture Studio: the editor's pure logic (R1b). Client-safe, unit-tested, no React.
//   - layers: locked generated base (TextureSpec) + paint layer (RGBA + erase mask) + an optional candidate
//   - tools: pencil / eraser / fill / line / rect with mirror and selection clipping
//   - history: every stroke, fill or accepted candidate is ONE step; undo / redo / jump
//   - compare: changed pixels, change regions (partial apply), apply inside a selection
//   - palette: ramps grouped from the spec palette, generated 5-shade ramps, Style DNA summary
import type { TextureSpec } from "../textures/dsl";
import { render, type Raster } from "../textures/render";
import type { QualityReport } from "../textures/quality";
import { blankRaster } from "./paint";

// ---------------------------------------------------------------------------- history

export type Step<T> = { label: string; snap: T };
export type History<T> = { steps: Step<T>[]; at: number };
export const MAX_STEPS = 200;

export const historyInit = <T>(label: string, snap: T): History<T> => ({ steps: [{ label, snap }], at: 0 });
/** Push a step after the current one (drops any redo branch). Keeps the newest MAX_STEPS. */
export function historyPush<T>(h: History<T>, label: string, snap: T, max = MAX_STEPS): History<T> {
  const steps = [...h.steps.slice(0, h.at + 1), { label, snap }];
  const drop = Math.max(0, steps.length - max);
  return { steps: steps.slice(drop), at: steps.length - 1 - drop };
}
export const canUndo = (h: History<unknown>) => h.at > 0;
export const canRedo = (h: History<unknown>) => h.at < h.steps.length - 1;
export const historyJump = <T>(h: History<T>, i: number): History<T> => ({ ...h, at: Math.max(0, Math.min(h.steps.length - 1, i)) });
export const historyUndo = <T>(h: History<T>) => historyJump(h, h.at - 1);
export const historyRedo = <T>(h: History<T>) => historyJump(h, h.at + 1);
export const current = <T>(h: History<T>) => h.steps[h.at].snap;

// ---------------------------------------------------------------------------- layers + composite

/** One editor snapshot: the base spec (null = none) and the paint layer. Treated as immutable. */
export type Layers = { spec: TextureSpec | null; size: number; paint: Uint8ClampedArray; cut: Uint8Array };
export type Visibility = { base: boolean; paint: boolean };
export const ALL_VISIBLE: Visibility = { base: true, paint: true };

const baseCache = new WeakMap<TextureSpec, Raster>();
/** Render a spec once per object (specs are immutable in the editor). */
export function baseOf(spec: TextureSpec | null, size: number): Raster {
  if (!spec) return blankRaster(size);
  let r = baseCache.get(spec);
  if (!r) { r = render(spec); baseCache.set(spec, r); }
  return r;
}

export function composite(l: Layers, vis: Visibility = ALL_VISIBLE, specOverride?: TextureSpec | null): Raster {
  const n = l.size, base = baseOf(specOverride === undefined ? l.spec : specOverride, n), out = new Uint8ClampedArray(n * n * 4);
  for (let i = 0; i < n * n; i++) {
    const o = i * 4;
    if (vis.paint && l.cut[i]) continue;
    if (vis.paint && l.paint[o + 3]) { out[o] = l.paint[o]; out[o + 1] = l.paint[o + 1]; out[o + 2] = l.paint[o + 2]; out[o + 3] = 255; continue; }
    if (vis.base) { out[o] = base.px[o]; out[o + 1] = base.px[o + 1]; out[o + 2] = base.px[o + 2]; out[o + 3] = base.px[o + 3]; }
  }
  return { size: n, px: out };
}

export const paintedPixels = (l: Layers) => { let c = 0; for (let i = 0; i < l.size * l.size; i++) if (l.paint[i * 4 + 3] || l.cut[i]) c++; return c; };

// ---------------------------------------------------------------------------- tools

export type Pt = [number, number];
export type Sel = { x: number; y: number; w: number; h: number } | null;
export const TOOLS = [
  { id: "pencil", label: "Pencil", key: "B" },
  { id: "eraser", label: "Eraser", key: "E" },
  { id: "fill", label: "Fill", key: "G" },
  { id: "picker", label: "Colour picker", key: "I" },
  { id: "select", label: "Select", key: "M" },
  { id: "line", label: "Line", key: "L" },
  { id: "rect", label: "Rectangle", key: "U" },
] as const;
export type ToolId = (typeof TOOLS)[number]["id"];
export const toolForKey = (k: string): ToolId | null => TOOLS.find((t) => t.key.toLowerCase() === k.toLowerCase())?.id ?? null;

export function linePts(a: { x: number; y: number }, b: { x: number; y: number }): Pt[] {
  const pts: Pt[] = [];
  let x0 = a.x, y0 = a.y;
  const dx = Math.abs(b.x - x0), dy = -Math.abs(b.y - y0), sx = x0 < b.x ? 1 : -1, sy = y0 < b.y ? 1 : -1;
  let err = dx + dy;
  for (let guard = 0; guard < 8192; guard++) {
    pts.push([x0, y0]);
    if (x0 === b.x && y0 === b.y) break;
    const e2 = 2 * err;
    if (e2 >= dy) { err += dy; x0 += sx; }
    if (e2 <= dx) { err += dx; y0 += sy; }
  }
  return pts;
}

export function rectPts(a: { x: number; y: number }, b: { x: number; y: number }): Pt[] {
  const pts: Pt[] = [];
  const x0 = Math.min(a.x, b.x), x1 = Math.max(a.x, b.x), y0 = Math.min(a.y, b.y), y1 = Math.max(a.y, b.y);
  for (let y = y0; y <= y1; y++) for (let x = x0; x <= x1; x++) if (y === y0 || y === y1 || x === x0 || x === x1) pts.push([x, y]);
  return pts;
}

export const inSel = (sel: Sel, x: number, y: number) => !sel || (x >= sel.x && y >= sel.y && x < sel.x + sel.w && y < sel.y + sel.h);
export const selFrom = (a: { x: number; y: number }, b: { x: number; y: number }): Sel => ({ x: Math.min(a.x, b.x), y: Math.min(a.y, b.y), w: Math.abs(b.x - a.x) + 1, h: Math.abs(b.y - a.y) + 1 });

export const hexRgb = (h: string): [number, number, number] => [parseInt(h.slice(1, 3), 16), parseInt(h.slice(3, 5), 16), parseInt(h.slice(5, 7), 16)];
export const rgbHex = (p: ArrayLike<number>, o: number) => "#" + [0, 1, 2].map((j) => p[o + j].toString(16).padStart(2, "0")).join("");

/**
 * Paint (color) or erase (null) a set of points on a COPY of the layers: mirror adds the reflected x, the selection
 * clips. Painting clears the erase mark; erasing drops the paint and marks the pixel clear (it erases the base too).
 */
export function stroke(l: Layers, pts: readonly Pt[], color: string | null, o: { mirror?: boolean; sel?: Sel } = {}): Layers {
  const n = l.size, paint = new Uint8ClampedArray(l.paint), cut = new Uint8Array(l.cut);
  const rgb = color ? hexRgb(color) : null;
  const put = (x: number, y: number) => {
    if (x < 0 || y < 0 || x >= n || y >= n || !inSel(o.sel ?? null, x, y)) return;
    const i = y * n + x, q = i * 4;
    if (rgb) { paint[q] = rgb[0]; paint[q + 1] = rgb[1]; paint[q + 2] = rgb[2]; paint[q + 3] = 255; cut[i] = 0; }
    else { paint[q] = paint[q + 1] = paint[q + 2] = paint[q + 3] = 0; cut[i] = 1; }
  };
  for (const [x, y] of pts) { put(x, y); if (o.mirror) put(n - 1 - x, y); }
  return { ...l, paint, cut };
}

/** Flood fill: the 4-connected region of the composite's colour at (x, y) (clear counts as a colour), inside the selection. */
export function floodPts(img: Raster, x: number, y: number, sel: Sel = null): Pt[] {
  const n = img.size;
  if (x < 0 || y < 0 || x >= n || y >= n) return [];
  const key = (i: number) => (img.px[i * 4 + 3] ? (img.px[i * 4] << 16) | (img.px[i * 4 + 1] << 8) | img.px[i * 4 + 2] : -1);
  const target = key(y * n + x);
  const seen = new Uint8Array(n * n), out: Pt[] = [], q: Pt[] = [[x, y]];
  while (q.length) {
    const [a, b] = q.pop()!;
    if (a < 0 || b < 0 || a >= n || b >= n) continue;
    const i = b * n + a;
    if (seen[i] || !inSel(sel, a, b)) continue;
    seen[i] = 1;
    if (key(i) !== target) continue;
    out.push([a, b]);
    q.push([a + 1, b], [a - 1, b], [a, b + 1], [a, b - 1]);
  }
  return out;
}

export function pickColor(img: Raster, x: number, y: number): string | null {
  const o = (y * img.size + x) * 4;
  return img.px[o + 3] ? rgbHex(img.px, o) : null;
}

// ---------------------------------------------------------------------------- compare + partial apply

export function changedMask(a: Raster, b: Raster): Uint8Array {
  const n = a.size, m = new Uint8Array(n * n);
  for (let i = 0; i < n * n; i++) { const o = i * 4; if (a.px[o + 3] !== b.px[o + 3] || (b.px[o + 3] && (a.px[o] !== b.px[o] || a.px[o + 1] !== b.px[o + 1] || a.px[o + 2] !== b.px[o + 2]))) m[i] = 1; }
  return m;
}

export type Region = { id: number; pixels: number[]; x: number; y: number; w: number; h: number; colors: string[]; cleared: number };
export const MAX_REGIONS = 8;

/**
 * Changed pixels grouped into 8-connected regions (biggest first): one checkbox each for a partial apply. Regions
 * past MAX_REGIONS merge into the last one so the list stays short.
 */
export function changeRegions(before: Raster, after: Raster): Region[] {
  const n = before.size, m = changedMask(before, after), seen = new Uint8Array(n * n), regions: number[][] = [];
  for (let s = 0; s < n * n; s++) {
    if (!m[s] || seen[s]) continue;
    const px: number[] = [], q = [s];
    seen[s] = 1;
    while (q.length) {
      const i = q.pop()!; px.push(i);
      const x = i % n, y = (i / n) | 0;
      for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) {
        const a = x + dx, b = y + dy;
        if ((dx || dy) && a >= 0 && b >= 0 && a < n && b < n) { const j = b * n + a; if (m[j] && !seen[j]) { seen[j] = 1; q.push(j); } }
      }
    }
    regions.push(px.sort((a, b) => a - b));
  }
  regions.sort((a, b) => b.length - a.length || a[0] - b[0]);
  if (regions.length > MAX_REGIONS) { const rest = regions.splice(MAX_REGIONS - 1).flat().sort((a, b) => a - b); regions.push(rest); }
  return regions.map((px, id) => {
    let x0 = n, y0 = n, x1 = -1, y1 = -1, cleared = 0;
    const colors = new Set<string>();
    for (const i of px) {
      const x = i % n, y = (i / n) | 0;
      x0 = Math.min(x0, x); y0 = Math.min(y0, y); x1 = Math.max(x1, x); y1 = Math.max(y1, y);
      if (after.px[i * 4 + 3]) colors.add(rgbHex(after.px, i * 4)); else cleared++;
    }
    return { id, pixels: px, x: x0, y: y0, w: x1 - x0 + 1, h: y1 - y0 + 1, colors: [...colors].slice(0, 4), cleared };
  });
}

/** Write the candidate's pixels for the given indices into the paint layer (a non-destructive, partial apply). */
export function applyPixels(l: Layers, cand: Raster, pixels: Iterable<number>): Layers {
  const paint = new Uint8ClampedArray(l.paint), cut = new Uint8Array(l.cut);
  for (const i of pixels) {
    const o = i * 4;
    if (cand.px[o + 3]) { paint[o] = cand.px[o]; paint[o + 1] = cand.px[o + 1]; paint[o + 2] = cand.px[o + 2]; paint[o + 3] = 255; cut[i] = 0; }
    else { paint[o] = paint[o + 1] = paint[o + 2] = paint[o + 3] = 0; cut[i] = 1; }
  }
  return { ...l, paint, cut };
}

export function selectionPixels(size: number, sel: Sel): number[] {
  if (!sel) return [];
  const out: number[] = [];
  for (let y = Math.max(0, sel.y); y < Math.min(size, sel.y + sel.h); y++) for (let x = Math.max(0, sel.x); x < Math.min(size, sel.x + sel.w); x++) out.push(y * size + x);
  return out;
}

/** Quality checks whose status differs between two reports (for the candidate card). */
export function qualityDelta(a: QualityReport, b: QualityReport): { id: string; from: string; to: string }[] {
  return b.checks.flatMap((c) => { const o = a.checks.find((x) => x.id === c.id); return o && o.status !== c.status ? [{ id: c.id, from: o.status, to: c.status }] : []; });
}

// ---------------------------------------------------------------------------- palette, ramps, Style DNA

const hsl = (hex: string) => {
  const [r, g, b] = hexRgb(hex).map((v) => v / 255);
  const mx = Math.max(r, g, b), mn = Math.min(r, g, b), d = mx - mn, l = (mx + mn) / 2;
  const s = d ? d / (1 - Math.abs(2 * l - 1)) : 0;
  let h = 0;
  if (d) h = mx === r ? ((g - b) / d) % 6 : mx === g ? (b - r) / d + 2 : (r - g) / d + 4;
  return { h: (h * 60 + 360) % 360, s, l };
};
const fromHsl = (H: number, S: number, L: number) => {
  const c = (1 - Math.abs(2 * L - 1)) * S, x = c * (1 - Math.abs(((H / 60) % 2) - 1)), m = L - c / 2;
  const [R, G, B] = H < 60 ? [c, x, 0] : H < 120 ? [x, c, 0] : H < 180 ? [0, c, x] : H < 240 ? [0, x, c] : H < 300 ? [x, 0, c] : [c, 0, x];
  return "#" + [R, G, B].map((v) => Math.round(Math.max(0, Math.min(1, v + m)) * 255).toString(16).padStart(2, "0")).join("");
};

/** 5-shade ramp from one colour: darker shades shift cooler, lighter warmer (classic pixel-art hue shifting). */
export function generateRamp(hex: string): string[] {
  const { h, s, l } = hsl(hex);
  return [-2, -1, 0, 1, 2].map((k) => fromHsl((h + k * -8 + 360) % 360, Math.min(1, s * (1 + Math.abs(k) * 0.04)), Math.max(0.06, Math.min(0.94, l + k * 0.12))));
}

const HUES: [number, string][] = [[15, "Red"], [45, "Amber"], [70, "Yellow"], [160, "Green"], [200, "Teal"], [255, "Blue"], [290, "Violet"], [335, "Pink"], [360, "Red"]];
const hueName = (h: number) => HUES.find(([lim]) => h < lim)![1];
const luminance = (hex: string) => { const [r, g, b] = hexRgb(hex); return 0.2126 * r + 0.7152 * g + 0.0722 * b; };

export type RampGroup = { label: string; keys: string[] };
/**
 * Group a spec palette into ramps for the strip. Library templates name their slots (m1-m5 primary, h1-h5 secondary,
 * x1-x5 accent, f* fixed); any other palette is grouped by hue (low saturation = Neutral), dark to light.
 */
export function paletteRamps(palette: Record<string, string>): RampGroup[] {
  const keys = Object.keys(palette);
  const slot = (k: string) => (/^m\d$/.test(k) ? "Primary" : /^h\d$/.test(k) ? "Secondary" : /^x\d$/.test(k) ? "Accent" : /^f[a-z]$/.test(k) ? "Fixed" : null);
  const named = keys.length > 0 && keys.every((k) => slot(k));
  const groups = new Map<string, string[]>();
  for (const k of keys) {
    const { h, s } = hsl(palette[k]);
    const g = named ? slot(k)! : s < 0.18 ? "Neutral" : hueName(h);
    groups.set(g, [...(groups.get(g) ?? []), k]);
  }
  const order = ["Primary", "Secondary", "Accent", "Neutral", "Fixed"];
  return [...groups.entries()]
    .map(([label, ks]) => ({ label, keys: ks.sort((a, b) => luminance(palette[a]) - luminance(palette[b])) }))
    .sort((a, b) => (order.indexOf(a.label) + 1 || 9) - (order.indexOf(b.label) + 1 || 9) || b.keys.length - a.keys.length);
}

/** The mod's Style DNA as shown on the strip (the build prompt's CUSTOM TEXTURES rules). */
export const DNA_RULES = ["Top-left light", "3-5 shade ramps", "No noise or gradients", "Clear background"] as const;
export function outlineColor(spec: TextureSpec | null): string | null {
  const o = spec?.ops.find((x) => x.op === "outline") as { c: string } | undefined;
  return o ? spec!.palette[o.c] ?? null : null;
}
/** A texture follows the Style DNA when the noise and outline checks pass (what the build service measures). */
export const followsDna = (r: QualityReport) => ["noise", "outline"].every((id) => { const c = r.checks.find((x) => x.id === id); return !c || c.status === "pass" || c.status === "not_run"; });
// Cyrus studios (R1b): the server-side service behind /api/cyrus/assets/v1. Every dependency is injected (host seam):
// the Cyrus tables through `StudioStore`, the build chain through `chain`, the plan through `planOf`, pack hosting
// through `publish`. lib/cyrus/studios/deps.ts wires the real ones; tests use in-memory fakes. No Nxeon internals here.
//
// Model: a project's texture = the newest CyrusProjectAsset row for its key (kind texture) that is not an undecided
// Cyrus candidate. Rows are append-only and content-addressed; the studio never edits a row or a revision: a save is
// a NEW revision (kind "asset") plus a new asset row holding the TextureDoc (spec + sparse paint layer, ./paint.ts).
import { validateItemModel, type ItemModelSpec } from "../itemmodel/spec";
import { canAsset, type AssetDecision } from "../engine-core/asset-gate";
import type { AddRevisionInput, RecordAssetInput } from "../engine-core/store";
import type { ManifestEntry } from "../engine-core/revisions";
import type { IdentifierKind } from "../engine-core/identifiers";
import type { MbAssets } from "../../modbuilder/types";
import { checkSpec, type TextureSpec } from "../textures/dsl";
import { encodePng } from "../textures/png";
import { QUALITY_VERSION, type QualityReport } from "../textures/quality";
import { buildPack } from "../textures/pack";
import { canonicalJson, sha256Hex } from "../assets/textures";
import { checkDoc, docFromSpec, docQuality, renderDoc, TEXTURE_DOC_MIME, type DocDecision, type TextureDoc } from "./paint";
import { studioPlanView, type StudioPlanView } from "./access";
import { resolveSoundSets, type SoundSetEntry } from "./sound-model";

export type ProjectRow = { id: string; userId: string; namespace: string; rootBuildId: string | null; headRevisionId: string | null; title: string | null };
export type AssetRow = { id: string; projectId: string; revisionId: string; assetKey: string; kind: string; sha256: string; size: number; origin: string; mime: string | null; path: string | null; provenance: unknown; createdAt: Date | string };
export type RevRow = { id: string; seq: number; kind: string; status: string; message: string | null; createdAt: Date | string; manifest: ManifestEntry[]; modBuildId: string | null };

export interface StudioStore {
  projectForRoot(rootBuildId: string): Promise<ProjectRow | null>;
  project(id: string): Promise<ProjectRow | null>;
  assets(projectId: string): Promise<AssetRow[]>;
  assetById(id: string): Promise<AssetRow | null>;
  revisions(projectId: string): Promise<RevRow[]>;
  addRevision(projectId: string, input: AddRevisionInput): Promise<{ id: string; seq: number }>;
  recordAsset(projectId: string, a: RecordAssetInput): Promise<{ id: string }>;
  reserve(projectId: string, kind: IdentifierKind, key: string): Promise<{ fullId: string }>;
}

/** The mod's build chain as far as the studio needs it (read through the existing ModBuild seam). */
export type ChainInfo = {
  rootBuildId: string;
  latestBuildId: string | null;
  mcVersion: string;
  pluginName: string | null;
  /** ModBuild.result.assets of the newest build that has one */
  assets: MbAssets | null;
  /** builds the Texture Studio started as AI candidates (change builds with the studio marker) */
  candidateBuilds: { id: string; key: string; status: string; error: string | null; createdAt: string; summary?: string }[];
  /** builds the Sound Studio started as AI candidates (one event of one set each); absent on older readers */
  soundCandidateBuilds?: { id: string; set: string; event: string; status: string; error: string | null; createdAt: string; summary?: string }[];
  /** the newest succeeded build that is not a studio candidate (the base for a new candidate); absent = latestBuildId */
  baseBuildId?: string | null;
};

export type PublishResult = { ok: true; url: string; sha1: string } | { ok: false; reason: string };
export type StudioServiceDeps = {
  store: StudioStore;
  planOf: (userId: string) => Promise<unknown>;
  chain: (userId: string, rootBuildId: string) => Promise<ChainInfo | null>;
  /** publish a rebuilt pack; absent / not configured = the pack is built and recorded but not hosted */
  publish?: (zip: Buffer) => Promise<PublishResult>;
  /** CYRUS_MANAGED_PLUGINS_REAL: packs are delivered to servers */
  deliveryOn: () => boolean;
};

/** Texture candidate build ids / Sound candidate build ids of a chain. */
export const textureCandidateIds = (c: Pick<ChainInfo, "candidateBuilds"> | null | undefined) => new Set((c?.candidateBuilds ?? []).map((b) => b.id));
export const soundCandidateIds = (c: Pick<ChainInfo, "soundCandidateBuilds"> | null | undefined) => new Set((c?.soundCandidateBuilds ?? []).map((b) => b.id));

export class StudioError extends Error {
  constructor(public status: number, public code: string, message: string, public extra: Record<string, unknown> = {}) { super(message); }
}

export const docSha = (doc: TextureDoc) => { const canonical = canonicalJson(doc); return { canonical, sha256: sha256Hex(canonical) }; };
const ts = (d: Date | string) => new Date(d).getTime();
const obj = (v: unknown): Record<string, unknown> => (v && typeof v === "object" && !Array.isArray(v) ? (v as Record<string, unknown>) : {});

/** The TextureDoc an asset row holds (generated rows hold a bare spec; uploads hold no pixels here: library only). */
export function docOfRow(row: AssetRow): TextureDoc | null {
  if (row.kind !== "texture") return null;
  const p = obj(row.provenance);
  if (row.mime === TEXTURE_DOC_MIME) { const d = checkDoc(p.doc); return d.ok ? d.doc : null; }
  if (p.spec) {
    const c = checkSpec(p.spec);
    if (!c.ok) return null;
    // a generated spec supersedes itself: a later build that returns it unchanged keeps any studio edit on top
    return { ...docFromSpec(c.spec), supersedes: [row.sha256] };
  }
  return null;
}

export type TextureEntry = {
  key: string; assetId: string; origin: string; revisionId: string; createdAt: string;
  doc: TextureDoc; quality: QualityReport; specSha256: string | null;
  history: { assetId: string; origin: string; revisionId: string; createdAt: string; doc: TextureDoc; label: string; decision: DocDecision | null }[];
  candidates: { buildId: string; assetId: string; createdAt: string; doc: TextureDoc; specSha256: string }[];
};

const ORIGIN_LABEL: Record<string, string> = { generated: "Generated by Cyrus", edited: "Edited in Texture Studio", library: "From the Texture Library", imported: "Imported", upload: "Uploaded" };
function labelOf(row: AssetRow, doc: TextureDoc): string {
  const p = obj(row.provenance);
  if (doc.decision && !doc.decision.accepted) return "Kept current (Cyrus candidate rejected)";
  if (doc.decision?.accepted) return "Accepted Cyrus candidate";
  if (p.keptStudioEdit) return "Studio edits kept by a build";
  if (row.origin === "generated" && p.kept) return "Kept unchanged by a build";
  return ORIGIN_LABEL[row.origin] ?? row.origin;
}

/** Pure: resolve each texture key's current doc, its history and its open candidates. */
export function resolveTextures(rows: readonly AssetRow[], candidateBuildIds: ReadonlySet<string>, ignoreBuildIds: ReadonlySet<string> = new Set()): TextureEntry[] {
  const byKey = new Map<string, AssetRow[]>();
  // rows written by an undecided OTHER-kind studio candidate (a Sound Studio change build) are not the mod's textures
  for (const r of rows) if (r.kind === "texture" && r.mime !== "image/png" && !ignoreBuildIds.has(String(obj(r.provenance).modBuildId ?? ""))) byKey.set(r.assetKey, [...(byKey.get(r.assetKey) ?? []), r]);
  const out: TextureEntry[] = [];
  for (const [key, list] of byKey) {
    list.sort((a, b) => ts(a.createdAt) - ts(b.createdAt) || (a.id < b.id ? -1 : 1));
    const docs = list.map((r) => ({ r, doc: docOfRow(r) })).filter((x): x is { r: AssetRow; doc: TextureDoc } => !!x.doc);
    const isCand = (r: AssetRow) => r.origin === "generated" && candidateBuildIds.has(String(obj(r.provenance).modBuildId ?? ""));
    const decided = new Set(docs.flatMap((x) => (x.doc.decision ? [x.doc.decision.candidate] : [])));
    const cur = [...docs].reverse().find((x) => !isCand(x.r));
    if (!cur) continue;
    out.push({
      key, assetId: cur.r.id, origin: cur.r.origin, revisionId: cur.r.revisionId, createdAt: new Date(cur.r.createdAt).toISOString(),
      doc: cur.doc, quality: docQuality(cur.doc), specSha256: cur.doc.spec ? sha256Hex(canonicalJson(cur.doc.spec)) : null,
      history: docs.filter((x) => !isCand(x.r)).reverse().slice(0, 20).map((x) => ({ assetId: x.r.id, origin: x.r.origin, revisionId: x.r.revisionId, createdAt: new Date(x.r.createdAt).toISOString(), doc: x.doc, label: labelOf(x.r, x.doc), decision: x.doc.decision ?? null })),
      candidates: docs.filter((x) => isCand(x.r) && !decided.has(String(obj(x.r.provenance).modBuildId))).map((x) => ({ buildId: String(obj(x.r.provenance).modBuildId), assetId: x.r.id, createdAt: new Date(x.r.createdAt).toISOString(), doc: x.doc, specSha256: x.r.sha256 })),
    });
  }
  // the mod's order: the oldest texture first (what the build made, then studio additions)
  const first = (t: TextureEntry) => ts(t.history[t.history.length - 1]?.createdAt ?? t.createdAt);
  return out.sort((a, b) => first(a) - first(b) || (a.key < b.key ? -1 : 1));
}

/** The current studio doc of one key, for lib/cyrus/assets/sync.ts (a build keeps studio edits it did not replace). */
export async function currentStudioDoc(store: Pick<StudioStore, "assets">, projectId: string, key: string, candidateBuildIds: ReadonlySet<string> = new Set()) {
  const t = resolveTextures(await store.assets(projectId), candidateBuildIds).find((x) => x.key === key);
  if (!t || (t.origin !== "edited" && t.origin !== "library")) return null; // nothing the studio made
  const { canonical, sha256 } = docSha(t.doc);
  return { doc: t.doc, sha256, canonical };
}

// ---------------------------------------------------------------------------- reads

export type PackStatus = {
  state: "hosted" | "delivery_off" | "unhosted" | "failed" | "none";
  sha1: string | null; bytes: number | null; format: number | null; mcVersion: string; required: boolean;
  textures: number; sounds: number; editedSinceBuild: boolean; notices: string[];
};

export function packStatusOf(chain: ChainInfo, deliveryOn: boolean, editedSinceBuild: boolean): PackStatus {
  const a = chain.assets;
  const state: PackStatus["state"] = !a || !a.pack ? (a?.status === "failed" ? "failed" : "none") : !deliveryOn ? "delivery_off" : a.status === "ready" && a.pack.url ? "hosted" : "unhosted";
  return {
    state, sha1: a?.pack?.sha1 ?? null, bytes: a?.pack?.bytes ?? null, format: a?.pack?.format ?? null, mcVersion: chain.mcVersion,
    required: a?.loader?.required ?? false, textures: a?.textures.length ?? 0, sounds: a?.sounds?.length ?? 0, editedSinceBuild, notices: (a?.notices ?? []).slice(0, 6),
  };
}

export type ProjectAssetsView = {
  project: { id: string; namespace: string; title: string | null; rootBuildId: string | null } | null;
  access: StudioPlanView;
  headRevisionId: string | null;
  textures: TextureEntry[];
  /** Sound Studio: the project's sound sets from its asset rows (current spec, history, open candidates) */
  soundSets: SoundSetEntry[];
  sounds: NonNullable<MbAssets["sounds"]>;
  soundRender: MbAssets["soundRender"] | null;
  pack: PackStatus | null;
  /** candidate build id -> what the customer asked for (the change request without the studio marker) */
  candidateSummaries: Record<string, string>;
  /** revision id -> seq (History shows "Revision N") */
  revisionSeq: Record<string, number>;
  mcVersion: string | null;
  /** Cyrus item model states: the mod's current ItemModelSpecs (asset rows kind "itemmodel"); the preview's contexts + states. */
  itemModels: ItemModelSpec[];
};

/** The latest valid ItemModelSpec per key (asset rows of kind "itemmodel", provenance.spec). */
export function resolveItemModels(rows: readonly AssetRow[]): ItemModelSpec[] {
  const latest = new Map<string, AssetRow>();
  for (const r of rows) if (r.kind === "itemmodel") { const cur = latest.get(r.assetKey); if (!cur || ts(r.createdAt) >= ts(cur.createdAt)) latest.set(r.assetKey, r); }
  const out: ItemModelSpec[] = [];
  for (const r of [...latest.values()].sort((a, b) => (a.assetKey < b.assetKey ? -1 : 1))) { const v = validateItemModel(obj(r.provenance).spec); if (v.ok) out.push(v.spec); }
  return out;
}

async function ownedProject(deps: StudioServiceDeps, userId: string, projectId: string): Promise<ProjectRow> {
  const p = await deps.store.project(projectId);
  if (!p || p.userId !== userId) throw new StudioError(404, "not_found", "Project not found.");
  return p;
}
const planView = async (deps: StudioServiceDeps, userId: string) => studioPlanView(await deps.planOf(userId).catch(() => null));

export async function projectAssets(deps: StudioServiceDeps, userId: string, rootBuildId: string): Promise<ProjectAssetsView> {
  const chain = await deps.chain(userId, rootBuildId);
  if (!chain) throw new StudioError(404, "not_found", "Mod not found.");
  const access = await planView(deps, userId);
  const p = await deps.store.projectForRoot(chain.rootBuildId);
  if (!p || p.userId !== userId) return { project: null, access, headRevisionId: null, textures: [], soundSets: [], sounds: chain.assets?.sounds ?? [], soundRender: chain.assets?.soundRender ?? null, pack: chain.assets ? packStatusOf(chain, deps.deliveryOn(), false) : null, revisionSeq: {}, mcVersion: chain.mcVersion, candidateSummaries: {}, itemModels: [] };
  const revs = await deps.store.revisions(p.id);
  const rows = await deps.store.assets(p.id);
  const textures = resolveTextures(rows, textureCandidateIds(chain), soundCandidateIds(chain));
  const soundSets = resolveSoundSets(rows, new Map((chain.soundCandidateBuilds ?? []).map((b) => [b.id, { set: b.set, event: b.event }])), textureCandidateIds(chain));
  const lastBuildRev = chain.assets?.revisionId ?? null;
  const edited = [...textures, ...soundSets].some((t) => (t.origin === "edited" || t.origin === "library") && t.revisionId !== lastBuildRev);
  return {
    project: { id: p.id, namespace: p.namespace, title: p.title, rootBuildId: p.rootBuildId }, access, headRevisionId: p.headRevisionId,
    textures, soundSets, sounds: chain.assets?.sounds ?? [], soundRender: chain.assets?.soundRender ?? null, pack: packStatusOf(chain, deps.deliveryOn(), edited),
    revisionSeq: Object.fromEntries(revs.map((r) => [r.id, r.seq])), mcVersion: chain.mcVersion,
    candidateSummaries: Object.fromEntries([...chain.candidateBuilds, ...(chain.soundCandidateBuilds ?? [])].filter((b) => b.summary).map((b) => [b.id, b.summary!])),
    itemModels: resolveItemModels(rows),
  };
}

// ---------------------------------------------------------------------------- writes

const gateOrThrow = (d: AssetDecision) => { if (!d.ok) throw new StudioError(d.code === "bad_request" ? 400 : 403, d.code, d.reason, d.needs ? { needs: d.needs } : {}); };

export type SaveInput = {
  userId: string; projectId: string; key: string; doc: unknown;
  /** the asset row the edit started from (null = a new texture) */
  baseAssetId: string | null;
  /** the project head the client saw; a newer head = 409 stale_head */
  expectedHeadId: string | null;
  origin?: "edited" | "library";
  decision?: DocDecision | null;
  /** spec sha256 values this doc also supersedes (server-computed: a rejected / accepted candidate) */
  alsoSupersedes?: string[];
  message?: string | null;
  provenance?: Record<string, unknown>;
};
export type SaveResult = { revisionId: string; seq: number; assetId: string; quality: QualityReport; pack: { sha1: string; hosted: boolean } | { skipped: string } };

export async function saveTexture(deps: StudioServiceDeps, input: SaveInput): Promise<SaveResult> {
  const origin = input.origin ?? "edited";
  gateOrThrow(canAsset(await deps.planOf(input.userId).catch(() => null), "texture", origin === "library" ? "create" : "edit"));
  const project = await ownedProject(deps, input.userId, input.projectId);
  const d = checkDoc(input.doc);
  if (!d.ok) throw new StudioError(400, "bad_doc", d.error);
  if (d.doc.name !== input.key) throw new StudioError(400, "bad_doc", "the texture name must match its key");
  const rows = await deps.store.assets(project.id);
  const base = input.baseAssetId ? rows.find((r) => r.id === input.baseAssetId && r.kind === "texture") : null;
  if (input.baseAssetId && !base) throw new StudioError(404, "not_found", "The texture this edit started from is not in this project.");
  if (!input.baseAssetId && rows.some((r) => r.kind === "texture" && r.assetKey === input.key && r.mime !== "image/png")) throw new StudioError(409, "exists", `This mod already has a texture called ${input.key}.`);
  const baseDoc = base ? docOfRow(base) : null;
  // supersedes is computed here, never taken from the client
  const sup = new Set<string>([...(baseDoc?.supersedes ?? []), ...(input.alsoSupersedes ?? [])]);
  const doc: TextureDoc = { ...d.doc, ...(sup.size ? { supersedes: [...sup].sort() } : {}), ...(input.decision ? { decision: input.decision } : {}) };
  if (!sup.size) delete doc.supersedes;
  if (!input.decision) delete doc.decision;
  const quality = docQuality(doc);
  if (quality.verdict === "fail") throw new StudioError(422, "quality", "This texture fails the quality checks, so it can't be saved. Fix the failing checks first.", { quality });
  const { canonical, sha256 } = docSha(doc);
  const png = encodePng(renderDoc(doc));

  // the pack, rebuilt from every current texture of the mod (sound packs are re-rendered by the next build instead)
  const revs = await deps.store.revisions(project.id);
  const head = revs.length ? revs[revs.length - 1] : null;
  if (input.expectedHeadId !== undefined && (head?.id ?? null) !== input.expectedHeadId) throw new StudioError(409, "stale_head", "This mod changed since you opened it. Reload to see the latest version, then save again.");
  const chain = project.rootBuildId ? await deps.chain(input.userId, project.rootBuildId) : null;
  const current = resolveTextures(rows, textureCandidateIds(chain), soundCandidateIds(chain)).filter((t) => t.key !== input.key).map((t) => t.doc);
  let pack: SaveResult["pack"] = { skipped: "no build to rebuild the pack for yet" };
  let packEntry: ManifestEntry | null = null;
  if (chain && chain.assets?.sounds?.length) pack = { skipped: "this pack also carries sounds; the next build rebuilds it with your texture" };
  else if (chain) {
    const built = buildPack({ namespace: project.namespace, description: `${chain.pluginName || "This mod"}: custom textures by Cyrus`.slice(0, 100), mcVersion: chain.mcVersion, textures: [...current, doc].slice(0, 24) });
    if (!built.ok) pack = { skipped: built.error };
    else {
      packEntry = { path: `resourcepack/${built.pack.sha1}.zip`, sha256: sha256Hex(built.pack.zip), role: "resourcePack" };
      const pub = deps.publish ? await deps.publish(built.pack.zip).catch((e) => ({ ok: false as const, reason: (e as Error).message })) : { ok: false as const, reason: "pack hosting is not configured" };
      pack = { sha1: built.pack.sha1, hosted: pub.ok };
    }
  }
  const path = `assets/textures/${input.key}.json`;
  const manifest: ManifestEntry[] = [
    ...(head?.manifest ?? []).filter((e) => e.path !== path && !(packEntry && e.role === "resourcePack")),
    { path, sha256, role: "asset" },
    ...(packEntry ? [packEntry] : []),
  ];
  let rev: { id: string; seq: number };
  try {
    rev = await deps.store.addRevision(project.id, {
      kind: "asset", manifest, status: "passed", expectedHeadId: head?.id ?? null,
      engine: { toolchain: `cyrus-texture-studio ${QUALITY_VERSION}` },
      message: (input.message ?? (input.decision ? (input.decision.accepted ? `Accepted Cyrus candidate for ${input.key}` : `Kept ${input.key} (rejected a Cyrus candidate)`) : origin === "library" ? `Added ${input.key} from the Texture Library` : `Edited ${input.key} in Texture Studio`)).slice(0, 200),
    });
  } catch (e) {
    if ((e as { code?: string }).code === "stale_head") throw new StudioError(409, "stale_head", "This mod changed since you opened it. Reload to see the latest version, then save again.");
    throw e;
  }
  const asset = await deps.store.recordAsset(project.id, {
    revisionId: rev.id, assetKey: input.key, kind: "texture", sha256, size: Buffer.byteLength(canonical), origin, mime: TEXTURE_DOC_MIME, path,
    provenance: { generator: "cyrus-texture-studio", doc, quality, pngSha256: sha256Hex(png), basedOn: base?.id ?? null, packSha1: "sha1" in pack ? pack.sha1 : null, ...(input.provenance ?? {}) },
  });
  return { revisionId: rev.id, seq: rev.seq, assetId: asset.id, quality, pack };
}

// ---------------------------------------------------------------------------- candidates (the AI edit interface)

/**
 * The interface the studio uses to ask Cyrus for a texture edit. The real implementation (./candidates.ts
 * changeBuildCandidates) creates a CHANGE BUILD through the existing flow and returns the build's texture when it
 * completes; tests and devhost use fakeCandidates. A candidate is never applied by the backend: the customer
 * accepts (saves a revision), applies part of it, or rejects it.
 */
export type CandidateRequest = { userId: string; user: unknown; project: ProjectRow; chain: ChainInfo; key: string; prompt: string; current: TextureEntry };
export type CandidatePoll =
  | { status: "pending"; note?: string }
  | { status: "ready"; doc: TextureDoc; specSha256: string; summary: string }
  | { status: "failed"; error: string };
export interface CandidateBackend {
  readonly id: string;
  request(r: CandidateRequest): Promise<{ ok: true; requestId: string } | { ok: false; status: number; code: string; error: string }>;
  poll(r: { userId: string; project: ProjectRow; chain: ChainInfo; key: string; requestId: string }): Promise<CandidatePoll>;
}

export const MAX_PROMPT = 600;

export async function textureForEdit(deps: StudioServiceDeps, userId: string, projectId: string, key: string) {
  gateOrThrow(canAsset(await deps.planOf(userId).catch(() => null), "texture", "edit"));
  const project = await ownedProject(deps, userId, projectId);
  if (!project.rootBuildId) throw new StudioError(409, "no_build", "Build the mod once before asking Cyrus to edit its textures.");
  const chain = await deps.chain(userId, project.rootBuildId);
  if (!chain) throw new StudioError(404, "not_found", "Mod not found.");
  const t = resolveTextures(await deps.store.assets(project.id), textureCandidateIds(chain), soundCandidateIds(chain)).find((x) => x.key === key);
  if (!t) throw new StudioError(404, "not_found", `No texture called ${key} in this mod.`);
  return { project, chain, texture: t };
}

/**
 * The spec sha256 of a candidate, read on the SERVER (never from the client): a candidate build the asset sync already
 * recorded (any backend), else the backend's own poll. Null when it is not ready.
 */
export async function candidateSpecSha(backend: CandidateBackend, r: { userId: string; project: ProjectRow; chain: ChainInfo; texture: TextureEntry; key: string; requestId: string }): Promise<string | null> {
  const persisted = r.texture.candidates.find((c) => c.buildId === r.requestId);
  if (persisted) return persisted.specSha256;
  const poll = await backend.poll({ userId: r.userId, project: r.project, chain: r.chain, key: r.key, requestId: r.requestId });
  return poll.status === "ready" ? poll.specSha256 : null;
}

/** Reject a candidate: keep the current doc as a new revision that records the decision (and supersedes the candidate spec). */
export async function rejectCandidate(deps: StudioServiceDeps, backend: CandidateBackend, i: { userId: string; projectId: string; key: string; requestId: string; expectedHeadId: string | null }) {
  const { project, chain, texture } = await textureForEdit(deps, i.userId, i.projectId, i.key);
  const sha = await candidateSpecSha(backend, { userId: i.userId, project, chain, texture, key: i.key, requestId: i.requestId });
  const also = sha ? [sha] : [];
  return saveTexture(deps, {
    userId: i.userId, projectId: project.id, key: i.key, doc: { ...texture.doc, decision: undefined }, baseAssetId: texture.assetId, expectedHeadId: i.expectedHeadId,
    decision: { candidate: i.requestId, accepted: false }, alsoSupersedes: also,
  });
}

/** A deterministic fake: the "edit" applies the Style DNA (drops noise and gradient ops) or adds a 1 px highlight. */
export function fakeCandidates(opts: { readyAfter?: number } = {}): CandidateBackend & { requests: Map<string, { key: string; prompt: string; base: TextureDoc; polls: number }> } {
  const requests = new Map<string, { key: string; prompt: string; base: TextureDoc; polls: number }>();
  let n = 0;
  return {
    id: "fake", requests,
    async request(r) {
      const requestId = `fake${(++n).toString().padStart(4, "0")}${r.key.slice(0, 8)}`;
      requests.set(requestId, { key: r.key, prompt: r.prompt, base: r.current.doc, polls: 0 });
      return { ok: true, requestId };
    },
    async poll(r) {
      const q = requests.get(r.requestId);
      if (!q || q.key !== r.key) return { status: "failed", error: "unknown candidate" };
      if (++q.polls <= (opts.readyAfter ?? 1)) return { status: "pending", note: "Cyrus is drawing a candidate" };
      const spec = q.base.spec;
      if (!spec) return { status: "failed", error: "this texture has no generated base to edit" };
      let ops = spec.ops.filter((o) => o.op !== "noise" && o.op !== "gradient");
      if (ops.length === spec.ops.length) {
        const light = Object.entries(spec.palette).sort((a, b) => parseInt(b[1].slice(1), 16) - parseInt(a[1].slice(1), 16))[0][0];
        const at = Math.max(0, ops.findIndex((o) => o.op === "shade" || o.op === "outline"));
        ops = [...ops.slice(0, at), { op: "px", x: Math.floor(spec.size / 3), y: Math.floor(spec.size / 3), c: light }, ...ops.slice(at)];
      }
      const cand: TextureSpec = { ...spec, ops };
      return { status: "ready", doc: { ...docFromSpec(cand), name: q.key }, specSha256: sha256Hex(canonicalJson(cand)), summary: q.prompt };
    },
  };
}

