import path from "node:path";

const ROOT = path.resolve(__dirname, "..");
const CYRUS = path.join(ROOT, "lib", "cyrus");
const BASELINE = path.join(__dirname, "fixtures", "cyrus-host-seam-baseline.json");
const ALLOWED_BRIDGE = "lib/cyrus/host/nxeon.ts";
const IMPORT_RE = /(?:\bfrom|\bimport|\brequire)\s*\(?\s*["']([^"']+)["']/g;

function walk(dir: string, out: string[] = []): string[] {
  for (const n of readdirSync(dir)) {
    const p = path.join(dir, n);
    if (statSync(p).isDirectory()) walk(p, out);
    else if (/\.(ts|tsx)$/.test(n) && !/\.d\.ts$/.test(n)) out.push(p);
  }
  return out;
}

/** file -> sorted Nxeon targets (repo-relative, no extension) it imports from outside lib/cyrus. */
export function scanSeam(): Record<string, string[]> {
  const res: Record<string, string[]> = {};
  for (const file of walk(CYRUS)) {
    const rel = path.relative(ROOT, file).split(path.sep).join("/");
    if (rel === ALLOWED_BRIDGE) continue;
    const targets = new Set<string>();
    for (const m of readFileSync(file, "utf8").matchAll(IMPORT_RE)) {
      const spec = m[1];
      let abs: string | null = null;
      if (spec.startsWith(".")) abs = path.resolve(path.dirname(file), spec);
      else if (spec.startsWith("@/")) abs = path.join(ROOT, spec.slice(2));
      if (!abs) continue; // npm packages and node builtins are not platform coupling
      const t = path.relative(ROOT, abs).split(path.sep).join("/");
      if (t === "lib/cyrus" || t.startsWith("lib/cyrus/")) continue;
      targets.add(t);
    }
    if (targets.size) res[rel] = [...targets].sort();
  }
  return res;
}

describe("Cyrus host seam ratchet", () => {
  const now = scanSeam();
  if (process.env.UPDATE_CYRUS_SEAM_BASELINE === "1") writeFileSync(BASELINE, JSON.stringify(now, null, 2) + "\n");
  const base: Record<string, string[]> = JSON.parse(readFileSync(BASELINE, "utf8"));
  const pairs = (m: Record<string, string[]>) => new Set(Object.entries(m).flatMap(([f, ts]) => ts.map((t) => `${f} -> ${t}`)));

  it("adds no new imports of Nxeon internals under lib/cyrus (use lib/cyrus/host)", () => {
    const b = pairs(base);
    const added = [...pairs(now)].filter((p) => !b.has(p));
    assert.deepEqual(added, [], `new Nxeon imports in lib/cyrus; route them through lib/cyrus/host:\n${added.join("\n")}`);
  });
  it("baseline has no stale entries (tighten it when coupling is removed)", () => {
    const n = pairs(now);
    const stale = [...pairs(base)].filter((p) => !n.has(p));
    assert.deepEqual(stale, [], `baseline lists imports that no longer exist; run with UPDATE_CYRUS_SEAM_BASELINE=1:\n${stale.join("\n")}`);
  });
  it("the Nxeon bridge exists and the host registry defaults to it", () => {
    const idx = readFileSync(path.join(CYRUS, "host", "index.ts"), "utf8");
    assert.ok(idx.includes("nxeonHost"));
    assert.ok(statSync(path.join(ROOT, ALLOWED_BRIDGE)).isFile());
  });
});

// Cyrus engine core: the project + revision store and the identifier registry (DB half). SERVER ONLY.
// The only writer of CyrusProject / CyrusRevision / CyrusProjectAsset / CyrusIdentifier.
// Rules: revisions are append-only (no function here edits or deletes their content); a revision's status moves
// once, pending -> passed | failed; a project always records its last passing revision; a revert is a NEW revision
// that copies an older one's content. Appends lock the project row (FOR UPDATE), so seq has no gaps and two writers
// cannot both build on the same head.
import { randomBytes } from "node:crypto";
import { Prisma, type CyrusIdentifier, type CyrusProject, type CyrusRevision } from "@prisma/client";
import { db } from "../../db";
import { getAdapter } from "../adapters";
import { validateModSpec, GAME_ID_RE, type ModSpec, type SpecIssue } from "./spec";
import { diffManifests, validateEngineRecord, validateManifest, REVISION_KINDS, type EngineRecord, type ManifestDiff, type ManifestEntry, type RevisionKind, type RevisionStatus } from "./revisions";
import { buildIdentifier, glyphBlockStart, glyphHomeBlock, GLYPH_BLOCK, GLYPH_BLOCKS, namespaceFromSeed, type IdentifierKind } from "./identifiers";

export class EngineStoreError extends Error {
  constructor(public code: string, message: string, public issues: SpecIssue[] = []) {
    super(message);
    this.name = "EngineStoreError";
  }
}

const isUniqueViolation = (e: unknown, field?: string): boolean => {
  if (!(e instanceof Prisma.PrismaClientKnownRequestError) || e.code !== "P2002") return false;
  if (!field) return true;
  const t = (e.meta as { target?: unknown } | undefined)?.target;
  return (Array.isArray(t) ? t.join(",") : String(t ?? "")).includes(field);
};

