// Cyrus R3 item model states: ItemModelSpec v1. How ONE custom item looks in each display context (hotbar/gui,
// dropped, item frame, head, first/third person hands) and which texture it shows in which STATE (a bow idle vs
// pulled back in stages, a gun idle / aiming / reloading). The build model writes one spec per stateful item at
// assets/itemmodels/<name>.json; ./emit.ts turns it into the 1.21.4+ item model definition (assets/<ns>/items/<name>.json)
// plus one model JSON per state, inside the mod's normal resource pack (lib/cyrus/textures/pack.ts).
//
// Every condition below is a VERIFIED vanilla item model property (checked 2026-10-10 against the vanilla client jars
// 1.21.4 / 1.21.11 / 26.2 and the vanilla asset mirror; exact names and thresholds in docs/DOCUMENTATION.md "Cyrus item
// model states (R3)"). Nothing is free-form: closed condition set, hard caps, the display numbers are capped like the
// game caps them (translation +-80 = 5 blocks, scale +-4; rotation is not capped by the game, Cyrus caps it at +-360).
// Validation never throws: { ok, spec, needs, warnings } | { ok: false, errors }.
// The JSON Schema (itemmodel.v1.schema.json) is generated from these Zod types (scripts/cyrus/build-itemmodel-artifacts.ts;
// a test fails while it is stale).
import { z } from "zod";
import { getVersion } from "../versions/registry";

export const ITEMMODEL_SPEC_VERSION = 1;

/** The 8 display contexts every vanilla version since 1.21.4 has (1.21.9+ adds `on_shelf`: not emitted, vanilla items do not define it either). */
export const DISPLAY_CONTEXTS = ["gui", "ground", "fixed", "head", "firstperson_righthand", "firstperson_lefthand", "thirdperson_righthand", "thirdperson_lefthand"] as const;
export type DisplayContext = (typeof DISPLAY_CONTEXTS)[number];
/** Per-category display defaults (./defaults.ts). */
export const CATEGORIES = ["sword", "tool", "bow", "crossbow", "gun", "wand", "shield", "flat"] as const;
export type Category = (typeof CATEGORIES)[number];

export const ITEMMODEL_CAPS = {
  maxStates: 8, maxTextures: 9, maxPullStages: 4, maxModes: 6, maxFlags: 4, maxDamageStages: 4, maxContextStates: 3,
  rotation: 360, translation: 80, scale: 4, pullFrom: 100, maxSpecBytes: 16 * 1024, maxSpecsPerMod: 12, labelChars: 24,
} as const;

const NAME_RE = /^[a-z][a-z0-9_]{1,31}$/; // = a texture name (lib/cyrus/textures/dsl.ts)
const KEY_RE = /^[a-z][a-z0-9_]{0,23}$/;
const C = ITEMMODEL_CAPS;

const vec = (cap: number) => z.tuple([z.number().min(-cap).max(cap), z.number().min(-cap).max(cap), z.number().min(-cap).max(cap)]);
export const TransformOverrideSchema = z.object({ rotation: vec(C.rotation).optional(), translation: vec(C.translation).optional(), scale: vec(C.scale).optional() }).strict();
export const DisplayOverrideSchema = z.object(Object.fromEntries(DISPLAY_CONTEXTS.map((c) => [c, TransformOverrideSchema.optional()])) as Record<DisplayContext, z.ZodOptional<typeof TransformOverrideSchema>>).strict();
export type DisplayOverride = z.infer<typeof DisplayOverrideSchema>;

/**
 * The closed condition set. Layer order in the emitted definition (outermost first, the first that matches wins):
 * broken -> damage -> mode -> flag -> charged -> using / pull -> selected -> context -> the idle model.
 */
export const ConditionSchema = z.discriminatedUnion("type", [
  /** the item is being used (bow drawn, shield raised, a consumable-style gun being aimed): condition minecraft:using_item */
  z.object({ type: z.literal("using") }).strict(),
  /** a pull stage while used. use_duration: range_dispatch minecraft:use_duration scale 0.05 (20 ticks = 1.0; vanilla bow 0.65 / 0.9);
   *  crossbow: minecraft:crossbow/pull (0..1 of the crossbow's charge time; vanilla 0.58 / 1.0, crossbow base only). from 0 = the first stage. */
  z.object({ type: z.literal("pull"), from: z.number().min(0).max(C.pullFrom), source: z.enum(["use_duration", "crossbow"]).optional() }).strict(),
  /** a loaded crossbow: select minecraft:charge_type (crossbow base only) */
  z.object({ type: z.literal("charged"), charge: z.enum(["arrow", "rocket"]) }).strict(),
  /** plugin-set: select minecraft:custom_model_data on strings[0] (one mode at a time: reloading, aiming, empty...) */
  z.object({ type: z.literal("mode"), value: z.string().regex(KEY_RE) }).strict(),
  /** plugin-set: condition minecraft:custom_model_data on flags[index] (index assigned in declaration order) */
  z.object({ type: z.literal("flag"), name: z.string().regex(KEY_RE) }).strict(),
  /** in the selected hotbar slot: condition minecraft:selected */
  z.object({ type: z.literal("selected") }).strict(),
  /** where it is drawn: select minecraft:display_context */
  z.object({ type: z.literal("context"), contexts: z.array(z.enum(DISPLAY_CONTEXTS)).min(1).max(7) }).strict(),
  /** one use from breaking: condition minecraft:broken */

// Cyrus item model states: screenshots of the Texture Studio's Live preview context switcher + state scrubber
// (run ON node-2 against the devhost dev server, fixtures from scripts/cyrus/studio-fixtures.ts):
//   devhost db reset && devhost db push
//   devhost run -- npx tsx scripts/cyrus/studio-fixtures.ts > .studio-tokens.json
//   devhost dev
//   devhost run -- node test/e2e/cyrus-itemstates.shots.mjs .studio-tokens.json .itemstates-shots
//   devhost pull .itemstates-shots /root/agent-notes/cyrus-designs/impl-shots   (files are prefixed itemstates-)
import { chromium } from "playwright";
import { mkdirSync, readFileSync } from "node:fs";

const [, , tokFile, out = ".itemstates-shots"] = process.argv;
const T = JSON.parse(readFileSync(tokFile, "utf8"));
const BASE = process.env.BASE ?? `http://127.0.0.1:${process.env.PORT}`;
mkdirSync(out, { recursive: true });
const browser = await chromium.launch();
const tex = "/dashboard/cyrus/{build}/studio/texture";
let failures = 0;

async function shot(name, asset, { ctx = "First person", state = null, theme = "dark", full = false } = {}) {
  const c = await browser.newContext({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 2, colorScheme: theme, reducedMotion: "reduce" });
  await c.addCookies([{ name: T.cookie, value: T.all.token, url: BASE }, { name: "nxeon_cookie_consent", value: "all", url: BASE }]);
  const page = await c.newPage();
  await page.addInitScript((t) => { try { localStorage.setItem("nx-theme", t); localStorage.setItem("nx-tour-dismissed", "1"); localStorage.setItem("cyrus-sound", "off"); } catch {} }, theme);
  const errs = [];
  page.on("pageerror", (e) => errs.push(String(e).slice(0, 300)));
  page.on("console", (m) => { if (m.type() === "error") errs.push("console: " + m.text().slice(0, 200)); });
  await page.goto(BASE + tex.replace("{build}", T.all.buildId) + (asset ? `?asset=${asset}` : ""), { waitUntil: "networkidle", timeout: 180000 }).catch((e) => errs.push("goto " + e));
  for (const label of ["Got it", "Skip", "Not now", "Skip tour", "Maybe later", "Accept all"]) { const b = page.getByRole("button", { name: label, exact: true }); if (await b.count().catch(() => 0)) await b.first().click({ timeout: 800 }).catch(() => {}); }
  await page.waitForTimeout(1500);
  try {
    await page.getByRole("button", { name: "In game", exact: true }).click();
    await page.getByRole("group", { name: "Where the item is shown" }).getByRole("button", { name: ctx, exact: true }).click();
    if (state) await page.getByRole("group", { name: "Item state" }).getByRole("button", { name: state, exact: true }).click();
  } catch (e) { errs.push("act " + String(e).slice(0, 200)); }
  await page.waitForTimeout(500);
  const states = await page.getByRole("group", { name: "Item state" }).getByRole("button").allInnerTexts().catch(() => []);
  const hint = await page.locator(".tx-prev .tx-pvopts .cys-hint").innerText().catch(() => "");
  if (full) await page.screenshot({ path: `${out}/${name}-page.png` });
  await page.locator(".tx-prev").screenshot({ path: `${out}/${name}.png` });
  if (errs.length) failures++;
  console.log(`${out}/${name}.png`, JSON.stringify({ states, hint }), errs.length ? "ERR " + errs.join(" | ").slice(0, 500) : "");
  await c.close();
}

