// Portal half of the creature specs a build returns (Cyrus R3). The build service validated them with its generated
// JS copy of ./spec.ts; the portal never trusts that: it re-validates, compiles (.bbmodel + skin), runs the skin
// quality bar and identifies each RigSpec by the sha256 of its canonical JSON as WRITTEN (template form stays small).
import { canonicalJson, sha256Hex } from "../assets/textures";
import { compileCreature, type CompiledCreature } from "./compile";
import { skinQuality, type SkinQuality } from "./quality";
import { checkRigSpec, MAX_CREATURES, MAX_RIG_SPEC_BYTES, modelKey, NAME_RE, type RigSpec } from "./spec";

export const RIG_SPEC_MIME = "application/vnd.nxeon.rig-spec+json";

export type CheckedCreature =
  | { ok: true; name: string; key: string; input: unknown; spec: RigSpec; specSha256: string; canonical: string; compiled: CompiledCreature; quality: SkinQuality; warnings: string[] }
  | { ok: false; name: string; reason: string };

export function checkReturnedCreature(c: { name?: unknown; spec?: unknown }, namespace: string): CheckedCreature {
  const name = typeof c.name === "string" && NAME_RE.test(c.name) ? c.name : "?";
  const canonical = canonicalJson(c.spec ?? null);
  if (Buffer.byteLength(canonical) > MAX_RIG_SPEC_BYTES) return { ok: false, name, reason: `the creature spec is larger than ${MAX_RIG_SPEC_BYTES / 1024} KB` };
  const chk = checkRigSpec(c.spec, { namespace });
  if (!chk.ok) return { ok: false, name, reason: chk.error };
  if (chk.spec.name !== name) return { ok: false, name, reason: `spec name ${chk.spec.name} does not match ${name}` };
  const r = compileCreature(chk.spec, namespace);
  if (!r.ok) return { ok: false, name, reason: r.error };
  const quality = skinQuality(r.creature.raster, r.creature.layout);
  if (quality.verdict === "fail") return { ok: false, name, reason: `the skin failed Nxeon's skin checks (${quality.checks.filter((q) => q.verdict === "fail").map((q) => q.id).join(", ")})` };
  return { ok: true, name, key: modelKey(namespace, name), input: c.spec, spec: chk.spec, specSha256: sha256Hex(canonical), canonical, compiled: r.creature, quality, warnings: chk.warnings };
}

/** Re-check every returned creature (at most MAX_CREATURES, first wins on a duplicate name). */
export function checkReturnedCreatures(list: { name?: unknown; spec?: unknown }[] | undefined, namespace: string): { ok: Extract<CheckedCreature, { ok: true }>[]; dropped: { name: string; reason: string }[] } {
  const ok: Extract<CheckedCreature, { ok: true }>[] = [];
  const dropped: { name: string; reason: string }[] = [];
  for (const c of (list ?? []).slice(0, MAX_CREATURES)) {
    const r = checkReturnedCreature(c, namespace);
    if (!r.ok) { dropped.push({ name: r.name, reason: r.reason }); continue; }
    if (ok.some((x) => x.name === r.name)) continue;
    ok.push(r);
  }
  return { ok, dropped };
}

"use client";
// Cyrus studios: the shared shell (top bar with the studio's crumbs, the Texture/Sound switch, Mod assets, the token
// chip, the theme switch) + a toast. Same anatomy as the real studio's TopBar (components/cyrus/chrome/TopBar.tsx).
import { createContext, Fragment, useCallback, useContext, useEffect, useState, type ReactNode } from "react";
import Link from "next/link";
import { CyrusWordmark } from "@/components/cyrus/brand/CyrusBrand";
import { CategoryIcon } from "@/components/cyrus/icons/CategoryIcons";
import { CyrusTokenChip } from "@/components/cyrus-tokens";
import { SI } from "./icons";
import "./studios.css";

export type StudioMod = { buildId: string; rootId: string; name: string; category: { key: string; label: string; rgb: string } };
export type StudioKindUI = "texture" | "sound";

type Toast = { msg: string; err?: boolean; id: number } | null;
const ToastCtx = createContext<(msg: string, err?: boolean) => void>(() => undefined);
export const useToast = () => useContext(ToastCtx);

export const studioHref = (mod: Pick<StudioMod, "buildId">, s: StudioKindUI | "plans", q = "") => `/dashboard/cyrus/${mod.buildId}/studio/${s}${q}`;
export const assetsHref = (mod: Pick<StudioMod, "buildId">) => `/dashboard/cyrus/${mod.buildId}?tab=assets`;

function ThemeButton() {
  const [light, setLight] = useState(false);
  useEffect(() => { setLight(document.documentElement.getAttribute("data-theme") === "light"); }, []);
  const flip = () => {
    const next = !light;
    if (next) document.documentElement.setAttribute("data-theme", "light"); else document.documentElement.removeAttribute("data-theme");
    try { localStorage.setItem("nx-theme", next ? "light" : "dark"); } catch { /* storage blocked: the switch still works for this page */ }
    setLight(next);
  };
  return (
    <button type="button" className="cys-chip cys-soft icon" onClick={flip} aria-label="Switch light or dark" title="Switch light or dark">
      <SI n={light ? "sun" : "moon"} />
    </button>
  );
}

export function StudioShell({ mod, current, studio, children }: { mod: StudioMod; current: string; studio: StudioKindUI | null; children: ReactNode }) {
  const [toast, setToast] = useState<Toast>(null);
  const show = useCallback((msg: string, err?: boolean) => setToast({ msg, err, id: Date.now() }), []);
  useEffect(() => { if (!toast) return; const t = window.setTimeout(() => setToast(null), 3200); return () => window.clearTimeout(t); }, [toast]);
  const c = mod.category;
  const crumbs: ReactNode[] = [
    <Link key="core" className="cys-crumb" href="/dashboard/cyrus"><span className="core" />Core</Link>,
    // eslint-disable-next-line @next/next/no-img-element
    <Link key="g" className="cys-crumb" href="/dashboard/cyrus"><img src="/cyrus/games/minecraft.svg" alt="" width={15} height={15} />Minecraft</Link>,
    <Link key="c" className="cys-crumb" href="/dashboard/cyrus"><span style={{ color: `rgb(${c.rgb})`, display: "flex", fontSize: 14 }}><CategoryIcon k={c.key} /></span>{c.label}</Link>,
    <Link key="m" className="cys-crumb" href={assetsHref(mod)}><span className="cys-dot" style={{ background: `rgb(${c.rgb})`, boxShadow: `0 0 8px rgb(${c.rgb})` }} /><span style={{ maxWidth: 180, overflow: "hidden", textOverflow: "ellipsis" }}>{mod.name}</span></Link>,
    <span key="s" className="cys-crumb on" aria-current="page"><SI n={studio === "sound" ? "wave" : "image"} />{current}</span>,
  ];
  return (
    <ToastCtx.Provider value={show}>
      <div className="cys" data-studio={studio ?? "plans"}>
        <header className="cys-top">
          <Link href="/dashboard/cyrus" className="cys-brand" aria-label="Cyrus home">
            <CyrusWordmark height={19} className="topbar-logo" />
            <small>Mod Forge</small>
          </Link>
          <nav className="cys-crumbs cys-soft" aria-label="Location">
            {crumbs.map((x, i) => <Fragment key={i}>{i > 0 && <SI n="chevR" />}{x}</Fragment>)}
          </nav>
          <div className="cys-tbr">
            {studio && (
              <div className="cys-seg cys-soft hide-n" aria-label="Studio">
                <Link href={studioHref(mod, "texture")} className={studio === "texture" ? "on" : ""} aria-current={studio === "texture" ? "page" : undefined}><SI n="image" />Texture</Link>
                <Link href={studioHref(mod, "sound")} className={studio === "sound" ? "on" : ""} aria-current={studio === "sound" ? "page" : undefined}><SI n="wave" />Sound</Link>
              </div>
            )}
            <Link className="cys-chip cys-soft hide-n" href={assetsHref(mod)}><SI n="package" />Mod assets</Link>
            <span className="hide-n"><CyrusTokenChip compact beta={false} /></span>
            <ThemeButton />
          </div>
        </header>
        {children}
        {toast && (
          <div key={toast.id} className={`cys-toast ${toast.err ? "err" : ""}`} role="status">
            <SI n={toast.err ? "warn" : "check"} /><span>{toast.msg}</span>
          </div>
        )}
      </div>
    </ToastCtx.Provider>
  );
}
