// Preview renderer for compiled creatures (Cyrus R3): a tiny software rasteriser of the textured cuboids, so the
// owner, a reviewer (or later a vision-model judge) can SEE a RigSpec without a Minecraft client. Orthographic,
// painter's algorithm per texel quad, flat Minecraft-like face light. It approximates what BetterModel shows; it is
// NOT a substitute for a real-client check (lighting, display-entity interpolation and pack loading differ).
// Pure + deterministic.
import type { Raster } from "../textures/render";
