type Quad = { pts: [number, number][]; depth: number; rgb: [number, number, number] };

/** Draw one view of the creature into `canvas` at cell (cx, cy, size): yaw 0 = looking at its face. */
function drawView(canvas: Raster, cell: { x: number; y: number; size: number }, spec: RigSpec, layout: SkinLayout, skin: Raster, view: { yaw: number; pitch: number }, pose: { clip?: string; time?: number }, fit: { k: number; cx: number; cy: number }) {
  const mats = poseMatrices(spec, pose.clip, pose.time ?? 0);
  const V = mul(Rx(view.pitch), Ry(view.yaw));
  const quads: Quad[] = [];
  const s = spec.scale;
  const L: V3 = (() => { const v: V3 = [-0.45, 0.8, -0.4]; const n = Math.hypot(...v); return v.map((x) => x / n) as V3; })();
  for (const cl of layout.cubes) {
    const bone = spec.bones.find((b) => b.name === cl.bone)!;
    const c = bone.cubes[cl.index];
    const M = mul(V, mul(Sc(s, s, s), mats.get(bone.name)!));
    const inf = c.inflate;
    const a: V3 = [c.from[0] - inf, c.from[1] - inf, c.from[2] - inf], b: V3 = [c.to[0] + inf, c.to[1] + inf, c.to[2] + inf];
    for (const f of FACES) {
      const fc = faceCorners(f, a, b);
      const o = apply(M, [0, 0, 0]);
      const nn = apply(M, fc.n).map((v, i) => v - o[i]) as V3;
      const nl = Math.hypot(...nn) || 1;
      const n = nn.map((v) => v / nl) as V3;
      if (n[2] >= -1e-6) continue; // back face (camera looks along +z)
      const lit = (bone.tag === "glow" ? 1 : 0.62 + 0.38 * Math.max(0, n[0] * L[0] + n[1] * L[1] + n[2] * L[2]));
      const r = cl.faces[f];
      const TL = apply(M, fc.tl), TR = apply(M, fc.tr), BL = apply(M, fc.bl);
      const ex = TR.map((v, i) => v - TL[i]), ey = BL.map((v, i) => v - TL[i]);
      for (let j = 0; j < r.h; j++) for (let i = 0; i < r.w; i++) {
        const pi = ((r.y + j) * skin.size + (r.x + i)) * 4;
        if (skin.px[pi + 3] === 0) continue;
        const at = (u: number, v: number): V3 => [0, 1, 2].map((k) => TL[k] + ex[k] * (u / r.w) + ey[k] * (v / r.h)) as V3;
        const corners = [at(i, j), at(i + 1, j), at(i + 1, j + 1), at(i, j + 1)];
        const pts = corners.map((p) => [cell.x + cell.size / 2 + (-(p[0]) - fit.cx) * fit.k, cell.y + cell.size / 2 - (p[1] - fit.cy) * fit.k] as [number, number]);
        const depth = corners.reduce((acc, p) => acc + p[2], 0) / 4;
        quads.push({ pts, depth, rgb: [skin.px[pi] * lit, skin.px[pi + 1] * lit, skin.px[pi + 2] * lit] });
      }
    }
  }
  quads.sort((p, q) => q.depth - p.depth);
  for (const q of quads) fillPoly(canvas, q.pts, q.rgb, cell);
}

function fillPoly(c: Raster, pts: [number, number][], rgb: [number, number, number], clip: { x: number; y: number; size: number }) {
  const xs = pts.map((p) => p[0]), ys = pts.map((p) => p[1]);
  const x0 = Math.max(clip.x, Math.floor(Math.min(...xs))), x1 = Math.min(clip.x + clip.size - 1, Math.ceil(Math.max(...xs)));
  const y0 = Math.max(clip.y, Math.floor(Math.min(...ys))), y1 = Math.min(clip.y + clip.size - 1, Math.ceil(Math.max(...ys)));
  for (let y = y0; y <= y1; y++) for (let x = x0; x <= x1; x++) {
    const px = x + 0.5, py = y + 0.5;
    let inside = false;
    for (let i = 0, j = pts.length - 1; i < pts.length; j = i++) {
      const [xi, yi] = pts[i], [xj, yj] = pts[j];
      if ((yi > py) !== (yj > py) && px < ((xj - xi) * (py - yi)) / (yj - yi) + xi) inside = !inside;
    }
    if (!inside) continue;
    const k = (y * c.size + x) * 4;
    c.px[k] = Math.min(255, Math.round(rgb[0])); c.px[k + 1] = Math.min(255, Math.round(rgb[1])); c.px[k + 2] = Math.min(255, Math.round(rgb[2])); c.px[k + 3] = 255;
  }
}

export type PreviewCell = { label: string; yaw: number; pitch: number; clip?: string; time?: number };
/** A 3x3 contact sheet: 4 rest-pose views + idle/walk/attack/hurt/death frames. */
export const DEFAULT_CELLS: PreviewCell[] = [
  { label: "front", yaw: 0, pitch: -12 }, { label: "three-quarter", yaw: 35, pitch: -15 }, { label: "side", yaw: 90, pitch: -8 },
  { label: "back", yaw: 180, pitch: -12 }, { label: "idle 0.25", yaw: 30, pitch: -12, clip: "idle", time: 0.75 }, { label: "walk 0.25", yaw: 90, pitch: -8, clip: "walk", time: 0.25 },
  { label: "attack wind-up", yaw: 60, pitch: -10, clip: "attack", time: -0.35 }, { label: "attack strike", yaw: 60, pitch: -10, clip: "attack", time: -0.55 }, { label: "death", yaw: 60, pitch: -18, clip: "death", time: -0.62 },
];

/** Render the contact sheet as a square PNG (cell px each). Negative `time` = a fraction of the clip length. */
export function previewSheet(spec: RigSpec, layout: SkinLayout, skin: Raster, opts: { cell?: number; cells?: PreviewCell[] } = {}): { png: Buffer; raster: Raster } {
  const cells = opts.cells ?? DEFAULT_CELLS;
  const cols = Math.ceil(Math.sqrt(cells.length));
  const cellSize = opts.cell ?? 200;
  const size = cols * cellSize;
  const canvas: Raster = { size, px: new Uint8ClampedArray(size * size * 4) };

