// Cyrus Model Studio, layer 2 (cuboid + bone editor): the editor's DOCUMENT MODEL. Our own design (not Blockbench's:
// it is GPL-3 and never embedded or copied). Pure + client-safe (zod + plain TS, no node: imports).
//
// The editor reads and writes RigSpec v1 (lib/cyrus/creature/spec.ts); this document is the richer working copy around
// it: every bone, cube and keyframe has a stable opaque id (merge + undo need them), cubes carry editor-only fields
// (label, rotation, pivot, UV pin, hide/lock) that RigSpec v1 cannot hold yet (RigSpec v1.1 / rig-c2 = plan task F2).
// ./rigspec.ts converts both ways; ./validate.ts says exactly which editor-only fields a target would drop or refuse.
//
// Coordinates are RigSpec's: Blockbench-style units (16 = one block), ABSOLUTE (a cube's from/to are world rest-pose
// positions, not relative to its bone), y up, the creature faces north (-z). A cube's origin is `from`, its size is
// `to - from`; both corners are stored so a load -> save round trip is byte-stable (no float drift from origin + size).
import * as z from "zod";
import { ARCHETYPES, BASE_ENTITIES, BONE_RE, BONE_TAGS, CHANNELS, FACES, MAX_COORD, NAME_RE, PALETTE_KEY_RE, SOUND_ROLES, type Decal, type Face } from "../../creature/spec";

export const MODEL_DOC_VERSION = 1 as const;
/** Asset-row mime of a saved editor document (MODEL-STUDIO-PLAN "ModelDoc v1"). */
export const MODEL_DOC_MIME = "application/vnd.cyrus.modeldoc+json";
export const MAX_DOC_BYTES = 256 * 1024;

export type Vec3 = [number, number, number];
export type BoneTag = (typeof BONE_TAGS)[number];
export type Channel = (typeof CHANNELS)[number];
export type Ease = "linear" | "smooth";

export type EBone = {
  id: string;
  name: string;
  /** parent bone id; null = the root (RigSpec allows exactly one) */
  parent: string | null;
  pivot: Vec3;
  /** rest rotation, degrees, applied Z * Y * X around the pivot (Blockbench bone convention, = creature/preview.ts) */
  rotation: Vec3;
  tag: BoneTag;
  hidden?: boolean;
  locked?: boolean;
};

export type ECube = {
  id: string;
  /** owning bone id */
  bone: string;
  /** editor-only label (RigSpec cubes have no names; the compiler names them <bone>_<index>) */
  label?: string;
  from: Vec3;
  to: Vec3;
  /** editor-only: cube rotation (degrees, Z * Y * X around `pivot`). RigSpec v1 cannot hold it (validate.ts refuses). */
  rotation: Vec3;
  /** editor-only: the cube's own rotation pivot (defaults to its centre) */
  pivot: Vec3;
  inflate: number;
  material: string;
  shade: "solid" | "fade";
  fadeTo?: string;
  /** texture slot key (./doc textures); RigSpec v1 has one skin, so every cube uses "skin" */
  texture: string;
  /** UV box origin on the sheet, pinned by the user; null = auto-pack (the compiler's shelf layout) */
  uv: [number, number] | null;
  decals?: Partial<Record<Face, Decal[]>>;
  hidden?: boolean;
  locked?: boolean;
};

export type EKey = { id: string; t: number; v: Vec3; ease: Ease };
export type EWave = { amp: Vec3; offset?: Vec3; cycles: number; phase: number };
export type ETrack = { bone: string; channel: Channel; wave?: EWave; keys?: EKey[] };
export type EClip = { name: string; length: number; loop: boolean; tracks: ETrack[] };
export type TextureSlot = { key: string; size: 64 | 128 | null; path: string };

export type ModelMeta = {
  displayName?: string;
  archetype: (typeof ARCHETYPES)[number];
  scale: number;
  hitbox: { width: number; height: number };
  baseEntity: (typeof BASE_ENTITIES)[number];
  sounds: Partial<Record<(typeof SOUND_ROLES)[number], string>>;
};

export type ModelDoc = {
  v: typeof MODEL_DOC_VERSION;
  kind: "creature";
  name: string;
  meta: ModelMeta;
  palette: Record<string, string>;
  textures: TextureSlot[];
  bones: EBone[];
  cubes: ECube[];
  clips: EClip[];
  /** id counter: every new node takes the next number, so replaying the same ops gives the same ids */
  seq: number;
};

// ------------------------------------------------------------------------------------------------ untrusted docs ----
const coord = z.number().min(-MAX_COORD).max(MAX_COORD);
const V3 = z.tuple([coord, coord, coord]);
const Ang = z.tuple([z.number().min(-360).max(360), z.number().min(-360).max(360), z.number().min(-360).max(360)]);
const Ampl = z.tuple([z.number().min(-180).max(180), z.number().min(-180).max(180), z.number().min(-180).max(180)]);
export const ID_RE = /^[bck][1-9][0-9]{0,5}$/;
const id = (p: "b" | "c" | "k") => z.string().regex(ID_RE).refine((s) => s[0] === p, `${p}-id expected`);
const pal = z.string().regex(PALETTE_KEY_RE);
const px = z.number().int().min(0).max(127);
const DecalZ = z.discriminatedUnion("op", [
  z.object({ op: z.literal("px"), x: px, y: px, c: pal }).strict(),
  z.object({ op: z.literal("rect"), x: px, y: px, w: z.number().int().min(1).max(128), h: z.number().int().min(1).max(128), c: pal }).strict(),
  z.object({ op: z.literal("line"), x1: px, y1: px, x2: px, y2: px, c: pal }).strict(),
]);
const BoneZ = z.object({
  id: id("b"), name: z.string().max(40), parent: id("b").nullable(), pivot: V3, rotation: Ang, tag: z.enum(BONE_TAGS),
  hidden: z.boolean().optional(), locked: z.boolean().optional(),
}).strict();
const CubeZ = z.object({
  id: id("c"), bone: id("b"), label: z.string().max(40).optional(), from: V3, to: V3, rotation: Ang, pivot: V3,
  inflate: z.number().min(0).max(1), material: pal, shade: z.enum(["solid", "fade"]), fadeTo: pal.optional(), texture: pal,
  uv: z.tuple([z.number().int().min(0).max(255), z.number().int().min(0).max(255)]).nullable(),
  decals: z.partialRecord(z.enum(FACES), z.array(DecalZ).max(24)).optional(), hidden: z.boolean().optional(), locked: z.boolean().optional(),
}).strict();
const KeyZ = z.object({ id: id("k"), t: z.number().min(0).max(1), v: Ang, ease: z.enum(["linear", "smooth"]) }).strict();
const WaveZ = z.object({ amp: Ampl, offset: Ampl.optional(), cycles: z.number().int().min(1).max(8), phase: z.number().min(0).max(1) }).strict();
const TrackZ = z.object({ bone: id("b"), channel: z.enum(CHANNELS), wave: WaveZ.optional(), keys: z.array(KeyZ).max(64).optional() }).strict();
const ClipZ = z.object({ name: z.string().max(40), length: z.number().min(0.1).max(10), loop: z.boolean(), tracks: z.array(TrackZ).max(64) }).strict();
const SlotZ = z.object({ key: pal, size: z.union([z.literal(64), z.literal(128), z.null()]), path: z.string().max(200) }).strict();
export const ModelDocSchema = z.object({
  v: z.literal(MODEL_DOC_VERSION),
  kind: z.literal("creature"),
  name: z.string().regex(NAME_RE),
  meta: z.object({
    displayName: z.string().min(2).max(40).optional(),
    archetype: z.enum(ARCHETYPES),
    scale: z.number().min(0.4).max(3),
    hitbox: z.object({ width: z.number().min(0.3).max(3), height: z.number().min(0.3).max(4) }).strict(),
    baseEntity: z.enum(BASE_ENTITIES),
    sounds: z.partialRecord(z.enum(SOUND_ROLES), z.string().max(80)),
  }).strict(),
  palette: z.record(pal, z.string().regex(/^#[0-9a-f]{6}$/)),
  textures: z.array(SlotZ).min(1).max(4),
  // generous structural caps (the RigSpec limits are validate.ts issues, so an over-budget draft can still be opened)
  bones: z.array(BoneZ).max(96),
  cubes: z.array(CubeZ).max(192),
  clips: z.array(ClipZ).max(16),
  seq: z.number().int().min(0).max(999999),
}).strict();

export type DocCheck = { ok: true; doc: ModelDoc } | { ok: false; error: string };

/** Parse an untrusted ModelDoc (API body, draft, asset row). Never throws. Structural only: see validate.ts for rules. */
export function checkModelDoc(raw: unknown): DocCheck {
  let bytes = 0;
  try { bytes = JSON.stringify(raw ?? null).length; } catch { return { ok: false, error: "the model document is not JSON" }; }
  if (bytes > MAX_DOC_BYTES) return { ok: false, error: `the model document is larger than ${MAX_DOC_BYTES / 1024} KB` };
  const p = ModelDocSchema.safeParse(raw);
  if (!p.success) {
    const i = p.error.issues[0];
    return { ok: false, error: `${i.path.map(String).join(".") || "doc"}: ${i.message}` };
  }
  return { ok: true, doc: p.data as ModelDoc };
}

// ------------------------------------------------------------------------------------------------------ helpers ----
export const size = (c: Pick<ECube, "from" | "to">): Vec3 => [c.to[0] - c.from[0], c.to[1] - c.from[1], c.to[2] - c.from[2]];
export const centre = (c: Pick<ECube, "from" | "to">): Vec3 => [(c.from[0] + c.to[0]) / 2, (c.from[1] + c.to[1]) / 2, (c.from[2] + c.to[2]) / 2];
/** Round to 1e-4 and kill -0 (the compiler's own rounding), so edited numbers serialise identically. */
export const r4 = (v: number) => { const x = Math.round(v * 10000) / 10000; return Object.is(x, -0) ? 0 : x; };
export const r4v = (v: readonly number[]): Vec3 => [r4(v[0]), r4(v[1]), r4(v[2])];
export const isZero = (v: readonly number[]) => v.every((x) => x === 0);

export const boneById = (d: ModelDoc, id: string) => d.bones.find((b) => b.id === id);
export const cubeById = (d: ModelDoc, id: string) => d.cubes.find((c) => c.id === id);
export const boneByName = (d: ModelDoc, name: string) => d.bones.find((b) => b.name === name);
export const cubesOf = (d: ModelDoc, boneId: string) => d.cubes.filter((c) => c.bone === boneId);
export const childrenOf = (d: ModelDoc, boneId: string | null) => d.bones.filter((b) => b.parent === boneId);
export const rootBone = (d: ModelDoc) => d.bones.find((b) => b.parent === null);

/** The bone and every bone under it (depth first, document order). Cycle-safe. */
export function subtree(d: ModelDoc, boneId: string): string[] {
  const out: string[] = [];
  const seen = new Set<string>();
  const walk = (id: string) => {
    if (seen.has(id)) return;
    seen.add(id); out.push(id);
    for (const c of childrenOf(d, id)) walk(c.id);
  };
  walk(boneId);
  return out;
}

/** Depth of a bone (root = 0); -1 when its parent chain is broken or cyclic. */
export function depthOf(d: ModelDoc, boneId: string): number {
  let n = 0, cur = boneById(d, boneId);
  const seen = new Set<string>();
  while (cur && cur.parent !== null) {
    if (seen.has(cur.id)) return -1;
    seen.add(cur.id);
    cur = boneById(d, cur.parent);
    if (!cur) return -1;
    n++;
  }
  return cur ? n : -1;
}

/** Allocate the next id of a kind (b = bone, c = cube, k = key). Returns the new doc seq too. */
export function nextId(seq: number, kind: "b" | "c" | "k"): { id: string; seq: number } {
  const n = seq + 1;
  return { id: `${kind}${n}`, seq: n };
}

/** A bone name not taken yet: `base`, else base_2, base_3 ... (cut to the 24-char RigSpec limit). */
export function freeBoneName(d: ModelDoc, base: string): string {
  const clean = (base.toLowerCase().replace(/[^a-z0-9_]/g, "_").replace(/^[^a-z]+/, "") || "bone").slice(0, 24);
  if (!boneByName(d, clean)) return clean;
  for (let i = 2; i < 1000; i++) {
    const s = `_${i}`;
    const n = clean.slice(0, 24 - s.length) + s;
    if (!boneByName(d, n)) return n;
  }
  return clean;
}

export const validBoneName = (n: string) => BONE_RE.test(n);

/** A track's rest value: rotation/position offsets are 0, scale is a factor of 1. */
export const restValue = (ch: Channel): Vec3 => (ch === "scale" ? [1, 1, 1] : [0, 0, 0]);

