// Model Studio L2: RigSpec v1 <-> ModelDoc. Pure + client-safe.
//   fromRigSpec(spec)            a validated, expanded RigSpec (creature/spec.ts checkRigSpec) -> a fresh document
//   fromRigSpec(spec, { like })  the same, but every bone / cube / key that matches a node of `like` keeps that node's
//                                id and editor-only fields (how an AI candidate built from revision R is lined up with R
//                                for the 3-way merge, ./merge.ts; RigSpec v1 has no ids of its own)
//   toRigSpec(doc)               -> the explicit-form RigSpec input the compiler and the build service read, plus the
//                                editor-only fields it had to leave out (validate.ts turns those into issues)
// Matching rules for `like` (documented, deterministic): bones by name; cubes inside a matched bone by identical
// from/to/material first, then by position among the still-unmatched ones; keys by (clip, bone, channel, t).
import type { RigSpec, RigSpecInput } from "../../creature/spec";
import { centre, nextId, type EBone, type EClip, type ECube, type EKey, type ETrack, type ModelDoc, type Vec3 } from "./doc";

const v3 = (v: readonly number[] | undefined, d: Vec3 = [0, 0, 0]): Vec3 => (v ? [v[0], v[1], v[2]] : [...d] as Vec3);
const same = (a: readonly number[], b: readonly number[]) => a.length === b.length && a.every((x, i) => x === b[i]);
export const skinPath = (name: string) => `assets/creatures/${name}.png`;

export function fromRigSpec(spec: RigSpec, opts: { like?: ModelDoc } = {}): ModelDoc {
  const like = opts.like;
  let seq = like?.seq ?? 0;
  const take = (k: "b" | "c" | "k") => { const n = nextId(seq, k); seq = n.seq; return n.id; };

  // bones
  const likeBone = new Map((like?.bones ?? []).map((b) => [b.name, b]));
  const boneId = new Map<string, string>();
  for (const b of spec.bones) boneId.set(b.name, likeBone.get(b.name)?.id ?? "");
  // allocate new ids in document order (deterministic)
  for (const b of spec.bones) if (!boneId.get(b.name)) boneId.set(b.name, take("b"));
  const bones: EBone[] = spec.bones.map((b) => {
    const prev = likeBone.get(b.name);
    return {
      id: boneId.get(b.name)!, name: b.name, parent: b.parent === null ? null : boneId.get(b.parent) ?? null,
      pivot: v3(b.pivot), rotation: v3(b.rotation), tag: b.tag,
      ...(prev?.hidden ? { hidden: true } : {}), ...(prev?.locked ? { locked: true } : {}),
    };
  });

  // cubes
  const cubes: ECube[] = [];
  for (const b of spec.bones) {
    const bid = boneId.get(b.name)!;
    const pool = (like?.cubes ?? []).filter((c) => likeBone.get(b.name) && c.bone === likeBone.get(b.name)!.id);
    const used = new Set<string>();
    const exact = b.cubes.map((c) => {
      const m = pool.find((p) => !used.has(p.id) && same(p.from, c.from) && same(p.to, c.to) && p.material === c.material);
      if (m) used.add(m.id);
      return m;
    });
    const matched = exact.map((m) => m);
    for (let i = 0; i < b.cubes.length; i++) if (!matched[i]) {
      const m = pool.find((p) => !used.has(p.id));
      if (m) { used.add(m.id); matched[i] = m; }
    }
    b.cubes.forEach((c, i) => {
      const prev = matched[i];
      const from = v3(c.from), to = v3(c.to);
      const geomSame = prev && same(prev.from, from) && same(prev.to, to);
      cubes.push({
        id: prev?.id ?? "", bone: bid, ...(prev?.label ? { label: prev.label } : {}), from, to,
        // editor-only fields survive a match (RigSpec v1 cannot carry them); a moved cube keeps its rotation but its
        // pivot follows the new geometry when the old pivot was the default centre
        rotation: prev ? v3(prev.rotation) : [0, 0, 0],
        pivot: prev && (geomSame || !same(prev.pivot, centre(prev))) ? v3(prev.pivot) : centre({ from, to }),
        inflate: c.inflate, material: c.material, shade: c.shade, ...(c.fadeTo ? { fadeTo: c.fadeTo } : {}),
        texture: prev?.texture ?? "skin", uv: prev?.uv ?? null,
        ...(c.decals ? { decals: JSON.parse(JSON.stringify(c.decals)) } : {}),
        ...(prev?.hidden ? { hidden: true } : {}), ...(prev?.locked ? { locked: true } : {}),
      });
    });
  }
  for (const c of cubes) if (!c.id) c.id = take("c");

  // clips (order kept: it is the compiler's output order)
  const likeKeys = new Map<string, EKey[]>();
  for (const cl of like?.clips ?? []) for (const t of cl.tracks) for (const k of t.keys ?? []) {
    const key = `${cl.name}|${t.bone}|${t.channel}|${k.t}`;
    likeKeys.set(key, [...(likeKeys.get(key) ?? []), k]);
  }
  const usedKeys = new Set<string>();
  const clips: EClip[] = Object.entries(spec.animations).map(([name, clip]) => ({
    name, length: clip.length, loop: clip.loop,
    tracks: clip.tracks.map((t): ETrack => {
      const bone = boneId.get(t.bone) ?? "";
      if (t.wave) return { bone, channel: t.channel, wave: { amp: v3(t.wave.amp), ...(t.wave.offset ? { offset: v3(t.wave.offset) } : {}), cycles: t.wave.cycles, phase: t.wave.phase } };
      return {
        bone, channel: t.channel,
        keys: (t.keys ?? []).map((k) => {
          const prev = (likeKeys.get(`${name}|${bone}|${t.channel}|${k.t}`) ?? []).find((p) => !usedKeys.has(p.id));
          if (prev) usedKeys.add(prev.id);
          return { id: prev?.id ?? "", t: k.t, v: v3(k.v), ease: k.ease };
        }),
      };
    }),
  }));
  for (const cl of clips) for (const t of cl.tracks) for (const k of t.keys ?? []) if (!k.id) k.id = take("k");

  return {
    v: 1, kind: "creature", name: spec.name,
    meta: {
      ...(spec.displayName ? { displayName: spec.displayName } : {}), archetype: spec.archetype, scale: spec.scale,
      hitbox: { width: spec.hitbox.width, height: spec.hitbox.height }, baseEntity: spec.baseEntity, sounds: { ...spec.sounds },
    },
    palette: { ...spec.skin.palette },
    textures: like?.textures?.length ? like.textures.map((t) => ({ ...t, ...(t.key === "skin" ? { size: spec.skin.size ?? null } : {}) })) : [{ key: "skin", size: spec.skin.size ?? null, path: skinPath(spec.name) }],
    bones, cubes, clips, seq,
  };
}

/** Editor-only content toRigSpec had to leave out (each is a validate.ts issue for the RigSpec target). */
export type Dropped = { node: string; field: "rotation" | "uv" | "texture" | "pivot"; note: string };

/** ModelDoc -> explicit-form RigSpec v1 input (what checkRigSpec + compileCreature read). Never throws. */
export function toRigSpec(doc: ModelDoc): { spec: RigSpecInput; dropped: Dropped[] } {
  const dropped: Dropped[] = [];
  const name = new Map(doc.bones.map((b) => [b.id, b.name]));
  const bones = doc.bones.map((b) => ({
    name: b.name,
    parent: b.parent === null ? null : name.get(b.parent) ?? b.parent,
    pivot: v3(b.pivot),
    ...(b.rotation.some((x) => x !== 0) ? { rotation: v3(b.rotation) } : {}),
    tag: b.tag,
    cubes: doc.cubes.filter((c) => c.bone === b.id).map((c) => {
      if (c.rotation.some((x) => x !== 0)) dropped.push({ node: c.id, field: "rotation", note: "cube rotation" });
      if (c.uv) dropped.push({ node: c.id, field: "uv", note: "pinned UV box" });
      if (c.texture !== "skin") dropped.push({ node: c.id, field: "texture", note: `texture slot ${c.texture}` });
      return {
        from: v3(c.from), to: v3(c.to), material: c.material, shade: c.shade, ...(c.fadeTo ? { fadeTo: c.fadeTo } : {}), inflate: c.inflate,
        ...(c.decals ? { decals: JSON.parse(JSON.stringify(c.decals)) } : {}),
      };
    }),
  }));
  const animations: Record<string, unknown> = {};
  for (const cl of doc.clips) {
    animations[cl.name] = {
      length: cl.length, loop: cl.loop,
      tracks: cl.tracks.map((t) => ({
        bone: name.get(t.bone) ?? t.bone, channel: t.channel,
        ...(t.wave ? { wave: { amp: v3(t.wave.amp), ...(t.wave.offset ? { offset: v3(t.wave.offset) } : {}), cycles: t.wave.cycles, phase: t.wave.phase } } : {}),
        ...(t.keys ? { keys: t.keys.map((k) => ({ t: k.t, v: v3(k.v), ease: k.ease })) } : {}),
      })),
    };
  }
  const skinSize = doc.textures.find((t) => t.key === "skin")?.size ?? null;
  const spec = {
    version: 1 as const, name: doc.name, ...(doc.meta.displayName ? { displayName: doc.meta.displayName } : {}), archetype: doc.meta.archetype,
    scale: doc.meta.scale, hitbox: { ...doc.meta.hitbox }, baseEntity: doc.meta.baseEntity,
    skin: { ...(skinSize ? { size: skinSize } : {}), palette: { ...doc.palette } },
    bones, animations, sounds: { ...doc.meta.sounds },
  } as RigSpecInput;
  return { spec, dropped };
}

