/** World matrix of a cube (its bone's matrix, then its own editor-only rotation about its pivot). */
export function cubeMatrix(doc: ModelDoc, bones: Map<string, M4>, cubeId: string): M4 {
  const c = cubeById(doc, cubeId)!;
