// Model Studio L2: the editor OPERATIONS (the v1 cut line of MODEL-STUDIO-PLAN section 3). Pure + client-safe.
// Every user action is one serialisable Op; applyOp(doc, op) returns a NEW document (inputs are never mutated) or a
// refusal with a reason. Ops carry everything they need (target ids, values, the snap step), so replaying the same
// op list on the same base always gives byte-identical documents (./history.ts relies on it).
//
// v1:    add / delete / duplicate / mirror X (paired _l/_r), move / rotate / resize / scale with snapping, reparent,
//        pivot edit, UV box pin / auto-UV, rename, hide / lock, group, material / shade / inflate / tag, palette,
//        clips + keys (set / delete / move / ease, wave -> keys), replace (an accepted AI merge = one step)
// later: multi-select box/lasso, free item rotation rules, IK/constraints (never: new rigging tools), per-face UV
//        editing beyond box UV, UV pack optimiser, onion skin, curve editor
import { FACES, MAX_CLIPS, MAX_KEYS_PER_TRACK, PALETTE_KEY_RE, faceSize, type Decal, type Face } from "../../creature/spec";
import {
  boneById, centre, childrenOf, cubeById, freeBoneName, nextId, r4, r4v, restValue, size, subtree, validBoneName,
  type BoneTag, type Channel, type Ease, type EBone, type EClip, type ECube, type EKey, type ETrack, type ModelDoc, type Vec3,
} from "./doc";
import { sampleTrack } from "./pose";

export const CLIP_RE = /^[a-z][a-z0-9_]{1,23}$/;
/** Default move/resize grid: 1 unit = 1/16 block (MODEL-STUDIO-PLAN "1/16 snap"). */
export const DEFAULT_SNAP = 1;
export const SNAP_STEPS = [0, 0.25, 0.5, 1, 2] as const;
export const ANGLE_SNAPS = [0, 2.5, 5, 15, 22.5, 45] as const;

export type Op =
  | { op: "addBone"; parent: string; name?: string; pivot?: Vec3 }
  | { op: "addCube"; bone: string; from?: Vec3; size?: Vec3; material?: string }
  | { op: "delete"; ids: string[] }
  | { op: "duplicate"; ids: string[] }
  | { op: "mirror"; ids: string[]; animations?: boolean }
  | { op: "move"; ids: string[]; delta: Vec3; snap?: number }
  | { op: "rotate"; ids: string[]; rotation: Vec3; mode: "set" | "add"; snap?: number }
  | { op: "resize"; id: string; size: Vec3; snap?: number }
  | { op: "scale"; ids: string[]; factor: number; about?: Vec3 }
  | { op: "setPivot"; id: string; pivot: Vec3; snap?: number }
  | { op: "reparent"; id: string; parent: string }
  | { op: "setCube"; id: string; props: { material?: string; shade?: "solid" | "fade"; fadeTo?: string | null; inflate?: number } }
  | { op: "setBone"; id: string; props: { tag?: BoneTag } }
  | { op: "setUv"; id: string; uv: [number, number] | null }
  | { op: "autoUv"; ids?: string[] }
  | { op: "rename"; id: string; name: string }
  | { op: "setFlag"; ids: string[]; flag: "hidden" | "locked"; value: boolean }
  | { op: "group"; ids: string[]; name?: string }
  | { op: "setPalette"; key: string; color: string | null }
  | { op: "setKey"; clip: string; bone: string; channel: Channel; t: number; v: Vec3; ease?: Ease }
  | { op: "deleteKey"; clip: string; key: string }
  | { op: "moveKey"; clip: string; key: string; t: number }
  | { op: "setEase"; clip: string; key: string; ease: Ease }
  | { op: "deleteTrack"; clip: string; bone: string; channel: Channel }
  | { op: "waveToKeys"; clip: string; bone: string; channel: Channel }
  | { op: "addClip"; name: string; length: number; loop: boolean }
  | { op: "setClip"; name: string; length?: number; loop?: boolean; rename?: string }
  | { op: "deleteClip"; name: string }
  | { op: "replace"; doc: ModelDoc; label: string };

export type OpResult = { ok: true; doc: ModelDoc; label: string; select?: string[] } | { ok: false; error: string };

const fail = (error: string): OpResult => ({ ok: false, error });
const finite = (v: readonly number[]) => v.length === 3 && v.every((x) => Number.isFinite(x));
const snapTo = (v: number, s?: number) => (s && s > 0 ? r4(Math.round(v / s) * s) : r4(v));
const normAngle = (a: number) => { let x = ((a + 180) % 360 + 360) % 360 - 180; if (x === -180) x = 180; return r4(x); };
const add3 = (a: readonly number[], b: readonly number[]): Vec3 => [a[0] + b[0], a[1] + b[1], a[2] + b[2]];
const sub3 = (a: readonly number[], b: readonly number[]): Vec3 => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
const isCentred = (c: ECube) => c.pivot.every((p, i) => Math.abs(p - centre(c)[i]) < 1e-9);
const nameOf = (d: ModelDoc, id: string) => boneById(d, id)?.name ?? (cubeById(d, id) ? cubeLabel(d, id) : id);

/** "cube 0" style label (position inside its bone) unless the cube has its own label. */
export function cubeLabel(d: ModelDoc, id: string): string {
  const c = cubeById(d, id);
  if (!c) return id;
  if (c.label) return c.label;
  return `cube ${d.cubes.filter((x) => x.bone === c.bone).findIndex((x) => x.id === id)}`;
}

function lockedIn(d: ModelDoc, ids: Iterable<string>): string | null {
  for (const id of ids) {
    const n = boneById(d, id) ?? cubeById(d, id);
    if (n?.locked) return nameOf(d, id);
  }
  return null;
}
/** Every node an edit of `ids` touches: a bone drags its whole subtree (bones + cubes) along. */
function affected(d: ModelDoc, ids: string[]): { bones: Set<string>; cubes: Set<string> } {
  const bones = new Set<string>(), cubes = new Set<string>();
  for (const id of ids) {
    if (boneById(d, id)) for (const b of subtree(d, id)) bones.add(b);
    else if (cubeById(d, id)) cubes.add(id);
  }
  for (const c of d.cubes) if (bones.has(c.bone)) cubes.add(c.id);
  return { bones, cubes };
}
function known(d: ModelDoc, ids: string[]): string | null {
  if (!ids.length) return "select something first";
  for (const id of ids) if (!boneById(d, id) && !cubeById(d, id)) return `unknown node ${id}`;
  return null;
}
const withSeq = (d: ModelDoc) => { let seq = d.seq; return { take: (k: "b" | "c" | "k") => { const n = nextId(seq, k); seq = n.seq; return n.id; }, seq: () => seq }; };
const clipOf = (d: ModelDoc, name: string) => d.clips.find((c) => c.name === name);
const trackOf = (cl: EClip, bone: string, ch: Channel) => cl.tracks.find((t) => t.bone === bone && t.channel === ch);
const mapClips = (d: ModelDoc, name: string, fn: (c: EClip) => EClip) => d.clips.map((c) => (c.name === name ? fn(c) : c));

// ----------------------------------------------------------------------------------------------- mirror helpers ----
const mirrorName = (n: string) => (/_l$/.test(n) ? n.replace(/_l$/, "_r") : /_r$/.test(n) ? n.replace(/_r$/, "_l") : /left/.test(n) ? n.replace(/left/, "right") : /right/.test(n) ? n.replace(/right/, "left") : null);
const mirrorRot = (r: readonly number[]): Vec3 => r4v([r[0], -r[1], -r[2]]);
const mirrorX = (v: readonly number[]): Vec3 => r4v([-v[0], v[1], v[2]]);
function mirrorDecals(c: ECube, decals: ECube["decals"]): ECube["decals"] {
  if (!decals) return undefined;
  const out: Partial<Record<Face, Decal[]>> = {};
  for (const f of FACES) {
    const list = decals[f];
    if (!list) continue;
    const to: Face = f === "east" ? "west" : f === "west" ? "east" : f;
    const [fw] = faceSize(c, to);
    out[to] = list.map((dc) => (dc.op === "px" ? { ...dc, x: fw - 1 - dc.x } : dc.op === "rect" ? { ...dc, x: Math.max(0, fw - dc.x - dc.w) } : { ...dc, x1: fw - 1 - dc.x1, x2: fw - 1 - dc.x2 }));
  }
  return out;
}
function mirrorCube(c: ECube, id: string, bone: string): ECube {
  const from: Vec3 = r4v([-c.to[0], c.from[1], c.from[2]]), to: Vec3 = r4v([-c.from[0], c.to[1], c.to[2]]);
  const m: ECube = { ...c, id, bone, from, to, rotation: mirrorRot(c.rotation), pivot: mirrorX(c.pivot), uv: null };
  delete m.label; delete m.locked; delete m.hidden;
  const dec = mirrorDecals(m, c.decals);
  if (dec) m.decals = dec; else delete m.decals;
  return m;
}
function mirrorTrack(t: ETrack, bone: string, take: (k: "k") => string): ETrack {
  const tf = (v: readonly number[]): Vec3 => (t.channel === "rotation" ? mirrorRot(v) : t.channel === "position" ? mirrorX(v) : r4v(v));
  if (t.wave) return { bone, channel: t.channel, wave: { ...t.wave, amp: tf(t.wave.amp), ...(t.wave.offset ? { offset: tf(t.wave.offset) } : {}) } };
  return { bone, channel: t.channel, keys: (t.keys ?? []).map((k) => ({ ...k, id: take("k"), v: tf(k.v) })) };
}

// ------------------------------------------------------------------------------------------------------- apply ----
export function applyOp(d: ModelDoc, op: Op): OpResult {
  try { return applyInner(d, op); } catch (e) { return fail(`could not apply ${op.op}: ${(e as Error).message}`); }
}

function applyInner(d: ModelDoc, op: Op): OpResult {
  switch (op.op) {
    case "addBone": {
      const parent = boneById(d, op.parent);
      if (!parent) return fail("pick the bone the new bone hangs from");
      if (op.pivot && !finite(op.pivot)) return fail("bad pivot");
      const s = withSeq(d);
      const name = op.name ? op.name : freeBoneName(d, "bone");
      if (!validBoneName(name)) return fail("bone names are 1-24 lowercase letters, digits and underscores");
      if (d.bones.some((b) => b.name === name)) return fail(`there is already a bone called ${name}`);
      const bone: EBone = { id: s.take("b"), name, parent: parent.id, pivot: r4v(op.pivot ?? parent.pivot), rotation: [0, 0, 0], tag: "none" };
      const at = d.bones.findIndex((b) => b.id === subtree(d, parent.id).at(-1)) + 1;
      return { ok: true, doc: { ...d, bones: [...d.bones.slice(0, at), bone, ...d.bones.slice(at)], seq: s.seq() }, label: `Add bone ${name}`, select: [bone.id] };
    }
    case "addCube": {
      const bone = boneById(d, op.bone);
      if (!bone) return fail("pick the bone the cube belongs to");
      if (bone.locked) return fail(`${bone.name} is locked`);
      const sz = op.size ?? [4, 4, 4];
      const from = op.from ?? r4v(sub3(bone.pivot, [sz[0] / 2, 0, sz[2] / 2]));
      if (!finite(from) || !finite(sz) || sz.some((v) => v <= 0)) return fail("bad cube size");
      const material = op.material ?? d.cubes.find((c) => c.bone === bone.id)?.material ?? Object.keys(d.palette)[0];
      if (!material || !(material in d.palette)) return fail("add a palette colour first");
      const s = withSeq(d);
      const to = r4v(add3(from, sz));
      const cube: ECube = { id: s.take("c"), bone: bone.id, from: r4v(from), to, rotation: [0, 0, 0], pivot: r4v(centre({ from, to })), inflate: 0, material, shade: "solid", texture: "skin", uv: null };
      const last = d.cubes.map((c) => c.bone).lastIndexOf(bone.id);
      const at = last >= 0 ? last + 1 : d.cubes.length;
      return { ok: true, doc: { ...d, cubes: [...d.cubes.slice(0, at), cube, ...d.cubes.slice(at)], seq: s.seq() }, label: `Add cube to ${bone.name}`, select: [cube.id] };
    }
    case "delete": {
      const k = known(d, op.ids); if (k) return fail(k);
      const { bones, cubes } = affected(d, op.ids);
      const lk = lockedIn(d, [...bones, ...cubes]); if (lk) return fail(`${lk} is locked`);
      if ([...bones].some((id) => boneById(d, id)!.parent === null)) return fail("the root bone can't be deleted (a creature needs one root)");
      const clips = d.clips.map((c) => ({ ...c, tracks: c.tracks.filter((t) => !bones.has(t.bone)) }));
      const what = op.ids.length === 1 ? nameOf(d, op.ids[0]) : `${op.ids.length} items`;
      return { ok: true, doc: { ...d, bones: d.bones.filter((b) => !bones.has(b.id)), cubes: d.cubes.filter((c) => !cubes.has(c.id)), clips }, label: `Delete ${what}`, select: [] };
    }
    case "duplicate": {
      const k = known(d, op.ids); if (k) return fail(k);
      const s = withSeq(d);
      let doc = d;
      const sel: string[] = [];
      for (const id of op.ids) {
        const c = cubeById(doc, id);
        if (c) {
          const copy: ECube = { ...c, id: s.take("c"), uv: null, ...(c.label ? { label: `${c.label} copy`.slice(0, 40) } : {}) };
          delete copy.locked;
          const at = doc.cubes.findIndex((x) => x.id === id) + 1;
          doc = { ...doc, cubes: [...doc.cubes.slice(0, at), copy, ...doc.cubes.slice(at)] };
          sel.push(copy.id);
          continue;
        }
        const b = boneById(doc, id)!;
        if (b.parent === null) return fail("the root bone can't be duplicated");
        const ids = subtree(doc, id);
        const map = new Map<string, string>();
        const newBones: EBone[] = [];
        let tmp = doc;
        for (const bid of ids) {
          const ob = boneById(doc, bid)!;
          const nid = s.take("b");
          map.set(bid, nid);
          const nb: EBone = { ...ob, id: nid, name: freeBoneName(tmp, ob.name), parent: bid === id ? ob.parent : map.get(ob.parent!) ?? ob.parent };
          delete nb.locked;
          newBones.push(nb);
          tmp = { ...tmp, bones: [...tmp.bones, nb] };
        }
        const newCubes = doc.cubes.filter((c) => map.has(c.bone)).map((c) => { const nc: ECube = { ...c, id: s.take("c"), bone: map.get(c.bone)!, uv: null }; delete nc.locked; return nc; });
        const at = doc.bones.findIndex((x) => x.id === ids.at(-1)) + 1;
        doc = { ...doc, bones: [...doc.bones.slice(0, at), ...newBones, ...doc.bones.slice(at)], cubes: [...doc.cubes, ...newCubes] };
        sel.push(map.get(id)!);
      }
      return { ok: true, doc: { ...doc, seq: s.seq() }, label: op.ids.length === 1 ? `Duplicate ${nameOf(d, op.ids[0])}` : `Duplicate ${op.ids.length} items`, select: sel };
    }
    case "mirror": {
      const k = known(d, op.ids); if (k) return fail(k);
      const s = withSeq(d);
      let doc = d;
      const sel: string[] = [];
      for (const id of op.ids) {
        const c = cubeById(doc, id);
        if (c) {
          const m = mirrorCube(c, s.take("c"), c.bone);
          const at = doc.cubes.findIndex((x) => x.id === id) + 1;
          doc = { ...doc, cubes: [...doc.cubes.slice(0, at), m, ...doc.cubes.slice(at)] };
          sel.push(m.id);
          continue;
        }
        const b = boneById(doc, id)!;
        if (b.parent === null) return fail("the root bone can't be mirrored; mirror one of its limbs");
        const ids = subtree(doc, id);
        const map = new Map<string, string>();
        const newBones: EBone[] = [];
        let tmp = doc;
        for (const bid of ids) {
          const ob = boneById(doc, bid)!;
          const paired = mirrorName(ob.name);
          const name = paired ?? freeBoneName(tmp, `${ob.name}_m`);
          if (tmp.bones.some((x) => x.name === name)) return fail(`${name} already exists; delete or rename it before mirroring ${ob.name}`);
          const nid = s.take("b");
          map.set(bid, nid);
          const nb: EBone = { ...ob, id: nid, name, parent: bid === id ? ob.parent : map.get(ob.parent!) ?? ob.parent, pivot: mirrorX(ob.pivot), rotation: mirrorRot(ob.rotation) };
          delete nb.locked; delete nb.hidden;
          newBones.push(nb);
          tmp = { ...tmp, bones: [...tmp.bones, nb] };
        }
        const newCubes = doc.cubes.filter((x) => map.has(x.bone)).map((x) => mirrorCube(x, s.take("c"), map.get(x.bone)!));
        const clips = op.animations === false ? doc.clips : doc.clips.map((cl) => ({ ...cl, tracks: [...cl.tracks, ...cl.tracks.filter((t) => map.has(t.bone)).map((t) => mirrorTrack(t, map.get(t.bone)!, s.take))] }));
        const at = doc.bones.findIndex((x) => x.id === ids.at(-1)) + 1;
        doc = { ...doc, bones: [...doc.bones.slice(0, at), ...newBones, ...doc.bones.slice(at)], cubes: [...doc.cubes, ...newCubes], clips };
        sel.push(map.get(id)!);
      }
      return { ok: true, doc: { ...doc, seq: s.seq() }, label: op.ids.length === 1 ? `Mirror ${nameOf(d, op.ids[0])} on X` : `Mirror ${op.ids.length} items on X`, select: sel };
    }
    case "move": {
      const k = known(d, op.ids); if (k) return fail(k);
      if (!finite(op.delta)) return fail("bad move");
      const { bones, cubes } = affected(d, op.ids);
      const lk = lockedIn(d, [...bones, ...cubes]); if (lk) return fail(`${lk} is locked`);
      // snap the FIRST target's reference point (a bone pivot or a cube origin) and move everything by the same amount
      const ref = boneById(d, op.ids[0])?.pivot ?? cubeById(d, op.ids[0])!.from;
      const eff = [0, 1, 2].map((i) => r4(snapTo(ref[i] + op.delta[i], op.snap) - ref[i])) as Vec3;
      if (eff.every((x) => x === 0)) return fail("nothing moved");
      return {
        ok: true, label: op.ids.length === 1 ? `Move ${nameOf(d, op.ids[0])}` : `Move ${op.ids.length} items`,
        doc: {
          ...d,
          bones: d.bones.map((b) => (bones.has(b.id) ? { ...b, pivot: r4v(add3(b.pivot, eff)) } : b)),
          cubes: d.cubes.map((c) => (cubes.has(c.id) ? { ...c, from: r4v(add3(c.from, eff)), to: r4v(add3(c.to, eff)), pivot: r4v(add3(c.pivot, eff)) } : c)),
        },
      };
    }
    case "rotate": {
      const k = known(d, op.ids); if (k) return fail(k);
      if (!finite(op.rotation)) return fail("bad rotation");
      const lk = lockedIn(d, op.ids); if (lk) return fail(`${lk} is locked`);
      const set = new Set(op.ids);
      const rot = (cur: Vec3): Vec3 => [0, 1, 2].map((i) => normAngle(snapTo(op.mode === "add" ? cur[i] + op.rotation[i] : op.rotation[i], op.snap))) as Vec3;
      return {
        ok: true, label: op.ids.length === 1 ? `Rotate ${nameOf(d, op.ids[0])}` : `Rotate ${op.ids.length} items`,
        doc: { ...d, bones: d.bones.map((b) => (set.has(b.id) ? { ...b, rotation: rot(b.rotation) } : b)), cubes: d.cubes.map((c) => (set.has(c.id) ? { ...c, rotation: rot(c.rotation) } : c)) },
      };
    }
    case "resize": {
      const c = cubeById(d, op.id);
      if (!c) return fail("pick a cube to resize");
      if (c.locked) return fail(`${cubeLabel(d, c.id)} is locked`);
      if (!finite(op.size)) return fail("bad size");
      const min = op.snap && op.snap > 0 ? op.snap : 0.25;
      const sz = op.size.map((v) => Math.max(min, snapTo(v, op.snap))) as Vec3;
      const to = r4v(add3(c.from, sz));
      const next: ECube = { ...c, to, pivot: isCentred(c) ? r4v(centre({ from: c.from, to })) : c.pivot };
      return { ok: true, label: `Resize ${cubeLabel(d, c.id)}`, doc: { ...d, cubes: d.cubes.map((x) => (x.id === c.id ? next : x)) } };
    }
    case "scale": {
      const k = known(d, op.ids); if (k) return fail(k);
      if (!(op.factor > 0.05 && op.factor < 20)) return fail("scale factor must be between 0.05 and 20");
      const { bones, cubes } = affected(d, op.ids);
      const lk = lockedIn(d, [...bones, ...cubes]); if (lk) return fail(`${lk} is locked`);
      const about = op.about ?? boneById(d, op.ids[0])?.pivot ?? centre(cubeById(d, op.ids[0])!);
      if (!finite(about)) return fail("bad scale centre");
      const sc = (p: readonly number[]): Vec3 => r4v([0, 1, 2].map((i) => about[i] + (p[i] - about[i]) * op.factor));
      return {
        ok: true, label: op.ids.length === 1 ? `Scale ${nameOf(d, op.ids[0])}` : `Scale ${op.ids.length} items`,
        doc: {
          ...d,
          bones: d.bones.map((b) => (bones.has(b.id) ? { ...b, pivot: sc(b.pivot) } : b)),
          cubes: d.cubes.map((c) => (cubes.has(c.id) ? { ...c, from: sc(c.from), to: sc(c.to), pivot: sc(c.pivot), inflate: r4(Math.min(1, c.inflate * op.factor)) } : c)),
        },
      };
    }
    case "setPivot": {
      if (!finite(op.pivot)) return fail("bad pivot");
      const p = op.pivot.map((v) => snapTo(v, op.snap)) as Vec3;
      const b = boneById(d, op.id);
      if (b) {
        if (b.locked) return fail(`${b.name} is locked`);
        return { ok: true, label: `Move pivot of ${b.name}`, doc: { ...d, bones: d.bones.map((x) => (x.id === b.id ? { ...x, pivot: p } : x)) } };
      }
      const c = cubeById(d, op.id);
      if (!c) return fail(`unknown node ${op.id}`);
      if (c.locked) return fail(`${cubeLabel(d, c.id)} is locked`);
      return { ok: true, label: `Move pivot of ${cubeLabel(d, c.id)}`, doc: { ...d, cubes: d.cubes.map((x) => (x.id === c.id ? { ...x, pivot: p } : x)) } };
    }
    case "reparent": {
      const parent = boneById(d, op.parent);
      if (!parent) return fail("drop it on a bone");
      const b = boneById(d, op.id);
      if (b) {
        if (b.parent === null) return fail("the root bone stays the root");
        if (subtree(d, b.id).includes(parent.id)) return fail(`${b.name} can't hang from its own child`);
        if (b.parent === parent.id) return fail("nothing changed");
        const lk = lockedIn(d, [b.id]); if (lk) return fail(`${lk} is locked`);
        return { ok: true, label: `Move ${b.name} under ${parent.name}`, doc: { ...d, bones: d.bones.map((x) => (x.id === b.id ? { ...x, parent: parent.id } : x)) } };
      }
      const c = cubeById(d, op.id);
      if (!c) return fail(`unknown node ${op.id}`);
      if (c.locked) return fail(`${cubeLabel(d, c.id)} is locked`);
      if (c.bone === parent.id) return fail("nothing changed");
      const rest = d.cubes.filter((x) => x.id !== c.id);
      const last = rest.map((x) => x.bone).lastIndexOf(parent.id);
      const at = last >= 0 ? last + 1 : rest.length;
      const moved = { ...c, bone: parent.id };
      return { ok: true, label: `Move ${cubeLabel(d, c.id)} to ${parent.name}`, doc: { ...d, cubes: [...rest.slice(0, at), moved, ...rest.slice(at)] } };
    }
    case "setCube": {
      const c = cubeById(d, op.id);
      if (!c) return fail(`unknown cube ${op.id}`);
      if (c.locked) return fail(`${cubeLabel(d, c.id)} is locked`);
      const pr = op.props;
      if (pr.material !== undefined && !(pr.material in d.palette)) return fail(`unknown palette colour ${pr.material}`);
      if (pr.fadeTo && !(pr.fadeTo in d.palette)) return fail(`unknown palette colour ${pr.fadeTo}`);
      if (pr.inflate !== undefined && !(pr.inflate >= 0 && pr.inflate <= 1)) return fail("inflate is 0-1 units");
      const next: ECube = { ...c, ...(pr.material !== undefined ? { material: pr.material } : {}), ...(pr.shade ? { shade: pr.shade } : {}), ...(pr.inflate !== undefined ? { inflate: r4(pr.inflate) } : {}) };
      if (pr.fadeTo === null) delete next.fadeTo; else if (pr.fadeTo) next.fadeTo = pr.fadeTo;
      if (next.shade === "fade" && !next.fadeTo) next.fadeTo = Object.keys(d.palette).find((k) => k !== next.material) ?? next.material;
      return { ok: true, label: `Edit ${cubeLabel(d, c.id)}`, doc: { ...d, cubes: d.cubes.map((x) => (x.id === c.id ? next : x)) } };
    }
    case "setBone": {
      const b = boneById(d, op.id);
      if (!b) return fail(`unknown bone ${op.id}`);
      if (b.locked) return fail(`${b.name} is locked`);
      if (op.props.tag === "head" && d.bones.some((x) => x.tag === "head" && x.id !== b.id)) return fail("only one bone can be the head; untag the other one first");
      return { ok: true, label: `Tag ${b.name} ${op.props.tag ?? b.tag}`, doc: { ...d, bones: d.bones.map((x) => (x.id === b.id ? { ...x, ...(op.props.tag ? { tag: op.props.tag } : {}) } : x)) } };
    }
    case "setUv": {
      const c = cubeById(d, op.id);
      if (!c) return fail(`unknown cube ${op.id}`);
      if (c.locked) return fail(`${cubeLabel(d, c.id)} is locked`);
      if (op.uv && !(op.uv.every((v) => Number.isInteger(v) && v >= 0 && v <= 255))) return fail("UV box origin is whole pixels on the sheet");
      return { ok: true, label: op.uv ? `Pin UV of ${cubeLabel(d, c.id)}` : `Auto UV for ${cubeLabel(d, c.id)}`, doc: { ...d, cubes: d.cubes.map((x) => (x.id === c.id ? { ...x, uv: op.uv ? [op.uv[0], op.uv[1]] : null } : x)) } };
    }
    case "autoUv": {
      const set = op.ids?.length ? new Set(op.ids) : null;
      if (!d.cubes.some((c) => c.uv && (!set || set.has(c.id)))) return fail("every UV box is already auto-packed");
      return { ok: true, label: "Auto-pack UV boxes", doc: { ...d, cubes: d.cubes.map((c) => (c.uv && (!set || set.has(c.id)) && !c.locked ? { ...c, uv: null } : c)) } };
    }
    case "rename": {
      const name = op.name.trim();
      const b = boneById(d, op.id);
      if (b) {
        if (!validBoneName(name)) return fail("bone names are 1-24 lowercase letters, digits and underscores");
        if (name === b.name) return fail("nothing changed");
        if (d.bones.some((x) => x.name === name)) return fail(`there is already a bone called ${name}`);
        return { ok: true, label: `Rename ${b.name} to ${name}`, doc: { ...d, bones: d.bones.map((x) => (x.id === b.id ? { ...x, name } : x)) } };
      }
      const c = cubeById(d, op.id);
      if (!c) return fail(`unknown node ${op.id}`);
      if (name.length > 40 || /[\u0000-\u001f<>]/.test(name)) return fail("cube labels are up to 40 plain characters");
      const next = { ...c };
      if (name) next.label = name; else delete next.label;
      return { ok: true, label: `Rename ${cubeLabel(d, c.id)}`, doc: { ...d, cubes: d.cubes.map((x) => (x.id === c.id ? next : x)) } };
    }
    case "setFlag": {
      const k = known(d, op.ids); if (k) return fail(k);
      const set = new Set(op.ids);
      const f = <N extends EBone | ECube>(n: N): N => { if (!set.has(n.id)) return n; const x = { ...n }; if (op.value) x[op.flag] = true; else delete x[op.flag]; return x; };
      return { ok: true, label: `${op.value ? (op.flag === "hidden" ? "Hide" : "Lock") : op.flag === "hidden" ? "Show" : "Unlock"} ${op.ids.length === 1 ? nameOf(d, op.ids[0]) : `${op.ids.length} items`}`, doc: { ...d, bones: d.bones.map(f), cubes: d.cubes.map(f) } };
    }
    case "group": {
      const k = known(d, op.ids); if (k) return fail(k);
      const lk = lockedIn(d, op.ids); if (lk) return fail(`${lk} is locked`);
      const cubes = op.ids.map((id) => cubeById(d, id)).filter((c): c is ECube => !!c);
      const bones = op.ids.map((id) => boneById(d, id)).filter((b): b is EBone => !!b);
      if (cubes.length && bones.length) return fail("group either cubes of one bone or bones with the same parent");
      const name = op.name ?? freeBoneName(d, "group");
      if (!validBoneName(name) || d.bones.some((b) => b.name === name)) return fail(`pick a free bone name (${name} is taken or invalid)`);
      const s = withSeq(d);
      const gid = s.take("b");
      if (cubes.length) {
        const owner = cubes[0].bone;
        if (cubes.some((c) => c.bone !== owner)) return fail("group cubes of one bone at a time");
        const lo = [0, 1, 2].map((i) => Math.min(...cubes.map((c) => c.from[i]))), hi = [0, 1, 2].map((i) => Math.max(...cubes.map((c) => c.to[i])));
        const g: EBone = { id: gid, name, parent: owner, pivot: r4v([(lo[0] + hi[0]) / 2, lo[1], (lo[2] + hi[2]) / 2]), rotation: [0, 0, 0], tag: "none" };
        const set = new Set(cubes.map((c) => c.id));
        const at = d.bones.findIndex((b) => b.id === owner) + 1;
        return { ok: true, label: `Group ${cubes.length} cube${cubes.length > 1 ? "s" : ""} as ${name}`, select: [gid], doc: { ...d, bones: [...d.bones.slice(0, at), g, ...d.bones.slice(at)], cubes: d.cubes.map((c) => (set.has(c.id) ? { ...c, bone: gid } : c)), seq: s.seq() } };
      }
      const parent = bones[0].parent;
      if (parent === null || bones.some((b) => b.parent !== parent)) return fail("group bones that share a parent (not the root)");
      const g: EBone = { id: gid, name, parent, pivot: [...bones[0].pivot] as Vec3, rotation: [0, 0, 0], tag: "none" };
      const set = new Set(bones.map((b) => b.id));
      const at = d.bones.findIndex((b) => set.has(b.id));
      const moved = d.bones.map((b) => (set.has(b.id) ? { ...b, parent: gid } : b));
      return { ok: true, label: `Group ${bones.length} bone${bones.length > 1 ? "s" : ""} as ${name}`, select: [gid], doc: { ...d, bones: [...moved.slice(0, at), g, ...moved.slice(at)], seq: s.seq() } };
    }
    case "setPalette": {
      if (!PALETTE_KEY_RE.test(op.key)) return fail("colour names are lowercase letters, digits and underscores");
      if (op.color === null) {
        if (!(op.key in d.palette)) return fail(`no colour ${op.key}`);
        if (d.cubes.some((c) => c.material === op.key || c.fadeTo === op.key || Object.values(c.decals ?? {}).some((l) => l?.some((x) => x.c === op.key)))) return fail(`${op.key} is still used by a cube`);
        const palette = { ...d.palette }; delete palette[op.key];
        return { ok: true, label: `Remove colour ${op.key}`, doc: { ...d, palette } };
      }
      if (!/^#[0-9a-fA-F]{6}$/.test(op.color)) return fail("colours are #rrggbb");
      return { ok: true, label: `${op.key in d.palette ? "Change" : "Add"} colour ${op.key}`, doc: { ...d, palette: { ...d.palette, [op.key]: op.color.toLowerCase() } } };
    }
    // -------------------------------------------------------------------------------------------- animation ----
    case "setKey": {
      const cl = clipOf(d, op.clip);
      if (!cl) return fail(`no clip ${op.clip}`);
      const b = boneById(d, op.bone);
      if (!b) return fail(`unknown bone ${op.bone}`);
      if (!finite(op.v) || !(op.t >= 0 && op.t <= 1)) return fail("bad key");
      const t = r4(op.t), v = r4v(op.v), ease = op.ease ?? "smooth";
      const s = withSeq(d);
      let track = trackOf(cl, b.id, op.channel);
      if (track?.wave) return fail(`${b.name} ${op.channel} is a wave; convert it to keys first`);
      let keys: EKey[] = track?.keys ? track.keys.map((k) => ({ ...k })) : [{ id: s.take("k"), t: 0, v: restValue(op.channel), ease: "smooth" }, { id: s.take("k"), t: 1, v: restValue(op.channel), ease: "smooth" }];
      const put = (tt: number) => {
        const i = keys.findIndex((k) => Math.abs(k.t - tt) < 1e-6);
        if (i >= 0) keys[i] = { ...keys[i], v, ease };
        else keys = [...keys, { id: s.take("k"), t: tt, v, ease }].sort((a, c) => a.t - c.t);
      };
      put(t);
      if (cl.loop && (t === 0 || t === 1)) put(t === 0 ? 1 : 0); // a looping clip ends where it starts
      if (keys.length > MAX_KEYS_PER_TRACK) return fail(`a track holds at most ${MAX_KEYS_PER_TRACK} keys`);
      track = { bone: b.id, channel: op.channel, keys };
      const tracks = trackOf(cl, b.id, op.channel) ? cl.tracks.map((x) => (x.bone === b.id && x.channel === op.channel ? track! : x)) : [...cl.tracks, track];
      return { ok: true, label: `Key ${b.name} ${op.channel} at ${Math.round(t * cl.length * 100) / 100}s`, doc: { ...d, clips: mapClips(d, cl.name, (c) => ({ ...c, tracks })), seq: s.seq() } };
    }
    case "deleteKey": case "moveKey": case "setEase": {
      const cl = clipOf(d, op.clip);
      if (!cl) return fail(`no clip ${op.clip}`);
      const tr = cl.tracks.find((t) => t.keys?.some((k) => k.id === op.key));
      if (!tr) return fail("unknown key");
      const keys = tr.keys!;
      const i = keys.findIndex((k) => k.id === op.key);
      const edge = i === 0 || i === keys.length - 1;
      let next: EKey[];
      if (op.op === "deleteKey") {
        if (edge) return fail("the first and last keys hold the clip's start and end; change their values instead");
        next = keys.filter((k) => k.id !== op.key);
      } else if (op.op === "moveKey") {
        if (edge) return fail("the first and last keys stay at the start and end of the clip");
        const t = r4(op.t);
        if (!(t > keys[i - 1].t && t < keys[i + 1].t)) return fail("a key can't move past its neighbours");
        next = keys.map((k) => (k.id === op.key ? { ...k, t } : k));
      } else next = keys.map((k) => (k.id === op.key ? { ...k, ease: op.ease } : k));
      const tracks = cl.tracks.map((t) => (t === tr ? { ...t, keys: next } : t));
      const bn = boneById(d, tr.bone)?.name ?? tr.bone;
      const label = op.op === "deleteKey" ? `Delete key on ${bn}` : op.op === "moveKey" ? `Move key on ${bn}` : `Ease ${op.ease} on ${bn}`;
      return { ok: true, label, doc: { ...d, clips: mapClips(d, cl.name, (c) => ({ ...c, tracks })) } };
    }
    case "deleteTrack": {
      const cl = clipOf(d, op.clip);
      if (!cl || !trackOf(cl, op.bone, op.channel)) return fail("no such track");
      return { ok: true, label: `Delete ${boneById(d, op.bone)?.name ?? op.bone} ${op.channel} track`, doc: { ...d, clips: mapClips(d, cl.name, (c) => ({ ...c, tracks: c.tracks.filter((t) => !(t.bone === op.bone && t.channel === op.channel)) })) } };
    }
    case "waveToKeys": {
      const cl = clipOf(d, op.clip);
      const tr = cl && trackOf(cl, op.bone, op.channel);
      if (!cl || !tr?.wave) return fail("that track is not a wave");
      const n = Math.min(MAX_KEYS_PER_TRACK - 1, 8 * tr.wave.cycles);
      const s = withSeq(d);
      const keys: EKey[] = [];
      for (let i = 0; i <= n; i++) keys.push({ id: s.take("k"), t: r4(i / n), v: r4v(sampleTrack(tr, cl, i === n && cl.loop ? 0 : (i / n) * cl.length)), ease: "smooth" });
      const tracks = cl.tracks.map((t) => (t === tr ? { bone: t.bone, channel: t.channel, keys } : t));
      return { ok: true, label: `Convert ${boneById(d, op.bone)?.name ?? op.bone} ${op.channel} wave to keys`, doc: { ...d, clips: mapClips(d, cl.name, (c) => ({ ...c, tracks })), seq: s.seq() } };
    }
    case "addClip": {
      if (!CLIP_RE.test(op.name)) return fail("clip names are 2-24 lowercase letters, digits and underscores");
      if (clipOf(d, op.name)) return fail(`there is already a clip called ${op.name}`);
      if (d.clips.length >= MAX_CLIPS) return fail(`a creature has at most ${MAX_CLIPS} clips`);
      if (!(op.length >= 0.1 && op.length <= 10)) return fail("clip length is 0.1-10 seconds");
      return { ok: true, label: `Add clip ${op.name}`, doc: { ...d, clips: [...d.clips, { name: op.name, length: r4(op.length), loop: op.loop, tracks: [] }] } };
    }
    case "setClip": {
      const cl = clipOf(d, op.name);
      if (!cl) return fail(`no clip ${op.name}`);
      if (op.length !== undefined && !(op.length >= 0.1 && op.length <= 10)) return fail("clip length is 0.1-10 seconds");
      if (op.rename !== undefined && (!CLIP_RE.test(op.rename) || (op.rename !== cl.name && clipOf(d, op.rename)))) return fail("pick a free clip name");
      const next = { ...cl, ...(op.length !== undefined ? { length: r4(op.length) } : {}), ...(op.loop !== undefined ? { loop: op.loop } : {}), ...(op.rename ? { name: op.rename } : {}) };
      return { ok: true, label: `Edit clip ${cl.name}`, doc: { ...d, clips: d.clips.map((c) => (c.name === cl.name ? next : c)) } };
    }
    case "deleteClip": {
      if (!clipOf(d, op.name)) return fail(`no clip ${op.name}`);
      return { ok: true, label: `Delete clip ${op.name}`, doc: { ...d, clips: d.clips.filter((c) => c.name !== op.name) } };
    }
    case "replace":
      return { ok: true, label: op.label.slice(0, 80), doc: op.doc };
    default:
      return fail(`unknown operation ${(op as { op?: string }).op}`);
  }
}

/** Apply ops in order; stops at the first refusal (returns how far it got). */
export function applyAll(d: ModelDoc, ops: readonly Op[]): { doc: ModelDoc; applied: number; error?: string } {
  let doc = d;
  for (let i = 0; i < ops.length; i++) {
    const r = applyOp(doc, ops[i]);
    if (!r.ok) return { doc, applied: i, error: r.error };
    doc = r.doc;
  }
  return { doc, applied: ops.length };
}

/** Size helper for the inspector (origin = from). */
export const cubeOriginSize = (c: ECube) => ({ origin: [...c.from] as Vec3, size: r4v(size(c)) });
export { childrenOf };

