// Model Studio L2: undo / redo as an OPERATION LOG with deterministic replay. Pure + client-safe.
// The log is { base, entries, at }: the document at step i is replay(base, entries[0..i)). A per-step document cache
// makes undo/redo O(1); replay() rebuilds any step from the base alone (the test suite proves both agree byte for byte).
// One gizmo drag, one field commit, one key, one accepted AI candidate = ONE entry (the UI previews drags outside the
// log and commits a single op on release). At most MAX_STEPS entries: older ones fold into the base.
import { canonicalJson } from "./canonical";
import { applyOp, type Op } from "./ops";
import type { ModelDoc } from "./doc";

export const MAX_STEPS = 200;

export type LogEntry = { op: Op; label: string };
export type OpLog = { base: ModelDoc; entries: LogEntry[]; at: number; docs: ModelDoc[] };

export const logInit = (base: ModelDoc): OpLog => ({ base, entries: [], at: 0, docs: [base] });
export const currentDoc = (l: OpLog): ModelDoc => l.docs[l.at];
export const canUndo = (l: OpLog) => l.at > 0;
export const canRedo = (l: OpLog) => l.at < l.entries.length;

/** Apply + record one op (drops any redo branch). A refused op leaves the log unchanged and says why. */
export function logApply(l: OpLog, op: Op, max = MAX_STEPS): { ok: true; log: OpLog; select?: string[] } | { ok: false; error: string; log: OpLog } {
  const r = applyOp(currentDoc(l), op);
  if (!r.ok) return { ok: false, error: r.error, log: l };
  let entries = [...l.entries.slice(0, l.at), { op, label: r.label }];
  let docs = [...l.docs.slice(0, l.at + 1), r.doc];
  let base = l.base;
  while (entries.length > max) { base = docs[1]; entries = entries.slice(1); docs = docs.slice(1); }
  return { ok: true, log: { base, entries, at: entries.length, docs }, select: r.select };
}
export const logUndo = (l: OpLog): OpLog => (canUndo(l) ? { ...l, at: l.at - 1 } : l);
export const logRedo = (l: OpLog): OpLog => (canRedo(l) ? { ...l, at: l.at + 1 } : l);
export const logJump = (l: OpLog, at: number): OpLog => ({ ...l, at: Math.max(0, Math.min(l.entries.length, at)) });
/** Unsaved = the current document differs from the base it was opened (or last saved) as. */
export const unsavedCount = (l: OpLog) => l.at;

/** Rebuild the document at step `upTo` from the base and the recorded ops only (deterministic). */
export function replay(base: ModelDoc, entries: readonly LogEntry[], upTo = entries.length): ModelDoc {
  let doc = base;
  for (let i = 0; i < upTo; i++) {
    const r = applyOp(doc, entries[i].op);
    if (!r.ok) throw new Error(`replay diverged at step ${i + 1} (${entries[i].label}): ${r.error}`);
    doc = r.doc;
  }
  return doc;
}

/** A saved revision becomes the new base (history before it is dropped: the revision list is the long-term history). */
export const logRebase = (doc: ModelDoc): OpLog => logInit(doc);

/** Byte-stable serialisation of a document (sorted keys) for hashing, saving and comparisons. */
export const serializeDoc = (d: ModelDoc) => canonicalJson(d);

