// Sorted-keys JSON, the same bytes as lib/cyrus/assets/textures.ts canonicalJson (that module pulls in node:crypto and
// the PNG encoder, so the client-safe editor keeps its own copy; a test checks both agree). Undefined fields drop out.
export function canonicalJson(v: unknown): string {
  if (Array.isArray(v)) return `[${v.map((x) => (x === undefined ? "null" : canonicalJson(x))).join(",")}]`;
  if (v && typeof v === "object") {
    const o = v as Record<string, unknown>;
    return `{${Object.keys(o).filter((k) => o[k] !== undefined).sort().map((k) => `${JSON.stringify(k)}:${canonicalJson(o[k])}`).join(",")}}`;
  }
  return JSON.stringify(v);
}

