// Model Studio L2: box-UV layout on the skin sheet. Pure + client-safe.
// Auto-packed boxes use EXACTLY the compiler's shelf packer (creature/compile.ts layoutSkin, rig-c1; a test proves the
// same rectangles), so what the editor shows is what the creature ships. Pinned boxes (the user dragged a UV box) are
// placed first where the user put them and the shelf packer flows around them. RigSpec v1 / rig-c1 cannot carry pins
// yet (plan task F2: RigSpec v1.1 `uv` + compiler rig-c2), so validate.ts warns that a pinned layout is editor-only.
import type { Face } from "../../creature/spec";
import type { ECube, ModelDoc } from "./doc";

export type UvRect = { x: number; y: number; w: number; h: number };
export type UvBox = { cube: string; u: number; v: number; w: number; h: number; d: number; pinned: boolean; faces: Record<Face, UvRect> };
export type UvLayout = { size: 64 | 128; boxes: UvBox[]; fits: boolean; overlaps: [string, string][]; outside: string[] };

const ceil = (v: number) => Math.max(1, Math.ceil(v - 1e-9));
export const boxDims = (c: Pick<ECube, "from" | "to">) => ({ w: ceil(c.to[0] - c.from[0]), h: ceil(c.to[1] - c.from[1]), d: ceil(c.to[2] - c.from[2]) });
/** The net's footprint on the sheet: 2(w + d) wide, d + h tall. */
export const netSize = (c: Pick<ECube, "from" | "to">) => { const { w, h, d } = boxDims(c); return { fw: 2 * (w + d), fh: d + h }; };

/** Box-UV rectangles of one cube at (u, v): the Minecraft box net (= compile.ts boxFaces). */
export function boxFaces(u: number, v: number, w: number, h: number, d: number): Record<Face, UvRect> {
  return {
    east: { x: u, y: v + d, w: d, h },
    north: { x: u + d, y: v + d, w, h },
    west: { x: u + d + w, y: v + d, w: d, h },
    south: { x: u + 2 * d + w, y: v + d, w, h },
    up: { x: u + d, y: v, w, h: d },
    down: { x: u + d + w, y: v, w, h: d },
  };
}

const hit = (a: UvRect, b: UvRect) => a.x < b.x + b.w && b.x < a.x + a.w && a.y < b.y + b.h && b.y < a.y + a.h;

function pack(doc: ModelDoc, size: 64 | 128): UvLayout | null {
  const order = new Map<string, number>();
  doc.bones.forEach((b, bi) => doc.cubes.filter((c) => c.bone === b.id).forEach((c, ci) => order.set(c.id, bi * 1000 + ci)));
  const cubes = doc.cubes.filter((c) => order.has(c.id)).sort((a, b) => order.get(a.id)! - order.get(b.id)!);
  const boxes: UvBox[] = [];
  const outside: string[] = [];
  const overlaps: [string, string][] = [];
  const pinnedRects: { id: string; r: UvRect }[] = [];
  for (const c of cubes) if (c.uv) {
    const { w, h, d } = boxDims(c), { fw, fh } = netSize(c);
    const r = { x: c.uv[0], y: c.uv[1], w: fw, h: fh };
    if (r.x + r.w > size || r.y + r.h > size) outside.push(c.id);
    for (const p of pinnedRects) if (hit(p.r, r)) overlaps.push([p.id, c.id]);
    pinnedRects.push({ id: c.id, r });
    boxes.push({ cube: c.id, u: r.x, v: r.y, w, h, d, pinned: true, faces: boxFaces(r.x, r.y, w, h, d) });
  }
  // the compiler's order: tallest net first, then widest, then document order
  const auto = cubes.filter((c) => !c.uv).map((c, i) => ({ c, ...netSize(c), order: i }));
  auto.sort((a, b) => b.fh - a.fh || b.fw - a.fw || a.order - b.order);
  let x = 0, y = 0, row = 0;
  for (const it of auto) {
    if (it.fw > size) return null;
    for (let guard = 0; guard < 4096; guard++) {
      if (x + it.fw > size) { x = 0; y += row; row = 0; }
      if (y + it.fh > size) return null;
      const r = { x, y, w: it.fw, h: it.fh };
      const block = pinnedRects.find((p) => hit(p.r, r));
      if (!block) break;
      x = block.r.x + block.r.w; // flow around the pinned box
      row = Math.max(row, 1);
    }
    const { w, h, d } = boxDims(it.c);
    boxes.push({ cube: it.c.id, u: x, v: y, w, h, d, pinned: false, faces: boxFaces(x, y, w, h, d) });
    x += it.fw; row = Math.max(row, it.fh);
  }
  boxes.sort((a, b) => order.get(a.cube)! - order.get(b.cube)!);
  return { size, boxes, fits: outside.length === 0 && overlaps.length === 0, overlaps, outside };
}

/** Lay out every cube's box net: the skin slot's size if set, else the smallest sheet (64, then 128) that fits. */
export function layoutUv(doc: ModelDoc): UvLayout {
  const fixed = doc.textures.find((t) => t.key === "skin")?.size ?? null;
  for (const s of fixed ? [fixed] : ([64, 128] as const)) {
    const l = pack(doc, s);
    if (l) return l;
  }
  const s = fixed ?? 128;
  return { size: s, boxes: [], fits: false, overlaps: [], outside: doc.cubes.map((c) => c.id) };
}

