// Model Studio L2: what each export TARGET allows, for the validator. Pure + client-safe.
// minecraft-bettermodel = RigSpec v1 -> compiler rig-c1 -> .bbmodel for the Nxeon-managed BetterModel plugin (verified on
// a real Paper 26.2 server, docs "Cyrus creature pipeline (R3)"). hytale-draft = the DRAFT .blockymodel exporter
// (maturity "planned"): only the facts marked V in /root/agent-notes/cyrus-research/N-hytale.md are encoded as rules.
import type { AdapterMaturity } from "../../adapters/types";

export type TargetId = "minecraft-bettermodel" | "hytale-draft";
export type TargetProfile = {
  id: TargetId;
  game: "minecraft" | "hytale";
  label: string;
  maturity: AdapterMaturity;
  /** RigSpec v1 has no cube rotation: refuse it, or allow it (the target can rotate a node) */
  cubeRotation: "refuse" | "allow";
  /** RigSpec v1 / rig-c1 re-packs every UV box; a pin is kept in the editor only */
  uvPins: "editor-only" | "kept";
  maxTextureRes: number;
  /** texels per block the game expects for this kind of model (null = the compiler's own 16 px per block) */
  texelsPerBlock: number | null;
  /** cuboids only (both targets): Hytale allows cuboids and quads only (V), Minecraft display entities draw cuboids */
  shapes: readonly ("box" | "quad")[];
  notes: readonly string[];
};

export const TARGETS: Readonly<Record<TargetId, TargetProfile>> = {
  "minecraft-bettermodel": {
    id: "minecraft-bettermodel", game: "minecraft", label: "Minecraft (BetterModel)", maturity: "beta",
    cubeRotation: "refuse", uvPins: "editor-only", maxTextureRes: 128, texelsPerBlock: null, shapes: ["box"],
    notes: ["RigSpec v1 -> rig-c1 .bbmodel, loaded on a real Paper 26.2 server with BetterModel 3.5.0"],
  },
  "hytale-draft": {
    id: "hytale-draft", game: "hytale", label: "Hytale (draft, planned)", maturity: "planned",
    // UNVERIFIED: node rotation exists in the format; the exporter writes cube rotation as a node orientation
    cubeRotation: "allow", uvPins: "kept",
    // UNVERIFIED: the max texture size is not published; 256 is the conservative placeholder from N-hytale.md
    maxTextureRes: 256,
    // VERIFIED: player, mobs (likely) and equipment use 64 px per block-unit; blocks use 32
    texelsPerBlock: 64, shapes: ["box", "quad"],
    notes: ["format and limits are unpublished; nothing here has been loaded by a real Hytale client"],
  },
};

