// Model Studio L2: validation with STRUCTURED issues and the live budgets. Pure + client-safe.
// Layers, cheapest first: document structure (ids, parents, cycles, one root) -> name and path safety -> the RigSpec
// caps (lib/cyrus/creature/spec.ts constants, the same numbers the build service enforces) -> the export target's
// rules (./profiles.ts) -> the authoritative RigSpec validator itself (checkRigSpec on toRigSpec(doc)), whose errors are
// mapped back to the bone / cube / clip they are about. "error" blocks a save; "warn" and "info" never do.
import { isSafeProjectPath } from "../../engine-core/revisions";
import {
  checkRigSpec, BONE_RE, MAX_BONES, MAX_CLIPS, MAX_COORD, MAX_CUBES, MAX_CUBES_PER_BONE, MAX_DEPTH, MAX_KEYS_PER_TRACK,
  MAX_RIG_SPEC_BYTES, MAX_TRACKS_PER_CLIP, NAME_RE, PALETTE_KEY_RE,
} from "../../creature/spec";
import { canonicalJson } from "./canonical";
import { depthOf, size, type ModelDoc } from "./doc";
import { CLIP_RE, cubeLabel } from "./ops";
import { TARGETS, type TargetId } from "./profiles";
import { toRigSpec } from "./rigspec";
import { layoutUv, type UvLayout } from "./uv";

export type Severity = "error" | "warn" | "info";
export type Issue = { code: string; severity: Severity; path: string; node?: string; message: string };
export type Budget = { id: string; label: string; used: number; max: number };
export type Validation = { ok: boolean; issues: Issue[]; budgets: Budget[]; uv: UvLayout; specBytes: number; target: TargetId };

export function validateDoc(doc: ModelDoc, target: TargetId = "minecraft-bettermodel"): Validation {
  const T = TARGETS[target];
  const issues: Issue[] = [];
  const add = (severity: Severity, code: string, path: string, message: string, node?: string) => issues.push({ code, severity, path, message, ...(node ? { node } : {}) });

  // ---- structure
  const ids = new Set<string>();
  const dupe = (id: string, path: string) => { if (ids.has(id)) add("error", "duplicate_id", path, `the id ${id} is used twice`, id); ids.add(id); };
  doc.bones.forEach((b, i) => dupe(b.id, `bones.${i}`));
  doc.cubes.forEach((c, i) => dupe(c.id, `cubes.${i}`));
  const boneIds = new Set(doc.bones.map((b) => b.id));
  const roots = doc.bones.filter((b) => b.parent === null);
  if (roots.length !== 1) add("error", "one_root", "bones", `a creature needs exactly one root bone; this one has ${roots.length}`);
  doc.bones.forEach((b, i) => {
    if (b.parent !== null && !boneIds.has(b.parent)) add("error", "missing_parent", `bones.${i}.parent`, `${b.name} hangs from a bone that no longer exists`, b.id);
    const dep = depthOf(doc, b.id);
    if (dep < 0 && b.parent !== null && boneIds.has(b.parent)) add("error", "parent_cycle", `bones.${i}`, `${b.name} is part of a parent loop`, b.id);
    if (dep > MAX_DEPTH) add("error", "too_deep", `bones.${i}`, `${b.name} is nested ${dep} deep; the limit is ${MAX_DEPTH}`, b.id);
  });
  doc.cubes.forEach((c, i) => { if (!boneIds.has(c.bone)) add("error", "orphan_cube", `cubes.${i}.bone`, `a cube belongs to a bone that no longer exists`, c.id); });
  const keyIds = new Set<string>();
  doc.clips.forEach((cl, ci) => {
    const seen = new Set<string>();
    cl.tracks.forEach((t, ti) => {
      const at = `clips.${ci}.tracks.${ti}`;
      if (!boneIds.has(t.bone)) add("error", "orphan_track", at, `${cl.name} animates a bone that no longer exists`);
      const k = `${t.bone}/${t.channel}`;
      if (seen.has(k)) add("error", "duplicate_track", at, `${cl.name} has two ${t.channel} tracks for one bone`);
      seen.add(k);
      if (!!t.wave === !!t.keys) add("error", "track_shape", at, "a track is either a wave or keys");
      for (const key of t.keys ?? []) { if (keyIds.has(key.id) || ids.has(key.id)) add("error", "duplicate_id", at, `the id ${key.id} is used twice`); keyIds.add(key.id); }
      if ((t.keys?.length ?? 0) > MAX_KEYS_PER_TRACK) add("error", "too_many_keys", at, `${t.keys!.length} keys; a track holds at most ${MAX_KEYS_PER_TRACK}`);
    });
    if (cl.tracks.length > MAX_TRACKS_PER_CLIP) add("error", "too_many_tracks", `clips.${ci}`, `${cl.name} has ${cl.tracks.length} tracks; the limit is ${MAX_TRACKS_PER_CLIP}`);
    if (!cl.tracks.length) add("error", "empty_clip", `clips.${ci}`, `${cl.name} has no tracks yet; key at least one bone`);
  });

  // ---- names and paths
  if (!NAME_RE.test(doc.name)) add("error", "bad_name", "name", "the model name is 2-32 lowercase letters, digits and underscores, starting with a letter");
  const names = new Map<string, number>();
  doc.bones.forEach((b, i) => {
    if (!BONE_RE.test(b.name)) add("error", "bad_bone_name", `bones.${i}.name`, `"${b.name.slice(0, 30)}" is not a valid bone name (1-24 lowercase letters, digits, underscores)`, b.id);
    names.set(b.name, (names.get(b.name) ?? 0) + 1);
  });
  for (const [n, k] of names) if (k > 1) add("error", "duplicate_bone_name", "bones", `${k} bones are called ${n}`, doc.bones.find((b) => b.name === n)?.id);
  const clipNames = new Set<string>();
  doc.clips.forEach((cl, i) => {
    if (!CLIP_RE.test(cl.name)) add("error", "bad_clip_name", `clips.${i}.name`, `"${cl.name.slice(0, 30)}" is not a valid clip name`);
    if (clipNames.has(cl.name)) add("error", "duplicate_clip", `clips.${i}.name`, `two clips are called ${cl.name}`);
    clipNames.add(cl.name);
  });
  for (const k of Object.keys(doc.palette)) if (!PALETTE_KEY_RE.test(k)) add("error", "bad_palette_key", `palette.${k}`, `"${k.slice(0, 20)}" is not a valid colour name`);
  doc.textures.forEach((t, i) => {
    if (!PALETTE_KEY_RE.test(t.key)) add("error", "bad_slot", `textures.${i}.key`, "texture slot keys are lowercase letters, digits and underscores");
    if (!isSafeProjectPath(t.path) || !t.path.startsWith("assets/") || !t.path.endsWith(".png")) add("error", "unsafe_path", `textures.${i}.path`, `the texture path ${t.path.slice(0, 60)} is not a safe assets/...png path`);
  });

  // ---- caps
  if (doc.bones.length > MAX_BONES) add("error", "too_many_bones", "bones", `${doc.bones.length} bones; the limit is ${MAX_BONES}`);
  if (doc.cubes.length > MAX_CUBES) add("error", "too_many_cubes", "cubes", `${doc.cubes.length} cubes; the limit is ${MAX_CUBES}`);
  if (doc.clips.length > MAX_CLIPS) add("error", "too_many_clips", "clips", `${doc.clips.length} clips; the limit is ${MAX_CLIPS}`);
  for (const b of doc.bones) { const n = doc.cubes.filter((c) => c.bone === b.id).length; if (n > MAX_CUBES_PER_BONE) add("error", "too_many_cubes_in_bone", "cubes", `${b.name} holds ${n} cubes; the limit is ${MAX_CUBES_PER_BONE}`, b.id); }
  doc.cubes.forEach((c, i) => {
    const s = size(c);
    if (s.some((v) => v < 0.2)) add("error", "cube_too_thin", `cubes.${i}`, `${cubeLabel(doc, c.id)}: every side must be at least 0.2 units`, c.id);
    if (s.some((v) => v > 48)) add("error", "cube_too_big", `cubes.${i}`, `${cubeLabel(doc, c.id)}: a side may be at most 48 units`, c.id);
    if ([...c.from, ...c.to].some((v) => Math.abs(v) > MAX_COORD)) add("error", "out_of_bounds", `cubes.${i}`, `${cubeLabel(doc, c.id)} reaches past ${MAX_COORD} units from the origin`, c.id);
    if (c.rotation.some((x) => x !== 0)) {
      if (T.cubeRotation === "refuse") add("error", "cube_rotation_unsupported", `cubes.${i}.rotation`, `${cubeLabel(doc, c.id)} is rotated, but ${T.label} cubes can't rotate on their own (RigSpec v1). Rotate its bone, or group it into a new bone and rotate that.`, c.id);
      else add("info", "cube_rotation_unverified", `cubes.${i}.rotation`, `${cubeLabel(doc, c.id)} is rotated; ${T.label} rotation is not verified`, c.id);
    }
    if (c.texture !== "skin" && target === "minecraft-bettermodel") add("error", "texture_slot_unsupported", `cubes.${i}.texture`, "Minecraft creatures have one skin sheet", c.id);
    if (c.hidden) add("info", "hidden_ships", `cubes.${i}`, `${cubeLabel(doc, c.id)} is hidden in the editor only; it still ships`, c.id);
  });

  // ---- UV layout
  const uv = layoutUv(doc);
  if (!uv.boxes.length && doc.cubes.length) add("error", "uv_overflow", "cubes", `the cubes do not fit on a ${uv.size} px skin sheet; use fewer or smaller cubes`);
  for (const id of uv.outside) if (uv.boxes.some((b) => b.cube === id)) add("error", "uv_outside", "cubes", `${cubeLabel(doc, id)}'s UV box reaches past the ${uv.size} px sheet`, id);
  for (const [a, b] of uv.overlaps) add("warn", "uv_overlap", "cubes", `the UV boxes of ${cubeLabel(doc, a)} and ${cubeLabel(doc, b)} overlap (they will share paint)`, b);
  if (uv.size > T.maxTextureRes) add("error", "texture_too_big", "textures", `${uv.size} px is larger than ${T.label} allows (${T.maxTextureRes})`);
  if (T.uvPins === "editor-only" && doc.cubes.some((c) => c.uv)) add("warn", "uv_pin_editor_only", "cubes", "Pinned UV boxes are kept in the editor, but this version of the creature compiler re-packs every box when it builds (pins ship with RigSpec v1.1).");

  // ---- the authoritative RigSpec check (mapped back to nodes)
  const { spec } = toRigSpec(doc);
  const specBytes = canonicalJson(spec).length;
  if (specBytes > MAX_RIG_SPEC_BYTES) add("error", "spec_too_big", "doc", `the creature spec is ${(specBytes / 1024).toFixed(1)} KB; the limit is ${MAX_RIG_SPEC_BYTES / 1024} KB`);
  const structuralBroken = issues.some((i) => i.severity === "error" && ["duplicate_id", "one_root", "missing_parent", "parent_cycle", "orphan_cube", "orphan_track"].includes(i.code));
  if (!structuralBroken) {
    const r = checkRigSpec(spec);
    if (!r.ok) {
      for (const e of r.errors) {
        const mapped = mapRigPath(doc, e.path);
        if (issues.some((i) => i.severity === "error" && i.message === e.message)) continue;
        add("error", "rigspec", mapped.path, e.message, mapped.node);
      }
    } else for (const w of r.warnings) add("warn", "rigspec_warning", "doc", w);
  }
  if (target === "hytale-draft") add("info", "format_unverified", "doc", "The Hytale model format is not published; this export is a draft no Hytale client has loaded.");

  const order: Record<Severity, number> = { error: 0, warn: 1, info: 2 };
  issues.sort((a, b) => order[a.severity] - order[b.severity]);
  return { ok: !issues.some((i) => i.severity === "error"), issues, budgets: budgets(doc, specBytes, uv), uv, specBytes, target };
}

/** checkRigSpec paths ("bones.3.cubes.1.material", "animations.walk.tracks.0") -> the editor node + a doc path. */
