}

export function budgets(doc: ModelDoc, specBytes: number, uv: UvLayout): Budget[] {
  const depth = Math.max(0, ...doc.bones.map((b) => depthOf(doc, b.id)));
  const tracks = Math.max(0, ...doc.clips.map((c) => c.tracks.length));
  const keys = Math.max(0, ...doc.clips.flatMap((c) => c.tracks.map((t) => t.keys?.length ?? 0)));
