    { id: "depth", label: "Depth", used: depth, max: MAX_DEPTH },
    { id: "clips", label: "Clips", used: doc.clips.length, max: MAX_CLIPS },
    { id: "tracks", label: "Tracks / clip", used: tracks, max: MAX_TRACKS_PER_CLIP },
    { id: "keys", label: "Keys / track", used: keys, max: MAX_KEYS_PER_TRACK },
    { id: "spec", label: "Spec KB", used: Math.round((specBytes / 1024) * 10) / 10, max: MAX_RIG_SPEC_BYTES / 1024 },
