// Model Studio L2: the merge rule for AI edits that arrive mid-session (MODEL-STUDIO-PLAN section 2, "AI edit
// mid-session"). Pure + client-safe.
//   * The AI never touches the working copy. A candidate is built from base revision R (its RigSpec is lined up with R
//     through rigspec.ts fromRigSpec(spec, { like: R }), so its bones/cubes/keys carry R's ids).
//   * mergeCandidate(R, ours, theirs) is a 3-way merge PER NODE ID (bone, cube, key; plus clip, track, palette colour
//     and the model's meta), field by field inside a node: a field only one side changed takes that side; a field both
//     sides changed to different values is an OVERLAP. Human wins by default (overlap -> ours); `resolve` can pick
//     Cyrus's side per overlap. `accept` limits which of Cyrus's non-overlapping changes are applied ("Apply part").
//   * Both sides allocate new ids after R.seq, so Cyrus's NEW ids are renumbered first (no collisions); a bone name
//     both sides added is kept for the human's bone and Cyrus's gets a free name; nodes left hanging (a Cyrus cube on
//     a bone the human deleted) are dropped and reported. The result is a normal ModelDoc: accepting it is one
//     "replace" op, i.e. one undo step.
import { canonicalJson } from "./canonical";
import { freeBoneName, nextId, type EBone, type EClip, type ECube, type EKey, type EWave, type ModelDoc } from "./doc";

export type NodeKind = "bone" | "cube" | "key" | "clip" | "track" | "palette" | "meta";
export type Change = { id: string; kind: NodeKind; node: string; field: string | null; action: "add" | "modify" | "delete"; label: string };
export type Overlap = { id: string; kind: NodeKind; node: string; field: string | null; label: string; ours: unknown; theirs: unknown; resolution: "ours" | "theirs" };
export type MergeOptions = { accept?: ReadonlySet<string> | null; resolve?: Readonly<Record<string, "ours" | "theirs">> };
export type MergeResult = { doc: ModelDoc; applied: Change[]; skipped: Change[]; overlaps: Overlap[]; notes: string[] };

type Rec = Record<string, unknown>;
type Node = { kind: NodeKind; key: string; value: Rec; order: number; label: string };
const eq = (a: unknown, b: unknown) => canonicalJson(a ?? null) === canonicalJson(b ?? null);
/** Editor view flags are per-session conveniences, never merged (the human's stay). */
const VIEW_FIELDS = new Set(["hidden", "locked"]);

const trackKey = (clip: string, bone: string, ch: string) => `${clip}|${bone}|${ch}`;

function nodesOf(d: ModelDoc): Map<string, Node> {
  const out = new Map<string, Node>();
  const boneName = new Map(d.bones.map((b) => [b.id, b.name]));
  let i = 0;
  const put = (kind: NodeKind, key: string, value: Rec, label: string) => out.set(`${kind}:${key}`, { kind, key, value, order: i++, label });
  put("meta", "meta", { ...d.meta } as Rec, "model settings");
  for (const [k, c] of Object.entries(d.palette)) put("palette", k, { color: c }, `colour ${k}`);
  for (const b of d.bones) { const { id, hidden: _h, locked: _l, ...v } = b; void _h; void _l; put("bone", id, v as Rec, b.name); }
  const cubeIdx = new Map<string, number>();
  for (const c of d.cubes) {
    const n = cubeIdx.get(c.bone) ?? 0; cubeIdx.set(c.bone, n + 1);
    const { id, hidden: _h, locked: _l, ...v } = c; void _h; void _l;
    put("cube", id, v as Rec, `${boneName.get(c.bone) ?? "?"} · ${c.label ?? `cube ${n}`}`);
  }
  for (const cl of d.clips) {
    put("clip", cl.name, { length: cl.length, loop: cl.loop }, `clip ${cl.name}`);
    for (const t of cl.tracks) {
      const tk = trackKey(cl.name, t.bone, t.channel);
      put("track", tk, t.wave ? { wave: t.wave } : { keyed: true }, `${cl.name} ${boneName.get(t.bone) ?? "?"} ${t.channel}`);
      for (const k of t.keys ?? []) put("key", k.id, { track: tk, t: k.t, v: k.v, ease: k.ease }, `${cl.name} ${boneName.get(t.bone) ?? "?"} ${t.channel} key`);
    }
  }
  return out;
}

/** Cyrus's new ids (not in R) renumbered past both sides' counters. Deterministic (document order). */
function renumber(base: ModelDoc, ours: ModelDoc, theirs: ModelDoc): ModelDoc {
  const known = new Set<string>([...base.bones.map((b) => b.id), ...base.cubes.map((c) => c.id), ...base.clips.flatMap((c) => c.tracks.flatMap((t) => (t.keys ?? []).map((k) => k.id)))]);
  let seq = Math.max(ours.seq, theirs.seq, base.seq);
  const map = new Map<string, string>();
  const re = (id: string, kind: "b" | "c" | "k") => { if (known.has(id)) return id; let m = map.get(id); if (!m) { const n = nextId(seq, kind); seq = n.seq; m = n.id; map.set(id, m); } return m; };
  const bones = theirs.bones.map((b) => ({ ...b, id: re(b.id, "b") }));
  const fix = (id: string | null) => (id === null ? null : map.get(id) ?? id);
  return {
    ...theirs,
    bones: bones.map((b) => ({ ...b, parent: fix(b.parent) })),
    cubes: theirs.cubes.map((c) => ({ ...c, id: re(c.id, "c"), bone: fix(c.bone)! })),
    clips: theirs.clips.map((cl) => ({ ...cl, tracks: cl.tracks.map((t) => ({ ...t, bone: fix(t.bone)!, ...(t.keys ? { keys: t.keys.map((k) => ({ ...k, id: re(k.id, "k") })) } : {}) })) })),
    seq,
  };
}

/** Every change from `from` to `to`, field by field (also the "What changed" list of the approve view). */
export function diffDocs(from: ModelDoc, to: ModelDoc): Change[] {
  const a = nodesOf(from), b = nodesOf(to);
  const out: Change[] = [];
  for (const [k, n] of b) {
    const o = a.get(k);
    if (!o) { out.push({ id: `${k}:*`, kind: n.kind, node: n.key, field: null, action: "add", label: `${n.label} added` }); continue; }
    for (const f of new Set([...Object.keys(o.value), ...Object.keys(n.value)])) if (!eq(o.value[f], n.value[f])) out.push({ id: `${k}:${f}`, kind: n.kind, node: n.key, field: f, action: "modify", label: `${n.label}: ${f}` });
  }
  for (const [k, n] of a) if (!b.has(k)) out.push({ id: `${k}:*`, kind: n.kind, node: n.key, field: null, action: "delete", label: `${n.label} removed` });
  return out;
}

export function mergeCandidate(base: ModelDoc, ours: ModelDoc, theirsIn: ModelDoc, opts: MergeOptions = {}): MergeResult {
  const theirs = renumber(base, ours, theirsIn);
  const B = nodesOf(base), O = nodesOf(ours), T = nodesOf(theirs);
  const accept = (id: string) => !opts.accept || opts.accept.has(id);
  const applied: Change[] = [], skipped: Change[] = [], overlaps: Overlap[] = [], notes: string[] = [];
  const result = new Map<string, Rec | null>(); // node key -> value (null = deleted)
  const take = (c: Change, ok: () => void) => { if (accept(c.id)) { applied.push(c); ok(); } else skipped.push(c); };

  for (const k of new Set([...B.keys(), ...O.keys(), ...T.keys()])) {
    const b = B.get(k), o = O.get(k), t = T.get(k);
    const n = (t ?? o ?? b)!;
    const label = (o ?? t ?? b)!.label;
    if (b && o && t) {
      const v: Rec = { ...o.value };
      for (const f of new Set([...Object.keys(b.value), ...Object.keys(o.value), ...Object.keys(t.value)])) {
        if (VIEW_FIELDS.has(f)) continue;
        const bf = b.value[f], of = o.value[f], tf = t.value[f];
        if (eq(tf, bf) || eq(of, tf)) continue;
        if (eq(of, bf)) take({ id: `${k}:${f}`, kind: n.kind, node: n.key, field: f, action: "modify", label: `${label}: ${f}` }, () => { if (tf === undefined) delete v[f]; else v[f] = tf; });
        else {
          const id = `${k}:${f}`, res = opts.resolve?.[id] ?? "ours";
          overlaps.push({ id, kind: n.kind, node: n.key, field: f, label: `${label}: ${f}`, ours: of, theirs: tf, resolution: res });
          if (res === "theirs") { if (tf === undefined) delete v[f]; else v[f] = tf; }
        }
      }
      result.set(k, v);
    } else if (b && o && !t) {
      if (eq(o.value, b.value)) { result.set(k, o.value); take({ id: `${k}:*`, kind: n.kind, node: n.key, field: null, action: "delete", label: `${label} removed` }, () => result.set(k, null)); }
      else {
        const id = `${k}:*`, res = opts.resolve?.[id] ?? "ours";
        overlaps.push({ id, kind: n.kind, node: n.key, field: null, label: `${label}: you edited it, Cyrus removed it`, ours: o.value, theirs: null, resolution: res });
        result.set(k, res === "theirs" ? null : o.value);
      }
    } else if (b && !o && t) {
      if (eq(t.value, b.value)) result.set(k, null);
      else {
        const id = `${k}:*`, res = opts.resolve?.[id] ?? "ours";
        overlaps.push({ id, kind: n.kind, node: n.key, field: null, label: `${label}: you removed it, Cyrus edited it`, ours: null, theirs: t.value, resolution: res });
        result.set(k, res === "theirs" ? t.value : null);
      }
    } else if (b && !o && !t) result.set(k, null);
    else if (!b && o && !t) result.set(k, o.value);
    else if (!b && !o && t) { result.set(k, null); take({ id: `${k}:*`, kind: n.kind, node: n.key, field: null, action: "add", label: `${label} added` }, () => result.set(k, t.value)); }
    else if (!b && o && t) {
      // both added the same palette key / clip / track (ids cannot collide after renumber)
      if (eq(o.value, t.value)) { result.set(k, o.value); continue; }
      const id = `${k}:*`, res = opts.resolve?.[id] ?? "ours";
      overlaps.push({ id, kind: n.kind, node: n.key, field: null, label: `${label}: both added it differently`, ours: o.value, theirs: t.value, resolution: res });
      result.set(k, res === "theirs" ? t.value : o.value);
    }
  }

  // ---- rebuild the document (ours' order; Cyrus's additions after their predecessor in Cyrus's order)
  const val = (kind: NodeKind, key: string) => result.get(`${kind}:${key}`) ?? null;
  const ordered = <X>(oursList: X[], theirsList: X[], keyOf: (x: X) => string): string[] => {
    const out = oursList.map(keyOf);
    let prev: string | null = null;
    for (const x of theirsList) {
      const k = keyOf(x);
      if (!out.includes(k)) { const at = prev === null ? 0 : out.indexOf(prev) + 1; out.splice(at, 0, k); }
      prev = k;
    }
    return out;
  };
  const oursFlags = new Map<string, { hidden?: boolean; locked?: boolean }>([...ours.bones, ...ours.cubes].map((n) => [n.id, { ...(n.hidden ? { hidden: true } : {}), ...(n.locked ? { locked: true } : {}) }]));
  const meta = (val("meta", "meta") ?? ours.meta) as ModelDoc["meta"];
  const palette: Record<string, string> = {};
  for (const k of ordered(Object.keys(ours.palette), Object.keys(theirs.palette), (x) => x)) { const v = val("palette", k); if (v) palette[k] = String(v.color); }
  let bones: EBone[] = ordered(ours.bones, theirs.bones, (b) => b.id).flatMap((id) => { const v = val("bone", id); return v ? [{ id, ...(v as Omit<EBone, "id">), ...oursFlags.get(id) }] : []; });
  let cubes: ECube[] = ordered(ours.cubes, theirs.cubes, (c) => c.id).flatMap((id) => { const v = val("cube", id); return v ? [{ id, ...(v as Omit<ECube, "id">), ...oursFlags.get(id) }] : []; });

  // dangling: bones whose parent is gone, then cubes on missing bones (repeat until stable)
  for (let guard = 0; guard < 64; guard++) {
    const ids = new Set(bones.map((b) => b.id));
    const lost = bones.filter((b) => b.parent !== null && !ids.has(b.parent));
    if (!lost.length) break;
    for (const b of lost) notes.push(`${b.name} was left out: the bone it hangs from was removed`);
    bones = bones.filter((b) => !lost.includes(b));
  }
  const boneIds = new Set(bones.map((b) => b.id));
  for (const c of cubes) if (!boneIds.has(c.bone)) notes.push(`a cube was left out: its bone was removed`);
  cubes = cubes.filter((c) => boneIds.has(c.bone));
  // duplicate bone names: the human's bone keeps the name
  const oursIds = new Set(ours.bones.map((b) => b.id));
  for (const b of [...bones].sort((x, y) => Number(oursIds.has(y.id)) - Number(oursIds.has(x.id)))) {
    if (bones.some((x) => x !== b && x.name === b.name) && !oursIds.has(b.id)) {
      const tmp: ModelDoc = { ...ours, bones: bones.filter((x) => x !== b) };
      const nn = freeBoneName(tmp, b.name);
      notes.push(`Cyrus's new bone ${b.name} was renamed ${nn} (you already have a ${b.name})`);
      bones = bones.map((x) => (x === b ? { ...x, name: nn } : x));
    }
  }

  // clips, tracks, keys
  const clipNames = ordered(ours.clips, theirs.clips, (c) => c.name);
  const trackOrder = new Map<string, string[]>();
  for (const cn of clipNames) {
    const oc = ours.clips.find((c) => c.name === cn), tc = theirs.clips.find((c) => c.name === cn);
    trackOrder.set(cn, ordered(oc?.tracks ?? [], tc?.tracks ?? [], (t) => trackKey(cn, t.bone, t.channel)));
  }
  const keysByTrack = new Map<string, EKey[]>();
  for (const [k, v] of result) {
    if (!v || !k.startsWith("key:")) continue;
    const tk = String(v.track);
    keysByTrack.set(tk, [...(keysByTrack.get(tk) ?? []), { id: k.slice(4), t: Number(v.t), v: v.v as EKey["v"], ease: v.ease as EKey["ease"] }]);
  }
  const clips: EClip[] = clipNames.flatMap((cn) => {
    const cv = val("clip", cn);
    if (!cv) return [];
    const tracks = (trackOrder.get(cn) ?? []).flatMap((tk) => {
      const tv = val("track", tk);
      if (!tv) return [];
      const [, bone, channel] = tk.split("|");
      if (!boneIds.has(bone)) { notes.push(`the ${cn} ${channel} track was left out: its bone was removed`); return []; }
      if (tv.wave) return [{ bone, channel: channel as EClip["tracks"][number]["channel"], wave: tv.wave as EWave }];
      const keys = (keysByTrack.get(tk) ?? []).sort((a, b) => a.t - b.t || (a.id < b.id ? -1 : 1));
      return keys.length ? [{ bone, channel: channel as EClip["tracks"][number]["channel"], keys }] : [];
    });
    return [{ name: cn, length: Number(cv.length), loop: Boolean(cv.loop), tracks }];
  });

  const doc: ModelDoc = { ...ours, meta, palette, bones, cubes, clips, seq: Math.max(ours.seq, theirs.seq) };
  return { doc, applied, skipped, overlaps, notes };
}

/** Short summary for the candidate bar: "3 changes · 1 overlap". */
export function mergeSummary(m: Pick<MergeResult, "applied" | "skipped" | "overlaps">): string {
  const n = m.applied.length + m.skipped.length;
  return `${n} change${n === 1 ? "" : "s"}${m.overlaps.length ? ` · ${m.overlaps.length} overlap${m.overlaps.length === 1 ? "" : "s"}` : ""}`;
}

