// Model Studio L2: the plan gate for the cuboid + bone editor. Pure + client-safe; the SERVER calls it again on every
// request (the UI only uses it as a hint). Model creation/editing needs the top plan (ASSET_MIN_PLAN.model = "all",
// shown as "All models"); an unknown plan FAILS CLOSED for creating/editing and never for viewing or exporting.
import { canAsset, MODEL_EDITOR_ACTION_OP, normalizePlan, PLAN_LABEL, type AssetDecision } from "../../engine-core/asset-gate";

export type ModelEditorAction = keyof typeof MODEL_EDITOR_ACTION_OP;
export const MODEL_EDITOR_ACTIONS = Object.keys(MODEL_EDITOR_ACTION_OP) as ModelEditorAction[];

export const canModelEditor = (plan: unknown, action: ModelEditorAction): AssetDecision =>
  (MODEL_EDITOR_ACTIONS as string[]).includes(action)
    ? canAsset(plan, "model", MODEL_EDITOR_ACTION_OP[action])
    : { ok: false, code: "bad_request", reason: `unknown model editor action ${String(action)}` };

export type ModelEditorAccess = { plan: string | null; planLabel: string; edit: AssetDecision; create: AssetDecision };
export function modelEditorAccess(rawPlan: unknown): ModelEditorAccess {
  const p = normalizePlan(rawPlan);
  return { plan: p, planLabel: p ? PLAN_LABEL[p] : "Unknown", edit: canModelEditor(p, "edit"), create: canModelEditor(p, "create") };
}

