// Model Studio L2: the autosave schedule (MODEL-STUDIO-PLAN: debounce 5 s idle, at most 30 s after the first unsaved
// edit). Pure: the client feeds it clock times, so it is tested without timers. Drafts are never built or shared;
// "Save revision" stays an explicit action.
export const AUTOSAVE_IDLE_MS = 5_000;
export const AUTOSAVE_MAX_MS = 30_000;

export type AutosaveState = { dirtySince: number | null; lastEditAt: number | null; savedSha: string | null };
export const autosaveInit = (savedSha: string | null = null): AutosaveState => ({ dirtySince: null, lastEditAt: null, savedSha });

/** Record an edit at `now` (the document's sha after it). An edit back to the saved bytes clears the dirty state. */
export function autosaveEdit(s: AutosaveState, now: number, sha: string): AutosaveState {
  if (sha === s.savedSha) return { ...s, dirtySince: null, lastEditAt: null };
  return { ...s, dirtySince: s.dirtySince ?? now, lastEditAt: now };
}

/** Milliseconds until the draft should be written (0 = now), or null when there is nothing to save. */
export function autosaveDueIn(s: AutosaveState, now: number, o = { idleMs: AUTOSAVE_IDLE_MS, maxMs: AUTOSAVE_MAX_MS }): number | null {
  if (s.dirtySince === null || s.lastEditAt === null) return null;
  const idle = s.lastEditAt + o.idleMs - now;
  const cap = s.dirtySince + o.maxMs - now;
  return Math.max(0, Math.min(idle, cap));
}

/** The draft with this sha was written. */
export const autosaveDone = (s: AutosaveState, sha: string): AutosaveState => ({ dirtySince: null, lastEditAt: null, savedSha: sha });

