// Model Studio L2: the GAME-NEUTRAL exporter interface. An exporter turns a ModelDoc into the files one game reads.
// Exporting is never plan-gated (asset-gate: export), but it IS maturity-gated: an exporter at maturity "planned"
// only runs when the caller explicitly allows planned exporters (tests, devhost), never for customers.
import type { AdapterMaturity } from "../../../adapters/types";
import type { ModelDoc } from "../doc";
import type { TargetId } from "../profiles";
import type { Issue } from "../validate";

export type ExportFile = { path: string; mime: string; data: Buffer | string; sha256: string };
export type ExportContext = { namespace: string; allowPlanned?: boolean };
export type ExportResult =
  | { ok: true; exporter: string; files: ExportFile[]; issues: Issue[]; unverified: readonly string[] }
  | { ok: false; exporter: string; code: "exporter_planned" | "invalid" | "compile_failed"; error: string; issues: Issue[] };

export interface ModelExporter {
  readonly id: string;
  readonly game: string;
  readonly target: TargetId;
  readonly label: string;
  /** the file formats it writes (".bbmodel", ".blockymodel" ...) */
  readonly formats: readonly string[];
  readonly maturity: AdapterMaturity;
  /** every format assumption that no real client has confirmed (empty = verified end to end) */
  readonly unverified: readonly string[];
  run(doc: ModelDoc, ctx: ExportContext): ExportResult;
}

/** Maturity gate: "planned" exporters run only when the caller allows it explicitly. */
export function exportAllowed(e: Pick<ModelExporter, "maturity">, ctx: Pick<ExportContext, "allowPlanned">): boolean {
  return e.maturity !== "planned" || ctx.allowPlanned === true;
}

