// Model Studio L2 exporter #1: ModelDoc -> RigSpec v1 -> the EXISTING creature compiler (rig-c1) -> .bbmodel + skin PNG
// for the Nxeon-managed BetterModel plugin. Nothing new about the format: it re-validates with checkRigSpec, compiles
// with compileCreature and applies the skin quality bar exactly like a build does (creature/portal.ts). SERVER ONLY.
import { canonicalJson, sha256Hex } from "../../../assets/textures";
import { checkReturnedCreature } from "../../../creature/portal";
import { toRigSpec } from "../rigspec";
import { validateDoc } from "../validate";
import type { ExportResult, ModelExporter } from "./types";

export const bbmodelExporter: ModelExporter = {
  id: "minecraft-bbmodel", game: "minecraft", target: "minecraft-bettermodel", label: "Minecraft creature (BetterModel .bbmodel)",
  formats: [".bbmodel", ".png", ".json"], maturity: "beta", unverified: [],
  run(doc, ctx): ExportResult {
    const v = validateDoc(doc, "minecraft-bettermodel");
    if (!v.ok) return { ok: false, exporter: this.id, code: "invalid", error: v.issues.find((i) => i.severity === "error")!.message, issues: v.issues };
    const { spec } = toRigSpec(doc);
    const c = checkReturnedCreature({ name: doc.name, spec }, ctx.namespace);
    if (!c.ok) return { ok: false, exporter: this.id, code: "compile_failed", error: c.reason, issues: v.issues };
    const canonical = canonicalJson(spec);
    return {
      ok: true, exporter: this.id, issues: v.issues, unverified: this.unverified,
      files: [
        { path: `assets/creatures/${doc.name}.json`, mime: "application/json", data: canonical, sha256: sha256Hex(canonical) },
        { path: `bettermodel/${c.key}.bbmodel`, mime: "application/json", data: c.compiled.bbmodel, sha256: c.compiled.bbmodelSha256 },
        { path: `bettermodel/${c.key}.png`, mime: "image/png", data: c.compiled.png, sha256: c.compiled.pngSha256 },
      ],
    };
  },
};

