// Model Studio L2 exporter #2: a DRAFT Hytale exporter (.blockymodel + .blockyanim + PNG), maturity "planned".
// SERVER ONLY (PNG encoder). It is never offered to customers: exportAllowed() refuses it unless the caller passes
// allowPlanned (tests / devhost). No Hytale client has loaded its output.
//
// Built ONLY on the facts marked VERIFIED in /root/agent-notes/cyrus-research/N-hytale.md (read 2026-10-10):
//   V1  models are `.blockymodel`, animations `.blockyanim`, textures PNG
//   V2  geometry is cuboids and quads only (this exporter writes cuboids only), materials are fixed (none written)
//   V3  texel density: blocks 32 px per block-unit; player, mobs (likely) and equipment 64 px per block-unit
// EVERYTHING ELSE below is an assumption, listed one by one in HYTALE_UNVERIFIED (also in the report, the docs and the
// golden test). The Hytale schema is not officially published; the layout is a guess to be replaced by one fixture
// from a real file (Blockbench's official Hytale plugin output or a game asset) before maturity can move past
// "planned". Keep this a pure function: a format change is one file.
import { createHash } from "node:crypto";
import { compileCreature, type SkinLayout } from "../../../creature/compile";
import { checkRigSpec, FACES, type Face } from "../../../creature/spec";
import { encodePng } from "../../../textures/png";
import type { Raster } from "../../../textures/render";
import { canonicalJson } from "../canonical";
import { boneById, centre, size, type ModelDoc, type Vec3 } from "../doc";
import { sampleTrack } from "../pose";
import { TARGETS } from "../profiles";
import { toRigSpec } from "../rigspec";
import { validateDoc, type Issue } from "../validate";
import type { ExportFile, ExportResult, ModelExporter } from "./types";

export const HYTALE_EXPORTER_VERSION = "hy-draft-0";
/** Cyrus geometry units per block (RigSpec / Blockbench convention). */
const UNITS_PER_BLOCK = 16;
/** Assumed animation clock (UNVERIFIED U11). */
export const HYTALE_ASSUMED_FPS = 60;

export const HYTALE_UNVERIFIED: readonly string[] = [
  "U1 .blockymodel JSON layout: { nodes: [node], lod } with node = { id, name, position, orientation, shape, children }",
  "U2 units: 1 Cyrus unit (1/16 block) = 1 Hytale model unit",
  "U3 node position is relative to the parent node's origin; a bone node's origin is its pivot",
  "U4 orientation is a quaternion {x,y,z,w} composed Z*Y*X from our Euler degrees",
  "U5 shape = { type: box|none, offset, stretch, settings.size, textureLayout, unwrapMode, visible, doubleSided, shadingMode }; offset = box centre from the node origin",
  "U6 face names front/back/left/right/top/bottom; Cyrus north=front, south=back, west=left, east=right, up=top, down=bottom",
  "U7 textureLayout per face = { offset {x,y} in texels of the upscaled sheet, mirror {x,y}, angle } (box net as in Minecraft)",
  "U8 inflate is written as shape.stretch (1 + 2*inflate/size per axis)",
  "U9 glow bones are written as shadingMode \"fullbright\"",
  "U10 one PNG per model, folder layout hytale/<name>/{model.blockymodel, texture.png, animations/<clip>.blockyanim} (not a real asset-pack layout; no manifest.json written)",
  "U11 .blockyanim layout { formatVersion, duration, holdLastKeyframe, nodeAnimations: { <node name>: { position, orientation, shapeStretch, shapeVisible, shapeUvOffset } } }; time in frames at 60 fps",
  "U12 animation position keys are deltas in model units; orientation keys are delta quaternions on top of the rest pose",
  "U13 scale tracks have no verified equivalent and are left out (a warning per track)",
  "U14 the maximum texture size (256 px used as a placeholder) and node/key limits",
  "U15 our clip names (idle, walk, attack, hurt, death) map to whatever Hytale's animation sets expect",
  "U16 waves baked to 8 keys per cycle (like rig-c1) are acceptable to the Hytale animator",
];
export const HYTALE_VERIFIED_INPUTS: readonly string[] = [
  "V1 file extensions .blockymodel / .blockyanim, PNG textures",
  "V2 cuboids (and quads) only; fixed materials",
  "V3 texel density 64 px per block-unit for mobs and equipment (32 for blocks)",
];

const r6 = (v: number) => { const x = Math.round(v * 1e6) / 1e6; return Object.is(x, -0) ? 0 : x; };
const xyz = (v: readonly number[]) => ({ x: r6(v[0]), y: r6(v[1]), z: r6(v[2]) });
/** Euler degrees (applied Z * Y * X, the bone convention) -> unit quaternion {x,y,z,w}. */
export function eulerToQuat(r: readonly number[]): { x: number; y: number; z: number; w: number } {
  const h = (d: number) => (d * Math.PI) / 360;
  const [cx, sx, cy, sy, cz, sz] = [Math.cos(h(r[0])), Math.sin(h(r[0])), Math.cos(h(r[1])), Math.sin(h(r[1])), Math.cos(h(r[2])), Math.sin(h(r[2]))];
  // q = qz * qy * qx
  const w = cz * cy * cx + sz * sy * sx;
  const x = cz * cy * sx - sz * sy * cx;
  const y = cz * sy * cx + sz * cy * sx;
  const z = sz * cy * cx - cz * sy * sx;
  return { x: r6(x), y: r6(y), z: r6(z), w: r6(w) };
}
const FACE_NAME: Record<Face, string> = { north: "front", south: "back", west: "left", east: "right", up: "top", down: "bottom" };

/** Nearest-neighbour upscale (k x k texels per source pixel): the skin at the game's texel density. */
export function upscale(r: Raster, k: number): Raster {
  const n = r.size * k, px = new Uint8ClampedArray(n * n * 4);
  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
    const s = (((y / k) | 0) * r.size + ((x / k) | 0)) * 4, d = (y * n + x) * 4;
    px[d] = r.px[s]; px[d + 1] = r.px[s + 1]; px[d + 2] = r.px[s + 2]; px[d + 3] = r.px[s + 3];
  }
  return { size: n, px };
}

const emptyShape = () => ({ type: "none", offset: xyz([0, 0, 0]), stretch: xyz([1, 1, 1]), settings: { isPiece: false }, textureLayout: {}, unwrapMode: "custom", visible: true, doubleSided: false, shadingMode: "flat" });

function blockyModel(doc: ModelDoc, layout: SkinLayout, k: number): Record<string, unknown> {
  let nid = 0;
  const boneName = new Map(doc.bones.map((b) => [b.id, b.name]));
  const node = (boneId: string): Record<string, unknown> => {
    const b = boneById(doc, boneId)!;
    const parent = b.parent ? boneById(doc, b.parent) : null;
    const origin = parent ? parent.pivot : [0, 0, 0];
    const id = String(++nid);
    const cubes = doc.cubes.filter((c) => c.bone === b.id).map((c, i) => {
      const cl = layout.cubes.find((x) => x.bone === b.name && x.index === i)!;
      const s = size(c);
      const textureLayout: Record<string, unknown> = {};
      for (const f of FACES) textureLayout[FACE_NAME[f]] = { offset: { x: cl.faces[f].x * k, y: cl.faces[f].y * k }, mirror: { x: false, y: false }, angle: 0 };
      return {
        id: String(++nid), name: `${b.name}_${i}`, position: xyz([c.pivot[0] - b.pivot[0], c.pivot[1] - b.pivot[1], c.pivot[2] - b.pivot[2]]), orientation: eulerToQuat(c.rotation),
        shape: {
          type: "box", offset: xyz(centre(c).map((v, j) => v - c.pivot[j])), stretch: xyz(s.map((v) => (v > 0 ? 1 + (2 * c.inflate) / v : 1))),
          settings: { isPiece: false, size: xyz(s) }, textureLayout, unwrapMode: "custom", visible: true, doubleSided: false, shadingMode: b.tag === "glow" ? "fullbright" : "flat",
        },
        children: [],
      };
    });
    return {
      id, name: b.name, position: xyz([b.pivot[0] - origin[0], b.pivot[1] - origin[1], b.pivot[2] - origin[2]]), orientation: eulerToQuat(b.rotation),
      shape: emptyShape(), children: [...cubes, ...doc.bones.filter((x) => x.parent === b.id).map((x) => node(x.id))],
    };
  };
  const root = doc.bones.find((b) => b.parent === null)!;
  void boneName;
  return { nodes: [node(root.id)], lod: "auto" };
}

function blockyAnim(doc: ModelDoc, clipName: string, issues: Issue[]): Record<string, unknown> {
  const clip = doc.clips.find((c) => c.name === clipName)!;
  const frames = Math.max(1, Math.round(clip.length * HYTALE_ASSUMED_FPS));
  const nodeAnimations: Record<string, Record<string, unknown[]>> = {};
  for (const t of clip.tracks) {
    const b = boneById(doc, t.bone);
    if (!b) continue;
    if (t.channel === "scale") { issues.push({ code: "hytale_scale_dropped", severity: "warn", path: `clips.${clipName}`, node: b.id, message: `${clipName}: the ${b.name} scale track is not exported (no verified Hytale scale channel)` }); continue; }
    const na = (nodeAnimations[b.name] ??= { position: [], orientation: [], shapeStretch: [], shapeVisible: [], shapeUvOffset: [] });
    const samples: { u: number; v: Vec3; interp: string }[] = [];
    if (t.wave) { const n = 8 * t.wave.cycles; for (let i = 0; i <= n; i++) samples.push({ u: i / n, v: sampleTrack(t, clip, i === n && clip.loop ? 0 : (i / n) * clip.length), interp: "smooth" }); }
    else for (const k of t.keys ?? []) samples.push({ u: k.t, v: k.v, interp: k.ease === "linear" ? "linear" : "smooth" });
    for (const s of samples) {
      const time = Math.round(s.u * frames);
      if (t.channel === "position") na.position.push({ time, delta: xyz(s.v), interpolationType: s.interp });
      else na.orientation.push({ time, delta: eulerToQuat(s.v), interpolationType: s.interp });
    }
  }
  return { formatVersion: 1, duration: frames, holdLastKeyframe: !clip.loop && clipName === "death", nodeAnimations };
}

const sha = (d: Buffer | string) => createHash("sha256").update(d).digest("hex");

export const hytaleDraftExporter: ModelExporter = {
  id: "hytale-blockymodel-draft", game: "hytale", target: "hytale-draft", label: "Hytale model (draft .blockymodel)",
  formats: [".blockymodel", ".blockyanim", ".png"], maturity: "planned", unverified: HYTALE_UNVERIFIED,
  run(doc, ctx): ExportResult {
    if (ctx.allowPlanned !== true) return { ok: false, exporter: this.id, code: "exporter_planned", error: "The Hytale exporter is planned: its format is unverified and no Hytale client has loaded its output.", issues: [] };
    const v = validateDoc(doc, "hytale-draft");
    if (!v.ok) return { ok: false, exporter: this.id, code: "invalid", error: v.issues.find((i) => i.severity === "error")!.message, issues: v.issues };
    // the skin comes from the SAME compiler as Minecraft (box UV net + palette shading), then goes to 64 px per block
    const chk = checkRigSpec(toRigSpec(doc).spec);
    if (!chk.ok) return { ok: false, exporter: this.id, code: "invalid", error: chk.error, issues: v.issues };
    const comp = compileCreature(chk.spec, ctx.namespace);
    if (!comp.ok) return { ok: false, exporter: this.id, code: "compile_failed", error: comp.error, issues: v.issues };
    const k = (TARGETS["hytale-draft"].texelsPerBlock ?? UNITS_PER_BLOCK) / UNITS_PER_BLOCK;
    const tex = upscale(comp.creature.raster, k);
    const issues: Issue[] = [...v.issues];
    if (tex.size > TARGETS["hytale-draft"].maxTextureRes) issues.push({ code: "hytale_texture_placeholder_limit", severity: "warn", path: "textures", message: `the ${tex.size} px texture is above the 256 px placeholder limit (the real Hytale limit is unpublished)` });
    const png = encodePng(tex);
    const dir = `hytale/${doc.name}`;
    const model = canonicalJson(blockyModel(doc, comp.creature.layout, k));
    const files: ExportFile[] = [
      { path: `${dir}/model.blockymodel`, mime: "application/json", data: model, sha256: sha(model) },
      { path: `${dir}/texture.png`, mime: "image/png", data: png, sha256: sha(png) },
    ];
    for (const cl of doc.clips) {
      const a = canonicalJson(blockyAnim(doc, cl.name, issues));
      files.push({ path: `${dir}/animations/${cl.name}.blockyanim`, mime: "application/json", data: a, sha256: sha(a) });
    }
    const sidecar = canonicalJson({
      cyrusExporter: HYTALE_EXPORTER_VERSION, maturity: "planned", draft: true, loadedByRealClient: false,
      texelsPerBlock: k * UNITS_PER_BLOCK, unitsPerBlock: UNITS_PER_BLOCK, textureSize: tex.size, fps: HYTALE_ASSUMED_FPS,
      verified: HYTALE_VERIFIED_INPUTS, unverified: HYTALE_UNVERIFIED,
    });
    files.push({ path: `${dir}/cyrus-export.json`, mime: "application/json", data: sidecar, sha256: sha(sidecar) });
    return { ok: true, exporter: this.id, files, issues, unverified: HYTALE_UNVERIFIED };
  },
};

