// Model Studio L2: the exporter registry. SERVER ONLY. A new game = one exporter file + one row here.
import { bbmodelExporter } from "./bbmodel";
import { hytaleDraftExporter } from "./hytale";
import { exportAllowed, type ExportContext, type ExportResult, type ModelExporter } from "./types";
import type { ModelDoc } from "../doc";

export const EXPORTERS: readonly ModelExporter[] = [bbmodelExporter, hytaleDraftExporter];
export const exporterById = (id: string) => EXPORTERS.find((e) => e.id === id) ?? null;
/** What the UI may list for a game (planned ones only with allowPlanned). */
export const exportersFor = (game: string, ctx: Pick<ExportContext, "allowPlanned"> = {}) => EXPORTERS.filter((e) => e.game === game && exportAllowed(e, ctx));

export function runExport(id: string, doc: ModelDoc, ctx: ExportContext): ExportResult {
  const e = exporterById(id);
  if (!e) return { ok: false, exporter: id, code: "invalid", error: `unknown exporter ${id}`, issues: [] };
  if (!exportAllowed(e, ctx)) return { ok: false, exporter: id, code: "exporter_planned", error: `${e.label} is planned and not available yet.`, issues: [] };
  return e.run(doc, ctx);
}
export type { ModelExporter, ExportResult, ExportContext } from "./types";

