  if (!viewer) return NOT_FOUND();
  if (!(await deps.enabled().catch(() => false))) return NOT_FOUND();
  const rl = deps.rateLimit(`model-editor:${limit.key}:${viewer.userId}`, limit.max, 60_000);
  if (!rl.ok) return json(429, { error: `Too many requests. Wait ${rl.retryAfterSec ?? 30}s.`, code: "rate_limited" });
  try { return await body(viewer); } catch (e) {
    if (e instanceof StudioError) return json(e.status, { error: e.message, code: e.code, ...e.extra });
    console.error("[cyrus-model-editor]", limit.key, (e as Error).message);
    return json(500, { error: "Something went wrong on our side. Nothing was changed.", code: "server_error" });
  }
}

type P = { projectId?: string; key?: string };
const params = (p: P) => { need(RE.project.test(p.projectId ?? ""), "projectId is not valid"); need(RE.key.test(p.key ?? ""), "key is not valid"); return p as Required<P>; };

/** GET /model-editor?root=<rootBuildId>: the mod's models + the viewer's access. */
export const handleModelList = (req: Request, deps: ModelEditorApiDeps) => run(deps, { key: "read", max: 120 }, async (v) => {
  const root = new URL(req.url).searchParams.get("root") ?? "";
  need(RE.root.test(root), "root must be a build id");
  return json(200, await listModels(deps.service, v.userId, root));
});

/** GET /model-editor/:projectId/:key: the model document, validation, access, the viewer's draft, exporters. */
export const handleModelGet = (_req: Request, p: P, deps: ModelEditorApiDeps) => run(deps, { key: "read", max: 120 }, async (v) => {
  const { projectId, key } = params(p);
  const view = await loadModel(deps.service, v.userId, projectId, key);
  return json(200, { ...view, exporters: exportersFor("minecraft", { allowPlanned: deps.allowPlanned }).concat(exportersFor("hytale", { allowPlanned: deps.allowPlanned })).map((e) => ({ id: e.id, label: e.label, maturity: e.maturity, unverified: e.unverified.length })) });
});

/** POST /model-editor/:projectId/:key { doc, baseAssetId, expectedHeadId, message?, action? }: save a revision. */
export const handleModelSave = (req: Request, p: P, deps: ModelEditorApiDeps) => run(deps, { key: "save", max: 30 }, async (v) => {
  const { projectId, key } = params(p);
  const b = await readJson(req);
  need(typeof b.baseAssetId === "string" && RE.id.test(b.baseAssetId), "baseAssetId is required");
  need(b.expectedHeadId === null || (typeof b.expectedHeadId === "string" && RE.id.test(b.expectedHeadId)), "expectedHeadId is required (null for none)");
  need(b.message === undefined || b.message === null || (typeof b.message === "string" && b.message.length <= 200), "message is at most 200 characters");
  need(b.action === undefined || b.action === "save" || b.action === "approve", "action is save or approve");
  const r = await saveModelRevision(deps.service, { userId: v.userId, projectId, key, doc: b.doc, baseAssetId: b.baseAssetId as string, expectedHeadId: b.expectedHeadId as string | null, message: (b.message as string | null | undefined) ?? null, action: (b.action as "save" | "approve" | undefined) ?? "save" });
  return json(200, r);
});

/** PUT /model-editor/:projectId/:key/draft { doc, baseAssetId, baseHeadId }: autosave. 503 while drafts are not wired. */
export const handleDraftPut = (req: Request, p: P, deps: ModelEditorApiDeps) => run(deps, { key: "draft", max: 30 }, async (v) => {
  const { projectId, key } = params(p);
  const b = await readJson(req);
  return json(200, await saveDraft(deps.service, { userId: v.userId, projectId, key, doc: b.doc, baseAssetId: typeof b.baseAssetId === "string" ? b.baseAssetId : null, baseHeadId: typeof b.baseHeadId === "string" ? b.baseHeadId : null }));
});

/** POST /model-editor/:projectId/:key/export { exporter, doc }: export files (never plan-gated; maturity-gated). */
export const handleModelExport = (req: Request, p: P, deps: ModelEditorApiDeps) => run(deps, { key: "export", max: 20 }, async (v) => {
  const { projectId, key } = params(p);
  const b = await readJson(req);
  need(typeof b.exporter === "string" && /^[a-z0-9-]{3,40}$/.test(b.exporter), "exporter is required");
  const d = canModelEditor(null, "export"); // export is never gated, even on an unknown plan
  if (!d.ok) throw new StudioError(403, d.code, d.reason);
  const view = await loadModel(deps.service, v.userId, projectId, key);
  const doc = b.doc === undefined ? view.model.doc : (() => { const c = checkModelDoc(b.doc); if (!c.ok) throw new StudioError(400, "bad_doc", c.error); return c.doc; })();
  const r = runExport(b.exporter as string, doc, { namespace: view.namespace, allowPlanned: deps.allowPlanned });
  if (!r.ok) return json(r.code === "exporter_planned" ? 409 : 422, { error: r.error, code: r.code, issues: r.issues.slice(0, 20) });
  return json(200, { exporter: r.exporter, unverified: r.unverified, issues: r.issues, files: r.files.map((f) => ({ path: f.path, mime: f.mime, sha256: f.sha256, bytes: typeof f.data === "string" ? Buffer.byteLength(f.data) : f.data.length, ...(f.mime === "application/json" && typeof f.data === "string" && f.data.length < 200_000 ? { text: f.data } : {}) })) });
});

