// Model Studio L2: a DETERMINISTIC stand-in for an AI model edit, so the candidate bar + 3-way merge can be exercised
// without any model call (tests, devhost screenshots with ?fakeCandidate=1 outside production). It behaves like the
// real path will: it takes the BASE revision's RigSpec (never the working copy), edits the spec, re-validates it and
// lines it up with the base (fromRigSpec like), so its ids match R. Pure + client-safe.
import { checkRigSpec, type RigSpecInput } from "../../creature/spec";
import { boneByName, type ModelDoc } from "./doc";
import { fromRigSpec, toRigSpec } from "./rigspec";

type SpecBone = { name: string; cubes: { from: number[]; to: number[] }[] };
type SpecClip = { tracks: { bone: string; channel: string; wave?: { amp: number[] }; keys?: { v: number[] }[] }[] };

/** "make the hood longer ..." -> lengthen the named bone's first cube by 2 units downward and widen its idle sway. */
export function fakeModelCandidate(base: ModelDoc, prompt: string): { ok: true; doc: ModelDoc; summary: string } | { ok: false; error: string } {
  const spec = JSON.parse(JSON.stringify(toRigSpec(base).spec)) as RigSpecInput & { bones: SpecBone[]; animations: Record<string, SpecClip> };
  const words = prompt.toLowerCase().match(/[a-z_]+/g) ?? [];
  const target = spec.bones.find((b) => words.includes(b.name) && b.cubes.length) ?? spec.bones.find((b) => b.cubes.length && boneByName(base, b.name)?.parent !== null);
  if (!target) return { ok: false, error: "nothing to edit" };
  const c = target.cubes[0];
  c.from[1] = Math.max(-63, c.from[1] - 2);
  for (const t of spec.animations.idle?.tracks ?? []) if (t.bone === target.name && t.channel === "rotation") {
    if (t.wave) t.wave.amp = t.wave.amp.map((v) => Math.max(-180, Math.min(180, Math.round(v * 1.5 * 100) / 100)));
    else for (const k of t.keys ?? []) k.v = k.v.map((v) => Math.round(v * 1.5 * 100) / 100);
  }
  const chk = checkRigSpec(spec);
  if (!chk.ok) return { ok: false, error: chk.error };
  return { ok: true, doc: fromRigSpec(chk.spec, { like: base }), summary: `Longer ${target.name} and a wider idle sway` };
}

