    assert.deepEqual(r.doc.bones.find((b) => b.id === arm.id)!.rotation, [0, 0, -157.5]);
    const r2 = ok(applyOp(r.doc, { op: "rotate", ids: [arm.id], rotation: [5, 0, 0], mode: "add", snap: 5 }));
