  it("resize keeps the origin, snaps, keeps a centred pivot centred; scale works around a point", () => {
    const c = d0.cubes[0];
    const r = ok(applyOp(d0, { op: "resize", id: c.id, size: [6.3, 2, 2.6], snap: 1 }));
    const n = r.doc.cubes[0];
    assert.deepEqual(n.from, c.from);
    assert.deepEqual(n.to.map((v, i) => Math.round((v - n.from[i]) * 1e4) / 1e4), [6, 2, 3]);
    assert.deepEqual(n.pivot, n.from.map((v, i) => (v + n.to[i]) / 2));
    const s = ok(applyOp(d0, { op: "scale", ids: [c.id], factor: 2, about: [0, 0, 0] }));
