    assert.ok(!r.doc.cubes.some((c) => c.bone === head.id));
    assert.ok(!r.doc.clips.some((cl) => cl.tracks.some((t) => t.bone === head.id)));
    assert.equal(applyOp(d0, { op: "delete", ids: [d0.bones.find((b) => b.parent === null)!.id] }).ok, false);
    const locked = ok(applyOp(d0, { op: "setFlag", ids: [bone(d0, "eyes").id], flag: "locked", value: true })).doc;
