    assert.equal(applyOp(d0, { op: "reparent", id: head.id, parent: eyes.id }).ok, false);
    const r = ok(applyOp(d0, { op: "reparent", id: eyes.id, parent: bone(d0, "body").id }));
    assert.equal(r.doc.bones.find((b) => b.id === eyes.id)!.parent, bone(d0, "body").id);
    const hair = bone(d0, "hair");
    const g = ok(applyOp(d0, { op: "group", ids: cubesOf(d0, hair.id).slice(1).map((c) => c.id), name: "hair_sides" }));
    const gb = bone(g.doc, "hair_sides");
