  });
  it("UV pin / auto-UV, rename, hide, tag, palette, cube props", () => {
    const c = d0.cubes[1];
    const p = ok(applyOp(d0, { op: "setUv", id: c.id, uv: [90, 90] })).doc;
    assert.deepEqual(p.cubes[1].uv, [90, 90]);
    assert.equal(ok(applyOp(p, { op: "autoUv" })).doc.cubes[1].uv, null);
    assert.equal(applyOp(d0, { op: "autoUv" }).ok, false);
    const rn = ok(applyOp(d0, { op: "rename", id: bone(d0, "wisp").id, name: "trail" })).doc;
    assert.ok(boneByName(rn, "trail"));
    assert.equal(ok(applyOp(d0, { op: "rename", id: c.id, name: "veil hem" })).doc.cubes[1].label, "veil hem");
    assert.equal(applyOp(d0, { op: "setBone", id: bone(d0, "body").id, props: { tag: "head" } }).ok, false, "one head only");
    assert.equal(applyOp(d0, { op: "setPalette", key: "robe", color: null }).ok, false, "a used colour can't be removed");
    const sc = ok(applyOp(d0, { op: "setCube", id: c.id, props: { shade: "fade", inflate: 0.25 } })).doc.cubes[1];
    assert.equal(sc.shade, "fade"); assert.ok(sc.fadeTo); assert.equal(sc.inflate, 0.25);
    assert.equal(cubeLabel(d0, c.id), "cube 0");
  });
  it("keys: set inserts sorted and keeps a loop seam, edge keys are protected, waves convert to equal keys", () => {
    const head = bone(d0, "head");
    let d = ok(applyOp(d0, { op: "setKey", clip: "attack", bone: head.id, channel: "position", t: 0.4, v: [0, 2, 0], ease: "linear" })).doc;
    const tr = d.clips.find((c) => c.name === "attack")!.tracks.find((t) => t.bone === head.id && t.channel === "position")!;
    assert.deepEqual(tr.keys!.map((k) => k.t), [0, 0.4, 1]);
    assert.equal(applyOp(d, { op: "deleteKey", clip: "attack", key: tr.keys![0].id }).ok, false);
    assert.equal(applyOp(d, { op: "moveKey", clip: "attack", key: tr.keys![1].id, t: 1.2 }).ok, false);
    d = ok(applyOp(d, { op: "moveKey", clip: "attack", key: tr.keys![1].id, t: 0.6 })).doc;
    const idle = d.clips.find((c) => c.name === "idle")!;
    const wave = idle.tracks.find((t) => t.wave)!;
    const conv = ok(applyOp(d, { op: "waveToKeys", clip: "idle", bone: wave.bone, channel: wave.channel })).doc;
    const keyed = conv.clips.find((c) => c.name === "idle")!.tracks.find((t) => t.bone === wave.bone && t.channel === wave.channel)!;
    for (const k of keyed.keys!) assert.ok(sampleTrack(wave, idle, k.t * idle.length).every((v, i) => Math.abs(v - k.v[i]) < 1e-3 || k.t === 1));
    assert.ok(validateDoc(conv).ok, "converted clip still validates (loop seam kept)");
    const looped = ok(applyOp(conv, { op: "setKey", clip: "idle", bone: keyed.bone, channel: keyed.channel, t: 0, v: [3, 0, 0] })).doc;
    const lk = looped.clips.find((c) => c.name === "idle")!.tracks.find((t) => t.bone === keyed.bone && t.channel === keyed.channel)!.keys!;
    assert.deepEqual(lk[0].v, lk[lk.length - 1].v, "a looping clip's first and last key stay equal");
    assert.equal(applyOp(d0, { op: "setKey", clip: "idle", bone: wave.bone, channel: wave.channel, t: 0.5, v: [1, 1, 1] }).ok, false, "a wave must be converted first");
  });
  it("clips: add / rename / delete with name rules and the clip cap", () => {
    let d = ok(applyOp(d0, { op: "addClip", name: "wail", length: 1.5, loop: false })).doc;
    assert.equal(applyOp(d, { op: "addClip", name: "wail", length: 1, loop: false }).ok, false);
    assert.equal(validateDoc(d).issues.some((i) => i.code === "empty_clip"), true);
    d = ok(applyOp(d, { op: "setClip", name: "wail", rename: "scream", loop: true })).doc;
    assert.ok(d.clips.some((c) => c.name === "scream" && c.loop));
    d = ok(applyOp(d, { op: "deleteClip", name: "scream" })).doc;
    assert.equal(d.clips.length, d0.clips.length);
    for (let i = d0.clips.length; i < 8; i++) d = ok(applyOp(d, { op: "addClip", name: `extra_${i}`, length: 1, loop: false })).doc;
    assert.equal(applyOp(d, { op: "addClip", name: "one_more", length: 1, loop: false }).ok, false);
  });
  it("ops never mutate their input document", () => {
    const before = serializeDoc(d0);
    for (const op of [{ op: "move", ids: [d0.cubes[0].id], delta: [3, 0, 0] }, { op: "delete", ids: [bone(d0, "head").id] }, { op: "mirror", ids: [d0.cubes[0].id] }] as Op[]) ok(applyOp(d0, op));
    assert.equal(serializeDoc(d0), before);
  });
});

describe("Model Studio L2: op log undo / redo", () => {
  it("undo/redo walk the log and replay(base, ops) equals the cached documents byte for byte", () => {
    const base = docOf("dire_wolf");
    let log = logInit(base);
    const ops: Op[] = [
      { op: "move", ids: [base.cubes[0].id], delta: [1, 0, 0] },
      { op: "addCube", bone: base.bones[0].id },
      { op: "rename", id: base.bones[1].id, name: "neck_x" },
      { op: "setKey", clip: "walk", bone: base.bones[0].id, channel: "position", t: 0.5, v: [0, 1, 0] },
    ];
    for (const op of ops) { const r = logApply(log, op); assert.ok(r.ok, (r as { error?: string }).error); log = r.log; }
    assert.equal(serializeDoc(replay(log.base, log.entries)), serializeDoc(currentDoc(log)));
    log = logUndo(logUndo(log));
    assert.equal(serializeDoc(currentDoc(log)), serializeDoc(replay(log.base, log.entries, 2)));
    assert.ok(canRedo(log) && canUndo(log));
    log = logRedo(log);
    assert.equal(log.at, 3);
    const branched = logApply(log, { op: "autoUv" });
    assert.equal(branched.ok, false, "a refused op does not touch the log");
    const b2 = logApply(log, { op: "setFlag", ids: [base.cubes[0].id], flag: "hidden", value: true });
    assert.ok(b2.ok);
    assert.equal(b2.log.entries.length, 4, "the redo branch was dropped");
  });
  it(`keeps at most ${MAX_STEPS} steps by folding the oldest into the base`, () => {
    const base = docOf("banshee");
    let log = logInit(base);
    for (let i = 0; i < MAX_STEPS + 15; i++) log = (logApply(log, { op: "move", ids: [base.cubes[0].id], delta: [i % 2 ? -1 : 1, 0, 0] }) as { log: typeof log }).log;
    assert.equal(log.entries.length, MAX_STEPS);
    assert.equal(serializeDoc(replay(log.base, log.entries)), serializeDoc(currentDoc(log)));
  });
});

