describe("Model Studio L2: UV layout and pose sampler match the compiler", () => {
  for (const n of FIXTURES) {
    it(`${n}: auto-pack == creature/compile.ts layoutSkin`, () => {
      const s = spec(load(n));
      const doc = fromRigSpec(s);
      const lay = layoutSkin(s);
      assert.ok(lay.ok);
      const mine = layoutUv(doc);
      assert.equal(mine.size, lay.ok && lay.layout.size);
      const byKey = new Map(mine.boxes.map((b) => [b.cube, b]));
      lay.ok && lay.layout.cubes.forEach((cl) => {
        const id = cubesOf(doc, bone(doc, cl.bone).id)[cl.index].id;
        assert.deepEqual(byKey.get(id)!.faces, cl.faces);
      });
    });
    it(`${n}: sampleTrack + bone matrices == the compiler and preview renderer`, () => {
      const s = spec(load(n));
      const doc = fromRigSpec(s);
      for (const cl of doc.clips) {
        const rc = s.animations[cl.name];
        cl.tracks.forEach((t, i) => {
          for (let k = 0; k <= 12; k++) {
            const time = (k / 12) * cl.length;
            const a = sampleTrack(t, cl, time), b = compilerSample(rc.tracks[i], rc, time);
            assert.ok(a.every((v, j) => Math.abs(v - b[j]) < 1e-9));
          }
        });
        const mine = boneMatrices(doc, samplePose(doc, cl.name, cl.length * 0.37));
        const theirs = poseMatrices(s, cl.name, cl.length * 0.37);
        for (const b of doc.bones) assert.ok(mine.get(b.id)!.every((v, j) => Math.abs(v - theirs.get(b.name)![j]) < 1e-9));
      }
    });
  }
});

