// Cyrus Model Studio layer 2 (cuboid + bone editor), pure + service tests: document model, every v1 operation, the
// op-log undo/redo with deterministic replay, validation issues + budgets, UV layout == the compiler's, the pose
// sampler == the compiler's, the 3-way merge rule for AI edits, the plan gate matrix, the autosave schedule, RigSpec
// round trips (byte-stable, same .bbmodel), the exporter interface (bbmodel + DRAFT Hytale golden), the save path
// (revisions, stale_head, gate, drafts) and the HTTP handlers (flag off = 404).
// Golden files: test/fixtures/cyrus-modelstudio/. Regenerate ONLY on a deliberate format change:
//   UPDATE_MODELSTUDIO_GOLDEN=1 npx tsx --test test/cyrus-modelstudio-editor.test.ts
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { checkRigSpec, type RigSpec } from "../lib/cyrus/creature/spec";
import { compileCreature, layoutSkin, sampleTrack as compilerSample } from "../lib/cyrus/creature/compile";
import { poseMatrices } from "../lib/cyrus/creature/preview";
import { canonicalJson as assetsCanonical } from "../lib/cyrus/assets/textures";
import { RIG_SPEC_MIME } from "../lib/cyrus/creature/portal";
import { canonicalJson } from "../lib/cyrus/modelstudio/editor/canonical";
import { checkModelDoc, MODEL_DOC_MIME, boneByName, cubesOf, type ModelDoc } from "../lib/cyrus/modelstudio/editor/doc";
import { fromRigSpec, toRigSpec } from "../lib/cyrus/modelstudio/editor/rigspec";
import { applyOp, applyAll, cubeLabel, type Op } from "../lib/cyrus/modelstudio/editor/ops";
import { canRedo, canUndo, currentDoc, logApply, logInit, logRedo, logUndo, replay, serializeDoc, MAX_STEPS } from "../lib/cyrus/modelstudio/editor/history";
import { validateDoc } from "../lib/cyrus/modelstudio/editor/validate";
import { layoutUv } from "../lib/cyrus/modelstudio/editor/uv";
import { boneMatrices, samplePose, sampleTrack } from "../lib/cyrus/modelstudio/editor/pose";
import { diffDocs, mergeCandidate, mergeSummary } from "../lib/cyrus/modelstudio/editor/merge";
import { canModelEditor, MODEL_EDITOR_ACTIONS } from "../lib/cyrus/modelstudio/editor/gate";
import { autosaveDone, autosaveDueIn, autosaveEdit, autosaveInit } from "../lib/cyrus/modelstudio/editor/autosave";
import { buildScene, fitCamera, pickCube, axisDrag, project } from "../lib/cyrus/modelstudio/editor/scene";
import { fakeModelCandidate } from "../lib/cyrus/modelstudio/editor/fake-candidate";
import { EXPORTERS, runExport, exportersFor } from "../lib/cyrus/modelstudio/editor/export";
import { HYTALE_UNVERIFIED, eulerToQuat } from "../lib/cyrus/modelstudio/editor/export/hytale";
import { memoryDraftStore, resolveModels, saveModelRevision, saveDraft, loadModel, type ModelEditorDeps } from "../lib/cyrus/modelstudio/editor/service";
import { handleModelGet, handleModelSave, type ModelEditorApiDeps } from "../lib/cyrus/modelstudio/editor/http";
import { MODEL_EDITOR_ACTION_OP } from "../lib/cyrus/engine-core/asset-gate";
import type { AssetRow, ProjectRow, RevRow } from "../lib/cyrus/studios/service";

const ROOT = path.resolve(__dirname, "..");
const FX = path.join(ROOT, "test/fixtures/cyrus-creatures");
const GOLD = path.join(ROOT, "test/fixtures/cyrus-modelstudio");
const NS = "nx_r6cr34tr";
const load = (n: string) => JSON.parse(fs.readFileSync(path.join(FX, `${n}.json`), "utf8"));
const spec = (raw: unknown): RigSpec => { const c = checkRigSpec(raw); if (!c.ok) throw new Error(c.error); return c.spec; };
const docOf = (n: string) => fromRigSpec(spec(load(n)));
const FIXTURES = ["banshee", "ghoul", "dire_wolf"];
const ok = (r: ReturnType<typeof applyOp>) => { if (!r.ok) throw new Error(r.error); return r; };
const bbmodel = (s: RigSpec) => { const c = compileCreature(s, NS); if (!c.ok) throw new Error(c.error); return c.creature; };
const bone = (d: ModelDoc, name: string) => { const b = boneByName(d, name); if (!b) throw new Error(`no bone ${name}`); return b; };

describe("Model Studio L2: document + RigSpec round trip", () => {
  for (const n of FIXTURES) {
    it(`${n}: RigSpec -> ModelDoc -> RigSpec compiles to the byte-identical .bbmodel and skin`, () => {
      const s = spec(load(n));
      const doc = fromRigSpec(s);
      assert.equal(checkModelDoc(doc).ok, true, "the converted doc parses as a ModelDoc");
      const back = spec(toRigSpec(doc).spec);
      const a = bbmodel(s), b = bbmodel(back);
      assert.equal(b.bbmodelSha256, a.bbmodelSha256);
      assert.equal(b.pngSha256, a.pngSha256);
    });
    it(`${n}: the round trip is a fixed point (second pass byte-identical) and ids are deterministic`, () => {
      const once = toRigSpec(fromRigSpec(spec(load(n)))).spec;
      const twice = toRigSpec(fromRigSpec(spec(once))).spec;
      assert.equal(canonicalJson(twice), canonicalJson(once));
      assert.equal(serializeDoc(fromRigSpec(spec(load(n)))), serializeDoc(fromRigSpec(spec(load(n)))));
    });
    it(`${n}: load -> save -> load with like keeps every id (byte-stable document)`, () => {
      const doc = docOf(n);
      const again = fromRigSpec(spec(toRigSpec(doc).spec), { like: doc });
      assert.equal(serializeDoc(again), serializeDoc(doc));
    });
  }
  it("the canonical twin matches lib/cyrus/assets canonicalJson", () => {
    const d = docOf("banshee");
    assert.equal(canonicalJson(d), assetsCanonical(d));
  });
  it("checkModelDoc refuses junk and oversize docs, never throws", () => {
    for (const bad of [null, 1, {}, { ...docOf("banshee"), v: 2 }, { ...docOf("banshee"), extra: 1 }, { ...docOf("banshee"), name: "Bad Name" }]) assert.equal(checkModelDoc(bad).ok, false);
    const d = docOf("banshee") as unknown as Record<string, unknown>;
    assert.equal(checkModelDoc({ ...d, bones: Array.from({ length: 97 }, (_, i) => ({ ...(d.bones as object[])[0], id: `b${i + 1}` })) }).ok, false);
  });
  it("an edited model saves byte-stable: same ops on the same base -> same RigSpec and .bbmodel", () => {
    const run = () => {
      const d = docOf("ghoul");
      const head = bone(d, "head");
      const r = applyAll(d, [
        { op: "move", ids: [cubesOf(d, head.id)[0].id], delta: [0, 1.3, 0], snap: 1 },
        { op: "setKey", clip: "idle", bone: head.id, channel: "rotation", t: 0.5, v: [6, 0, 0] },
      ]);
      assert.equal(r.error, undefined);
      const s = spec(toRigSpec(r.doc).spec);
      return { doc: serializeDoc(r.doc), bb: bbmodel(s).bbmodelSha256 };
    };
    assert.deepEqual(run(), run());
  });
  it("editor-only fields are reported as dropped by toRigSpec", () => {
    const d = docOf("banshee");
    const c = d.cubes[0];
    const e = ok(applyOp(ok(applyOp(d, { op: "rotate", ids: [c.id], rotation: [0, 0, 10], mode: "set" })).doc, { op: "setUv", id: c.id, uv: [100, 100] })).doc;
    const dropped = toRigSpec(e).dropped.map((x) => x.field).sort();
    assert.deepEqual(dropped, ["rotation", "uv"]);
  });
});

