describe("Model Studio L2: op log undo / redo", () => {
  it("undo/redo walk the log and replay(base, ops) equals the cached documents byte for byte", () => {
    const base = docOf("dire_wolf");
    let log = logInit(base);
    const ops: Op[] = [
      { op: "move", ids: [base.cubes[0].id], delta: [1, 0, 0] },
      { op: "addCube", bone: base.bones[0].id },
      { op: "rename", id: base.bones[1].id, name: "neck_x" },
      { op: "setKey", clip: "walk", bone: base.bones[0].id, channel: "position", t: 0.5, v: [0, 1, 0] },
    ];
    for (const op of ops) { const r = logApply(log, op); assert.ok(r.ok, (r as { error?: string }).error); log = r.log; }
    assert.equal(serializeDoc(replay(log.base, log.entries)), serializeDoc(currentDoc(log)));
    log = logUndo(logUndo(log));
    assert.equal(serializeDoc(currentDoc(log)), serializeDoc(replay(log.base, log.entries, 2)));
    assert.ok(canRedo(log) && canUndo(log));
    log = logRedo(log);
    assert.equal(log.at, 3);
    const branched = logApply(log, { op: "autoUv" });
    assert.equal(branched.ok, false, "a refused op does not touch the log");
    const b2 = logApply(log, { op: "setFlag", ids: [base.cubes[0].id], flag: "hidden", value: true });
    assert.ok(b2.ok);
    assert.equal(b2.log.entries.length, 4, "the redo branch was dropped");
  });
  it(`keeps at most ${MAX_STEPS} steps by folding the oldest into the base`, () => {
    const base = docOf("banshee");
    let log = logInit(base);
    for (let i = 0; i < MAX_STEPS + 15; i++) log = (logApply(log, { op: "move", ids: [base.cubes[0].id], delta: [i % 2 ? -1 : 1, 0, 0] }) as { log: typeof log }).log;
    assert.equal(log.entries.length, MAX_STEPS);
    assert.equal(serializeDoc(replay(log.base, log.entries)), serializeDoc(currentDoc(log)));
  });
});

