describe("Model Studio L2: merge rule for AI edits mid-session", () => {
  const R = docOf("banshee");
  const hood = () => bone(R, "hair");
  it("disjoint changes merge; Cyrus's change and the human's both land", () => {
    const ours = ok(applyOp(R, { op: "move", ids: [cubesOf(R, bone(R, "body").id)[0].id], delta: [0, 0, 1] })).doc;
    const theirs = ok(applyOp(R, { op: "setCube", id: cubesOf(R, hood().id)[0].id, props: { inflate: 0.5 } })).doc;
    const m = mergeCandidate(R, ours, theirs);
    assert.equal(m.overlaps.length, 0);
    assert.equal(m.applied.length, 1);
    assert.equal(cubesOf(m.doc, hood().id)[0].inflate, 0.5);
    assert.deepEqual(cubesOf(m.doc, bone(R, "body").id)[0].from, cubesOf(ours, bone(R, "body").id)[0].from);
    assert.ok(validateDoc(m.doc).ok);
  });
  it("the same field changed on both sides is ONE overlap; human wins by default, resolve can pick Cyrus", () => {
    const cid = cubesOf(R, hood().id)[0].id;
    const ours = ok(applyOp(R, { op: "setCube", id: cid, props: { inflate: 0.25 } })).doc;
    const theirs = ok(applyOp(R, { op: "setCube", id: cid, props: { inflate: 0.75 } })).doc;
    const m = mergeCandidate(R, ours, theirs);
    assert.equal(m.overlaps.length, 1);
    assert.equal(mergeSummary(m), "0 changes · 1 overlap");
    assert.equal(m.doc.cubes.find((c) => c.id === cid)!.inflate, 0.25);
    const t = mergeCandidate(R, ours, theirs, { resolve: { [m.overlaps[0].id]: "theirs" } });
    assert.equal(t.doc.cubes.find((c) => c.id === cid)!.inflate, 0.75);
  });
  it("edit vs delete is an overlap (human wins); Apply part skips unchecked changes", () => {
    const head = bone(R, "head");
    const ours = ok(applyOp(R, { op: "rotate", ids: [head.id], rotation: [10, 0, 0], mode: "set" })).doc;
    const theirs = applyAll(R, [{ op: "delete", ids: [head.id] }, { op: "setCube", id: R.cubes[0].id, props: { inflate: 0.5 } }]).doc;
    const m = mergeCandidate(R, ours, theirs);
    assert.ok(m.overlaps.some((o) => o.node === head.id && o.field === null));
    assert.ok(boneByName(m.doc, "head"), "the human's edited head stays");
    const part = mergeCandidate(R, ours, theirs, { accept: new Set() });
    assert.equal(part.applied.length, 0);
    assert.ok(part.skipped.length > 0);
    assert.equal(part.doc.cubes[0].inflate, R.cubes[0].inflate);
  });
  it("both sides adding nodes: Cyrus's ids are renumbered, a clashing bone name is renamed, dangling nodes dropped", () => {
    const body = bone(R, "body");
    const ours = ok(applyOp(R, { op: "addBone", parent: body.id, name: "tail" })).doc;
    const t1 = ok(applyOp(R, { op: "addBone", parent: body.id, name: "tail" }));
    const theirs = ok(applyOp(t1.doc, { op: "addCube", bone: t1.select![0] })).doc;
    assert.equal(t1.select![0], ours.bones.find((b) => b.name === "tail")!.id, "same id on both sides before the merge");
    const m = mergeCandidate(R, ours, theirs);
    assert.equal(new Set(m.doc.bones.map((b) => b.id)).size, m.doc.bones.length);
    assert.equal(new Set(m.doc.bones.map((b) => b.name)).size, m.doc.bones.length);
    assert.ok(m.notes.some((n) => /renamed tail_2/.test(n)));
    // Cyrus adds a cube to a bone the human deleted -> dropped with a note
    const wisp = bone(R, "wisp");
    const oursDel = ok(applyOp(R, { op: "delete", ids: [wisp.id] })).doc;
    const theirsAdd = ok(applyOp(R, { op: "addCube", bone: wisp.id })).doc;
    const m2 = mergeCandidate(R, oursDel, theirsAdd);
    assert.ok(!m2.doc.cubes.some((c) => c.bone === wisp.id));
    assert.ok(m2.notes.some((n) => /cube was left out/.test(n)));
    assert.ok(validateDoc(m2.doc).issues.every((i) => i.code !== "orphan_cube"));
  });
  it("the fake AI candidate is built from the BASE revision and merges against the working copy", () => {
    const head = bone(R, "head");
    const ours = ok(applyOp(R, { op: "rotate", ids: [head.id], rotation: [8, 0, 0], mode: "set" })).doc;
    const cand = fakeModelCandidate(R, "make the hair longer");
    assert.ok(cand.ok);
    const m = mergeCandidate(R, ours, cand.ok ? cand.doc : R);
    assert.equal(m.overlaps.length, 0);
    assert.ok(m.applied.some((c) => c.kind === "cube" && c.field === "from"));
    assert.deepEqual(m.doc.bones.find((b) => b.id === head.id)!.rotation, [8, 0, 0]);
    assert.ok(diffDocs(R, m.doc).length >= 2);
  });
  it("merging is deterministic", () => {
    const ours = ok(applyOp(R, { op: "move", ids: [R.cubes[3].id], delta: [1, 0, 0] })).doc;
    const cand = fakeModelCandidate(R, "hair");
    const a = mergeCandidate(R, ours, cand.ok ? cand.doc : R), b = mergeCandidate(R, ours, cand.ok ? cand.doc : R);
    assert.equal(serializeDoc(a.doc), serializeDoc(b.doc));
  });
});

describe("Model Studio L2: plan gate + autosave schedule", () => {
  it("only the top plan may create/edit; view + export are never gated; unknown fails closed for edits", () => {
    const edits = MODEL_EDITOR_ACTIONS.filter((a) => MODEL_EDITOR_ACTION_OP[a] === "edit" || MODEL_EDITOR_ACTION_OP[a] === "create");
    assert.deepEqual(edits.sort(), ["ai_edit", "approve", "autosave", "create", "edit", "save"]);
    for (const plan of ["free", "katara", "saka", null, "typo", undefined]) {
      for (const a of edits) assert.equal(canModelEditor(plan, a).ok, false, `${plan} ${a}`);
      assert.equal(canModelEditor(plan, "view").ok, true);
      assert.equal(canModelEditor(plan, "export").ok, true);
    }
    for (const plan of ["all", "yakko", "All models"]) for (const a of MODEL_EDITOR_ACTIONS) assert.equal(canModelEditor(plan, a).ok, true);
    const d = canModelEditor("saka", "save");
    assert.ok(!d.ok && d.code === "asset_locked" && d.needs === "all");
    const u = canModelEditor(null, "save");
    assert.ok(!u.ok && u.code === "plan_unknown");
    assert.equal(canModelEditor("all", "fly" as never).ok, false);
  });
  it("autosave: 5 s after the last edit, at most 30 s after the first unsaved edit", () => {
    let s = autosaveInit("saved");
    assert.equal(autosaveDueIn(s, 0), null);
    s = autosaveEdit(s, 1000, "a");
    assert.equal(autosaveDueIn(s, 1000), 5000);
    for (let t = 2000; t <= 30000; t += 2000) s = autosaveEdit(s, t, `x${t}`);
    assert.equal(autosaveDueIn(s, 30000), 1000, "the 30 s cap wins over the idle timer");
    s = autosaveDone(s, "x30000");
    assert.equal(autosaveDueIn(s, 31000), null);
    assert.equal(autosaveDueIn(autosaveEdit(s, 32000, "x30000"), 32000), null, "editing back to the saved bytes is not dirty");
  });
});

describe("Model Studio L2: exporters", () => {
  it("the registry is game-neutral; planned exporters are hidden and refused without allowPlanned", () => {
    assert.deepEqual(EXPORTERS.map((e) => [e.id, e.maturity]), [["minecraft-bbmodel", "beta"], ["hytale-blockymodel-draft", "planned"]]);
    assert.deepEqual(exportersFor("hytale").map((e) => e.id), []);
    assert.deepEqual(exportersFor("hytale", { allowPlanned: true }).map((e) => e.id), ["hytale-blockymodel-draft"]);
    const r = runExport("hytale-blockymodel-draft", docOf("banshee"), { namespace: NS });
    assert.ok(!r.ok && r.code === "exporter_planned");
  });
  it("the bbmodel exporter writes exactly what the creature compiler writes", () => {
    const s = spec(load("banshee"));
    const r = runExport("minecraft-bbmodel", fromRigSpec(s), { namespace: NS });
    assert.ok(r.ok, !r.ok ? r.error : "");
    const c = bbmodel(s);
    assert.equal(r.ok && r.files.find((f) => f.path.endsWith(".bbmodel"))!.sha256, c.bbmodelSha256);
    assert.equal(r.ok && r.files.find((f) => f.path.endsWith(".png"))!.sha256, c.pngSha256);
    const bad = ok(applyOp(fromRigSpec(s), { op: "rotate", ids: [fromRigSpec(s).cubes[0].id], rotation: [0, 10, 0], mode: "set" })).doc;
    const rb = runExport("minecraft-bbmodel", bad, { namespace: NS });
    assert.ok(!rb.ok && rb.code === "invalid");
  });
  it("DRAFT Hytale golden: the assumed .blockymodel/.blockyanim layout (every guess listed as UNVERIFIED)", () => {
    // Documents the ASSUMED layout (HYTALE_UNVERIFIED U1-U16); only V1-V3 of N-hytale.md are facts. If a real Hytale
    // file disagrees, change export/hytale.ts and regenerate these goldens deliberately.
    assert.equal(HYTALE_UNVERIFIED.length, 16);
    const r = runExport("hytale-blockymodel-draft", docOf("banshee"), { namespace: NS, allowPlanned: true });
    assert.ok(r.ok, !r.ok ? r.error : "");
    if (!r.ok) return;
    const files = Object.fromEntries(r.files.map((f) => [f.path, f]));
    const model = JSON.parse(String(files["hytale/banshee/model.blockymodel"].data));
    assert.equal(model.nodes.length, 1);
    assert.equal(model.nodes[0].name, "body");
    const shapes: string[] = [];
    const walk = (n: { shape: { type: string }; children: unknown[] }) => { shapes.push(n.shape.type); n.children.forEach((c) => walk(c as never)); };
    walk(model.nodes[0]);
    assert.ok(shapes.every((s) => s === "box" || s === "none"), "cuboids only (V2)");
    assert.equal(shapes.filter((s) => s === "box").length, docOf("banshee").cubes.length);
    const png = files["hytale/banshee/texture.png"].data as Buffer;
    assert.equal(png.readUInt32BE(16), layoutUv(docOf("banshee")).size * 4, "64 px per block = 4 texels per unit (V3)");
    const side = JSON.parse(String(files["hytale/banshee/cyrus-export.json"].data));
    assert.equal(side.loadedByRealClient, false);
    assert.equal(side.unverified.length, 16);
    const golden = { model: String(files["hytale/banshee/model.blockymodel"].data), idle: String(files["hytale/banshee/animations/idle.blockyanim"].data), pngSha256: files["hytale/banshee/texture.png"].sha256 };
    const gp = path.join(GOLD, "banshee.hytale-draft.golden.json");
    if (process.env.UPDATE_MODELSTUDIO_GOLDEN === "1") { fs.mkdirSync(GOLD, { recursive: true }); fs.writeFileSync(gp, JSON.stringify(golden, null, 1) + "\n"); }
    const want = JSON.parse(fs.readFileSync(gp, "utf8"));
    assert.equal(golden.model, want.model);
    assert.equal(golden.idle, want.idle);
    assert.equal(golden.pngSha256, want.pngSha256);
  });
  it("euler -> quaternion is unit length and identity for zero", () => {
    assert.deepEqual(eulerToQuat([0, 0, 0]), { x: 0, y: 0, z: 0, w: 1 });
    const q = eulerToQuat([30, 45, 60]);
    assert.ok(Math.abs(Math.hypot(q.x, q.y, q.z, q.w) - 1) < 1e-5);
  });
});

// ---------------------------------------------------------------------------------------------- service + http ----
function memory(plan: unknown = "all") {
  const project: ProjectRow = { id: "cp" + "a".repeat(20), userId: "u1", namespace: NS, rootBuildId: "root1", headRevisionId: null, title: "Banshee Hunt" };
  const revs: RevRow[] = [];
  const assets: AssetRow[] = [];
  let n = 0;
  const store: ModelEditorDeps["store"] = {
    project: async (id) => (id === project.id ? project : null),
    projectForRoot: async (r) => (r === project.rootBuildId ? project : null),
    assets: async () => assets,
    revisions: async () => revs,
    addRevision: async (_p, i) => {
      if (i.expectedHeadId !== undefined && (revs.at(-1)?.id ?? null) !== i.expectedHeadId) throw Object.assign(new Error("stale"), { code: "stale_head" });
      const r: RevRow = { id: `rev${++n}`, seq: revs.length + 1, kind: i.kind, status: i.status ?? "passed", message: i.message ?? null, createdAt: new Date(Date.UTC(2026, 9, 10, 0, 0, n)), manifest: i.manifest as RevRow["manifest"], modBuildId: null };
      revs.push(r); return { id: r.id, seq: r.seq };
    },
    recordAsset: async (_p, a) => { const id = `as${++n}`; assets.push({ id, projectId: project.id, revisionId: a.revisionId, assetKey: a.assetKey, kind: a.kind, sha256: a.sha256, size: a.size, origin: a.origin, mime: a.mime ?? null, path: a.path ?? null, provenance: a.provenance, createdAt: new Date(Date.UTC(2026, 9, 10, 0, 0, n)) }); return { id }; },
  };
  const drafts = memoryDraftStore();
  const deps: ModelEditorDeps = { store, planOf: async () => plan, drafts };
  return { project, revs, assets, deps, drafts };
}
async function seed(m: ReturnType<typeof memory>) {
  const raw = load("banshee");
  const rev = await m.deps.store.addRevision(m.project.id, { kind: "generated", manifest: [], expectedHeadId: null });
  const a = await m.deps.store.recordAsset(m.project.id, { revisionId: rev.id, assetKey: "banshee", kind: "model", sha256: "f".repeat(64), size: 1, origin: "generated", mime: RIG_SPEC_MIME, path: "assets/creatures/banshee.json", provenance: { spec: raw } });
  return { headId: rev.id, assetId: a.id };
}

describe("Model Studio L2: save path (revisions, stale head, gate, drafts)", () => {
  it("a build's RigSpec row loads as a ModelDoc; a save writes a new asset revision + ModelDoc row", async () => {
    const m = memory();
    const s = await seed(m);
    const view = await loadModel(m.deps, "u1", m.project.id, "banshee");
    assert.equal(view.model.source, "rigspec");
    const doc = ok(applyOp(view.model.doc, { op: "move", ids: [view.model.doc.cubes[0].id], delta: [0, 1, 0] })).doc;
    const r = await saveModelRevision(m.deps, { userId: "u1", projectId: m.project.id, key: "banshee", doc, baseAssetId: s.assetId, expectedHeadId: s.headId });
    assert.equal(m.revs.at(-1)!.kind, "asset");
    assert.deepEqual(m.revs.at(-1)!.manifest.map((e) => e.path).sort(), ["assets/creatures/banshee.json", "assets/models/banshee.modeldoc.json", `bettermodel/${NS}_banshee.bbmodel`]);
    const row = m.assets.at(-1)!;
    assert.equal(row.mime, MODEL_DOC_MIME);
    assert.equal(row.origin, "edited");
    assert.equal(r.specSha256.length, 64);
    const again = resolveModels(m.assets).find((x) => x.key === "banshee")!;
    assert.equal(again.source, "modeldoc");
    assert.equal(serializeDoc(again.doc), serializeDoc(doc));
  });
  it("stale head -> 409; invalid doc -> 422 with issues; key mismatch -> 400; other owner -> 404", async () => {
    const m = memory();
    const s = await seed(m);
    const doc = (await loadModel(m.deps, "u1", m.project.id, "banshee")).model.doc;
    await assert.rejects(saveModelRevision(m.deps, { userId: "u1", projectId: m.project.id, key: "banshee", doc, baseAssetId: s.assetId, expectedHeadId: "old" }), (e: { status: number; code: string }) => e.status === 409 && e.code === "stale_head");
    const rotated = ok(applyOp(doc, { op: "rotate", ids: [doc.cubes[0].id], rotation: [0, 0, 5], mode: "set" })).doc;
    await assert.rejects(saveModelRevision(m.deps, { userId: "u1", projectId: m.project.id, key: "banshee", doc: rotated, baseAssetId: s.assetId, expectedHeadId: s.headId }), (e: { status: number; extra: { issues: unknown[] } }) => e.status === 422 && e.extra.issues.length > 0);
    await assert.rejects(saveModelRevision(m.deps, { userId: "u1", projectId: m.project.id, key: "ghoul", doc, baseAssetId: s.assetId, expectedHeadId: s.headId }), (e: { status: number }) => e.status === 400);
    await assert.rejects(saveModelRevision(m.deps, { userId: "u2", projectId: m.project.id, key: "banshee", doc, baseAssetId: s.assetId, expectedHeadId: s.headId }), (e: { status: number }) => e.status === 404);
  });
  it("the gate runs server side first: Saka 403 asset_locked, unknown plan 403 plan_unknown, viewing still works", async () => {
    for (const [plan, code] of [["saka", "asset_locked"], [null, "plan_unknown"]] as const) {
      const m = memory(plan);
      const s = await seed(m);
      const view = await loadModel(m.deps, "u1", m.project.id, "banshee");
      assert.equal(view.access.edit.ok, false);
      assert.equal(view.draft, null);
      await assert.rejects(saveModelRevision(m.deps, { userId: "u1", projectId: m.project.id, key: "banshee", doc: view.model.doc, baseAssetId: s.assetId, expectedHeadId: s.headId }), (e: { status: number; code: string }) => e.status === 403 && e.code === code);
      await assert.rejects(saveDraft(m.deps, { userId: "u1", projectId: m.project.id, key: "banshee", doc: view.model.doc, baseAssetId: s.assetId, baseHeadId: s.headId }), (e: { status: number }) => e.status === 403);
      assert.equal(m.revs.length, 1, "nothing written");
    }
  });
  it("drafts: autosave writes a draft (never a revision), 503 when no draft store is wired, cleared by a save", async () => {
    const m = memory();
    const s = await seed(m);
    const doc = (await loadModel(m.deps, "u1", m.project.id, "banshee")).model.doc;
    await saveDraft(m.deps, { userId: "u1", projectId: m.project.id, key: "banshee", doc, baseAssetId: s.assetId, baseHeadId: s.headId });
    assert.equal(m.revs.length, 1);
    assert.ok((await loadModel(m.deps, "u1", m.project.id, "banshee")).draft);
    await saveModelRevision(m.deps, { userId: "u1", projectId: m.project.id, key: "banshee", doc, baseAssetId: s.assetId, expectedHeadId: s.headId });
    assert.equal(m.drafts.rows.size, 0);
    await assert.rejects(saveDraft({ ...m.deps, drafts: null }, { userId: "u1", projectId: m.project.id, key: "banshee", doc, baseAssetId: null, baseHeadId: null }), (e: { status: number }) => e.status === 503);
  });
  it("HTTP: the editor flag OFF (default) or no viewer = 404; ON = the model and a save", async () => {
    const m = memory();
    const s = await seed(m);
    const api = (enabled: boolean, viewer = true): ModelEditorApiDeps => ({ viewer: async () => (viewer ? { userId: "u1", preview: true } : null), enabled: async () => enabled, service: m.deps, rateLimit: () => ({ ok: true }), allowPlanned: false });
    const p = { projectId: m.project.id, key: "banshee" };
    assert.equal((await handleModelGet(new Request("http://x/"), p, api(false))).status, 404);
    assert.equal((await handleModelGet(new Request("http://x/"), p, api(true, false))).status, 404);
    const g = await handleModelGet(new Request("http://x/"), p, api(true));
    assert.equal(g.status, 200);
    const body = await g.json() as { model: { doc: ModelDoc }; exporters: { id: string }[] };
    assert.deepEqual(body.exporters.map((e) => e.id), ["minecraft-bbmodel"], "the planned Hytale exporter is not offered");
    const post = await handleModelSave(new Request("http://x/", { method: "POST", body: JSON.stringify({ doc: body.model.doc, baseAssetId: s.assetId, expectedHeadId: s.headId }) }), p, api(true));
    assert.equal(post.status, 200);
    const bad = await handleModelSave(new Request("http://x/", { method: "POST", body: JSON.stringify({ doc: body.model.doc, baseAssetId: "../x", expectedHeadId: null }) }), p, api(true));
    assert.equal(bad.status, 400);
  });
});

