"use client";
// Client calls of the model editor API (/api/cyrus/assets/v1/model-editor). The editor talks to nothing else.
import type { ModelDoc } from "@/lib/cyrus/modelstudio/editor/doc";
import type { ModelListView, ModelView, SaveModelResult } from "@/lib/cyrus/modelstudio/editor/service";

export const MAPI = "/api/cyrus/assets/v1/model-editor";
export class ModelApiError extends Error { constructor(public status: number, public code: string, message: string, public body: Record<string, unknown>) { super(message); } }
export type ModelViewJson = ModelView & { exporters: { id: string; label: string; maturity: string; unverified: number }[] };

async function call<T>(path: string, init?: RequestInit): Promise<T> {
  const r = await fetch(MAPI + path, { cache: "no-store", ...init, headers: { ...(init?.body ? { "content-type": "application/json" } : {}), ...(init?.headers ?? {}) } });
  const j = (await r.json().catch(() => ({}))) as Record<string, unknown>;
  if (!r.ok) throw new ModelApiError(r.status, String(j.code ?? r.status), String(j.error ?? "Something went wrong."), j);
  return j as T;
}

export const modelApi = {
  list: (root: string) => call<ModelListView>(`?root=${encodeURIComponent(root)}`),
  get: (projectId: string, key: string) => call<ModelViewJson>(`/${projectId}/${key}`),
  save: (projectId: string, key: string, body: { doc: ModelDoc; baseAssetId: string; expectedHeadId: string | null; action?: "save" | "approve" }) => call<SaveModelResult>(`/${projectId}/${key}`, { method: "POST", body: JSON.stringify(body) }),
  draft: (projectId: string, key: string, body: { doc: ModelDoc; baseAssetId: string | null; baseHeadId: string | null }) => call<{ updatedAt: string; sha256: string }>(`/${projectId}/${key}/draft`, { method: "PUT", body: JSON.stringify(body) }),
};

