"use client";
// Model Studio L2 panels: Outliner, Budget, Inspector (bone / cube / UV box), Keyframe, Checks, Timeline, the AI
// candidate bar. Presentational: every change goes out as ONE editor op through `commit` (lib/cyrus/modelstudio/editor/ops.ts).
import { useEffect, useMemo, useRef, useState, type ReactNode } from "react";
import { FACES } from "@/lib/cyrus/creature/spec";
import { boneById, childrenOf, cubeById, size, type EBone, type ECube, type EKey, type ModelDoc, type Vec3 } from "@/lib/cyrus/modelstudio/editor/doc";
import { cubeLabel, type Op } from "@/lib/cyrus/modelstudio/editor/ops";
import { sampleTrack } from "@/lib/cyrus/modelstudio/editor/pose";
import type { Budget, Issue, Validation } from "@/lib/cyrus/modelstudio/editor/validate";
import type { UvLayout } from "@/lib/cyrus/modelstudio/editor/uv";
import { mixHex } from "@/lib/cyrus/modelstudio/editor/scene";
import { SI } from "@/components/cyrus/studios/icons";
import { MI } from "./icons";

export type Commit = (op: Op) => boolean;
const fmt = (v: number) => (Math.round(v * 100) / 100).toString();

// ------------------------------------------------------------------------------------------------- number field ----
export function NumField({ value, onCommit, disabled, step = 1, label, axis }: { value: number; onCommit: (v: number) => void; disabled?: boolean; step?: number; label: string; axis?: "x" | "y" | "z" }) {
  const [s, setS] = useState(fmt(value));
  useEffect(() => setS(fmt(value)), [value]);
  const done = () => { const v = Number(s); if (Number.isFinite(v) && fmt(v) !== fmt(value)) onCommit(v); else setS(fmt(value)); };
  return (
    <label className={`me-num ${axis ?? ""}`}>
      {axis && <i>{axis.toUpperCase()}</i>}
      <input aria-label={label} inputMode="decimal" value={s} disabled={disabled} onChange={(e) => setS(e.target.value)} onBlur={done}
        onKeyDown={(e) => { if (e.key === "Enter") { (e.target as HTMLInputElement).blur(); } else if (e.key === "ArrowUp" || e.key === "ArrowDown") { e.preventDefault(); onCommit(value + (e.key === "ArrowUp" ? step : -step)); } }} />
    </label>
  );
}
export function Vec3Field({ v, onCommit, disabled, step, label }: { v: Vec3; onCommit: (v: Vec3) => void; disabled?: boolean; step?: number; label: string }) {
  return (
    <div className="me-v3" role="group" aria-label={label}>
      {(["x", "y", "z"] as const).map((a, i) => <NumField key={a} axis={a} label={`${label} ${a}`} value={v[i]} step={step} disabled={disabled} onCommit={(n) => { const next = [...v] as Vec3; next[i] = n; onCommit(next); }} />)}
    </div>
  );
}

// ---------------------------------------------------------------------------------------------------- outliner ----
export function Outliner({ doc, sel, setSel, commit, readOnly, issues }: { doc: ModelDoc; sel: string[]; setSel: (ids: string[]) => void; commit: Commit; readOnly: boolean; issues: Issue[] }) {
  const [closed, setClosed] = useState<Record<string, boolean>>({});
  const [drag, setDrag] = useState<string | null>(null);
  const bad = useMemo(() => new Set(issues.filter((i) => i.severity === "error" && i.node).map((i) => i.node!)), [issues]);
  const pick = (id: string, add: boolean) => setSel(add ? (sel.includes(id) ? sel.filter((x) => x !== id) : [...sel, id]) : [id]);
  const rows: ReactNode[] = [];
  const walk = (b: EBone, depth: number) => {
    const kids = childrenOf(doc, b.id), cubes = doc.cubes.filter((c) => c.bone === b.id);
    const open = !closed[b.id];
    rows.push(
      <div key={b.id} role="treeitem" aria-selected={sel.includes(b.id)} aria-expanded={kids.length + cubes.length ? open : undefined}
        className={`me-node bone ${sel.includes(b.id) ? "on" : ""} ${drag && drag !== b.id ? "drop" : ""}`} style={{ paddingLeft: 6 + depth * 14 }}
        draggable={!readOnly && b.parent !== null} onDragStart={(e) => { setDrag(b.id); e.dataTransfer.setData("text/plain", b.id); }} onDragEnd={() => setDrag(null)}
        onDragOver={(e) => { if (drag && drag !== b.id) e.preventDefault(); }} onDrop={(e) => { e.preventDefault(); const id = e.dataTransfer.getData("text/plain"); setDrag(null); if (id && id !== b.id) commit({ op: "reparent", id, parent: b.id }); }}>
        <button type="button" className="tw" aria-label={open ? "Collapse" : "Expand"} onClick={() => setClosed({ ...closed, [b.id]: open })} style={{ visibility: kids.length + cubes.length ? "visible" : "hidden" }}><SI n={open ? "chevD" : "chevR"} /></button>
        <button type="button" className="nm" onClick={(e) => pick(b.id, e.shiftKey || e.metaKey || e.ctrlKey)}><MI n="bone" /><span>{b.name}</span></button>
        {b.tag !== "none" && <span className="cys-tag dim">{b.tag}</span>}
        {bad.has(b.id) && <span className="cys-dot bad" title="has an error" />}
        <button type="button" className="cys-ib sm" aria-label={b.locked ? `Unlock ${b.name}` : `Lock ${b.name}`} disabled={readOnly} onClick={() => commit({ op: "setFlag", ids: [b.id], flag: "locked", value: !b.locked })}><SI n={b.locked ? "lock" : "edit"} /></button>
        <button type="button" className="cys-ib sm" aria-label={b.hidden ? `Show ${b.name}` : `Hide ${b.name}`} onClick={() => commit({ op: "setFlag", ids: [b.id], flag: "hidden", value: !b.hidden })}><SI n={b.hidden ? "eyeoff" : "eye"} /></button>
      </div>,
    );
    if (!open) return;
    for (const c of cubes) rows.push(
      <div key={c.id} role="treeitem" aria-selected={sel.includes(c.id)} className={`me-node cube ${sel.includes(c.id) ? "on" : ""}`} style={{ paddingLeft: 26 + depth * 14 }}
        draggable={!readOnly} onDragStart={(e) => { setDrag(c.id); e.dataTransfer.setData("text/plain", c.id); }} onDragEnd={() => setDrag(null)}>
        <button type="button" className="nm" onClick={(e) => pick(c.id, e.shiftKey || e.metaKey || e.ctrlKey)}><SI n="cube" /><span>{cubeLabel(doc, c.id)}</span></button>
        <span className="mat"><i style={{ background: doc.palette[c.material] }} />{c.material}</span>
        {bad.has(c.id) && <span className="cys-dot bad" title="has an error" />}
        <button type="button" className="cys-ib sm" aria-label={c.hidden ? "Show cube" : "Hide cube"} onClick={() => commit({ op: "setFlag", ids: [c.id], flag: "hidden", value: !c.hidden })}><SI n={c.hidden ? "eyeoff" : "eye"} /></button>
      </div>,
    );
    for (const k of kids) walk(k, depth + 1);
  };
  const root = doc.bones.find((b) => b.parent === null);
  if (root) walk(root, 0);
  for (const b of doc.bones) if (b.parent !== null && !boneById(doc, b.parent)) walk(b, 0); // orphans stay visible
  return <div className="me-tree" role="tree" aria-label="Bones and cubes">{rows}</div>;
}

export function BudgetPanel({ budgets }: { budgets: Budget[] }) {
  return (
    <div className="me-budget">
      {budgets.map((b) => {
        const r = b.max ? b.used / b.max : 0;
        return (
          <div key={b.id} className={`bi ${r > 1 ? "bad" : r > 0.85 ? "warn" : ""}`}>
            <span>{b.label}</span><b>{b.used}<small>/{b.max}</small></b>
            <i><em style={{ width: `${Math.min(100, r * 100)}%` }} /></i>
          </div>
        );
      })}
    </div>
  );
}

// -------------------------------------------------------------------------------------------------- inspector ----
function Seg<T extends string>({ value, options, onPick, disabled, label }: { value: T; options: readonly T[]; onPick: (v: T) => void; disabled?: boolean; label: string }) {
  return <div className="cys-seg cys-soft sm" role="group" aria-label={label}>{options.map((o) => <button key={o} type="button" className={o === value ? "on" : ""} disabled={disabled} onClick={() => o !== value && onPick(o)}>{o}</button>)}</div>;
}

export function BoneInspector({ doc, bone, commit, readOnly, snap, angleSnap }: { doc: ModelDoc; bone: EBone; commit: Commit; readOnly: boolean; snap: number; angleSnap: number }) {
  const parent = bone.parent ? boneById(doc, bone.parent) : null;
  const ro = readOnly || !!bone.locked;
  return (
    <section className="me-sec">
      <div className="me-sh"><span className="cys-eyebrow">Bone · {bone.name}</span><span className="cys-eyebrow r">Parent {parent?.name ?? "none (root)"}</span></div>
      <div className="me-row"><span>Name</span><RenameField key={bone.id} value={bone.name} disabled={ro} onCommit={(n) => commit({ op: "rename", id: bone.id, name: n })} /></div>
      <div className="me-row"><span>Pivot</span><Vec3Field label="Pivot" v={bone.pivot} disabled={ro} step={snap || 0.5} onCommit={(p) => commit({ op: "setPivot", id: bone.id, pivot: p })} /></div>
      <div className="me-row"><span>Rotation</span><Vec3Field label="Rotation" v={bone.rotation} disabled={ro} step={angleSnap || 5} onCommit={(r) => commit({ op: "rotate", ids: [bone.id], rotation: r, mode: "set" })} /></div>
      <div className="me-row"><span>Tag</span><Seg label="Bone tag" value={bone.tag} options={["none", "head", "glow"] as const} disabled={ro} onPick={(t) => commit({ op: "setBone", id: bone.id, props: { tag: t } })} /></div>
      {bone.locked && <p className="cys-hint me-pad"><SI n="lock" /> Locked: unlock it in the outliner to edit.</p>}
    </section>
  );
}

function RenameField({ value, onCommit, disabled }: { value: string; onCommit: (v: string) => void; disabled?: boolean }) {
  const [s, setS] = useState(value);
  useEffect(() => setS(value), [value]);
  return <input className="cys-field me-name" aria-label="Name" value={s} disabled={disabled} onChange={(e) => setS(e.target.value)} onBlur={() => { if (s.trim() !== value) onCommit(s.trim()); }} onKeyDown={(e) => { if (e.key === "Enter") (e.target as HTMLInputElement).blur(); }} />;
}

export function CubeInspector({ doc, cube, commit, readOnly, snap, angleSnap, target }: { doc: ModelDoc; cube: ECube; commit: Commit; readOnly: boolean; snap: number; angleSnap: number; target: string }) {
  const ro = readOnly || !!cube.locked;
  const s = size(cube);
  const rotated = cube.rotation.some((x) => x !== 0);
  return (
    <section className="me-sec">
      <div className="me-sh"><span className="cys-eyebrow">{cubeLabel(doc, cube.id)}</span>{rotated && target === "minecraft-bettermodel" && <span className="cys-tag bad">rotation not shippable</span>}</div>
      <div className="me-row"><span>From</span><Vec3Field label="From" v={cube.from} disabled={ro} step={snap || 0.5} onCommit={(f) => commit({ op: "move", ids: [cube.id], delta: [f[0] - cube.from[0], f[1] - cube.from[1], f[2] - cube.from[2]], snap: 0 })} /></div>
      <div className="me-row"><span>Size</span><Vec3Field label="Size" v={s} disabled={ro} step={snap || 0.5} onCommit={(z) => commit({ op: "resize", id: cube.id, size: z, snap: 0 })} /></div>
      <div className="me-row"><span>Inflate</span><input type="range" min={0} max={1} step={0.05} value={cube.inflate} disabled={ro} aria-label="Inflate" onChange={(e) => commit({ op: "setCube", id: cube.id, props: { inflate: Number(e.target.value) } })} /><b className="mono me-val">{fmt(cube.inflate)}</b></div>
      <div className="me-row"><span>Material</span>
        <select className="cys-field me-mat" aria-label="Material" value={cube.material} disabled={ro} onChange={(e) => commit({ op: "setCube", id: cube.id, props: { material: e.target.value } })}>{Object.keys(doc.palette).map((k) => <option key={k} value={k}>{k}</option>)}</select>
        <i className="me-sw" style={{ background: doc.palette[cube.material] }} />
        <Seg label="Shade" value={cube.shade} options={["solid", "fade"] as const} disabled={ro} onPick={(v) => commit({ op: "setCube", id: cube.id, props: { shade: v } })} />
      </div>
      <details className="me-adv">
        <summary>Cube rotation and pivot <small>(editor only for Minecraft)</small></summary>
        <div className="me-row"><span>Rotation</span><Vec3Field label="Cube rotation" v={cube.rotation} disabled={ro} step={angleSnap || 5} onCommit={(r) => commit({ op: "rotate", ids: [cube.id], rotation: r, mode: "set" })} /></div>
        <div className="me-row"><span>Pivot</span><Vec3Field label="Cube pivot" v={cube.pivot} disabled={ro} step={snap || 0.5} onCommit={(p) => commit({ op: "setPivot", id: cube.id, pivot: p })} /></div>
        <p className="cys-hint me-pad">Minecraft creatures (RigSpec v1) can&apos;t rotate a single cube: rotate its bone, or group the cube into its own bone.</p>
      </details>
    </section>
  );
}

// ----------------------------------------------------------------------------------------------------- UV box ----
export function UvSheet({ doc, uv, sel, commit, readOnly }: { doc: ModelDoc; uv: UvLayout; sel: string | null; commit: Commit; readOnly: boolean }) {
  const ref = useRef<HTMLCanvasElement>(null);
  const [drag, setDrag] = useState<{ id: string; dx: number; dy: number; u: number; v: number } | null>(null);
  const box = sel ? uv.boxes.find((b) => b.cube === sel) : null;
  const cube = sel ? cubeById(doc, sel) : null;
  useEffect(() => {
    const c = ref.current;
    if (!c) return;
    const S = 256; c.width = S; c.height = S;
    const g = c.getContext("2d")!;
    const k = S / uv.size;
    g.clearRect(0, 0, S, S);
    for (const b of uv.boxes) {
      const cc = cubeById(doc, b.cube);
      const base = (cc && doc.palette[cc.material]) || "#888888";
      const off = drag && drag.id === b.cube ? [drag.u - b.u, drag.v - b.v] : [0, 0];
      for (const f of FACES) {
        const r = b.faces[f];
        g.fillStyle = f === "up" ? mixHex(base, "#ffffff", 0.16) : f === "down" ? mixHex(base, "#0b0a14", 0.24) : base;
        g.fillRect((r.x + off[0]) * k, (r.y + off[1]) * k, r.w * k, r.h * k);
      }
      if (b.cube === sel || b.pinned) {
        g.strokeStyle = b.cube === sel ? "#a78bfa" : "rgba(255,255,255,.6)";
        g.lineWidth = b.cube === sel ? 2 : 1;
        g.setLineDash(b.pinned && b.cube !== sel ? [3, 2] : []);
        g.strokeRect((b.u + off[0]) * k + 1, (b.v + off[1]) * k + 1, (2 * (b.w + b.d)) * k - 2, (b.d + b.h) * k - 2);
        g.setLineDash([]);
      }
    }
  }, [doc, uv, sel, drag]);
  const at = (e: React.PointerEvent) => { const r = ref.current!.getBoundingClientRect(); return [((e.clientX - r.left) / r.width) * uv.size, ((e.clientY - r.top) / r.height) * uv.size]; };
  return (
    <section className="me-sec grow">
      <div className="me-sh"><span className="cys-eyebrow">UV box</span><span className="cys-eyebrow r mono">{box ? `${box.u}, ${box.v} · ${2 * (box.w + box.d)} × ${box.d + box.h} px` : `${uv.size} px sheet`}</span></div>
      <div className="me-uv">
        <canvas ref={ref} aria-label={`Skin sheet ${uv.size} by ${uv.size} with every cube's box net`}
          onPointerDown={(e) => { if (readOnly || !box || cube?.locked) return; const [x, y] = at(e); if (x >= box.u && y >= box.v && x < box.u + 2 * (box.w + box.d) && y < box.v + box.d + box.h) { (e.target as HTMLElement).setPointerCapture(e.pointerId); setDrag({ id: box.cube, dx: x - box.u, dy: y - box.v, u: box.u, v: box.v }); } }}
          onPointerMove={(e) => { if (!drag) return; const [x, y] = at(e); setDrag({ ...drag, u: Math.max(0, Math.round(x - drag.dx)), v: Math.max(0, Math.round(y - drag.dy)) }); }}
          onPointerUp={() => { if (drag && box && (drag.u !== box.u || drag.v !== box.v)) commit({ op: "setUv", id: drag.id, uv: [drag.u, drag.v] }); setDrag(null); }} />
      </div>
      <div className="me-row"><span>Placement</span>
        <div className="cys-seg cys-soft sm" role="group" aria-label="UV placement">
          <button type="button" className={cube && !cube.uv ? "on" : ""} disabled={readOnly || !cube} onClick={() => cube?.uv && commit({ op: "setUv", id: cube.id, uv: null })}>Auto-pack</button>
          <button type="button" className={cube?.uv ? "on" : ""} disabled={readOnly || !cube || !box} onClick={() => cube && box && !cube.uv && commit({ op: "setUv", id: cube.id, uv: [box.u, box.v] })}>Pinned</button>
        </div>
        <button type="button" className="cys-btn xs ghost" disabled={readOnly || !doc.cubes.some((c) => c.uv)} onClick={() => commit({ op: "autoUv" })}>Re-pack all</button>
      </div>
      <p className="cys-hint me-pad">Drag the selected box to pin it. Minecraft re-packs pins when it builds (pins ship with RigSpec v1.1).</p>
    </section>
  );
}

// ---------------------------------------------------------------------------------------------- keyframe tab ----
export function KeyInspector({ doc, clip, time, boneId, keySel, setKeySel, commit, readOnly }: { doc: ModelDoc; clip: string | null; time: number; boneId: string | null; keySel: string | null; setKeySel: (k: string | null) => void; commit: Commit; readOnly: boolean }) {
  const cl = doc.clips.find((c) => c.name === clip);
  const [channel, setChannel] = useState<"rotation" | "position" | "scale">("rotation");
  const [newClip, setNewClip] = useState("");
  if (!cl) return <p className="cys-empty">Pick a clip in the timeline.</p>;
  const found = keySel ? cl.tracks.flatMap((t) => (t.keys ?? []).map((k) => ({ t, k }))).find((x) => x.k.id === keySel) : null;
  const bone = boneId ? boneById(doc, boneId) : null;
  const tr = bone ? cl.tracks.find((t) => t.bone === bone.id && t.channel === channel) : null;
  const cur = tr ? sampleTrack(tr, cl, time) : channel === "scale" ? [1, 1, 1] : [0, 0, 0];
  const u = Math.round((time / cl.length) * 10000) / 10000;
  return (
    <div className="me-keys">
      <section className="me-sec">
        <div className="me-sh"><span className="cys-eyebrow">Clip · {cl.name}</span></div>
        <div className="me-row"><span>Length</span><NumField label="Clip length" value={cl.length} step={0.1} disabled={readOnly} onCommit={(v) => commit({ op: "setClip", name: cl.name, length: v })} /><span className="mono me-val">s</span>
          <Seg label="Loop" value={cl.loop ? "loop" : "once"} options={["loop", "once"] as const} disabled={readOnly} onPick={(v) => commit({ op: "setClip", name: cl.name, loop: v === "loop" })} /></div>
        <div className="me-row"><span>New clip</span><input className="cys-field" aria-label="New clip name" placeholder="wail" value={newClip} disabled={readOnly} onChange={(e) => setNewClip(e.target.value.toLowerCase())} />
          <button type="button" className="cys-btn xs" disabled={readOnly || !newClip} onClick={() => { if (commit({ op: "addClip", name: newClip, length: 1, loop: false })) setNewClip(""); }}><SI n="plus" />Add</button></div>
      </section>
      {found ? (
        <section className="me-sec">
          <div className="me-sh"><span className="cys-eyebrow">Key · {boneById(doc, found.t.bone)?.name} {found.t.channel}</span><button type="button" className="cys-btn xs ghost" onClick={() => setKeySel(null)}>Done</button></div>
          <div className="me-row"><span>Time</span><b className="mono me-val">{fmt(found.k.t * cl.length)} s</b></div>
          <div className="me-row"><span>Value</span><Vec3Field label="Key value" v={found.k.v} disabled={readOnly} onCommit={(v) => commit({ op: "setKey", clip: cl.name, bone: found.t.bone, channel: found.t.channel, t: found.k.t, v, ease: found.k.ease })} /></div>
          <div className="me-row"><span>Easing</span><Seg label="Easing" value={found.k.ease} options={["linear", "smooth"] as const} disabled={readOnly} onPick={(e) => commit({ op: "setEase", clip: cl.name, key: found.k.id, ease: e })} /></div>
          <div className="me-row"><span /><button type="button" className="cys-btn xs ghost" disabled={readOnly} onClick={() => { if (commit({ op: "deleteKey", clip: cl.name, key: found.k.id })) setKeySel(null); }}><SI n="trash" />Delete key</button></div>
        </section>
      ) : (
        <section className="me-sec">
          <div className="me-sh"><span className="cys-eyebrow">{bone ? `Key ${bone.name} at ${fmt(time)} s` : "Select a bone to key it"}</span></div>
          <div className="me-row"><span>Channel</span><Seg label="Channel" value={channel} options={["rotation", "position", "scale"] as const} onPick={setChannel} /></div>
          {bone && (tr?.wave ? (
            <div className="me-row"><span /><p className="cys-hint">This track is a wave.</p><button type="button" className="cys-btn xs" disabled={readOnly} onClick={() => commit({ op: "waveToKeys", clip: cl.name, bone: bone.id, channel })}>Convert to keys</button></div>
          ) : (
            <div className="me-row"><span>Value</span><Vec3Field label="New key value" v={cur.map((x) => Math.round(x * 100) / 100) as Vec3} disabled={readOnly} onCommit={(v) => commit({ op: "setKey", clip: cl.name, bone: bone.id, channel, t: u, v })} /></div>
          ))}
        </section>
      )}
    </div>
  );
}

// ---------------------------------------------------------------------------------------------------- checks ----
export function ChecksPanel({ v, onPick }: { v: Validation; onPick: (node: string) => void }) {
  const errors = v.issues.filter((i) => i.severity === "error"), warns = v.issues.filter((i) => i.severity === "warn");
  return (
    <div>
      <div className="cys-verdict">
        <span className={`cys-dot ${errors.length ? "bad" : warns.length ? "warn" : "ok"}`} />
        <div><b>{errors.length ? `${errors.length} error${errors.length > 1 ? "s" : ""}` : "Valid RigSpec"}</b><div className="cys-hint">{errors.length ? "Fix these before you save a revision." : `${warns.length} warning${warns.length === 1 ? "" : "s"}. Checked by the RigSpec validator; not loaded on a real server yet.`}</div></div>
      </div>
      <ul className="cys-checks">
        {v.issues.map((i, n) => (
          <li key={n} className={`cys-check ${i.severity === "error" ? "fail" : i.severity === "warn" ? "warn" : "not_run"}`}>
            <span className="ic"><SI n={i.severity === "error" ? "close" : i.severity === "warn" ? "warn" : "info"} /></span>
            <span className="id">{i.code}</span>
            <span className="val">{i.node ? <button type="button" className="cys-btn xs ghost" onClick={() => onPick(i.node!)}>show</button> : null}</span>
            <span className="msg">{i.message}</span>
          </li>
        ))}
        <li className="cys-check not_run"><span className="ic"><SI n="minus" /></span><span className="id">bettermodel_load</span><span className="val">not run</span><span className="msg">Not loaded on a real server yet (Test Flight).</span></li>
      </ul>
    </div>
  );
}

// -------------------------------------------------------------------------------------------------- timeline ----
export function Timeline({ doc, clip, setClip, time, setTime, playing, setPlaying, boneSel, keySel, setKeySel, commit, readOnly, onKey }: {
  doc: ModelDoc; clip: string | null; setClip: (c: string | null) => void; time: number; setTime: (t: number) => void; playing: boolean; setPlaying: (p: boolean) => void;
  boneSel: string | null; keySel: string | null; setKeySel: (k: string | null) => void; commit: Commit; readOnly: boolean; onKey: () => void;
}) {
  const cl = doc.clips.find((c) => c.name === clip) ?? null;
  const lane = useRef<HTMLDivElement>(null);
  const [drag, setDrag] = useState<{ key: string; t: number } | null>(null);
  const tAt = (x: number) => { const r = lane.current!.getBoundingClientRect(); return Math.max(0, Math.min(1, (x - r.left) / r.width)); };
  const ticks = cl ? Math.min(20, Math.max(2, Math.round(cl.length / 0.5))) : 0;
  return (
    <div className="me-tl cys-glass cys-panel">
      <div className="me-tlh">
        <button type="button" className={`cys-ib ${playing ? "on" : ""}`} aria-label={playing ? "Pause" : "Play"} disabled={!cl} onClick={() => setPlaying(!playing)}><SI n={playing ? "pause" : "play"} /></button>
        <div className="cys-seg cys-soft sm me-clips" role="tablist" aria-label="Clips">
          <button type="button" role="tab" aria-selected={clip === null} className={clip === null ? "on" : ""} onClick={() => setClip(null)}>rest</button>
          {doc.clips.map((c) => <button key={c.name} type="button" role="tab" aria-selected={c.name === clip} className={c.name === clip ? "on" : ""} onClick={() => setClip(c.name)}>{c.name}</button>)}
        </div>
        {cl && <span className="me-time mono"><b>{fmt(time)} s</b> / {fmt(cl.length)} s</span>}
        {cl && <span className="cys-tag dim">{fmt(cl.length)} s · {cl.loop ? "loop" : "once"}</span>}
        <span className="sp" />
        <button type="button" className="cys-btn xs" disabled={readOnly || !cl || !boneSel} onClick={onKey} title="Key the selected bone's rotation at the playhead"><MI n="key" />Key</button>
      </div>
      {cl ? (
        <div className="me-tlb">
          <div className="me-tracks">
            {cl.tracks.map((t, i) => {
              const b = boneById(doc, t.bone);
              return (
                <div key={i} className={`me-trk ${t.bone === boneSel ? "on" : ""}`}>
                  <span className="lb"><b>{b?.name ?? "?"}</b> {t.channel === "rotation" ? "rot" : t.channel === "position" ? "pos" : "scale"}</span>
                  <span className="n mono">{t.wave ? "wave" : `${t.keys?.length ?? 0} keys`}</span>
                </div>
              );
            })}
          </div>
          <div className="me-lanes" ref={lane} onPointerDown={(e) => { if ((e.target as HTMLElement).dataset.key) return; setPlaying(false); setTime(tAt(e.clientX) * cl.length); }}>
            <div className="me-ruler">{Array.from({ length: ticks + 1 }, (_, i) => <span key={i} style={{ left: `${(i / ticks) * 100}%` }}>{fmt((i / ticks) * cl.length)}</span>)}</div>
            {cl.tracks.map((t, i) => (
              <div key={i} className="me-lane">
                {t.wave ? <svg viewBox="0 0 100 10" preserveAspectRatio="none" aria-hidden="true"><path d={Array.from({ length: 41 }, (_, j) => `${j ? "L" : "M"}${j * 2.5} ${5 - 4 * Math.sin(2 * Math.PI * ((j / 40) * t.wave!.cycles + t.wave!.phase))}`).join(" ")} /></svg> : null}
                {(t.keys ?? []).map((k: EKey, j: number) => {
                  const edge = j === 0 || j === (t.keys!.length - 1);
                  const at = drag?.key === k.id ? drag.t : k.t;
                  return <button key={k.id} type="button" data-key={k.id} aria-label={`Key ${fmt(k.t * cl.length)} s`} className={`me-key ${keySel === k.id ? "on" : ""} ${k.ease}`} style={{ left: `${at * 100}%` }}
                    onPointerDown={(e) => { e.stopPropagation(); setKeySel(k.id); if (!readOnly && !edge) { (e.target as HTMLElement).setPointerCapture(e.pointerId); setDrag({ key: k.id, t: k.t }); } }}
                    onPointerMove={(e) => { if (drag?.key === k.id) setDrag({ key: k.id, t: tAt(e.clientX) }); }}
                    onPointerUp={() => { if (drag?.key === k.id && Math.abs(drag.t - k.t) > 0.005) commit({ op: "moveKey", clip: cl.name, key: k.id, t: drag.t }); setDrag(null); }} />;
                })}
              </div>
            ))}
            <div className="me-head" style={{ left: `${(time / cl.length) * 100}%` }} />
          </div>
        </div>
      ) : <p className="cys-hint me-pad">Rest pose. Pick a clip to scrub, play and key it.</p>}
    </div>
  );
}

export function issueCount(v: Validation) { return { errors: v.issues.filter((i) => i.severity === "error").length, warns: v.issues.filter((i) => i.severity === "warn").length }; }
export { cubeById };

toolu_01GTV5outood1xVdGsXc2UFs.content:
"use client";
// Model Studio L2 panels: Outliner, Budget, Inspector (bone / cube / UV box), Keyframe, Checks, Timeline, the AI
// candidate bar. Presentational: every change goes out as ONE editor op through `commit` (lib/cyrus/modelstudio/editor/ops.ts).
import { useEffect, useMemo, useRef, useState, type ReactNode } from "react";
import { FACES } from "@/lib/cyrus/creature/spec";
import { boneById, childrenOf, cubeById, size, type EBone, type ECube, type EKey, type ModelDoc, type Vec3 } from "@/lib/cyrus/modelstudio/editor/doc";
import { cubeLabel, type Op } from "@/lib/cyrus/modelstudio/editor/ops";
import { sampleTrack } from "@/lib/cyrus/modelstudio/editor/pose";
import type { Budget, Issue, Validation } from "@/lib/cyrus/modelstudio/editor/validate";
import type { UvLayout } from "@/lib/cyrus/modelstudio/editor/uv";
import { mixHex } from "@/lib/cyrus/modelstudio/editor/scene";
import { SI } from "@/components/cyrus/studios/icons";
import { MI } from "./icons";

export type Commit = (op: Op) => boolean;
const fmt = (v: number) => (Math.round(v * 100) / 100).toString();

// ------------------------------------------------------------------------------------------------- number field ----
export function NumField({ value, onCommit, disabled, step = 1, label, axis }: { value: number; onCommit: (v: number) => void; disabled?: boolean; step?: number; label: string; axis?: "x" | "y" | "z" }) {
  const [s, setS] = useState(fmt(value));
  useEffect(() => setS(fmt(value)), [value]);
  const done = () => { const v = Number(s); if (Number.isFinite(v) && fmt(v) !== fmt(value)) onCommit(v); else setS(fmt(value)); };
  return (
    <label className={`me-num ${axis ?? ""}`}>
      {axis && <i>{axis.toUpperCase()}</i>}
      <input aria-label={label} inputMode="decimal" value={s} disabled={disabled} onChange={(e) => setS(e.target.value)} onBlur={done}
        onKeyDown={(e) => { if (e.key === "Enter") { (e.target as HTMLInputElement).blur(); } else if (e.key === "ArrowUp" || e.key === "ArrowDown") { e.preventDefault(); onCommit(value + (e.key === "ArrowUp" ? step : -step)); } }} />
    </label>
  );
}
export function Vec3Field({ v, onCommit, disabled, step, label }: { v: Vec3; onCommit: (v: Vec3) => void; disabled?: boolean; step?: number; label: string }) {
  return (
    <div className="me-v3" role="group" aria-label={label}>
      {(["x", "y", "z"] as const).map((a, i) => <NumField key={a} axis={a} label={`${label} ${a}`} value={v[i]} step={step} disabled={disabled} onCommit={(n) => { const next = [...v] as Vec3; next[i] = n; onCommit(next); }} />)}
    </div>
  );
}

// ---------------------------------------------------------------------------------------------------- outliner ----
export function Outliner({ doc, sel, setSel, commit, readOnly, issues }: { doc: ModelDoc; sel: string[]; setSel: (ids: string[]) => void; commit: Commit; readOnly: boolean; issues: Issue[] }) {
  const [closed, setClosed] = useState<Record<string, boolean>>({});
  const [drag, setDrag] = useState<string | null>(null);
  const bad = useMemo(() => new Set(issues.filter((i) => i.severity === "error" && i.node).map((i) => i.node!)), [issues]);
  const pick = (id: string, add: boolean) => setSel(add ? (sel.includes(id) ? sel.filter((x) => x !== id) : [...sel, id]) : [id]);
  const rows: ReactNode[] = [];
  const walk = (b: EBone, depth: number) => {
    const kids = childrenOf(doc, b.id), cubes = doc.cubes.filter((c) => c.bone === b.id);
    const open = !closed[b.id];
    rows.push(
      <div key={b.id} role="treeitem" aria-selected={sel.includes(b.id)} aria-expanded={kids.length + cubes.length ? open : undefined}
        className={`me-node bone ${sel.includes(b.id) ? "on" : ""} ${drag && drag !== b.id ? "drop" : ""}`} style={{ paddingLeft: 6 + depth * 14 }}
        draggable={!readOnly && b.parent !== null} onDragStart={(e) => { setDrag(b.id); e.dataTransfer.setData("text/plain", b.id); }} onDragEnd={() => setDrag(null)}
        onDragOver={(e) => { if (drag && drag !== b.id) e.preventDefault(); }} onDrop={(e) => { e.preventDefault(); const id = e.dataTransfer.getData("text/plain"); setDrag(null); if (id && id !== b.id) commit({ op: "reparent", id, parent: b.id }); }}>
        <button type="button" className="tw" aria-label={open ? "Collapse" : "Expand"} onClick={() => setClosed({ ...closed, [b.id]: open })} style={{ visibility: kids.length + cubes.length ? "visible" : "hidden" }}><SI n={open ? "chevD" : "chevR"} /></button>
        <button type="button" className="nm" onClick={(e) => pick(b.id, e.shiftKey || e.metaKey || e.ctrlKey)}><MI n="bone" /><span>{b.name}</span></button>
        {b.tag !== "none" && <span className="cys-tag dim">{b.tag}</span>}
        {bad.has(b.id) && <span className="cys-dot bad" title="has an error" />}
        <button type="button" className="cys-ib sm" aria-label={b.locked ? `Unlock ${b.name}` : `Lock ${b.name}`} disabled={readOnly} onClick={() => commit({ op: "setFlag", ids: [b.id], flag: "locked", value: !b.locked })}><SI n={b.locked ? "lock" : "edit"} /></button>
        <button type="button" className="cys-ib sm" aria-label={b.hidden ? `Show ${b.name}` : `Hide ${b.name}`} onClick={() => commit({ op: "setFlag", ids: [b.id], flag: "hidden", value: !b.hidden })}><SI n={b.hidden ? "eyeoff" : "eye"} /></button>
      </div>,
    );
    if (!open) return;
    for (const c of cubes) rows.push(
      <div key={c.id} role="treeitem" aria-selected={sel.includes(c.id)} className={`me-node cube ${sel.includes(c.id) ? "on" : ""}`} style={{ paddingLeft: 26 + depth * 14 }}
        draggable={!readOnly} onDragStart={(e) => { setDrag(c.id); e.dataTransfer.setData("text/plain", c.id); }} onDragEnd={() => setDrag(null)}>
        <button type="button" className="nm" onClick={(e) => pick(c.id, e.shiftKey || e.metaKey || e.ctrlKey)}><SI n="cube" /><span>{cubeLabel(doc, c.id)}</span></button>
        <span className="mat"><i style={{ background: doc.palette[c.material] }} />{c.material}</span>
        {bad.has(c.id) && <span className="cys-dot bad" title="has an error" />}
        <button type="button" className="cys-ib sm" aria-label={c.hidden ? "Show cube" : "Hide cube"} onClick={() => commit({ op: "setFlag", ids: [c.id], flag: "hidden", value: !c.hidden })}><SI n={c.hidden ? "eyeoff" : "eye"} /></button>
      </div>,
    );
    for (const k of kids) walk(k, depth + 1);
  };
  const root = doc.bones.find((b) => b.parent === null);
  if (root) walk(root, 0);
  for (const b of doc.bones) if (b.parent !== null && !boneById(doc, b.parent)) walk(b, 0); // orphans stay visible
  return <div className="me-tree" role="tree" aria-label="Bones and cubes">{rows}</div>;
}

export function BudgetPanel({ budgets }: { budgets: Budget[] }) {
  return (
    <div className="me-budget">
      {budgets.map((b) => {
        const r = b.max ? b.used / b.max : 0;
        return (
          <div key={b.id} className={`bi ${r > 1 ? "bad" : r > 0.85 ? "warn" : ""}`}>
            <span>{b.label}</span><b>{b.used}<small>/{b.max}</small></b>
            <i><em style={{ width: `${Math.min(100, r * 100)}%` }} /></i>
          </div>
        );
      })}
    </div>
  );
}

// -------------------------------------------------------------------------------------------------- inspector ----
function Seg<T extends string>({ value, options, onPick, disabled, label }: { value: T; options: readonly T[]; onPick: (v: T) => void; disabled?: boolean; label: string }) {
  return <div className="cys-seg cys-soft sm" role="group" aria-label={label}>{options.map((o) => <button key={o} type="button" className={o === value ? "on" : ""} disabled={disabled} onClick={() => o !== value && onPick(o)}>{o}</button>)}</div>;
}

export function BoneInspector({ doc, bone, commit, readOnly, snap, angleSnap }: { doc: ModelDoc; bone: EBone; commit: Commit; readOnly: boolean; snap: number; angleSnap: number }) {
  const parent = bone.parent ? boneById(doc, bone.parent) : null;
  const ro = readOnly || !!bone.locked;
  return (
    <section className="me-sec">
      <div className="me-sh"><span className="cys-eyebrow">Bone · {bone.name}</span><span className="cys-eyebrow r">Parent {parent?.name ?? "none (root)"}</span></div>
      <div className="me-row"><span>Name</span><RenameField key={bone.id} value={bone.name} disabled={ro} onCommit={(n) => commit({ op: "rename", id: bone.id, name: n })} /></div>
      <div className="me-row"><span>Pivot</span><Vec3Field label="Pivot" v={bone.pivot} disabled={ro} step={snap || 0.5} onCommit={(p) => commit({ op: "setPivot", id: bone.id, pivot: p })} /></div>
      <div className="me-row"><span>Rotation</span><Vec3Field label="Rotation" v={bone.rotation} disabled={ro} step={angleSnap || 5} onCommit={(r) => commit({ op: "rotate", ids: [bone.id], rotation: r, mode: "set" })} /></div>
      <div className="me-row"><span>Tag</span><Seg label="Bone tag" value={bone.tag} options={["none", "head", "glow"] as const} disabled={ro} onPick={(t) => commit({ op: "setBone", id: bone.id, props: { tag: t } })} /></div>
      {bone.locked && <p className="cys-hint me-pad"><SI n="lock" /> Locked: unlock it in the outliner to edit.</p>}
    </section>
  );
}

function RenameField({ value, onCommit, disabled }: { value: string; onCommit: (v: string) => void; disabled?: boolean }) {
  const [s, setS] = useState(value);
  useEffect(() => setS(value), [value]);
  return <input className="cys-field me-name" aria-label="Name" value={s} disabled={disabled} onChange={(e) => setS(e.target.value)} onBlur={() => { if (s.trim() !== value) onCommit(s.trim()); }} onKeyDown={(e) => { if (e.key === "Enter") (e.target as HTMLInputElement).blur(); }} />;
}

export function CubeInspector({ doc, cube, commit, readOnly, snap, angleSnap, target }: { doc: ModelDoc; cube: ECube; commit: Commit; readOnly: boolean; snap: number; angleSnap: number; target: string }) {
  const ro = readOnly || !!cube.locked;
  const s = size(cube);
  const rotated = cube.rotation.some((x) => x !== 0);
  return (
    <section className="me-sec">
      <div className="me-sh"><span className="cys-eyebrow">{cubeLabel(doc, cube.id)}</span>{rotated && target === "minecraft-bettermodel" && <span className="cys-tag bad">rotation not shippable</span>}</div>
      <div className="me-row"><span>From</span><Vec3Field label="From" v={cube.from} disabled={ro} step={snap || 0.5} onCommit={(f) => commit({ op: "move", ids: [cube.id], delta: [f[0] - cube.from[0], f[1] - cube.from[1], f[2] - cube.from[2]], snap: 0 })} /></div>
      <div className="me-row"><span>Size</span><Vec3Field label="Size" v={s} disabled={ro} step={snap || 0.5} onCommit={(z) => commit({ op: "resize", id: cube.id, size: z, snap: 0 })} /></div>
      <div className="me-row"><span>Inflate</span><input type="range" min={0} max={1} step={0.05} value={cube.inflate} disabled={ro} aria-label="Inflate" onChange={(e) => commit({ op: "setCube", id: cube.id, props: { inflate: Number(e.target.value) } })} /><b className="mono me-val">{fmt(cube.inflate)}</b></div>
      <div className="me-row"><span>Material</span>
        <select className="cys-field me-mat" aria-label="Material" value={cube.material} disabled={ro} onChange={(e) => commit({ op: "setCube", id: cube.id, props: { material: e.target.value } })}>{Object.keys(doc.palette).map((k) => <option key={k} value={k}>{k}</option>)}</select>
        <i className="me-sw" style={{ background: doc.palette[cube.material] }} />
        <Seg label="Shade" value={cube.shade} options={["solid", "fade"] as const} disabled={ro} onPick={(v) => commit({ op: "setCube", id: cube.id, props: { shade: v } })} />
      </div>
      <details className="me-adv">
        <summary>Cube rotation and pivot <small>(editor only for Minecraft)</small></summary>
        <div className="me-row"><span>Rotation</span><Vec3Field label="Cube rotation" v={cube.rotation} disabled={ro} step={angleSnap || 5} onCommit={(r) => commit({ op: "rotate", ids: [cube.id], rotation: r, mode: "set" })} /></div>
        <div className="me-row"><span>Pivot</span><Vec3Field label="Cube pivot" v={cube.pivot} disabled={ro} step={snap || 0.5} onCommit={(p) => commit({ op: "setPivot", id: cube.id, pivot: p })} /></div>
        <p className="cys-hint me-pad">Minecraft creatures (RigSpec v1) can&apos;t rotate a single cube: rotate its bone, or group the cube into its own bone.</p>
      </details>
    </section>
  );
}

// ----------------------------------------------------------------------------------------------------- UV box ----
export function UvSheet({ doc, uv, sel, commit, readOnly }: { doc: ModelDoc; uv: UvLayout; sel: string | null; commit: Commit; readOnly: boolean }) {
  const ref = useRef<HTMLCanvasElement>(null);
  const [drag, setDrag] = useState<{ id: string; dx: number; dy: number; u: number; v: number } | null>(null);
  const box = sel ? uv.boxes.find((b) => b.cube === sel) : null;
  const cube = sel ? cubeById(doc, sel) : null;
  useEffect(() => {
    const c = ref.current;
    if (!c) return;
    const S = 256; c.width = S; c.height = S;
    const g = c.getContext("2d")!;
    const k = S / uv.size;
    g.clearRect(0, 0, S, S);
    for (const b of uv.boxes) {
      const cc = cubeById(doc, b.cube);
      const base = (cc && doc.palette[cc.material]) || "#888888";
      const off = drag && drag.id === b.cube ? [drag.u - b.u, drag.v - b.v] : [0, 0];
      for (const f of FACES) {
        const r = b.faces[f];
        g.fillStyle = f === "up" ? mixHex(base, "#ffffff", 0.16) : f === "down" ? mixHex(base, "#0b0a14", 0.24) : base;
        g.fillRect((r.x + off[0]) * k, (r.y + off[1]) * k, r.w * k, r.h * k);
      }
      if (b.cube === sel || b.pinned) {
        g.strokeStyle = b.cube === sel ? "#a78bfa" : "rgba(255,255,255,.6)";
        g.lineWidth = b.cube === sel ? 2 : 1;
        g.setLineDash(b.pinned && b.cube !== sel ? [3, 2] : []);
        g.strokeRect((b.u + off[0]) * k + 1, (b.v + off[1]) * k + 1, (2 * (b.w + b.d)) * k - 2, (b.d + b.h) * k - 2);
        g.setLineDash([]);
      }
    }
  }, [doc, uv, sel, drag]);
  const at = (e: React.PointerEvent) => { const r = ref.current!.getBoundingClientRect(); return [((e.clientX - r.left) / r.width) * uv.size, ((e.clientY - r.top) / r.height) * uv.size]; };
  return (
    <section className="me-sec grow">
      <div className="me-sh"><span className="cys-eyebrow">UV box</span><span className="cys-eyebrow r mono">{box ? `${box.u}, ${box.v} · ${2 * (box.w + box.d)} × ${box.d + box.h} px` : `${uv.size} px sheet`}</span></div>
      <div className="me-uv">
        <canvas ref={ref} aria-label={`Skin sheet ${uv.size} by ${uv.size} with every cube's box net`}
          onPointerDown={(e) => { if (readOnly || !box || cube?.locked) return; const [x, y] = at(e); if (x >= box.u && y >= box.v && x < box.u + 2 * (box.w + box.d) && y < box.v + box.d + box.h) { (e.target as HTMLElement).setPointerCapture(e.pointerId); setDrag({ id: box.cube, dx: x - box.u, dy: y - box.v, u: box.u, v: box.v }); } }}
          onPointerMove={(e) => { if (!drag) return; const [x, y] = at(e); setDrag({ ...drag, u: Math.max(0, Math.round(x - drag.dx)), v: Math.max(0, Math.round(y - drag.dy)) }); }}
          onPointerUp={() => { if (drag && box && (drag.u !== box.u || drag.v !== box.v)) commit({ op: "setUv", id: drag.id, uv: [drag.u, drag.v] }); setDrag(null); }} />
      </div>
      <div className="me-row"><span>Placement</span>
        <div className="cys-seg cys-soft sm" role="group" aria-label="UV placement">
          <button type="button" className={cube && !cube.uv ? "on" : ""} disabled={readOnly || !cube} onClick={() => cube?.uv && commit({ op: "setUv", id: cube.id, uv: null })}>Auto-pack</button>
          <button type="button" className={cube?.uv ? "on" : ""} disabled={readOnly || !cube || !box} onClick={() => cube && box && !cube.uv && commit({ op: "setUv", id: cube.id, uv: [box.u, box.v] })}>Pinned</button>
        </div>
        <button type="button" className="cys-btn xs ghost" disabled={readOnly || !doc.cubes.some((c) => c.uv)} onClick={() => commit({ op: "autoUv" })}>Re-pack all</button>
      </div>
      <p className="cys-hint me-pad">Drag the selected box to pin it. Minecraft re-packs pins when it builds (pins ship with RigSpec v1.1).</p>
    </section>
  );
}

// ---------------------------------------------------------------------------------------------- keyframe tab ----
export function KeyInspector({ doc, clip, time, boneId, keySel, setKeySel, commit, readOnly }: { doc: ModelDoc; clip: string | null; time: number; boneId: string | null; keySel: string | null; setKeySel: (k: string | null) => void; commit: Commit; readOnly: boolean }) {
  const cl = doc.clips.find((c) => c.name === clip);
  const [channel, setChannel] = useState<"rotation" | "position" | "scale">("rotation");
  const [newClip, setNewClip] = useState("");
  if (!cl) return <p className="cys-empty">Pick a clip in the timeline.</p>;
  const found = keySel ? cl.tracks.flatMap((t) => (t.keys ?? []).map((k) => ({ t, k }))).find((x) => x.k.id === keySel) : null;
  const bone = boneId ? boneById(doc, boneId) : null;
  const tr = bone ? cl.tracks.find((t) => t.bone === bone.id && t.channel === channel) : null;
  const cur = tr ? sampleTrack(tr, cl, time) : channel === "scale" ? [1, 1, 1] : [0, 0, 0];
  const u = Math.round((time / cl.length) * 10000) / 10000;
  return (
    <div className="me-keys">
      <section className="me-sec">
        <div className="me-sh"><span className="cys-eyebrow">Clip · {cl.name}</span></div>
        <div className="me-row"><span>Length</span><NumField label="Clip length" value={cl.length} step={0.1} disabled={readOnly} onCommit={(v) => commit({ op: "setClip", name: cl.name, length: v })} /><span className="mono me-val">s</span>
          <Seg label="Loop" value={cl.loop ? "loop" : "once"} options={["loop", "once"] as const} disabled={readOnly} onPick={(v) => commit({ op: "setClip", name: cl.name, loop: v === "loop" })} /></div>
        <div className="me-row"><span>New clip</span><input className="cys-field" aria-label="New clip name" placeholder="wail" value={newClip} disabled={readOnly} onChange={(e) => setNewClip(e.target.value.toLowerCase())} />
          <button type="button" className="cys-btn xs" disabled={readOnly || !newClip} onClick={() => { if (commit({ op: "addClip", name: newClip, length: 1, loop: false })) setNewClip(""); }}><SI n="plus" />Add</button></div>
      </section>
      {found ? (
        <section className="me-sec">
          <div className="me-sh"><span className="cys-eyebrow">Key · {boneById(doc, found.t.bone)?.name} {found.t.channel}</span><button type="button" className="cys-btn xs ghost" onClick={() => setKeySel(null)}>Done</button></div>
          <div className="me-row"><span>Time</span><b className="mono me-val">{fmt(found.k.t * cl.length)} s</b></div>
          <div className="me-row"><span>Value</span><Vec3Field label="Key value" v={found.k.v} disabled={readOnly} onCommit={(v) => commit({ op: "setKey", clip: cl.name, bone: found.t.bone, channel: found.t.channel, t: found.k.t, v, ease: found.k.ease })} /></div>
          <div className="me-row"><span>Easing</span><Seg label="Easing" value={found.k.ease} options={["linear", "smooth"] as const} disabled={readOnly} onPick={(e) => commit({ op: "setEase", clip: cl.name, key: found.k.id, ease: e })} /></div>
          <div className="me-row"><span /><button type="button" className="cys-btn xs ghost" disabled={readOnly} onClick={() => { if (commit({ op: "deleteKey", clip: cl.name, key: found.k.id })) setKeySel(null); }}><SI n="trash" />Delete key</button></div>
        </section>
      ) : (
        <section className="me-sec">
          <div className="me-sh"><span className="cys-eyebrow">{bone ? `Key ${bone.name} at ${fmt(time)} s` : "Select a bone to key it"}</span></div>
          <div className="me-row"><span>Channel</span><Seg label="Channel" value={channel} options={["rotation", "position", "scale"] as const} onPick={setChannel} /></div>
          {bone && (tr?.wave ? (
            <div className="me-row"><span /><p className="cys-hint">This track is a wave.</p><button type="button" className="cys-btn xs" disabled={readOnly} onClick={() => commit({ op: "waveToKeys", clip: cl.name, bone: bone.id, channel })}>Convert to keys</button></div>
          ) : (
            <div className="me-row"><span>Value</span><Vec3Field label="New key value" v={cur.map((x) => Math.round(x * 100) / 100) as Vec3} disabled={readOnly} onCommit={(v) => commit({ op: "setKey", clip: cl.name, bone: bone.id, channel, t: u, v })} /></div>
          ))}
        </section>
      )}
    </div>
  );
}

// ---------------------------------------------------------------------------------------------------- checks ----
export function ChecksPanel({ v, onPick }: { v: Validation; onPick: (node: string) => void }) {
  const errors = v.issues.filter((i) => i.severity === "error"), warns = v.issues.filter((i) => i.severity === "warn");
  return (
    <div>
      <div className="cys-verdict">
        <span className={`cys-dot ${errors.length ? "bad" : warns.length ? "warn" : "ok"}`} />
        <div><b>{errors.length ? `${errors.length} error${errors.length > 1 ? "s" : ""}` : "Valid RigSpec"}</b><div className="cys-hint">{errors.length ? "Fix these before you save a revision." : `${warns.length} warning${warns.length === 1 ? "" : "s"}. Checked by the RigSpec validator; not loaded on a real server yet.`}</div></div>
      </div>
      <ul className="cys-checks">
        {v.issues.map((i, n) => (
          <li key={n} className={`cys-check ${i.severity === "error" ? "fail" : i.severity === "warn" ? "warn" : "not_run"}`}>
            <span className="ic"><SI n={i.severity === "error" ? "close" : i.severity === "warn" ? "warn" : "info"} /></span>
            <span className="id">{i.code}</span>
            <span className="val">{i.node ? <button type="button" className="cys-btn xs ghost" onClick={() => onPick(i.node!)}>show</button> : null}</span>
            <span className="msg">{i.message}</span>
          </li>
        ))}
        <li className="cys-check not_run"><span className="ic"><SI n="minus" /></span><span className="id">bettermodel_load</span><span className="val">not run</span><span className="msg">Not loaded on a real server yet (Test Flight).</span></li>
      </ul>
    </div>
  );
}

// -------------------------------------------------------------------------------------------------- timeline ----
export function Timeline({ doc, clip, setClip, time, setTime, playing, setPlaying, boneSel, keySel, setKeySel, commit, readOnly, onKey }: {
  doc: ModelDoc; clip: string | null; setClip: (c: string | null) => void; time: number; setTime: (t: number) => void; playing: boolean; setPlaying: (p: boolean) => void;
  boneSel: string | null; keySel: string | null; setKeySel: (k: string | null) => void; commit: Commit; readOnly: boolean; onKey: () => void;
}) {
  const cl = doc.clips.find((c) => c.name === clip) ?? null;
  const lane = useRef<HTMLDivElement>(null);
  const [drag, setDrag] = useState<{ key: string; t: number } | null>(null);
  const tAt = (x: number) => { const r = lane.current!.getBoundingClientRect(); return Math.max(0, Math.min(1, (x - r.left) / r.width)); };
  const ticks = cl ? Math.min(20, Math.max(2, Math.round(cl.length / 0.5))) : 0;
  return (
    <div className="me-tl cys-glass cys-panel">
      <div className="me-tlh">
        <button type="button" className={`cys-ib ${playing ? "on" : ""}`} aria-label={playing ? "Pause" : "Play"} disabled={!cl} onClick={() => setPlaying(!playing)}><SI n={playing ? "pause" : "play"} /></button>
        <div className="cys-seg cys-soft sm me-clips" role="tablist" aria-label="Clips">
          <button type="button" role="tab" aria-selected={clip === null} className={clip === null ? "on" : ""} onClick={() => setClip(null)}>rest</button>
          {doc.clips.map((c) => <button key={c.name} type="button" role="tab" aria-selected={c.name === clip} className={c.name === clip ? "on" : ""} onClick={() => setClip(c.name)}>{c.name}</button>)}
        </div>
        {cl && <span className="me-time mono"><b>{fmt(time)} s</b> / {fmt(cl.length)} s</span>}
        {cl && <span className="cys-tag dim">{fmt(cl.length)} s · {cl.loop ? "loop" : "once"}</span>}
        <span className="sp" />
        <button type="button" className="cys-btn xs" disabled={readOnly || !cl || !boneSel} onClick={onKey} title="Key the selected bone's rotation at the playhead"><MI n="key" />Key</button>
      </div>
      {cl ? (
        <div className="me-tlb">
          <div className="me-tracks">
            {cl.tracks.map((t, i) => {
              const b = boneById(doc, t.bone);
              return (
                <div key={i} className={`me-trk ${t.bone === boneSel ? "on" : ""}`}>
                  <span className="lb"><b>{b?.name ?? "?"}</b> {t.channel === "rotation" ? "rot" : t.channel === "position" ? "pos" : "scale"}</span>
                  <span className="n mono">{t.wave ? "wave" : `${t.keys?.length ?? 0} keys`}</span>
                </div>
              );
            })}
          </div>
          <div className="me-lanes" ref={lane} onPointerDown={(e) => { if ((e.target as HTMLElement).dataset.key) return; setPlaying(false); setTime(tAt(e.clientX) * cl.length); }}>
            <div className="me-ruler">{Array.from({ length: ticks + 1 }, (_, i) => <span key={i} style={{ left: `${(i / ticks) * 100}%` }}>{fmt((i / ticks) * cl.length)}</span>)}</div>
            {cl.tracks.map((t, i) => (
              <div key={i} className="me-lane">
                {t.wave ? <svg viewBox="0 0 100 10" preserveAspectRatio="none" aria-hidden="true"><path d={Array.from({ length: 41 }, (_, j) => `${j ? "L" : "M"}${j * 2.5} ${5 - 4 * Math.sin(2 * Math.PI * ((j / 40) * t.wave!.cycles + t.wave!.phase))}`).join(" ")} /></svg> : null}
                {(t.keys ?? []).map((k: EKey, j: number) => {
                  const edge = j === 0 || j === (t.keys!.length - 1);
                  const at = drag?.key === k.id ? drag.t : k.t;
                  return <button key={k.id} type="button" data-key={k.id} aria-label={`Key ${fmt(k.t * cl.length)} s`} className={`me-key ${keySel === k.id ? "on" : ""} ${k.ease}`} style={{ left: `${at * 100}%` }}
                    onPointerDown={(e) => { e.stopPropagation(); setKeySel(k.id); if (!readOnly && !edge) { (e.target as HTMLElement).setPointerCapture(e.pointerId); setDrag({ key: k.id, t: k.t }); } }}
                    onPointerMove={(e) => { if (drag?.key === k.id) setDrag({ key: k.id, t: tAt(e.clientX) }); }}
                    onPointerUp={() => { if (drag?.key === k.id && Math.abs(drag.t - k.t) > 0.005) commit({ op: "moveKey", clip: cl.name, key: k.id, t: drag.t }); setDrag(null); }} />;
                })}
              </div>
            ))}
            <div className="me-head" style={{ left: `${(time / cl.length) * 100}%` }} />
          </div>
        </div>
      ) : <p className="cys-hint me-pad">Rest pose. Pick a clip to scrub, play and key it.</p>}
    </div>
  );
}

export function issueCount(v: Validation) { return { errors: v.issues.filter((i) => i.severity === "error").length, warns: v.issues.filter((i) => i.severity === "warn").length }; }
export { cubeById };

