"use client";
// Cyrus MODEL STUDIO, layer 2: the cuboid + bone editor (full page). Anatomy from the v3 mockup
// (/root/agent-notes/cyrus-designs/v3-model-studio/model-editor.html, NOT owner-reviewed yet): left = outliner +
// budgets; centre = model bar, AI candidate bar, viewport with the tool rail, pose timeline, prompt dock; right =
// Cube / Keyframe / Checks inspector with the UV box. Narrow screens get the read-only turntable + approve view.
// All logic is in lib/cyrus/modelstudio/editor (pure, unit-tested); this file is state, wiring and drawing.
// The 3D view goes through ./viewport-adapter.ts (internal canvas stand-in until the layer-1 three.js viewport lands).
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { CyrusGlyph } from "@/components/cyrus/icons/CyrusLogo";
import { StudioShell, useToast, type StudioMod } from "@/components/cyrus/studios/StudioShell";
import { SI } from "@/components/cyrus/studios/icons";
import { boneById, cubeById, centre, type ModelDoc, type Vec3 } from "@/lib/cyrus/modelstudio/editor/doc";
import { canRedo, canUndo, currentDoc, logApply, logInit, logRebase, logRedo, logUndo, serializeDoc, unsavedCount, type OpLog } from "@/lib/cyrus/modelstudio/editor/history";
import { applyOp, ANGLE_SNAPS, cubeLabel, SNAP_STEPS, type Op } from "@/lib/cyrus/modelstudio/editor/ops";
import { validateDoc } from "@/lib/cyrus/modelstudio/editor/validate";
import { apply as applyM, sampleTrack } from "@/lib/cyrus/modelstudio/editor/pose";
import { axisDrag, buildScene, fitCamera, pickCube, type Camera } from "@/lib/cyrus/modelstudio/editor/scene";
import { diffDocs, mergeCandidate, mergeSummary } from "@/lib/cyrus/modelstudio/editor/merge";
import { fakeModelCandidate } from "@/lib/cyrus/modelstudio/editor/fake-candidate";
import { autosaveDone, autosaveDueIn, autosaveEdit, autosaveInit } from "@/lib/cyrus/modelstudio/editor/autosave";
import { canvasViewport, type Gizmo, type GizmoKind, type ModelViewport, type ModelViewportFactory, type ViewportFrame } from "./viewport-adapter";
import { modelApi, ModelApiError, type ModelViewJson } from "./api";
import { BoneInspector, BudgetPanel, ChecksPanel, CubeInspector, issueCount, KeyInspector, Outliner, Timeline, UvSheet, type Commit } from "./panels";
import { MI } from "./icons";
import "./editor.css";

type Tool = "select" | GizmoKind;
const TOOLS: { id: Tool; label: string; key: string; icon: string }[] = [
  { id: "select", label: "Select", key: "Q", icon: "pointer" }, { id: "move", label: "Move", key: "W", icon: "move" }, { id: "rotate", label: "Rotate", key: "E", icon: "rotate" },
  { id: "resize", label: "Resize", key: "R", icon: "resize" }, { id: "pivot", label: "Pivot", key: "P", icon: "pivot" },
];
type Cand = { base: ModelDoc; theirs: ModelDoc; summary: string; prompt: string; accept: Set<string> | null; resolve: Record<string, "ours" | "theirs">; compare: boolean; part: boolean };
type Loaded = { projectId: string; key: string; view: ModelViewJson; saved: ModelDoc; baseAssetId: string; headId: string | null; seq: number | null };
const hash = (s: string) => { let h = 2166136261; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); } return (h >>> 0).toString(16); };
const draftKey = (p: string, k: string) => `cyrus-model-draft:${p}:${k}`;

export function ModelEditor({ mod, initialKey, readOnly, devFakeCandidate, viewport = canvasViewport }: { mod: StudioMod; initialKey: string | null; readOnly: boolean; devFakeCandidate: boolean; viewport?: ModelViewportFactory }) {
  return (
    <StudioShell mod={mod} current="Model Studio" studio={null}>
      <Body mod={mod} initialKey={initialKey} readOnlyPlan={readOnly} devFake={devFakeCandidate} factory={viewport} />
    </StudioShell>
  );
}

function Body({ mod, initialKey, readOnlyPlan, devFake, factory }: { mod: StudioMod; initialKey: string | null; readOnlyPlan: boolean; devFake: boolean; factory: ModelViewportFactory }) {
  const toast = useToast();
  const [loaded, setLoaded] = useState<Loaded | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [keys, setKeys] = useState<string[]>([]);
  const [log, setLog] = useState<OpLog | null>(null);
  const [preview, setPreview] = useState<ModelDoc | null>(null);
  const [sel, setSel] = useState<string[]>([]);
  const [tool, setTool] = useState<Tool>("move");
  const [snap, setSnap] = useState(1);
  const [angleSnap, setAngleSnap] = useState(15);
  const [tab, setTab] = useState<"cube" | "key" | "checks">("cube");
  const [clip, setClip] = useState<string | null>("idle");
  const [time, setTime] = useState(0);
  const [playing, setPlaying] = useState(false);
  const [keySel, setKeySel] = useState<string | null>(null);
  const [view, setView] = useState<"persp" | "front" | "side">("persp");
  const [showBones, setShowBones] = useState(true);
  const [wire, setWire] = useState(false);
  const [cand, setCand] = useState<Cand | null>(null);
  const [prompt, setPrompt] = useState("");
  const [saving, setSaving] = useState(false);
  const [draftOffer, setDraftOffer] = useState<{ doc: ModelDoc; at: string; where: "server" | "browser" } | null>(null);
  const [draftNote, setDraftNote] = useState<string | null>(null);
  const auto = useRef(autosaveInit());
  const readOnly = readOnlyPlan || !loaded?.view.access.edit.ok;

  // ---- load
  const open = useCallback(async (key: string | null) => {
    setErr(null);
    try {
      const list = await modelApi.list(mod.rootId);
      if (!list.project) { setErr("This mod has no Cyrus project yet. Build it once, then open Model Studio."); return; }
      setKeys(list.models.map((m) => m.key));
      const k = key && list.models.some((m) => m.key === key) ? key : list.models[0]?.key;
      if (!k) { setErr("This mod has no creature models yet. Ask Cyrus for an animated creature first."); return; }
      const v = await modelApi.get(list.project.id, k);
      const seqOf = null;
      setLoaded({ projectId: list.project.id, key: k, view: v, saved: v.model.doc, baseAssetId: v.model.assetId, headId: v.headRevisionId, seq: seqOf });
      setLog(logInit(v.model.doc));
      auto.current = autosaveInit(hash(serializeDoc(v.model.doc)));
      setSel([]); setCand(null); setKeySel(null);
      setClip(v.model.doc.clips.some((c) => c.name === "idle") ? "idle" : null);
      // an unsaved draft (server first, else this browser) is offered, never applied silently
      let local: { doc: ModelDoc; at: string } | null = null;
      try { const raw = localStorage.getItem(draftKey(list.project.id, k)); if (raw) local = JSON.parse(raw); } catch { /* storage blocked */ }
      const d = v.draft ? { doc: v.draft.doc, at: v.draft.updatedAt, where: "server" as const } : local ? { ...local, where: "browser" as const } : null;
      setDraftOffer(d && serializeDoc(d.doc) !== serializeDoc(v.model.doc) && v.access.edit.ok ? d : null);
    } catch (e) { setErr(e instanceof ModelApiError ? e.message : "Model Studio could not load this mod."); }
  }, [mod.rootId]);
  useEffect(() => { void open(initialKey); }, [open, initialKey]);

  const doc = preview ?? (log ? currentDoc(log) : null);
  const validation = useMemo(() => (doc ? validateDoc(doc) : null), [doc]);
  const shown = useMemo(() => {
    if (!doc || !cand?.compare || !log) return doc;
    return mergeCandidate(cand.base, currentDoc(log), cand.theirs, { accept: cand.accept, resolve: cand.resolve }).doc;
  }, [doc, cand, log]);

  const commit: Commit = useCallback((op: Op) => {
    if (!log) return false;
    if (readOnly && !(op.op === "setFlag" && op.flag === "hidden")) { toast(loaded?.view.access.edit.ok === false ? loaded.view.access.edit.reason : "This model is view only.", true); return false; }
    const r = logApply(log, op);
    if (!r.ok) { toast(r.error, true); return false; }
    setLog(r.log);
    if (r.select) setSel(r.select);
    return true;
  }, [log, readOnly, toast, loaded]);

  // ---- autosave (5 s idle, 30 s max): server draft when wired, else this browser only
  useEffect(() => {
    if (!log || !loaded || readOnly) return;
    const s = serializeDoc(currentDoc(log));
    auto.current = autosaveEdit(auto.current, Date.now(), hash(s));
    const due = autosaveDueIn(auto.current, Date.now());
    if (due === null) return;
    const t = window.setTimeout(async () => {
      const d = currentDoc(log), h = hash(serializeDoc(d));
      try { await modelApi.draft(loaded.projectId, loaded.key, { doc: d, baseAssetId: loaded.baseAssetId, baseHeadId: loaded.headId }); setDraftNote("Draft saved"); }
      catch { try { localStorage.setItem(draftKey(loaded.projectId, loaded.key), JSON.stringify({ doc: d, at: new Date().toISOString() })); setDraftNote("Draft kept in this browser"); } catch { setDraftNote("Draft not saved"); } }
      auto.current = autosaveDone(auto.current, h);
    }, due);
    return () => window.clearTimeout(t);
  }, [log, loaded, readOnly]);

  // ---- playback
  useEffect(() => {
    if (!playing || !doc) return;
    const cl = doc.clips.find((c) => c.name === clip);
    if (!cl) { setPlaying(false); return; }
    let last = performance.now(), raf = 0;
    const tick = (now: number) => {
      const dt = (now - last) / 1000; last = now;
      setTime((t) => { const n = t + dt; if (n <= cl.length) return n; if (cl.loop) return n % cl.length; setPlaying(false); return cl.length; });
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [playing, clip, doc]);
  useEffect(() => { setTime(0); setKeySel(null); }, [clip]);

  const save = async (action: "save" | "approve" = "save") => {
    if (!loaded || !log || !doc) return;
    if (validation && !validation.ok) { setTab("checks"); toast("Fix the errors in Checks first.", true); return; }
    setSaving(true);
    try {
      const r = await modelApi.save(loaded.projectId, loaded.key, { doc: currentDoc(log), baseAssetId: loaded.baseAssetId, expectedHeadId: loaded.headId, action });
      const savedDoc = currentDoc(log);
      setLoaded({ ...loaded, saved: savedDoc, baseAssetId: r.assetId, headId: r.revisionId, seq: r.seq });
      setLog(logRebase(savedDoc));
      auto.current = autosaveInit(hash(serializeDoc(savedDoc)));
      try { localStorage.removeItem(draftKey(loaded.projectId, loaded.key)); } catch { /* ignore */ }
      setDraftNote(null);
      toast(`Saved as revision ${r.seq}.`);
    } catch (e) { toast(e instanceof ModelApiError ? e.message : "Saving failed. Nothing was changed.", true); }
    finally { setSaving(false); }
  };

  const ask = () => {
    if (!loaded || !prompt.trim()) return;
    if (readOnly) { toast(loaded.view.access.edit.ok ? "This model is view only." : loaded.view.access.edit.reason, true); return; }
    if (!devFake) { toast("Cyrus model edits are not connected yet. Nothing was sent.", true); return; }
    const c = fakeModelCandidate(loaded.saved, prompt);
    if (!c.ok) { toast(c.error, true); return; }
    setCand({ base: loaded.saved, theirs: c.doc, summary: c.summary, prompt: prompt.trim(), accept: null, resolve: {}, compare: false, part: false });
    setPrompt("");
  };
  const merged = useMemo(() => (cand && log ? mergeCandidate(cand.base, currentDoc(log), cand.theirs, { accept: cand.accept, resolve: cand.resolve }) : null), [cand, log]);
  const allChanges = useMemo(() => (cand && log ? mergeCandidate(cand.base, currentDoc(log), cand.theirs) : null), [cand, log]);
  const applyCand = () => {
    if (!merged || !cand) return;
    if (commit({ op: "replace", doc: merged.doc, label: `Accept Cyrus edit (${mergeSummary(merged)})` })) { toast(merged.notes[0] ?? `Applied ${merged.applied.length} change${merged.applied.length === 1 ? "" : "s"}.`); setCand(null); }
  };

  // ---- keyboard
  useEffect(() => {
    const on = (e: KeyboardEvent) => {
      const t = e.target as HTMLElement;
      if (t && (t.tagName === "INPUT" || t.tagName === "SELECT" || t.tagName === "TEXTAREA")) return;
      if (!log) return;
      const mod = e.ctrlKey || e.metaKey;
      if (mod && e.key.toLowerCase() === "z") { e.preventDefault(); setLog(e.shiftKey ? logRedo(log) : logUndo(log)); return; }
      if (mod && e.key.toLowerCase() === "y") { e.preventDefault(); setLog(logRedo(log)); return; }
      if (mod && e.key.toLowerCase() === "d" && sel.length) { e.preventDefault(); commit({ op: "duplicate", ids: sel }); return; }
      if (mod) return;
      const tl = TOOLS.find((x) => x.key.toLowerCase() === e.key.toLowerCase());
      if (tl) { setTool(tl.id); return; }
      if (e.key.toLowerCase() === "x" && sel.length) commit({ op: "mirror", ids: sel });
      else if ((e.key === "Delete" || e.key === "Backspace") && sel.length) commit({ op: "delete", ids: sel });
      else if (e.key.toLowerCase() === "h" && sel.length) commit({ op: "setFlag", ids: sel, flag: "hidden", value: true });
      else if (e.key === " ") { e.preventDefault(); setPlaying((p) => !p); }
      else if (e.key === "Escape") setSel([]);
    };
    window.addEventListener("keydown", on);
    return () => window.removeEventListener("keydown", on);
  }, [log, sel, commit]);

  if (err) return <main className="me-empty-wrap"><div className="cys-glass cys-panel me-empty"><SI n="info" /><p>{err}</p></div></main>;
  if (!loaded || !log || !doc || !validation || !shown) return <main className="me-empty-wrap"><div className="cys-glass cys-panel me-empty"><p>Loading Model Studio…</p></div></main>;

  const primary = sel[0] ?? null;
  const selBone = primary ? boneById(doc, primary) ?? null : null;
  const selCube = primary ? cubeById(doc, primary) ?? null : null;
  const boneForCube = selCube ? boneById(doc, selCube.bone) ?? null : null;
  const activeBone = selBone ?? boneForCube;
  const counts = issueCount(validation);
  const unsaved = unsavedCount(log);
  const changes = diffDocs(loaded.saved, currentDoc(log));
  const keyNow = () => {
    if (!activeBone || !clip) return;
    const cl = doc.clips.find((c) => c.name === clip);
    if (!cl) return;
    const tr = cl.tracks.find((t) => t.bone === activeBone.id && t.channel === "rotation");
    if (tr?.wave) { toast(`${activeBone.name} rotation is a wave; convert it to keys in the Keyframe tab first.`, true); return; }
    const v = tr ? sampleTrack(tr, cl, time) : [0, 0, 0];
    if (commit({ op: "setKey", clip: cl.name, bone: activeBone.id, channel: "rotation", t: Math.round((time / cl.length) * 10000) / 10000, v: v.map((x) => Math.round(x * 100) / 100) as Vec3 })) setTab("key");
  };

  return (
    <>
      <main className="me-ws" aria-label="Model Studio editor">
        {/* left: outliner + budgets */}
        <div className="me-col">
          <section className="cys-glass cys-panel me-outl">
            <div className="cys-ph"><span className="cys-eyebrow">Outliner</span><span className="cys-tag dim">{doc.bones.length} bones</span>
              <button type="button" className="cys-ib sm" aria-label="Add bone" disabled={readOnly} onClick={() => commit({ op: "addBone", parent: activeBone?.id ?? doc.bones.find((b) => b.parent === null)!.id })}><MI n="bone" /></button>
              <button type="button" className="cys-ib sm" aria-label="Add cube" disabled={readOnly || !activeBone} onClick={() => activeBone && commit({ op: "addCube", bone: activeBone.id })}><SI n="plus" /></button>
            </div>
            <div className="me-acts">
              <button type="button" className="cys-btn xs ghost" disabled={readOnly || !sel.length} onClick={() => commit({ op: "duplicate", ids: sel })} title="Duplicate (Ctrl D)"><SI n="copy" />Copy</button>
              <button type="button" className="cys-btn xs ghost" disabled={readOnly || !sel.length} onClick={() => commit({ op: "mirror", ids: sel })} title="Mirror on X (X)"><SI n="mirror" />Mirror</button>
              <button type="button" className="cys-btn xs ghost" disabled={readOnly || !sel.length} onClick={() => commit({ op: "group", ids: sel })} title="Group into a new bone"><MI n="group" />Group</button>
              <button type="button" className="cys-btn xs ghost" disabled={readOnly || !sel.length} onClick={() => commit({ op: "delete", ids: sel })} title="Delete (Del)"><SI n="trash" />Delete</button>
            </div>
            <Outliner doc={doc} sel={sel} setSel={setSel} commit={commit} readOnly={readOnly} issues={validation.issues} />
          </section>
          <section className="cys-glass cys-panel">
            <div className="cys-ph"><span className="cys-eyebrow">Budget</span><span className="cys-tag dim">RigSpec v1 caps</span></div>
            <BudgetPanel budgets={validation.budgets} />
          </section>
        </div>

        {/* centre */}
        <div className="me-col me-mid">
          <div className="me-bar cys-glass">
            <div className="ttl"><b>{doc.name}</b><span className="cys-tag dim">{doc.meta.archetype}</span><span className="cys-tag dim">base {doc.meta.baseEntity}</span>
              {keys.length > 1 && <select className="cys-field me-pick" aria-label="Model" value={loaded.key} onChange={(e) => void open(e.target.value)}>{keys.map((k) => <option key={k}>{k}</option>)}</select>}
            </div>
            <span className="sp" />
            {readOnly && <span className="cys-tag warn"><SI n="lock" /> view only</span>}
            <button type="button" className="cys-ib" aria-label="Undo" disabled={!canUndo(log)} onClick={() => setLog(logUndo(log))}><SI n="undo" /></button>
            <button type="button" className="cys-ib" aria-label="Redo" disabled={!canRedo(log)} onClick={() => setLog(logRedo(log))}><SI n="redo" /></button>
            <span className="me-unsaved mono"><span className={`cys-dot ${unsaved ? "warn" : "ok"}`} />{unsaved ? `${unsaved} unsaved edit${unsaved > 1 ? "s" : ""}` : "saved"}{draftNote && unsaved ? ` · ${draftNote}` : ""}</span>
            <button type="button" className="cys-btn sm primary" disabled={readOnly || saving || !unsaved} onClick={() => void save()}><SI n="check" />{saving ? "Saving…" : "Save revision"}</button>
          </div>
          {draftOffer && (
            <div className="me-cbar cys-soft" role="status">
              <SI n="restore" /><div className="tx"><b>Unsaved draft</b> from {new Date(draftOffer.at).toLocaleString()} ({draftOffer.where === "server" ? "saved on Nxeon" : "this browser"})</div>
              <span className="sp" />
              <button type="button" className="cys-btn xs primary" onClick={() => { commit({ op: "replace", doc: draftOffer.doc, label: "Restore draft" }); setDraftOffer(null); }}>Restore</button>
              <button type="button" className="cys-btn xs ghost" onClick={() => { try { localStorage.removeItem(draftKey(loaded.projectId, loaded.key)); } catch { /* ignore */ } setDraftOffer(null); }}>Discard</button>
            </div>
          )}
          {cand && merged && allChanges && (
            <div className="me-cbar cand" data-testid="model-candidate">
              <span className="av"><CyrusGlyph id="me-cand" /></span>
              <div className="tx"><b>Cyrus edit ready</b> · from revision {loaded.seq ?? "current"} · {allChanges.applied.length} change{allChanges.applied.length === 1 ? "" : "s"}<small>&ldquo;{cand.prompt}&rdquo; · {cand.summary}</small></div>
              {allChanges.overlaps.length > 0 && <span className="cys-tag warn">{allChanges.overlaps.length} overlap{allChanges.overlaps.length > 1 ? "s" : ""}</span>}
              <span className="sp" />
              <button type="button" className={`cys-btn xs ${cand.compare ? "primary" : ""}`} onClick={() => setCand({ ...cand, compare: !cand.compare })}><SI n="eye" />Compare</button>
              <button type="button" className={`cys-btn xs ${cand.part ? "primary" : ""}`} onClick={() => setCand({ ...cand, part: !cand.part, accept: cand.accept ?? new Set(allChanges.applied.map((c) => c.id)) })}>Apply part</button>
              <button type="button" className="cys-btn xs primary" disabled={readOnly} onClick={applyCand}>Apply</button>
              <button type="button" className="cys-btn xs ghost" onClick={() => setCand(null)}>Reject</button>
              {cand.part && (
                <ul className="cys-chg me-part">
                  {allChanges.applied.map((c) => (
                    <li key={c.id}><input type="checkbox" id={`mc-${c.id}`} checked={!cand.accept || cand.accept.has(c.id)} onChange={(e) => { const s = new Set(cand.accept ?? allChanges.applied.map((x) => x.id)); if (e.target.checked) s.add(c.id); else s.delete(c.id); setCand({ ...cand, accept: s }); }} /><label htmlFor={`mc-${c.id}`}><b>{c.label}</b><small>{c.action}</small></label></li>
                  ))}
                  {allChanges.overlaps.map((o) => (
                    <li key={o.id}><SI n="warn" /><div><b>{o.label}</b><small>both changed it · keeping {cand.resolve[o.id] === "theirs" ? "Cyrus's" : "yours"}</small></div>
                      <button type="button" className="cys-btn xs ghost" onClick={() => setCand({ ...cand, resolve: { ...cand.resolve, [o.id]: cand.resolve[o.id] === "theirs" ? "ours" : "theirs" } })}>{cand.resolve[o.id] === "theirs" ? "Keep mine" : "Take Cyrus's"}</button></li>
                  ))}
                </ul>
              )}
            </div>
          )}
          <Viewport factory={factory} doc={shown} clip={clip} time={time} sel={sel} setSel={setSel} tool={tool} setTool={setTool} snap={snap} setSnap={setSnap} angleSnap={angleSnap} setAngleSnap={setAngleSnap}
            view={view} setView={setView} showBones={showBones} setShowBones={setShowBones} wire={wire} setWire={setWire} readOnly={readOnly || !!cand?.compare}
            onPreview={(op) => { if (!log) return; if (!op) { setPreview(null); return; } const r = applyOp(currentDoc(log), op); setPreview(r.ok ? r.doc : null); }}
            onCommit={(op) => { setPreview(null); commit(op); }} activeBone={activeBone?.id ?? null} />
          <Timeline doc={doc} clip={clip} setClip={setClip} time={time} setTime={setTime} playing={playing} setPlaying={setPlaying} boneSel={activeBone?.id ?? null} keySel={keySel} setKeySel={(k) => { setKeySel(k); if (k) setTab("key"); }} commit={commit} readOnly={readOnly} onKey={keyNow} />
          <form className="cys-dock cys-glass" onSubmit={(e) => { e.preventDefault(); ask(); }}>
            <span className="route"><SI n="edit" />Edit {doc.name}</span>
            <input aria-label="Ask Cyrus to change this model" placeholder={readOnly ? "View only on your plan" : `Ask Cyrus: "make the ${activeBone?.name ?? "hood"} longer"`} value={prompt} disabled={readOnly} onChange={(e) => setPrompt(e.target.value)} />
            <span className="model"><SI n="sparkle" />Yakko</span>
            <button type="submit" className="send" aria-label="Send" disabled={readOnly || !prompt.trim()}><SI n="send" /></button>
          </form>
        </div>

        {/* right: inspector */}
        <aside className="cys-glass cys-panel me-insp">
          <div className="cys-tabs" role="tablist">
            <button type="button" role="tab" aria-selected={tab === "cube"} className={`cys-tab ${tab === "cube" ? "on" : ""}`} onClick={() => setTab("cube")}><SI n="cube" />{selCube ? "Cube" : "Bone"}</button>
            <button type="button" role="tab" aria-selected={tab === "key"} className={`cys-tab ${tab === "key" ? "on" : ""}`} onClick={() => setTab("key")}><MI n="key" />Keyframe</button>
            <button type="button" role="tab" aria-selected={tab === "checks"} className={`cys-tab ${tab === "checks" ? "on" : ""}`} onClick={() => setTab("checks")}><SI n="check" />Checks<span className={`cys-tag ${counts.errors ? "bad" : counts.warns ? "warn" : "ok"}`}>{counts.errors ? `${counts.errors} err` : counts.warns ? `${counts.warns} warn` : "pass"}</span></button>
          </div>
          <div className="me-ib">
            {tab === "cube" && (
              <>
                {activeBone ? <BoneInspector doc={doc} bone={activeBone} commit={commit} readOnly={readOnly} snap={snap} angleSnap={angleSnap} /> : <p className="cys-empty">Select a bone or cube in the outliner or the viewport.</p>}
                {selCube && <CubeInspector doc={doc} cube={selCube} commit={commit} readOnly={readOnly} snap={snap} angleSnap={angleSnap} target={validation.target} />}
                <UvSheet doc={doc} uv={validation.uv} sel={selCube?.id ?? null} commit={commit} readOnly={readOnly} />
              </>
            )}
            {tab === "key" && <KeyInspector doc={doc} clip={clip} time={time} boneId={activeBone?.id ?? null} keySel={keySel} setKeySel={setKeySel} commit={commit} readOnly={readOnly} />}
            {tab === "checks" && <ChecksPanel v={validation} onPick={(n) => { setSel([n]); setTab("cube"); }} />}
          </div>
        </aside>
      </main>
      <Narrow factory={factory} doc={doc} saved={loaded.saved} changes={changes.map((c) => c.label)} counts={counts} budgets={validation.budgets} readOnly={readOnly} saving={saving} seq={loaded.seq}
        onApprove={() => void save("approve")} onReject={() => { setLog(logRebase(loaded.saved)); try { localStorage.removeItem(draftKey(loaded.projectId, loaded.key)); } catch { /* ignore */ } toast("Kept the saved version."); }} />
    </>
  );
}

// ------------------------------------------------------------------------------------------------------ viewport ----
function useTheme(): "dark" | "light" {
  const [t, setT] = useState<"dark" | "light">("dark");
  useEffect(() => {
    const read = () => setT(document.documentElement.getAttribute("data-theme") === "light" ? "light" : "dark");
    read();
    const mo = new MutationObserver(read);
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] });
    return () => mo.disconnect();
  }, []);
  return t;
}

type VProps = {
  factory: ModelViewportFactory; doc: ModelDoc; clip: string | null; time: number; sel: string[]; setSel: (s: string[]) => void; tool: Tool; setTool: (t: Tool) => void;
  snap: number; setSnap: (n: number) => void; angleSnap: number; setAngleSnap: (n: number) => void; view: "persp" | "front" | "side"; setView: (v: "persp" | "front" | "side") => void;
  showBones: boolean; setShowBones: (b: boolean) => void; wire: boolean; setWire: (b: boolean) => void; readOnly: boolean; activeBone: string | null;
  onPreview: (op: Op | null) => void; onCommit: (op: Op) => void;
};

function Viewport(p: VProps) {
  const cv = useRef<HTMLCanvasElement>(null);
  const vp = useRef<ModelViewport | null>(null);
  const [dims, setDims] = useState({ w: 600, h: 400 });
  const [orbit, setOrbit] = useState({ yaw: 0, pitch: 0, zoom: 1 });
  const [hot, setHot] = useState<0 | 1 | 2 | null>(null);
  const drag = useRef<{ kind: "orbit" | "axis"; x: number; y: number; axis?: 0 | 1 | 2; op?: Op | null } | null>(null);
  const theme = useTheme();
  const { doc } = p;
  const scene = useMemo(() => buildScene(doc, { clip: p.clip, time: p.time }), [doc, p.clip, p.time]);
  const rest = useMemo(() => buildScene(doc), [doc]);
  // frame the camera on the model once per model + view (not on every edit, so the view does not jump)
  const frameKey = `${doc.name}|${p.view}`;
  const [frameBox, setFrameBox] = useState<{ key: string; min: Vec3; max: Vec3 } | null>(null);
  useEffect(() => { if (frameBox?.key !== frameKey) setFrameBox({ key: frameKey, min: rest.min, max: rest.max }); }, [frameKey, rest, frameBox]);
  const cam: Camera = useMemo(() => {
    const c = fitCamera(frameBox ?? rest, dims.w, dims.h, p.view);
    return { ...c, yaw: c.yaw + orbit.yaw, pitch: Math.max(-89, Math.min(89, c.pitch + orbit.pitch)), zoom: c.zoom * orbit.zoom, ortho: c.ortho && orbit.yaw === 0 && orbit.pitch === 0 };
  }, [frameBox, rest, dims, p.view, orbit]);
  useEffect(() => { setOrbit({ yaw: 0, pitch: 0, zoom: 1 }); }, [p.view]);

  const primary = p.sel[0] ?? null;
  const gizmo: Gizmo = useMemo(() => {
    if (!primary || p.tool === "select" || p.readOnly) return null;
    const b = boneById(doc, primary), c = cubeById(doc, primary);
    const world = (boneId: string, pt: Vec3): Vec3 => { const m = scene.matrices.get(boneId); return m ? applyM(m, pt) : pt; };
    if (b) return { kind: p.tool === "resize" ? "move" : p.tool, origin: world(b.id, b.pivot) };
    if (c) return { kind: p.tool, origin: world(c.bone, p.tool === "pivot" || p.tool === "rotate" ? c.pivot : p.tool === "resize" ? c.to : centre(c)) };
    return null;
  }, [primary, p.tool, p.readOnly, doc, scene]);
  const frame: ViewportFrame = { scene, camera: cam, selected: new Set(p.sel), selectedBone: primary && boneById(doc, primary) ? primary : cubeById(doc, primary ?? "")?.bone ?? null, showBones: p.showBones, wire: p.wire, gizmo, hot, theme };

  useEffect(() => {
    const c = cv.current;
    if (!c) return;
    vp.current = p.factory(c, { maxDpr: window.innerWidth < 760 ? 1.5 : 2 });
    const ro = new ResizeObserver(() => setDims({ w: Math.max(50, c.clientWidth), h: Math.max(50, c.clientHeight) }));
    ro.observe(c);
    return () => { ro.disconnect(); vp.current?.dispose(); vp.current = null; };
  }, [p.factory]);
  useEffect(() => { vp.current?.draw(frame); });

  const local = (e: React.PointerEvent | React.WheelEvent) => { const r = cv.current!.getBoundingClientRect(); return { x: e.clientX - r.left, y: e.clientY - r.top }; };
  const opFor = (axis: 0 | 1 | 2, dx: number, dy: number): Op | null => {
    if (!primary || !gizmo) return null;
    const u = axisDrag(cam, gizmo.origin, axis, dx, dy);
    const vec = (n: number): Vec3 => { const v: Vec3 = [0, 0, 0]; v[axis] = n; return v; };
    const c = cubeById(doc, primary), b = boneById(doc, primary);
    if (p.tool === "move" || (p.tool === "resize" && b)) return { op: "move", ids: p.sel, delta: vec(u), snap: p.snap };
    if (p.tool === "rotate") return { op: "rotate", ids: p.sel, rotation: vec(dx * 0.6), mode: "add", snap: p.angleSnap };
    if (p.tool === "pivot") { const base = b ? b.pivot : c!.pivot; return { op: "setPivot", id: primary, pivot: base.map((v, i) => (i === axis ? v + u : v)) as Vec3, snap: p.snap }; }
    if (p.tool === "resize" && c) { const s: Vec3 = [c.to[0] - c.from[0], c.to[1] - c.from[1], c.to[2] - c.from[2]]; s[axis] += u; return { op: "resize", id: c.id, size: s, snap: p.snap }; }
    return null;
  };

  return (
    <div className="me-stage">
      <canvas ref={cv} className="me-cv" aria-label={`3D view of ${doc.name}`} role="img"
        onContextMenu={(e) => e.preventDefault()}
        onPointerDown={(e) => {
          const { x, y } = local(e);
          (e.target as HTMLElement).setPointerCapture(e.pointerId);
          const axis = e.button === 0 && vp.current ? vp.current.gizmoAxisAt(frame, x, y) : null;
          if (axis !== null) { drag.current = { kind: "axis", x, y, axis, op: null }; return; }
          if (e.button === 0) {
            const hit = pickCube(scene, cam, x, y);
            if (hit) { p.setSel(e.shiftKey ? (p.sel.includes(hit) ? p.sel.filter((s) => s !== hit) : [...p.sel, hit]) : [hit]); drag.current = null; return; }
          }
          drag.current = { kind: "orbit", x, y };
        }}
        onPointerMove={(e) => {
          const { x, y } = local(e);
          const d = drag.current;
          if (!d) { if (vp.current && gizmo) { const a = vp.current.gizmoAxisAt(frame, x, y); if (a !== hot) setHot(a); } return; }
          if (d.kind === "orbit") { setOrbit((o) => ({ ...o, yaw: o.yaw - (x - d.x) * 0.4, pitch: o.pitch - (y - d.y) * 0.3 })); drag.current = { ...d, x, y }; return; }
          const op = opFor(d.axis!, x - d.x, y - d.y);
          d.op = op;
          p.onPreview(op);
        }}
        onPointerUp={() => { const d = drag.current; drag.current = null; if (d?.kind === "axis") { if (d.op) p.onCommit(d.op); else p.onPreview(null); } }}
        onWheel={(e) => setOrbit((o) => ({ ...o, zoom: Math.max(0.3, Math.min(5, o.zoom * (e.deltaY > 0 ? 0.9 : 1.1))) }))} />
      <div className="me-tools cys-glass" role="toolbar" aria-label="Tools">
        {TOOLS.map((t) => <button key={t.id} type="button" className={`cys-ib ${p.tool === t.id ? "on" : ""}`} aria-label={`${t.label} (${t.key})`} aria-pressed={p.tool === t.id} data-tip={`${t.label}  ${t.key}`} onClick={() => p.setTool(t.id)}><MI n={t.icon} /></button>)}
        <span className="cys-sep" />
        <button type="button" className={`cys-ib tog ${p.showBones ? "on" : ""}`} aria-label="Show bones" aria-pressed={p.showBones} data-tip="Bones" onClick={() => p.setShowBones(!p.showBones)}><MI n="bone" /></button>
        <button type="button" className={`cys-ib tog ${p.wire ? "on" : ""}`} aria-label="Wireframe" aria-pressed={p.wire} data-tip="Wire" onClick={() => p.setWire(!p.wire)}><MI n="wire" /></button>
      </div>
      <div className="me-vtop">
        <span className="cys-chip cys-soft me-pose"><MI n="bone" />{p.clip ? <>Pose <b>{p.clip}</b> at <b className="mono">{p.time.toFixed(2)} s</b></> : "Rest pose"}</span>
        <span className="sp" />
        <label className="me-snap cys-soft"><span>Snap</span><select aria-label="Move snap" value={p.snap} onChange={(e) => p.setSnap(Number(e.target.value))}>{SNAP_STEPS.map((s) => <option key={s} value={s}>{s ? `${s} u` : "off"}</option>)}</select></label>
        <label className="me-snap cys-soft"><span>Angle</span><select aria-label="Angle snap" value={p.angleSnap} onChange={(e) => p.setAngleSnap(Number(e.target.value))}>{ANGLE_SNAPS.map((s) => <option key={s} value={s}>{s ? `${s}°` : "off"}</option>)}</select></label>
        <div className="cys-seg cys-soft sm" role="group" aria-label="View">{(["persp", "front", "side"] as const).map((v) => <button key={v} type="button" className={p.view === v ? "on" : ""} onClick={() => p.setView(v)}>{v === "persp" ? "Persp" : v === "front" ? "Front" : "Side"}</button>)}</div>
      </div>
      {primary && (
        <div className="me-hud cys-soft mono">
          {cubeById(doc, primary) ? (() => { const c = cubeById(doc, primary)!; const s = [0, 1, 2].map((i) => Math.round((c.to[i] - c.from[i]) * 100) / 100); return `${boneById(doc, c.bone)?.name} · ${cubeLabel(doc, c.id)} · ${s.join(" × ")}`; })() : `${boneById(doc, primary)?.name} · pivot ${boneById(doc, primary)?.pivot.join(", ")}`}
          {p.sel.length > 1 ? ` · +${p.sel.length - 1}` : ""}
        </div>
      )}
      <div className="me-axes" aria-hidden="true"><i className="x">X</i><i className="y">Y</i><i className="z">Z</i></div>
    </div>
  );
}

// -------------------------------------------------------------------------------------------- narrow approve ----
function Narrow({ factory, doc, saved, changes, counts, budgets, readOnly, saving, seq, onApprove, onReject }: {
  factory: ModelViewportFactory; doc: ModelDoc; saved: ModelDoc; changes: string[]; counts: { errors: number; warns: number }; budgets: { id: string; label: string; used: number; max: number }[];
  readOnly: boolean; saving: boolean; seq: number | null; onApprove: () => void; onReject: () => void;
}) {
  const cv = useRef<HTMLCanvasElement>(null);
  const vp = useRef<ModelViewport | null>(null);
  const [yaw, setYaw] = useState(20);
  const [dims, setDims] = useState({ w: 320, h: 240 });
  const theme = useTheme();
  const drag = useRef<number | null>(null);
  const scene = useMemo(() => buildScene(doc), [doc]);
  useEffect(() => {
    const c = cv.current;
    if (!c) return;
    vp.current = factory(c, { maxDpr: 1.5 });
    const ro = new ResizeObserver(() => setDims({ w: Math.max(50, c.clientWidth), h: Math.max(50, c.clientHeight) }));
    ro.observe(c);
    return () => { ro.disconnect(); vp.current?.dispose(); };
  }, [factory]);
  useEffect(() => {
    const cam = fitCamera(scene, dims.w, dims.h, "persp");
    vp.current?.draw({ scene, camera: { ...cam, yaw }, selected: new Set(), selectedBone: null, showBones: false, wire: false, gizmo: null, hot: null, theme });
  });
  const dirty = serializeDoc(doc) !== serializeDoc(saved);
  return (
    <main className="me-narrow" aria-label="Model review">
      <div className="n-card cys-glass">
        <div className="n-h"><span className="me-nic"><SI n="cube" /></span><div style={{ flex: 1 }}><h1>{doc.name}</h1><p>creature · RigSpec{seq ? ` · revision ${seq}` : ""}</p></div>
          <span className={`cys-tag ${counts.errors ? "bad" : counts.warns ? "warn" : "ok"}`}>{counts.errors ? `${counts.errors} error${counts.errors > 1 ? "s" : ""}` : counts.warns ? `${counts.warns} warning${counts.warns > 1 ? "s" : ""}` : "valid"}</span></div>
        <div className="me-nprev">
          <span className="cys-tag dim ro"><SI n="eye" />read only</span>
          <canvas ref={cv} aria-label={`Turntable of ${doc.name}`} role="img" onPointerDown={(e) => { drag.current = e.clientX; (e.target as HTMLElement).setPointerCapture(e.pointerId); }} onPointerMove={(e) => { if (drag.current !== null) { setYaw((y) => y - (e.clientX - drag.current!) * 0.5); drag.current = e.clientX; } }} onPointerUp={() => { drag.current = null; }} />
          <small>Drag to turn</small>
        </div>
        <div className="n-sec"><span className="cys-eyebrow">What changed</span>
          {changes.length ? <ul>{changes.slice(0, 6).map((c, i) => <li key={i}>{c}</li>)}{changes.length > 6 && <li>and {changes.length - 6} more</li>}</ul> : <p className="cys-hint">No unsaved changes.</p>}
        </div>
        <div className="n-sec"><span className="cys-eyebrow">Budget</span>
          <BudgetPanel budgets={budgets.filter((b) => ["bones", "cubes", "clips", "spec"].includes(b.id))} />
        </div>
        <div className="n-note"><SI n="info" /><span>Checked by the RigSpec validator and the creature compiler. Not loaded on a real server yet. Editing needs a larger screen.</span></div>
        <div className="n-act">
          <button type="button" className="cys-btn" disabled={!dirty} onClick={onReject}>Reject</button>
          <button type="button" className="cys-btn primary" disabled={readOnly || !dirty || saving || counts.errors > 0} onClick={onApprove}><SI n="check" />{readOnly ? "View only" : "Approve revision"}</button>
        </div>
      </div>
    </main>
  );
}

