/* Cyrus Model Studio L2 (cuboid + bone editor). Hangs off .cys (components/cyrus/studios/studios.css tokens: one
   violet accent, cyan = the playhead only, green/amber/red = pass/warn/fail; muted X/Y/Z on the gizmo + axis triad).
   Light theme follows the portal toggle (html[data-theme=light]) through the shared tokens. Every class is me-*. */

.cys .me-ws { flex: 1; min-height: 0; display: grid; grid-template-columns: 252px minmax(0, 1fr) 336px; gap: 12px; padding: 0 14px 14px; }
.cys .me-col { display: flex; flex-direction: column; gap: 10px; min-height: 0; min-width: 0; }
.cys .me-outl { flex: 1; min-height: 0; }
.cys .me-acts { display: flex; gap: 2px; padding: 0 8px 6px; flex-wrap: wrap; }
.cys .me-tree { overflow: auto; flex: 1; min-height: 0; padding: 0 6px 8px; }
.cys .me-node { display: flex; align-items: center; gap: 4px; height: 26px; border-radius: 8px; font: 500 12px/1 var(--mono); color: var(--ink-2); padding-right: 2px; }
.cys .me-node:hover { background: rgb(var(--glow) / .06); }
.cys .me-node.on { background: rgb(var(--glow) / .14); color: var(--ink); box-shadow: inset 2px 0 0 var(--accent); }
.cys .me-node.drop { outline: 1px dashed transparent; }
.cys .me-node.drop:hover { outline-color: var(--accent-line); }
.cys .me-node .tw { width: 16px; height: 16px; display: grid; place-items: center; color: var(--faint); font-size: 11px; flex: none; }
.cys .me-node .nm { display: flex; align-items: center; gap: 6px; flex: 1; min-width: 0; height: 100%; }
.cys .me-node .nm span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cys .me-node .nm svg { color: var(--muted); font-size: 13px; flex: none; }
.cys .me-node.cube .nm svg { font-size: 12px; }
.cys .me-node .mat { display: inline-flex; align-items: center; gap: 5px; font-size: 10.5px; color: var(--muted); }
.cys .me-node .mat i { width: 8px; height: 8px; border-radius: 2px; box-shadow: 0 0 0 1px var(--line-3); }
.cys .me-node .cys-tag { padding: 2px 4px; font-size: 8.5px; }
.cys .me-node .cys-ib.sm { width: 20px; height: 20px; font-size: 12px; opacity: .65; }
.cys .me-node .cys-ib.sm.off { opacity: .3; }
.cys .me-node:hover .cys-ib.sm.off { opacity: .6; }
.cys .me-node .cys-ib.sm.on { opacity: 1; color: var(--warn); background: transparent; }

.cys .me-budget { display: grid; grid-template-columns: 1fr 1fr; gap: 8px 14px; padding: 2px 14px 14px; }
.cys .me-budget .bi { display: grid; grid-template-columns: 1fr auto; gap: 4px 6px; font-size: 11.5px; color: var(--muted); }
.cys .me-budget .bi b { font: 600 11.5px/1 var(--mono); color: var(--ink); }
.cys .me-budget .bi b small { color: var(--faint); font-weight: 400; }
.cys .me-budget .bi i { grid-column: 1 / 3; height: 3px; border-radius: 3px; background: rgb(var(--glow) / .12); overflow: hidden; }
.cys .me-budget .bi em { display: block; height: 100%; border-radius: 3px; background: var(--accent); }
.cys .me-budget .bi.warn em { background: var(--warn); } .cys .me-budget .bi.bad em { background: var(--bad); }
.cys .me-budget .bi.bad b { color: var(--bad); }

/* centre */
.cys .me-mid { gap: 10px; }
.cys .me-bar { display: flex; align-items: center; gap: 8px; height: 46px; padding: 0 8px 0 12px; border-radius: 14px; flex: none; }
.cys .me-bar .ttl { display: flex; align-items: center; gap: 8px; min-width: 0; }
.cys .me-bar .ttl b { font: 600 13.5px/1 var(--mono); }
.cys .me-bar .sp, .cys .me-cbar .sp, .cys .me-vtop .sp, .cys .me-tlh .sp { flex: 1; }
.cys .me-pick { height: 28px; width: auto; padding-right: 26px; }
.cys .me-unsaved { display: inline-flex; align-items: center; gap: 6px; font-size: 11px; color: var(--muted); white-space: nowrap; }
.cys .me-cbar { display: flex; align-items: center; gap: 8px; padding: 8px 10px; border-radius: 14px; flex: none; flex-wrap: wrap; font-size: 12.5px; }
.cys .me-cbar.cand { border: 1px dashed var(--accent-line); background: linear-gradient(90deg, rgb(var(--glow) / .1), rgb(var(--glow) / .03)); }
.cys .me-cbar .av { width: 28px; height: 28px; border-radius: 9px; display: grid; place-items: center; background: rgb(var(--glow) / .14); flex: none; }
.cys .me-cbar .av svg { width: 16px; height: 16px; }
.cys .me-cbar .tx { min-width: 0; line-height: 1.35; }
.cys .me-cbar .tx b { font-weight: 600; }
.cys .me-cbar .tx small { display: block; color: var(--muted); font-size: 11.5px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; max-width: 380px; }
.cys .me-cbar > svg { color: var(--accent-ink); font-size: 16px; }
.cys .me-part { flex-basis: 100%; margin: 4px 0 0; }
.cys .me-part li > svg { color: var(--warn); margin-top: 2px; }
.cys .me-part li > div { flex: 1; }

.cys .me-stage { position: relative; flex: 1; min-height: 220px; border-radius: var(--r-lg); overflow: hidden; border: 1px solid var(--line);
  background: radial-gradient(70% 60% at 50% 45%, rgb(var(--glow) / .1), transparent 70%), radial-gradient(circle, rgb(var(--glow) / .11) 1px, transparent 1.2px) 0 0 / 22px 22px, var(--well); }
html[data-theme="light"] .cyrus-root .cys .me-stage { background: radial-gradient(70% 60% at 50% 45%, rgb(124 58 237 / .06), transparent 70%), radial-gradient(circle, rgb(var(--glow) / .14) 1px, transparent 1.2px) 0 0 / 22px 22px, #f4f1fb; }
.cys .me-cv { position: absolute; inset: 0; width: 100%; height: 100%; touch-action: none; cursor: crosshair; }
.cys .me-tools { position: absolute; left: 10px; top: 50%; transform: translateY(-50%); display: flex; flex-direction: column; gap: 2px; padding: 5px; border-radius: 14px; z-index: 2; }
.cys .me-tools .cys-ib { width: 32px; height: 32px; font-size: 16px; position: relative; }
.cys .me-tools .cys-ib.on { color: var(--on-accent); background: var(--accent-solid); box-shadow: 0 6px 16px -8px rgb(124 77 255 / .9); }
.cys .me-tools .cys-ib.tog.on { color: var(--accent-ink); background: var(--accent-soft); box-shadow: inset 0 0 0 1px var(--accent-line); }
.cys .me-tools .cys-sep { width: 20px; margin: 4px auto; }
.cys .me-tools .cys-ib[data-tip]:hover::after { content: attr(data-tip); position: absolute; left: 40px; top: 50%; transform: translateY(-50%); white-space: pre; padding: 5px 8px; border-radius: 7px; background: var(--solid); box-shadow: var(--pop-shadow); font: 500 11.5px/1 var(--font-inter), sans-serif; color: var(--ink); z-index: 4; }
.cys .me-vtop { position: absolute; top: 10px; left: 60px; right: 10px; display: flex; align-items: center; gap: 6px; z-index: 2; pointer-events: none; }
.cys .me-vtop > * { pointer-events: auto; }
.cys .me-pose { height: 30px; font: 500 11.5px/1 var(--mono); color: var(--muted); gap: 6px; }
.cys .me-pose b { color: var(--ink); font-weight: 600; }
.cys .me-snap { display: inline-flex; align-items: center; gap: 6px; height: 30px; padding: 0 4px 0 9px; border-radius: 10px; font-size: 11px; color: var(--muted); }
.cys .me-snap select { border: 0; background: transparent; font: 500 11.5px/1 var(--mono); color: var(--ink); outline: none; }
.cys .me-snap select option { background: var(--solid); }
.cys .me-hud { position: absolute; right: 10px; bottom: 10px; padding: 6px 10px; border-radius: 10px; font-size: 11px; color: var(--ink-2); z-index: 2; max-width: 60%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cys .me-axes { position: absolute; left: 12px; bottom: 10px; display: flex; gap: 6px; font: 600 9.5px/1 var(--mono); z-index: 2; }
.cys .me-axes i { font-style: normal; } .cys .me-axes .x { color: #d0605e; } .cys .me-axes .y { color: #5fae6e; } .cys .me-axes .z { color: #5f86d6; }

/* timeline */
.cys .me-tl { flex: none; height: 182px; overflow: hidden; }
.cys .me-tlh { display: flex; align-items: center; gap: 8px; padding: 8px 10px 6px; }
.cys .me-tlh > .cys-ib:first-child { color: var(--on-accent); background: var(--accent-solid); width: 28px; height: 28px; }
.cys .me-tlh > .cys-ib:first-child:disabled { opacity: .4; }
.cys .me-clips { overflow-x: auto; max-width: 52%; }
.cys .me-time { font-size: 11.5px; color: var(--muted); white-space: nowrap; }
.cys .me-time b { color: var(--cyan); font-weight: 600; }
.cys .me-tlb { display: grid; grid-template-columns: 150px minmax(0, 1fr); border-top: 1px solid var(--line); height: calc(100% - 44px); overflow-y: auto; }
.cys .me-tracks { padding-top: 20px; border-right: 1px solid var(--line); }
.cys .me-trk { height: 24px; display: flex; align-items: center; justify-content: space-between; padding: 0 10px; font: 400 11px/1 var(--mono); color: var(--muted); border-bottom: 1px solid var(--line); }
.cys .me-trk b { color: var(--ink-2); font-weight: 500; }
.cys .me-trk.on { background: rgb(var(--glow) / .08); } .cys .me-trk.on b { color: var(--ink); }
.cys .me-trk .n { font-size: 10px; color: var(--faint); }
.cys .me-lanes { position: relative; margin: 0 14px; cursor: ew-resize; touch-action: none; }
.cys .me-ruler { position: relative; height: 20px; }
.cys .me-ruler span { position: absolute; top: 5px; transform: translateX(-50%); font: 400 9.5px/1 var(--mono); color: var(--faint); }
.cys .me-lane { position: relative; height: 24px; border-bottom: 1px solid var(--line); }
.cys .me-lane svg { position: absolute; inset: 4px 0; width: 100%; height: 16px; fill: none; stroke: var(--accent-line); stroke-width: .6; vector-effect: non-scaling-stroke; }
.cys .me-key { position: absolute; top: 50%; width: 10px; height: 10px; transform: translate(-50%, -50%) rotate(45deg); background: var(--ink-2); border-radius: 2px; box-shadow: 0 0 0 2px var(--surface); cursor: grab; }
.cys .me-key.linear { border-radius: 0; }
.cys .me-key.on { background: var(--accent); box-shadow: 0 0 0 2px var(--surface), 0 0 10px rgb(var(--glow) / .8); }
.cys .me-head { position: absolute; top: 0; bottom: 0; width: 2px; margin-left: -1px; background: var(--cyan); box-shadow: 0 0 8px var(--cyan); pointer-events: none; }
.cys .me-head::before { content: ""; position: absolute; top: 0; left: -4px; border: 5px solid transparent; border-top-color: var(--cyan); }

/* inspector */
.cys .me-insp { min-height: 0; }
.cys .me-insp .cys-tab .cys-tag { padding: 2px 5px; font-size: 8.5px; }
.cys .me-ib { flex: 1; min-height: 0; overflow: auto; display: flex; flex-direction: column; }
.cys .me-sec { padding: 10px 12px 8px; border-bottom: 1px solid var(--line); display: flex; flex-direction: column; gap: 6px; }
.cys .me-sec.grow { flex: 1; border-bottom: 0; }
.cys .me-sh { display: flex; align-items: center; gap: 8px; min-height: 18px; }
.cys .me-sh .cys-eyebrow { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cys .me-sh .cys-eyebrow.r { flex: none; text-align: right; }
.cys .me-row { display: flex; align-items: center; gap: 8px; min-height: 30px; font-size: 12px; color: var(--muted); }
