/* Cyrus Model Studio L2 (cuboid + bone editor). Hangs off .cys (components/cyrus/studios/studios.css tokens: one
   violet accent, cyan = the playhead only, green/amber/red = pass/warn/fail; muted X/Y/Z on the gizmo + axis triad).
   Light theme follows the portal toggle (html[data-theme=light]) through the shared tokens. Every class is me-*. */

.cys .me-ws { flex: 1; min-height: 0; display: grid; grid-template-columns: 252px minmax(0, 1fr) 336px; gap: 12px; padding: 0 14px 14px; }
.cys .me-col { display: flex; flex-direction: column; gap: 10px; min-height: 0; min-width: 0; }
.cys .me-outl { flex: 1; min-height: 0; }
.cys .me-acts { display: flex; gap: 2px; padding: 0 8px 6px; flex-wrap: wrap; }
.cys .me-tree { overflow: auto; flex: 1; min-height: 0; padding: 0 6px 8px; }
.cys .me-node { display: flex; align-items: center; gap: 4px; height: 26px; border-radius: 8px; font: 500 12px/1 var(--mono); color: var(--ink-2); padding-right: 2px; }
.cys .me-node:hover { background: rgb(var(--glow) / .06); }
.cys .me-node.on { background: rgb(var(--glow) / .14); color: var(--ink); box-shadow: inset 2px 0 0 var(--accent); }
.cys .me-node.drop { outline: 1px dashed transparent; }
.cys .me-node.drop:hover { outline-color: var(--accent-line); }
.cys .me-node .tw { width: 16px; height: 16px; display: grid; place-items: center; color: var(--faint); font-size: 11px; flex: none; }
.cys .me-node .nm { display: flex; align-items: center; gap: 6px; flex: 1; min-width: 0; height: 100%; }
.cys .me-node .nm span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cys .me-node .nm svg { color: var(--muted); font-size: 13px; flex: none; }
.cys .me-node.cube .nm svg { font-size: 12px; }
.cys .me-node .mat { display: inline-flex; align-items: center; gap: 5px; font-size: 10.5px; color: var(--muted); }
.cys .me-node .mat i { width: 8px; height: 8px; border-radius: 2px; box-shadow: 0 0 0 1px var(--line-3); }
.cys .me-node .cys-tag { padding: 2px 4px; font-size: 8.5px; }
.cys .me-node .cys-ib.sm { width: 20px; height: 20px; font-size: 12px; opacity: .65; }
.cys .me-node .cys-ib.sm.off { opacity: .3; }
.cys .me-node:hover .cys-ib.sm.off { opacity: .6; }
.cys .me-node .cys-ib.sm.on { opacity: 1; color: var(--warn); background: transparent; }

.cys .me-budget { display: grid; grid-template-columns: 1fr 1fr; gap: 8px 14px; padding: 2px 14px 14px; }
.cys .me-budget .bi { display: grid; grid-template-columns: 1fr auto; gap: 4px 6px; font-size: 11.5px; color: var(--muted); }
.cys .me-budget .bi b { font: 600 11.5px/1 var(--mono); color: var(--ink); }
.cys .me-budget .bi b small { color: var(--faint); font-weight: 400; }
.cys .me-budget .bi i { grid-column: 1 / 3; height: 3px; border-radius: 3px; background: rgb(var(--glow) / .12); overflow: hidden; }
.cys .me-budget .bi em { display: block; height: 100%; border-radius: 3px; background: var(--accent); }
.cys .me-budget .bi.warn em { background: var(--warn); } .cys .me-budget .bi.bad em { background: var(--bad); }
.cys .me-budget .bi.bad b { color: var(--bad); }

