.cys .me-mid { gap: 10px; }
.cys .me-bar { display: flex; align-items: center; gap: 8px; height: 46px; padding: 0 8px 0 12px; border-radius: 14px; flex: none; }
.cys .me-bar .ttl { display: flex; align-items: center; gap: 8px; min-width: 0; }
.cys .me-bar .ttl b { font: 600 13.5px/1 var(--mono); }
.cys .me-bar .sp, .cys .me-cbar .sp, .cys .me-vtop .sp, .cys .me-tlh .sp { flex: 1; }
.cys .me-pick { height: 28px; width: auto; padding-right: 26px; }
.cys .me-unsaved { display: inline-flex; align-items: center; gap: 6px; font-size: 11px; color: var(--muted); white-space: nowrap; }
.cys .me-cbar { display: flex; align-items: center; gap: 8px; padding: 8px 10px; border-radius: 14px; flex: none; flex-wrap: wrap; font-size: 12.5px; }
