.cys .me-cbar .av { width: 28px; height: 28px; border-radius: 9px; display: grid; place-items: center; background: rgb(var(--glow) / .14); flex: none; }
.cys .me-cbar .av svg { width: 16px; height: 16px; }
.cys .me-cbar .tx { min-width: 0; line-height: 1.35; }
.cys .me-cbar .tx b { font-weight: 600; }
.cys .me-cbar .tx small { display: block; color: var(--muted); font-size: 11.5px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; max-width: 380px; }
.cys .me-cbar > svg { color: var(--accent-ink); font-size: 16px; }
.cys .me-part { flex-basis: 100%; margin: 4px 0 0; }
.cys .me-part li > svg { color: var(--warn); margin-top: 2px; }
.cys .me-part li > div { flex: 1; }

.cys .me-stage { position: relative; flex: 1; min-height: 220px; border-radius: var(--r-lg); overflow: hidden; border: 1px solid var(--line);
  background: radial-gradient(70% 60% at 50% 45%, rgb(var(--glow) / .1), transparent 70%), radial-gradient(circle, rgb(var(--glow) / .11) 1px, transparent 1.2px) 0 0 / 22px 22px, var(--well); }
html[data-theme="light"] .cyrus-root .cys .me-stage { background: radial-gradient(70% 60% at 50% 45%, rgb(124 58 237 / .06), transparent 70%), radial-gradient(circle, rgb(var(--glow) / .14) 1px, transparent 1.2px) 0 0 / 22px 22px, #f4f1fb; }
.cys .me-cv { position: absolute; inset: 0; width: 100%; height: 100%; touch-action: none; cursor: crosshair; }
.cys .me-tools { position: absolute; left: 10px; top: 50%; transform: translateY(-50%); display: flex; flex-direction: column; gap: 2px; padding: 5px; border-radius: 14px; z-index: 2; }
