// Cyrus Model Studio L2: add a generated creature (the banshee RigSpec fixture, compiled by the real creature
// compiler) to every "Banshee Hunt" project scripts/cyrus/studio-fixtures.ts seeded, so the model editor has something
// to open. Run AFTER studio-fixtures. Refuses anything but devhost's wt_* throwaway database on 127.0.0.1:5433.
//   devhost run -- npx tsx scripts/cyrus/model-editor-fixtures.ts .studio-tokens.json
import fs from "node:fs";
import path from "node:path";
import { db } from "../../lib/db";
import { addRevision, recordAsset } from "../../lib/cyrus/engine-core/store";
import { checkReturnedCreature, RIG_SPEC_MIME } from "../../lib/cyrus/creature/portal";
import { COMPILER_VERSION } from "../../lib/cyrus/creature/compile";

const url = process.env.DATABASE_URL ?? "";
if (!/@127\.0\.0\.1:5433\/wt_[a-z0-9_]+/.test(url)) { console.error("refusing: not the devhost throwaway database"); process.exit(2); }

(async () => {
  const tokens = JSON.parse(fs.readFileSync(process.argv[2] ?? ".studio-tokens.json", "utf8")) as Record<string, { projectId?: string }>;
  const raw = JSON.parse(fs.readFileSync(path.join(__dirname, "../../test/fixtures/cyrus-creatures/banshee.json"), "utf8"));
  for (const [who, t] of Object.entries(tokens)) {
    if (!t || typeof t !== "object" || !t.projectId) continue;
    const project = await db.cyrusProject.findUniqueOrThrow({ where: { id: t.projectId } });
    const spec = { ...raw, sounds: Object.fromEntries(Object.entries(raw.sounds as Record<string, string>).map(([k, v]) => [k, v.replace(/^nx_[a-z0-9]{8}/, project.namespace)])) };
    const c = checkReturnedCreature({ name: "banshee", spec }, project.namespace);
    if (!c.ok) throw new Error(c.reason);
    const head = await db.cyrusRevision.findFirst({ where: { projectId: project.id }, orderBy: { seq: "desc" } });
    const prev = (head?.manifest ?? []) as { path: string; sha256: string; role: string }[];
    const rev = await addRevision(project.id, {
      kind: "generated", status: "passed", expectedHeadId: head?.id ?? null, message: "creature build (fixture)",
      manifest: [...prev, { path: "assets/creatures/banshee.json", sha256: c.specSha256, role: "asset" }, { path: `bettermodel/${c.key}.bbmodel`, sha256: c.compiled.bbmodelSha256, role: "asset" }],
    });
    await recordAsset(project.id, {
      revisionId: rev.id, assetKey: "banshee", kind: "model", sha256: c.specSha256, size: Buffer.byteLength(c.canonical), origin: "generated", mime: RIG_SPEC_MIME, path: "assets/creatures/banshee.json",
      provenance: { generator: "cyrus-rigspec", compiler: COMPILER_VERSION, engine: "bettermodel@3.5.0", spec: c.input, modelKey: c.key, bbmodelSha256: c.compiled.bbmodelSha256, pngSha256: c.compiled.pngSha256, skinSize: c.compiled.layout.size, stats: c.compiled.stats, quality: c.quality, warnings: c.warnings, kept: false },
    });
    console.error(`model fixture: ${who} ${project.id} banshee`);
  }
  await db.$disconnect();
})().catch(async (e) => { console.error(e); await db.$disconnect(); process.exit(1); });

