//   devhost env set CYRUS_MODEL_EDITOR_DEV=1 ; devhost env set CYRUS_MODEL_EDITOR_DRAFTS=memory
//   devhost dev
//   devhost run -- node test/e2e/cyrus-model-editor.shots.mjs .studio-tokens.json .model-editor-shots
//   devhost pull .model-editor-shots /root/agent-notes/cyrus-designs/impl-shots   (files are prefixed editor-)
import { chromium } from "playwright";
import { mkdirSync, readFileSync } from "node:fs";

const [, , tokFile, out = ".model-editor-shots"] = process.argv;
const T = JSON.parse(readFileSync(tokFile, "utf8"));
const BASE = process.env.BASE ?? `http://127.0.0.1:${process.env.PORT}`;
mkdirSync(out, { recursive: true });
const browser = await chromium.launch();
let failures = 0;

async function session(who, { theme = "dark", narrow = false, q = "" } = {}) {
  const c = await browser.newContext({ viewport: narrow ? { width: 390, height: 844 } : { width: 1440, height: 900 }, deviceScaleFactor: narrow ? 2 : 1, colorScheme: theme, reducedMotion: "reduce" });
  await c.addCookies([{ name: T.cookie, value: T[who].token, url: BASE }, { name: "nxeon_cookie_consent", value: "all", url: BASE }]);
  const page = await c.newPage();
  await page.addInitScript((t) => { try { localStorage.setItem("nx-theme", t); localStorage.setItem("nx-tour-dismissed", "1"); localStorage.setItem("cyrus-sound", "off"); } catch {} }, theme);
  const errs = [];
  page.on("pageerror", (e) => errs.push(String(e).slice(0, 300)));
  page.on("console", (m) => { if (m.type() === "error" && !/favicon|Failed to load resource.*(404|503)/.test(m.text())) errs.push("console: " + m.text().slice(0, 200)); });
  await page.goto(`${BASE}/dashboard/cyrus/${T[who].buildId}/studio/model-editor${q}`, { waitUntil: "networkidle", timeout: 180000 }).catch((e) => errs.push("goto " + e));
  for (const label of ["Got it", "Skip", "Not now", "Skip tour", "Maybe later", "Accept all"]) { const b = page.getByRole("button", { name: label, exact: true }); if (await b.count().catch(() => 0)) await b.first().click({ timeout: 800 }).catch(() => {}); }
  await page.waitForSelector(narrow ? ".me-narrow canvas" : ".me-ws .me-cv", { timeout: 60000 }).catch((e) => errs.push("wait " + String(e).slice(0, 120)));
  await page.waitForTimeout(800);
  return { c, page, errs };
}
const node = (page, label, kind = "bone") => page.locator(`.me-node.${kind}`).filter({ hasText: new RegExp(`^${label}`) }).first().locator(".nm");
async function done(name, s, info = "") {
  await s.page.screenshot({ path: `${out}/${name}.png` });
  if (s.errs.length) failures++;
  console.log(`${out}/${name}.png`, info, s.errs.length ? "ERR " + s.errs.join(" | ").slice(0, 600) : "");
  await s.c.close();
}
async function pickHair(page) {
  await node(page, "hair").click();
  await page.locator(".me-node.cube").filter({ hasText: "cube 0" }).nth(6).locator(".nm").click().catch(() => {});
}

// 1. desktop dark: hair cube selected, idle scrubbed
{
  const s = await session("all");
  try {
    await node(s.page, "head").click();
    await s.page.locator(".me-lanes").click({ position: { x: 160, y: 40 } });
    await s.page.locator(".me-node.cube").nth(6).locator(".nm").click();
  } catch (e) { s.errs.push("act " + String(e).slice(0, 200)); }
  await done("editor-dark", s);
}
// 2. desktop light
{
  const s = await session("all", { theme: "light" });
  try { await s.page.locator(".me-node.cube").nth(6).locator(".nm").click(); } catch (e) { s.errs.push("act " + String(e).slice(0, 200)); }
  await done("editor-light", s);
}
// 3. a human edit + a (fake, deterministic) Cyrus candidate with Apply part open -> overlap list
{
  const s = await session("all", { q: "?fakeCandidate=1" });
  try {
    await node(s.page, "hair").click();
    await s.page.locator(".me-node.cube").filter({ hasText: "cube 0" }).nth(0).locator(".nm").click();
    const hairCube = s.page.locator(".me-node.cube").nth(6).locator(".nm");
    await hairCube.click();
    const fromY = s.page.getByLabel("From y");
    await fromY.fill("27"); await fromY.press("Enter");
    await s.page.getByLabel("Ask Cyrus to change this model").fill("make the hair longer and the sway wider");
    await s.page.getByRole("button", { name: "Send" }).click();
    await s.page.getByRole("button", { name: "Apply part" }).click();
  } catch (e) { s.errs.push("act " + String(e).slice(0, 200)); }
  const bar = await s.page.locator('[data-testid="model-candidate"]').innerText().catch(() => "");
  await done("editor-dark-candidate", s, JSON.stringify(bar.slice(0, 160)));
}
// 4. checks tab after an invalid edit (cube rotation is not shippable on Minecraft)
{
  const s = await session("all");
  try {
    await s.page.locator(".me-node.cube").nth(0).locator(".nm").click();
    await s.page.locator(".me-adv summary").click();
    const rz = s.page.getByLabel("Cube rotation z");
    await rz.fill("22.5"); await rz.press("Enter");
    await s.page.getByRole("tab", { name: /Checks/ }).click();
  } catch (e) { s.errs.push("act " + String(e).slice(0, 200)); }
  await done("editor-dark-checks", s);
}
// 5. keyframe tab + a real SAVE through the API into the throwaway DB
{
  const s = await session("all");
  let toast = "";
  try {
    await node(s.page, "arm_r").click();
    await s.page.locator(".me-lanes").click({ position: { x: 300, y: 40 } });
    await s.page.getByRole("button", { name: "Key", exact: true }).click();
    await s.page.getByRole("button", { name: "Save revision" }).click();
    toast = await s.page.locator(".cys-toast").innerText({ timeout: 20000 }).catch(() => "");
    if (!/Saved as revision/.test(toast)) s.errs.push("save toast: " + toast);
  } catch (e) { s.errs.push("act " + String(e).slice(0, 200)); }
  await done("editor-dark-keyframe-saved", s, JSON.stringify(toast));
}
// 6. Saka: view only (the API refuses edits too)
{
  const s = await session("saka");
  try { await s.page.locator(".me-node.cube").nth(6).locator(".nm").click(); } catch (e) { s.errs.push("act " + String(e).slice(0, 200)); }
  await done("editor-saka-viewonly", s);
}
// 7/8. phone: read-only turntable + approve (dark, light)
for (const theme of ["dark", "light"]) {
  const s = await session("all", { theme, narrow: true });
  await done(`editor-phone-${theme}`, s);
}
await browser.close();
console.log(failures ? `${failures} shots with errors` : "all shots clean");
EOF
