1	// Cyrus Model Studio L2: add a generated creature (the banshee RigSpec fixture, compiled by the real creature
2	// compiler) to every "Banshee Hunt" project scripts/cyrus/studio-fixtures.ts seeded, so the model editor has something
3	// to open. Run AFTER studio-fixtures. Refuses anything but devhost's wt_* throwaway database on 127.0.0.1:5433.
4	//   devhost run -- npx tsx scripts/cyrus/model-editor-fixtures.ts .studio-tokens.json
5	import fs from "node:fs";
6	import path from "node:path";
7	import { db } from "../../lib/db";
8	import { addRevision, manifestOf, recordAsset } from "../../lib/cyrus/engine-core/store";
9	import { checkReturnedCreature, RIG_SPEC_MIME } from "../../lib/cyrus/creature/portal";
10	import { COMPILER_VERSION } from "../../lib/cyrus/creature/compile";
11	
12	const url = process.env.DATABASE_URL ?? "";
13	if (!/@127\.0\.0\.1:5433\/wt_[a-z0-9_]+/.test(url)) { console.error("refusing: not the devhost throwaway database"); process.exit(2); }
14	
15	(async () => {
16	  const tokens = JSON.parse(fs.readFileSync(process.argv[2] ?? ".studio-tokens.json", "utf8")) as Record<string, { projectId?: string }>;
17	  const raw = JSON.parse(fs.readFileSync(path.join(__dirname, "../../test/fixtures/cyrus-creatures/banshee.json"), "utf8"));
18	  for (const [who, t] of Object.entries(tokens)) {
19	    if (!t || typeof t !== "object" || !t.projectId) continue;
20	    const project = await db.cyrusProject.findUniqueOrThrow({ where: { id: t.projectId } });
21	    const spec = { ...raw, sounds: Object.fromEntries(Object.entries(raw.sounds as Record<string, string>).map(([k, v]) => [k, v.replace(/^nx_[a-z0-9]{8}/, project.namespace)])) };
22	    const c = checkReturnedCreature({ name: "banshee", spec }, project.namespace);
23	    if (!c.ok) throw new Error(c.reason);
24	    const head = await db.cyrusRevision.findFirst({ where: { projectId: project.id }, orderBy: { seq: "desc" } });
25	    const prev = head ? manifestOf(head) : [];
26	    const rev = await addRevision(project.id, {
27	      kind: "generated", status: "passed", expectedHeadId: head?.id ?? null, message: "creature build (fixture)",
28	      manifest: [...prev, { path: "assets/creatures/banshee.json", sha256: c.specSha256, role: "asset" }, { path: `bettermodel/${c.key}.bbmodel`, sha256: c.compiled.bbmodelSha256, role: "asset" }],
29	    });
30	    await recordAsset(project.id, {
31	      revisionId: rev.id, assetKey: "banshee", kind: "model", sha256: c.specSha256, size: Buffer.byteLength(c.canonical), origin: "generated", mime: RIG_SPEC_MIME, path: "assets/creatures/banshee.json",
32	      provenance: { generator: "cyrus-rigspec", compiler: COMPILER_VERSION, engine: "bettermodel@3.5.0", spec: c.input, modelKey: c.key, bbmodelSha256: c.compiled.bbmodelSha256, pngSha256: c.compiled.pngSha256, skinSize: c.compiled.layout.size, stats: c.compiled.stats, quality: c.quality, warnings: c.warnings, kept: false },
33	    });

