// Cyrus TIMELINE core: the GAME-NEUTRAL keyframe / clip document model. Pure types + a kind registry, client-safe.
// Owner decision 2026-10-10: motion, animation and effects are a foundational, game-agnostic part of Cyrus (a banshee
// walk cycle, a gun's cock/fire/reload, a car's doors + a character getting in, explosions, fire, water), playable
// live in the studios and tied to the texture and sound studios. A later "Motion core" (EffectSpec ...) builds on
// these types, so: no game assumptions here (no Minecraft, no RigSpec, no BetterModel); game specifics live in
// exporters/adapters (../rigspec.ts, ../export/*).
//
// Time: a clip has a duration in SECONDS (`length`); every key / event / cue sits at a NORMALISED time `t` in 0..1 of
// the clip, so retiming a clip never moves its keys out of range. One deterministic sampler (./sampler.ts) evaluates
// every track kind at a time; ./clock.ts is the playback API (play, pause, scrub, loop, speed) a viewport drives.
//
// Track kinds: each track has a typed `kind`. "transform" (bone / node rotation, position, scale) and the clip's own
// `events` are IMPLEMENTED and stored in ModelDoc v1. The other kinds are declared EXTENSION POINTS: their shapes are
// fixed here so studios and the Motion core can target them, the sampler already evaluates them, but ModelDoc v1 does
// not store them yet and no exporter writes them (TRACK_KINDS says which).

export type Vec3 = [number, number, number];
export type Ease = "linear" | "smooth";
/** A key on a vector channel: normalised time t (0..1), value, easing INTO this key from the previous one. */
export type VecKey = { id: string; t: number; v: Vec3; ease: Ease };
/** A key on a scalar channel (light intensity, a material value ...). */
export type ScalarKey = { id: string; t: number; v: number; ease: Ease };
/** A seamless sine track: amplitude per axis, offset, whole cycles over the clip, start phase 0..1. */
export type Wave = { amp: Vec3; offset?: Vec3; cycles: number; phase: number };
export type TransformChannel = "rotation" | "position" | "scale";

/** Bone / node transform. `bone` is the target node id (a bone in a creature, a node in any rig). kind omitted = transform. */
export type TransformTrack = { kind?: "transform"; bone: string; channel: TransformChannel; wave?: Wave; keys?: VecKey[] };

// ---- extension points (shapes fixed, not stored in ModelDoc v1 yet) ----
/** Play a sound at a time (ties into the Sound Studio: `sound` is a Cyrus sound key / library ref). */
export type SoundCue = { id: string; t: number; sound: string; volume?: number; pitch?: number };
export type SoundCueTrack = { kind: "sound_cue"; target: string | null; cues: SoundCue[] };
/** Spawn a particle effect (an EffectSpec id once the Motion core exists) at a node. */
export type ParticleBurst = { id: string; t: number; effect: string; count?: number };
export type ParticleTrack = { kind: "particle"; target: string | null; bursts: ParticleBurst[] };
/** Animate a light on a node (intensity; colour later). */
export type LightTrack = { kind: "light"; target: string; property: "intensity" | "range"; keys: ScalarKey[] };
/** Animate a material value (emissive strength, UV offset ...; ties into the Texture Studio). */
export type MaterialTrack = { kind: "material"; target: string; property: string; keys: ScalarKey[] };
/** Drive a state machine (a door open/closed, a gun idle/aim/reload, a car seat occupied). */
export type StateChange = { id: string; t: number; state: string };
export type StateTrack = { kind: "state"; machine: string; changes: StateChange[] };

export type Track = TransformTrack | SoundCueTrack | ParticleTrack | LightTrack | MaterialTrack | StateTrack;
export type TrackKind = NonNullable<Track["kind"]>;

/** A named moment in a clip (a footstep, the muzzle flash, "door_open"): fired by the clock, read by game adapters. */
export type ClipEvent = { id: string; t: number; name: string; data?: Record<string, string | number | boolean> };

/** A clip: name, duration (seconds), loop, tracks of any kind, events at times. */
export type Clip<T extends Track = Track> = { name: string; length: number; loop: boolean; tracks: T[]; events?: ClipEvent[] };

export const TRACK_KINDS: Readonly<Record<TrackKind, { label: string; status: "implemented" | "planned"; instant: boolean }>> = {
  transform: { label: "Bone / node transform", status: "implemented", instant: false },
  sound_cue: { label: "Sound cue", status: "planned", instant: true },
  particle: { label: "Particle burst", status: "planned", instant: true },
  light: { label: "Light", status: "planned", instant: false },
  material: { label: "Material value", status: "planned", instant: false },
  state: { label: "State machine", status: "planned", instant: true },
};
export const kindOf = (t: Track): TrackKind => t.kind ?? "transform";
export const isTransform = (t: Track): t is TransformTrack => kindOf(t) === "transform";
export const restValue = (ch: TransformChannel): Vec3 => (ch === "scale" ? [1, 1, 1] : [0, 0, 0]);

