// Cyrus timeline: the ONE deterministic sampler over time, for every track kind. Pure + client-safe.
// Same inputs -> same numbers (no clocks, no randomness). Continuous kinds (transform, light, material) are evaluated
// AT a time; instant kinds (clip events, sound cues, particle bursts, state changes) are collected BETWEEN two times
// (firedBetween), which is what a clock tick, a scrub or an exporter baking a timeline needs.
// The transform maths equals the creature compiler's (lib/cyrus/creature/compile.ts sampleTrack; tested).
import { isTransform, kindOf, type Clip, type ClipEvent, type ScalarKey, type TrackKind, type TransformTrack, type Vec3 } from "./types";

const smooth = (t: number) => t * t * (3 - 2 * t);
const clamp01 = (u: number) => Math.max(0, Math.min(1, u));

/** Index pair + eased fraction for normalised time u over keys sorted by t. */
function segment<K extends { t: number; ease: "linear" | "smooth" }>(ks: readonly K[], u: number): { a: K; b: K; e: number } {
  let i = 0;
  while (i < ks.length - 2 && u > ks[i + 1].t) i++;
  const a = ks[i], b = ks[i + 1];
  const f = b.t === a.t ? 1 : clamp01((u - a.t) / (b.t - a.t));
  return { a, b, e: b.ease === "linear" ? f : smooth(f) };
}

/** A transform track at clip time `time` (seconds): rotation/position offsets from rest, scale as a factor. */
export function sampleTransform(t: Pick<TransformTrack, "channel" | "wave" | "keys">, clip: { length: number }, time: number): Vec3 {
  const base = t.channel === "scale" ? 1 : 0;
  if (t.wave) {
    const w = t.wave;
    const a = 2 * Math.PI * ((time / clip.length) * w.cycles + w.phase);
    return [0, 1, 2].map((k) => base + (w.offset?.[k] ?? 0) + w.amp[k] * Math.sin(a)) as Vec3;
  }
  const ks = t.keys ?? [];
  if (!ks.length) return [base, base, base];
  if (ks.length === 1) return [...ks[0].v] as Vec3;
  const { a, b, e } = segment(ks, clamp01(time / clip.length));
  return [0, 1, 2].map((k) => a.v[k] + (b.v[k] - a.v[k]) * e) as Vec3;
}

/** A scalar track (light / material) at clip time `time`. */
export function sampleScalar(ks: readonly ScalarKey[], clip: { length: number }, time: number, fallback = 0): number {
  if (!ks.length) return fallback;
  if (ks.length === 1) return ks[0].v;
  const { a, b, e } = segment(ks, clamp01(time / clip.length));
  return a.v + (b.v - a.v) * e;
}

export type NodeSample = { rotation?: Vec3; position?: Vec3; scale?: Vec3 };
export type ClipSample = {
  /** transform offsets per target node (rotation adds to the rest rotation; position adds; scale multiplies) */
  nodes: Map<string, NodeSample>;
  /** continuous scalar channels "<kind>:<target>:<property>" (light / material extension tracks) */
  scalars: Map<string, number>;
  /** the current state per machine (the last change at or before `time`) */
  states: Map<string, string>;
};

/** Evaluate every continuous track of a clip at `time` seconds. */
export function sampleClip(clip: Clip, time: number): ClipSample {
  const out: ClipSample = { nodes: new Map(), scalars: new Map(), states: new Map() };
  const u = clamp01(time / clip.length);
  for (const tr of clip.tracks) {
    if (isTransform(tr)) {
      const n = out.nodes.get(tr.bone) ?? {};
      n[tr.channel] = sampleTransform(tr, clip, time);
      out.nodes.set(tr.bone, n);
    } else if (tr.kind === "light" || tr.kind === "material") {
      out.scalars.set(`${tr.kind}:${tr.target}:${tr.property}`, sampleScalar(tr.keys, clip, time));
    } else if (tr.kind === "state") {
      const last = [...tr.changes].sort((a, b) => a.t - b.t || (a.id < b.id ? -1 : 1)).filter((c) => c.t <= u + 1e-9).at(-1);
      if (last) out.states.set(tr.machine, last.state);
    }
  }
  return out;
}

export type Fired = { kind: "event" | Exclude<TrackKind, "transform" | "light" | "material">; id: string; t: number; name: string; target: string | null; cycle: number };

/** Every instant in a clip (events + cue / burst / state tracks), sorted by time then id. */
export function instants(clip: Clip): Omit<Fired, "cycle">[] {
  const out: Omit<Fired, "cycle">[] = (clip.events ?? []).map((e: ClipEvent) => ({ kind: "event" as const, id: e.id, t: e.t, name: e.name, target: null }));
  for (const tr of clip.tracks) {
    const k = kindOf(tr);
    if (tr.kind === "sound_cue") for (const c of tr.cues) out.push({ kind: "sound_cue", id: c.id, t: c.t, name: c.sound, target: tr.target });
    else if (tr.kind === "particle") for (const b of tr.bursts) out.push({ kind: "particle", id: b.id, t: b.t, name: b.effect, target: tr.target });
    else if (tr.kind === "state") for (const c of tr.changes) out.push({ kind: "state", id: c.id, t: c.t, name: c.state, target: tr.machine });
    void k;
  }
  return out.sort((a, b) => a.t - b.t || (a.id < b.id ? -1 : 1));
}

/**
 * Instants crossed going from clip time `from` to `to` (seconds, `to` >= `from` in playback order; for a looping clip
 * `to` may exceed the length, wrapping as many times as needed). Half-open (from, to], except that a playback that
 * starts at exactly 0 fires the instants at t 0 (pass `includeStart`). Deterministic order: cycle, time, id.
 */
export function firedBetween(clip: Clip, from: number, to: number, o: { includeStart?: boolean } = {}): Fired[] {
  const list = instants(clip);
  if (!list.length || to < from) return [];
  const L = clip.length;
  const out: Fired[] = [];
  const startCycle = Math.floor(from / L), endCycle = clip.loop ? Math.floor(to / L) : 0;
  for (let cyc = clip.loop ? startCycle : 0; cyc <= endCycle; cyc++) {
    for (const it of list) {
      const at = (clip.loop ? cyc * L : 0) + it.t * L;
      const after = o.includeStart && cyc === startCycle ? at >= from - 1e-9 : at > from + 1e-9;
      if (after && at <= to + 1e-9) out.push({ ...it, cycle: cyc });
    }
  }
  return out;
}

