// Cyrus timeline core (game-neutral): kind registry, the one deterministic sampler (transform == the creature
// compiler's), instants fired between times (wrap-aware), the playback clock (play, pause, scrub, loop, speed), and
// the editor's clip events (ops, RigSpec drop note, merge).
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { checkRigSpec } from "../lib/cyrus/creature/spec";
import { sampleTrack as compilerSample } from "../lib/cyrus/creature/compile";
import { TRACK_KINDS, kindOf, sampleClip, sampleTransform, firedBetween, instants, clockInit, clockPlay, clockPause, clockScrub, clockSpeed, clockTick, clockToggle, MAX_SPEED, type Clip, type Track } from "../lib/cyrus/modelstudio/editor/timeline";
import { fromRigSpec, toRigSpec } from "../lib/cyrus/modelstudio/editor/rigspec";
import { applyOp, applyAll } from "../lib/cyrus/modelstudio/editor/ops";
import { mergeCandidate } from "../lib/cyrus/modelstudio/editor/merge";
import { validateDoc } from "../lib/cyrus/modelstudio/editor/validate";
import { checkModelDoc } from "../lib/cyrus/modelstudio/editor/doc";

const load = (n: string) => { const c = checkRigSpec(JSON.parse(fs.readFileSync(path.join(__dirname, "fixtures/cyrus-creatures", `${n}.json`), "utf8"))); if (!c.ok) throw new Error(c.error); return c.spec; };
const clip = (o: Partial<Clip> = {}): Clip => ({
  name: "fire", length: 2, loop: false,
  tracks: [
    { bone: "slide", channel: "position", keys: [{ id: "k1", t: 0, v: [0, 0, 0], ease: "smooth" }, { id: "k2", t: 0.25, v: [0, 0, -2], ease: "linear" }, { id: "k3", t: 1, v: [0, 0, 0], ease: "smooth" }] },
    { kind: "sound_cue", target: "muzzle", cues: [{ id: "s1", t: 0.1, sound: "nx_aaaaaaaa:glock.fire" }] },
    { kind: "particle", target: "muzzle", bursts: [{ id: "p1", t: 0.1, effect: "muzzle_flash", count: 6 }] },
    { kind: "light", target: "muzzle", property: "intensity", keys: [{ id: "l1", t: 0, v: 0, ease: "linear" }, { id: "l2", t: 0.1, v: 8, ease: "linear" }, { id: "l3", t: 0.3, v: 0, ease: "linear" }] },
    { kind: "state", machine: "gun", changes: [{ id: "x1", t: 0, state: "firing" }, { id: "x2", t: 0.8, state: "idle" }] },
  ],
  events: [{ id: "e1", t: 0.5, name: "eject_casing" }],
  ...o,
});

describe("timeline: kinds and the sampler", () => {
  it("declares transform as implemented and every other kind as a planned extension point", () => {
    assert.equal(TRACK_KINDS.transform.status, "implemented");
    for (const k of ["sound_cue", "particle", "light", "material", "state"] as const) assert.equal(TRACK_KINDS[k].status, "planned");
    assert.equal(kindOf({ bone: "a", channel: "rotation" } as Track), "transform");
  });
  it("transform sampling equals the creature compiler on every fixture track", () => {
    for (const n of ["banshee", "ghoul", "dire_wolf"]) {
      const s = load(n);
      for (const [, c] of Object.entries(s.animations)) for (const t of c.tracks) for (let i = 0; i <= 16; i++) {
        const a = sampleTransform(t, c, (i / 16) * c.length), b = compilerSample(t, c, (i / 16) * c.length);
        assert.ok(a.every((v, j) => Math.abs(v - b[j]) < 1e-12));
      }
    }
  });
  it("one call evaluates transforms, scalars and states deterministically", () => {
    const a = sampleClip(clip(), 0.1), b = sampleClip(clip(), 0.1);
    assert.deepEqual([...a.nodes], [...b.nodes]);
    assert.ok(Math.abs(a.nodes.get("slide")!.position![2] - -0.8) < 1e-9, "linear key at t 0.05/0.25");
    assert.equal(a.scalars.get("light:muzzle:intensity"), 4);
    assert.equal(sampleClip(clip(), 1.0).states.get("gun"), "firing");
    assert.equal(sampleClip(clip(), 1.7).states.get("gun"), "idle");
  });
  it("instants: events, cues, bursts and state changes sorted; firedBetween is half-open and wrap-aware", () => {
    assert.deepEqual(instants(clip()).map((x) => x.id), ["x1", "p1", "s1", "e1", "x2"]);
    assert.deepEqual(firedBetween(clip(), 0, 0.2, { includeStart: true }).map((x) => x.id), ["x1", "p1", "s1"]);
    assert.deepEqual(firedBetween(clip(), 0.2, 1.0).map((x) => x.id), ["e1"]);
    const loop = clip({ loop: true });
    const w = firedBetween(loop, 1.5, 2.3);
    assert.deepEqual(w.map((x) => `${x.id}@${x.cycle}`), ["x2@0", "x1@1", "p1@1", "s1@1"]);
    assert.deepEqual(firedBetween(clip(), 1.5, 9).map((x) => x.id), ["x2"], "a one-shot never wraps");
  });
});

describe("timeline: the playback clock", () => {
  it("play / pause / scrub / speed, a one-shot stops at its end and fires what it crossed", () => {
    const c0 = clipOf();
    let c = clockPlay(clockInit(c0));
    let r = clockTick(c, 0.25, c0);
    assert.equal(r.clock.time, 0.25);
    assert.deepEqual(r.fired.map((x) => x.id), ["x1", "p1", "s1"]);
    c = clockSpeed(r.clock, 2);
    r = clockTick(c, 1, c0);
    assert.equal(r.clock.time, 2);
    assert.equal(r.ended, true);
    assert.equal(r.clock.playing, false);
    assert.deepEqual(r.fired.map((x) => x.id), ["e1", "x2"]);
    assert.equal(clockTick(clockPause(clockPlay(clockInit(c0))), 1, c0).clock.time, 0, "paused clocks do not move");
    assert.equal(clockScrub(clockInit(c0), 99).time, 2);
    assert.equal(clockScrub(clockInit(c0), -1).time, 0);
    assert.equal(clockSpeed(clockInit(c0), 99).speed, MAX_SPEED);
    assert.equal(clockPlay({ ...clockInit(c0), time: 2, elapsed: 2 }).time, 0, "replaying a finished one-shot rewinds");
    assert.equal(clockToggle(clockInit(c0)).playing, true);
  });
  it("a looping clock wraps, counts wraps and keeps firing in order", () => {
    const c0 = clipOf({ loop: true });
    let c = clockPlay(clockInit(c0));
    const all: string[] = [];
    let wraps = 0;
    for (let i = 0; i < 25; i++) { const r = clockTick(c, 0.2, c0); c = r.clock; wraps += r.wrapped; all.push(...r.fired.map((x) => x.id)); }
    assert.ok(Math.abs(c.time - 1) < 1e-9);
    assert.equal(wraps, 2);
    assert.equal(all.filter((x) => x === "e1").length, 3);
    assert.equal(all.filter((x) => x === "x1").length, 3);
  });
});
function clipOf(o: Partial<Clip> = {}) { return clip(o); }

describe("timeline: clip events in the editor document", () => {
  const d0 = fromRigSpec(load("banshee"));
  it("setEvent / deleteEvent keep events sorted with fresh ids; the doc still parses", () => {
    const r = applyAll(d0, [{ op: "setEvent", clip: "walk", t: 0.5, name: "footstep" }, { op: "setEvent", clip: "walk", t: 0, name: "footstep" }]);
    assert.equal(r.error, undefined);
    const ev = r.doc.clips.find((c) => c.name === "walk")!.events!;
    assert.deepEqual(ev.map((e) => e.t), [0, 0.5]);
    assert.ok(checkModelDoc(r.doc).ok);
    assert.equal(applyOp(r.doc, { op: "setEvent", clip: "walk", t: 0.2, name: "Bad Name" }).ok, false);
    const del = applyOp(r.doc, { op: "deleteEvent", clip: "walk", id: ev[0].id });
    assert.ok(del.ok && del.doc.clips.find((c) => c.name === "walk")!.events!.length === 1);
  });
  it("RigSpec v1 cannot carry events: dropped with a note, kept through a like-load, a warning for Minecraft", () => {
    const d = (applyOp(d0, { op: "setEvent", clip: "attack", t: 0.4, name: "swipe" }) as { doc: typeof d0 }).doc;
    const { spec, dropped } = toRigSpec(d);
    assert.ok(dropped.some((x) => x.field === "events"));
    const c = checkRigSpec(spec);
    assert.ok(c.ok);
    const back = fromRigSpec(c.ok ? c.spec : load("banshee"), { like: d });
    assert.equal(back.clips.find((x) => x.name === "attack")!.events![0].name, "swipe");
    assert.ok(validateDoc(d).issues.some((i) => i.code === "clip_events_editor_only" && i.severity === "warn"));
  });
  it("events merge per id (both sides adding events keep both)", () => {
    const ours = (applyOp(d0, { op: "setEvent", clip: "walk", t: 0.25, name: "step_l" }) as { doc: typeof d0 }).doc;
    const theirs = (applyOp(d0, { op: "setEvent", clip: "walk", t: 0.75, name: "step_r" }) as { doc: typeof d0 }).doc;
    const m = mergeCandidate(d0, ours, theirs);
    assert.deepEqual(m.doc.clips.find((c) => c.name === "walk")!.events!.map((e) => e.name), ["step_l", "step_r"]);
    assert.equal(new Set(m.doc.clips.find((c) => c.name === "walk")!.events!.map((e) => e.id)).size, 2);
  });
});

